"use client";

import Link from "next/link";
import { useRouter } from "next/navigation";
import { useEffect, useId, useState } from "react";
import {
  AuthStandaloneCardHeader,
  AuthStandalonePageShell,
  authStandaloneCardClass,
} from "@/components/gestionale/auth-standalone-page";
import { GlobalLoadingView } from "@/components/design-system/global-loading";
import { pushGestionaleToast } from "@/context/toast-context";
import { GLOBAL_LOADING_MESSAGES } from "@/lib/ui/global-loading-messages";
import { isSupabasePublicEnvConfigured, MISSING_SUPABASE_ENV_MESSAGE } from "@/lib/env/supabase-public";
import { dsBtnPrimary, dsLabel, dsSearchFieldInput } from "@/lib/ui/design-system";
import { validatePasswordConfirmation } from "@/lib/validation/password-validation";
import { getBrowserSupabase } from "@/src/lib/supabase/browser-client";

const alertErrorClass =
  "rounded-[var(--ds-radius-lg)] border border-[color:color-mix(in_srgb,var(--cab-danger)_35%,var(--cab-border))] bg-[color:color-mix(in_srgb,var(--cab-danger)_8%,var(--cab-surface))] px-3 py-2 text-sm text-[color:color-mix(in_srgb,var(--cab-danger)_90%,var(--cab-text))]";

type ResetPhase = "loading" | "ready" | "no_session" | "success";

export function ResetPasswordForm() {
  const router = useRouter();
  const formId = useId();
  const passwordId = `${formId}-password`;
  const confirmId = `${formId}-confirm`;

  const [phase, setPhase] = useState<ResetPhase>("loading");
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [fieldError, setFieldError] = useState<string | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [pending, setPending] = useState(false);

  useEffect(() => {
    if (!isSupabasePublicEnvConfigured()) {
      setError(MISSING_SUPABASE_ENV_MESSAGE);
      setPhase("no_session");
      return;
    }

    let cancelled = false;
    const sb = getBrowserSupabase();

    const markReady = () => {
      if (!cancelled) setPhase("ready");
    };

    const { data: sub } = sb.auth.onAuthStateChange((event, session) => {
      if (cancelled) return;
      if (event === "PASSWORD_RECOVERY" && session) {
        markReady();
        return;
      }
      if (event === "SIGNED_IN" && session && window.location.pathname.startsWith("/login/reset-password")) {
        markReady();
      }
    });

    void (async () => {
      const { data } = await sb.auth.getSession();
      if (cancelled) return;
      if (data.session?.user) {
        markReady();
        return;
      }
      setPhase("no_session");
    })();

    return () => {
      cancelled = true;
      sub.subscription.unsubscribe();
    };
  }, []);

  async function onSubmit(e: React.FormEvent) {
    e.preventDefault();
    setError(null);
    setFieldError(null);

    const validation = validatePasswordConfirmation(password, confirm);
    if (validation) {
      setFieldError(validation);
      return;
    }

    setPending(true);
    try {
      const sb = getBrowserSupabase();
      const { error: updateErr } = await sb.auth.updateUser({ password });
      if (updateErr) {
        setError("Impossibile aggiornare la password. Il link potrebbe essere scaduto.");
        return;
      }
      setPhase("success");
      pushGestionaleToast("Password aggiornata. Accesso in corso…", "success", 4200);
      router.replace("/dashboard");
      router.refresh();
    } catch {
      setError("Impossibile aggiornare la password. Riprova tra poco.");
    } finally {
      setPending(false);
    }
  }

  if (phase === "loading") {
    return (
      <AuthStandalonePageShell>
        <div className="relative z-10 flex min-h-dvh items-center justify-center px-4 py-12">
          <GlobalLoadingView message={GLOBAL_LOADING_MESSAGES.default} />
        </div>
      </AuthStandalonePageShell>
    );
  }

  return (
    <AuthStandalonePageShell>
      <main className="relative z-10 flex min-h-dvh flex-col items-center justify-center px-4 py-10 sm:px-6 sm:py-14">
        <div className={authStandaloneCardClass}>
          <AuthStandaloneCardHeader srOnlyTitle="Imposta nuova password" />

          {phase === "no_session" ? (
            <div data-testid="smoke-reset-password-no-session" className="space-y-4 text-center">
              <p className={`${alertErrorClass} text-sm`} role="alert">
                {error ?? "Link non valido o scaduto. Richiedi un nuovo link di recupero password."}
              </p>
              <Link href="/login" className={`${dsBtnPrimary} block min-h-11 w-full py-2.5 text-center text-sm font-semibold`}>
                Torna al login
              </Link>
            </div>
          ) : (
            <form onSubmit={onSubmit} noValidate className="space-y-4">
              <p className="text-center text-sm text-[color:var(--cab-text-muted)]">
                Scegli una nuova password per il tuo account.
              </p>

              {error ? (
                <p className={alertErrorClass} role="alert">
                  {error}
                </p>
              ) : null}

              <div>
                <label htmlFor={passwordId} className={`block ${dsLabel} text-[color:var(--cab-text)]`}>
                  Nuova password
                </label>
                <div className="relative mt-1.5">
                <input
                  id={passwordId}
                  data-testid="smoke-reset-password"
                  type="password"
                  autoComplete="new-password"
                  className={dsSearchFieldInput}
                  value={password}
                  onChange={(e) => {
                    setPassword(e.target.value);
                    setFieldError(null);
                  }}
                  minLength={8}
                  maxLength={128}
                  required
                  disabled={pending}
                  aria-invalid={Boolean(fieldError)}
                />
                </div>
              </div>

              <div>
                <label htmlFor={confirmId} className={`block ${dsLabel} text-[color:var(--cab-text)]`}>
                  Conferma password
                </label>
                <div className="relative mt-1.5">
                <input
                  id={confirmId}
                  data-testid="smoke-reset-password-confirm"
                  type="password"
                  autoComplete="new-password"
                  className={dsSearchFieldInput}
                  value={confirm}
                  onChange={(e) => {
                    setConfirm(e.target.value);
                    setFieldError(null);
                  }}
                  minLength={8}
                  maxLength={128}
                  required
                  disabled={pending}
                  aria-invalid={Boolean(fieldError)}
                />
                </div>
              </div>

              {fieldError ? (
                <p className={alertErrorClass} role="alert">
                  {fieldError}
                </p>
              ) : null}

              <button
                type="submit"
                className={`${dsBtnPrimary} mt-1 min-h-11 w-full justify-center py-2.5 text-sm font-semibold`}
                disabled={pending}
              >
                {pending ? "Aggiornamento…" : "Salva nuova password"}
              </button>

              <p className="text-center text-xs">
                <Link href="/login" className="text-[color:var(--cab-primary)] underline-offset-2 hover:underline">
                  Torna al login
                </Link>
              </p>
            </form>
          )}
        </div>
      </main>
    </AuthStandalonePageShell>
  );
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { TablePagination } from "@/components/gestionale/table-pagination";
import {
  GestionaleLogEmpty,
  GestionaleLogEntryFourLines,
  GestionaleLogList,
  gestionaleLogScrollEmbeddedClass,
} from "@/components/gestionale/gestionale-log-ui";
import {
  CONFIGURAZIONE_LOG_STORAGE_KEY,
  loadConfigurazioneLog,
  migrateLegacyDashboardSettingsLogsToConfigurazione,
  type ConfigurazioneLogStored,
} from "@/lib/configurazione/configurazione-log-storage";
import { CAB_CONFIGURAZIONE_LOG_REFRESH } from "@/lib/sistema/cab-events";
import { useClientPagination } from "@/lib/ui/use-client-pagination";
import { useResponsiveListPageSize } from "@/lib/ui/use-responsive-list-page-size";

function vmFromStored(e: ConfigurazioneLogStored) {
  const { id: _id, ...vm } = e;
  return vm;
}

const GROUP_WINDOW_MS = 120_000;

function groupConfigurazioneEntries(entries: ConfigurazioneLogStored[]): ConfigurazioneLogStored[] {
  if (entries.length === 0) return [];
  const out: ConfigurazioneLogStored[] = [];
  let buf: ConfigurazioneLogStored[] = [];

  function flush() {
    if (buf.length === 0) return;
    if (buf.length === 1) {
      out.push(buf[0]);
    } else {
      const first = buf[0];
      const last = buf[buf.length - 1];
      const base = first.modificaRiga.replace(/\s*\(\d+\s+cambi\)\s*$/i, "").trim();
      out.push({
        ...last,
        id: `grp-${first.id}-${buf.length}-${last.atIso}`,
        modificaRiga: `${base} (${buf.length} sezioni)`,
      });
    }
    buf = [];
  }

  for (const e of entries) {
    const prev = buf[buf.length - 1];
    if (
      prev &&
      prev.tipoRiga === e.tipoRiga &&
      prev.autore === e.autore &&
      Math.abs(new Date(e.atIso).getTime() - new Date(prev.atIso).getTime()) <= GROUP_WINDOW_MS
    ) {
      buf.push(e);
    } else {
      flush();
      buf = [e];
    }
  }
  flush();
  return out;
}

function useConfigurazioneLogEntries(): ConfigurazioneLogStored[] {
  const [entries, setEntries] = useState<ConfigurazioneLogStored[]>([]);

  useEffect(() => {
    function refresh() {
      migrateLegacyDashboardSettingsLogsToConfigurazione();
      setEntries(loadConfigurazioneLog());
    }
    refresh();
    const onVis = () => {
      if (document.visibilityState === "visible") refresh();
    };
    const onStorage = (ev: StorageEvent) => {
      if (ev.key === CONFIGURAZIONE_LOG_STORAGE_KEY) refresh();
    };
    window.addEventListener(CAB_CONFIGURAZIONE_LOG_REFRESH, refresh);
    document.addEventListener("visibilitychange", onVis);
    window.addEventListener("storage", onStorage);
    return () => {
      window.removeEventListener(CAB_CONFIGURAZIONE_LOG_REFRESH, refresh);
      document.removeEventListener("visibilitychange", onVis);
      window.removeEventListener("storage", onStorage);
    };
  }, []);

  return entries;
}

export function ConfigurazioneLogListEmbedded({
  max = 40,
  className,
  paged = false,
}: {
  max?: number;
  className?: string;
  paged?: boolean;
}) {
  const entries = useConfigurazioneLogEntries();
  const grouped = useMemo(() => groupConfigurazioneEntries(entries), [entries]);

  const pageSize = useResponsiveListPageSize();
  const { page, setPage, pageCount, sliceItems, showPager, label, resetPage } = useClientPagination(
    grouped.length,
    pageSize,
  );

  useEffect(() => {
    if (!paged) return;
    resetPage();
  }, [paged, grouped.length, pageSize, resetPage]);

  const slice = useMemo(() => {
    if (paged) return sliceItems(grouped);
    return grouped.slice(0, max);
  }, [paged, grouped, max, sliceItems, page]);

  const list = (
    <>
      {slice.length === 0 ? (
        <GestionaleLogEmpty message="Nessuna modifica registrata. Ogni salvataggio in Configurazione viene tracciato qui." />
      ) : (
        <GestionaleLogList>
          {slice.map((e) => (
            <li key={e.id} className="list-none">
              <GestionaleLogEntryFourLines vm={vmFromStored(e)} />
            </li>
          ))}
        </GestionaleLogList>
      )}
    </>
  );

  if (paged) {
    return (
      <div className={`flex min-h-0 min-w-0 flex-1 flex-col gap-2 ${className ?? ""}`}>
        <div className={`${gestionaleLogScrollEmbeddedClass} min-h-0 min-w-0 flex-1 pr-1`}>{list}</div>
        {showPager ? <TablePagination page={page} pageCount={pageCount} onPageChange={setPage} label={label} /> : null}
      </div>
    );
  }

  return <div className={`${gestionaleLogScrollEmbeddedClass} min-h-0 min-w-0 flex-1 pr-1 ${className ?? ""}`}>{list}</div>;
}

