}) {
  const [mounted, setMounted] = useState(false);
  useEffect(() => setMounted(true), []);

  const [yearStr, monthStr] = monthKey.split("-");
  const viewYear = Number(yearStr);
  const viewMonth = Number(monthStr) - 1;

  const cells = useMemo(() => buildMonthGrid(viewYear, viewMonth), [viewYear, viewMonth]);
  const weeks = useMemo(() => groupCellsByWeek(cells), [cells]);
  const todayYmd = mounted ? toYmd(new Date()) : "";

  const selectedDayYmd = selection.mode === "day" ? selection.ymd : null;
  const selectedWeekStart = selection.mode === "week" ? selection.weekStartYmd : null;

  const shiftMonth = useCallback(
    (delta: number) => {
      const d = new Date(viewYear, viewMonth + delta, 1, 12, 0, 0, 0);
      onMonthKeyChange(`${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}`);
    },
    [viewYear, viewMonth, onMonthKeyChange],
  );

  const monthTitle = useMemo(() => {
    const d = new Date(viewYear, viewMonth, 1);
    return d.toLocaleDateString("it-IT", { month: "long", year: "numeric" });
  }, [viewYear, viewMonth]);

  return (
    <div className={`${globalInputCalendarGridShell} min-w-0`}>
      <div className="mb-2 flex min-w-0 flex-wrap items-center justify-between gap-2 px-1">
        <div className="flex min-w-0 items-center gap-1">
          <button
            type="button"
            className={dsPageToolbarIconBtn}
            aria-label="Mese precedente"
            onClick={() => shiftMonth(-1)}
          >
            <CalendarNavChevronLeft />
          </button>
          <span className="min-w-0 px-1 text-sm font-semibold capitalize text-[color:var(--cab-text)]">
            {monthTitle}
          </span>
          <button
            type="button"
            className={dsPageToolbarIconBtn}
            aria-label="Mese successivo"
            onClick={() => shiftMonth(1)}
          >
            <CalendarNavChevronRight />
          </button>
        </div>
        <div className="flex items-center gap-1">
          <div className="inline-flex rounded-lg border border-[color:var(--cab-border)] p-0.5">
            {(["month", "week"] as const).map((mode) => (
              <button
                key={mode}
                type="button"
                className={`rounded-md px-2 py-1 text-[11px] font-semibold uppercase tracking-wide ${
                  viewMode === mode
                    ? "bg-[color:color-mix(in_srgb,var(--cab-primary)_14%,var(--cab-surface))] text-[color:var(--cab-text)]"
                    : "text-[color:var(--cab-text-muted)] hover:bg-[var(--cab-hover)]"
                }`}
                onClick={() => onViewModeChange(mode)}
              >
                {mode === "month" ? "Mese" : "Settimana"}
              </button>
            ))}
          </div>
          {onGoToday ? (
            <button type="button" className={dsPageToolbarIconBtn} aria-label="Oggi" onClick={onGoToday}>
              <CalendarTodayIcon />
            </button>
          ) : null}
        </div>
      </div>

      <div
        className={`px-2 pt-1 transition-opacity duration-200 ${isLoading ? "opacity-55" : "opacity-100"}`}
      >
        <div className="mb-1 grid grid-cols-7 gap-0.5">
          {WEEKDAYS_IT.map((wd) => (
            <span
              key={wd}
              className={`${dsTypoCaption} flex items-center justify-center py-1 text-center text-[10px] font-bold uppercase text-[color:var(--cab-text-muted)]`}
            >
              {wd}
            </span>
          ))}
        </div>

        {weeks.map((weekCells, wi) => {
          const weekStart = weekStartYmdFromYmd(weekCells[0]?.ymd ?? "") ?? "";
          const weekEnd = weekRangeFromYmd(weekStart)?.end;
          const weekEndYmd = weekEnd ? ymdFromDate(weekEnd) : weekStart;
          const weekSelected = selectedWeekStart === weekStart && selection.mode === "week";

          return (
            <div key={wi} className="min-w-0">
              {viewMode === "week" ? (
                <button
                  type="button"
                  className={`mb-0.5 w-full rounded-md py-0.5 text-left text-[10px] font-semibold uppercase tracking-wide ${
                    weekSelected
                      ? "bg-[color:color-mix(in_srgb,var(--cab-primary)_12%,var(--cab-surface))] text-[color:var(--cab-primary)]"
                      : "text-[color:var(--cab-text-muted)] hover:bg-[var(--cab-hover)]"
                  }`}
                  onClick={() => onSelectWeek(weekStart, weekEndYmd)}
                >
                  Sett. {weekStart.slice(5).replace("-", "/")}
                </button>
              ) : null}
              <div className="grid grid-cols-7 justify-items-center gap-0.5 pb-0.5">
                {weekCells.map((cell) => {
                  const selected = selectedDayYmd === cell.ymd;
                  const inSelectedWeek =
                    selection.mode === "week" &&
                    weekStart &&
                    cell.ymd >= weekStart &&
                    cell.ymd <= weekEndYmd;
                  const isToday = mounted && todayYmd === cell.ymd;
                  const hasData = hasDataByDate[cell.ymd] === true && cell.inMonth;
                  return (
                    <button
                      key={cell.ymd}
                      type="button"
                      disabled={!cell.inMonth}
                      className={`${dayBtnClass} ${
                        !cell.inMonth ? "pointer-events-none opacity-25" : ""
                      } ${selected || inSelectedWeek ? globalInputCalendarDaySelected : ""} ${
                        isToday && !selected ? globalInputCalendarDayToday : ""
                      }`}
                      aria-label={cell.date.toLocaleDateString("it-IT")}
                      aria-pressed={Boolean(selected || inSelectedWeek)}
                      onClick={() => {
                        if (viewMode === "week") {
                          onSelectWeek(weekStart, weekEndYmd);
                        } else {
                          onSelectDay(cell.ymd);
                        }
                      }}
                    >
                      {cell.date.getDate()}
                      {hasData ? (
                        <span
                          className="absolute bottom-1 left-1/2 h-1 w-1 -translate-x-1/2 rounded-full bg-[color:var(--cab-primary)]"
                          aria-hidden
                        />
                      ) : null}
                    </button>
                  );
                })}
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

"use client";

import { useCallback, useMemo, useState } from "react";
import { GestionaleAiActionButton } from "@/components/design-system/gestionale-ai-action-button";
import { LoadingSkeletonBlock } from "@/components/design-system/loading/loading-skeleton";
import { buildReportModel } from "@/lib/report/build-report-model";
import { insightsFromAnalysisOutput } from "@/lib/report/calendar-report-service";
import { useReportAnalysis } from "@/lib/report/report-analysis/use-report-analysis";
import { buildKpiPerformanceModel } from "@/lib/report/kpi-performance/build-kpi-performance-model";
import { buildTopRicambiPeriodo } from "@/lib/report/report-classifiche";
import { compareRangeFor, dayRangeFromYmd, weekRangeFromYmd, ymdFromDate } from "@/lib/report/date-ranges";
import type { CalendarReportServiceInput } from "@/lib/report/calendar-report-service";
import type { ReportDerivedBundle } from "@/lib/report/report-derived-cache";
import type { ReportIntegrityBadgeView } from "@/lib/report/report-integrity-badge-model";
import type { CalendarSelection } from "@/components/dashboard/calendar-v2/calendar-v2-types";
import { dsTypoCaption, dsTypoSmall } from "@/lib/ui/design-system";

export function CalendarV2InsightsBlock({
  selection,
  serviceInput,
  derivedBundle,
  snapshotFingerprint,
  integrityView,
  deterministicInsights,
  canUseAi,
}: {
  selection: CalendarSelection;
  serviceInput: CalendarReportServiceInput;
  derivedBundle: ReportDerivedBundle;
  snapshotFingerprint: string;
  integrityView: ReportIntegrityBadgeView;
  deterministicInsights: string[];
  canUseAi: boolean;
}) {
  const [aiRequested, setAiRequested] = useState(false);

  const filterRange = useMemo(() => {
    if (selection.mode === "day") return dayRangeFromYmd(selection.ymd);
    return weekRangeFromYmd(selection.weekStartYmd);
  }, [selection]);

  const compareRange = useMemo(
    () => (filterRange ? compareRangeFor(filterRange, "prev_period") : null),
    [filterRange],
  );

  const customFrom = filterRange ? ymdFromDate(filterRange.start) : "";
  const customTo = filterRange ? ymdFromDate(filterRange.end) : "";

  const model = useMemo(() => {
    if (!filterRange) return null;
    return buildReportModel({
      anchor: serviceInput.anchor,
      preset: "custom",
      customFrom,
      customTo,
      compareMode: "prev_period",
      attive: serviceInput.attive,
      storico: serviceInput.storico,
      completate: serviceInput.completate,
      manualByMonth: serviceInput.manualByMonth,
      magazzino: serviceInput.magazzino,
      mezzi: serviceInput.mezzi,
      magLog: serviceInput.magLog,
      semanticIndex: derivedBundle.semanticIndex,
      derivedBundle,
    });
  }, [filterRange, customFrom, customTo, serviceInput, derivedBundle]);

  const perf = useMemo(() => {
    if (!filterRange) return null;
    return buildKpiPerformanceModel({
      anchor: serviceInput.anchor,
      range: filterRange,
      compareRange,
      attive: serviceInput.attive,
      completate: serviceInput.completate,
      mezzi: serviceInput.mezzi,
      magazzino: serviceInput.magazzino,
      magLog: serviceInput.magLog,
      magazzinoRows: serviceInput.magazzino.map((p) => ({
        id: p.id,
        costo: p.prezzoFornitoreOriginale,
      })) as import("@/src/types/supabase-tables").MagazzinoRicambioRow[],
      lavRows: serviceInput.lavRows,
      semanticIndex: derivedBundle.semanticIndex,
      schedeStore: null,
      schedeLoaded: false,
      costoOrario: 48,
    });
  }, [filterRange, compareRange, serviceInput, derivedBundle.semanticIndex]);

  const tops = useMemo(() => {
    if (!filterRange) return { mezzi: [], clienti: [], ricambi: [] };
    return {
      mezzi: derivedBundle.semanticIndex.topMezzi(filterRange),
      clienti: derivedBundle.semanticIndex.topClienti(filterRange),
      ricambi: buildTopRicambiPeriodo(derivedBundle.magLogSorted, serviceInput.magazzino, filterRange),
    };
  }, [filterRange, derivedBundle, serviceInput.magazzino]);

  const analysis = useReportAnalysis({
    preset: "custom",
    compareMode: "prev_period",
    filterRange: filterRange ?? { start: new Date(), end: new Date() },
    compareRange,
    model: model ?? {
      range: filterRange ?? { start: new Date(), end: new Date() },
      compareRange,
      compareMode: "prev_period" as const,
      kpis: [],
      compareDetail: null,
    },
    perf,
    integrityView,
    tops,
    snapshotFingerprint,
    perfReady: aiRequested && Boolean(model && perf && filterRange),
  });

  const aiInsights = useMemo(() => insightsFromAnalysisOutput(analysis.data), [analysis.data]);
  const displayInsights = aiRequested && analysis.status === "success" ? aiInsights : deterministicInsights;

  const onGenerate = useCallback(() => {
    setAiRequested(true);
    void analysis.generate();
  }, [analysis]);

  if (!filterRange || !model) {
    return null;
  }

  return (
    <section className="min-w-0 space-y-2" aria-labelledby="calendar-v2-insights-title">
      <div className="flex min-w-0 flex-wrap items-center justify-between gap-2">
        <h3 id="calendar-v2-insights-title" className={`${dsTypoSmall} font-semibold text-[color:var(--cab-text)]`}>
          Insight
        </h3>
        {canUseAi ? (
          <GestionaleAiActionButton
            size="sm"
            loading={analysis.isLoading}
            disabled={!analysis.canGenerate && !analysis.isLoading}
            onClick={onGenerate}
          >
            {analysis.status === "success" ? "Rigenera insight IA" : "Genera insight IA"}
          </GestionaleAiActionButton>
        ) : null}
      </div>
      {analysis.isLoading ? (
        <LoadingSkeletonBlock className="h-16 w-full rounded-lg" />
      ) : displayInsights.length === 0 ? (
        <p className={`${dsTypoCaption} text-[color:var(--cab-text-muted)]`}>Nessun insight per questo periodo.</p>
      ) : (
        <ul className="min-w-0 space-y-1.5">
          {displayInsights.map((line, i) => (
            <li
              key={`${i}-${line.slice(0, 24)}`}
              className={`${dsTypoSmall} rounded-md border border-[color:var(--cab-border)] bg-[var(--cab-surface)] px-2.5 py-2 text-[color:var(--cab-text)]`}
            >
              {line}
            </li>
          ))}
        </ul>
      )}
      {analysis.status === "error" ? (
        <p className={`${dsTypoCaption} text-[color:var(--cab-danger)]`}>{analysis.error?.message ?? "Errore IA"}</p>
      ) : null}
    </section>
  );
}

"use client";

import { dsTypoCaption, dsTypoSmall } from "@/lib/ui/design-system";
import type { CalendarDaySummary } from "@/lib/report/calendar-report-service";
import { operationalStatusLabel } from "@/lib/report/calendar-report-service";

function KpiTile({ label, value, sub }: { label: string; value: string; sub?: string }) {
  return (
    <div className="min-w-0 rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] px-3 py-2.5">
      <p className={`${dsTypoCaption} font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)]`}>
        {label}
      </p>
      <p className="mt-1 text-xl font-bold tabular-nums text-[color:var(--cab-text)]">{value}</p>
      {sub ? <p className={`mt-0.5 ${dsTypoCaption} text-[color:var(--cab-text-muted)]`}>{sub}</p> : null}
    </div>
  );
}

export function CalendarV2KpiCards({ summary }: { summary: CalendarDaySummary }) {
  const { kpis } = summary;
  return (
    <div className="min-w-0 space-y-2">
      <div className="grid min-w-0 grid-cols-3 gap-2">
        <KpiTile label="Ingressi" value={String(summary.entriesCount)} />
        <KpiTile label="Uscite" value={String(summary.exitsCount)} />
        <KpiTile
          label="Mezzi attivi"
          value={kpis.vehiclesActive != null ? String(kpis.vehiclesActive) : "—"}
          sub="Proxy officina"
        />
      </div>
      <div className={`flex flex-wrap items-center gap-x-3 gap-y-1 ${dsTypoSmall} text-[color:var(--cab-text-muted)]`}>
        {kpis.averageDwellTime != null ? (
          <span>Permanenza media: {kpis.averageDwellTime} gg</span>
        ) : null}
        {kpis.anomaliesCount != null ? <span>Anomalie: {kpis.anomaliesCount}</span> : null}
        <span className="font-medium text-[color:var(--cab-text)]">
          {operationalStatusLabel(summary.operationalStatus)}
        </span>
      </div>
    </div>
  );
}

export function CalendarV2WeekKpiCards({
  entriesCount,
  exitsCount,
  entriesTrendPct,
  exitsTrendPct,
  anomaliesCount,
}: {
  entriesCount: number;
  exitsCount: number;
  entriesTrendPct: number | null;
  exitsTrendPct: number | null;
  anomaliesCount: number;
}) {
  const fmtTrend = (pct: number | null) => {
    if (pct == null) return undefined;
    const dir = pct >= 0 ? "↑" : "↓";
    return `${dir} ${Math.abs(pct)}% vs sett. prec.`;
  };

  return (
    <div className="min-w-0 space-y-2">
      <div className="grid min-w-0 grid-cols-2 gap-2 sm:grid-cols-3">
        <KpiTile label="Ingressi sett." value={String(entriesCount)} sub={fmtTrend(entriesTrendPct)} />
        <KpiTile label="Uscite sett." value={String(exitsCount)} sub={fmtTrend(exitsTrendPct)} />
        <KpiTile label="Anomalie" value={String(anomaliesCount)} />
      </div>
    </div>
  );
}

