"use client";

import { useEffect, useState } from "react";
import {
  GLOBAL_LOADING_MESSAGES,
  type GlobalLoadingMessageKey,
} from "@/lib/ui/global-loading-messages";
import { LOADING_DELAYED_MESSAGE_MS } from "./loading-tokens";

/**
 * Mostra messaggio contestuale solo se il loading supera la soglia (default 1s).
 * Un solo timer per istanza — nessun polling.
 */
export function useDelayedLoadingMessage(
  isLoading: boolean,
  messageKey: GlobalLoadingMessageKey = "default",
): string | null {
  const [show, setShow] = useState(false);

  useEffect(() => {
    if (!isLoading) {
      setShow(false);
      return;
    }
    const id = window.setTimeout(() => setShow(true), LOADING_DELAYED_MESSAGE_MS);
    return () => window.clearTimeout(id);
  }, [isLoading]);

  if (!isLoading || !show) return null;
  return GLOBAL_LOADING_MESSAGES[messageKey];
}

"use client";

import type { KeyboardEvent, ReactNode } from "react";
import { memo } from "react";
import { Tooltip } from "@/components/design-system/tooltip";
import { erpFocus } from "@/components/gestionale/lavorazioni/lavorazioni-shared";
import { filterAuditMetadataModifiche, parseModificheLines, sanitizeLogOggettoRiga } from "@/lib/gestionale-log/log-summary";
import type { GestionaleLogEventTone, GestionaleLogViewModel } from "@/lib/gestionale-log/view-model";
import { formatGestionaleLogMetaLine } from "@/lib/gestionale-log/view-model";

const LOG_ENTRY_SHELL_CLASS =
  "rounded-[var(--ds-radius-lg)] border border-[color:var(--cab-border)] bg-[color:color-mix(in_srgb,var(--cab-surface-2)_40%,var(--cab-card))] px-3";

const LOG_ENTRY_INBOX_SHELL_CLASS =
  "gestionale-inbox-log-entry rounded-[var(--ds-radius-xl)] border border-[color:var(--cab-border)] bg-[var(--cab-card)] px-3.5 shadow-[var(--cab-shadow-sm)] transition-[border-color,box-shadow,background-color] duration-200";

const LOG_ENTRY_INBOX_SHELL_INTERACTIVE =
  "cursor-pointer hover:border-[color:color-mix(in_srgb,var(--cab-primary)_34%,var(--cab-border))] hover:bg-[var(--cab-hover)] hover:shadow-[var(--cab-shadow-md)]";

const LOG_ENTRY_INTERACTIVE_CLASS = `w-full cursor-pointer text-left transition-colors hover:border-[color:color-mix(in_srgb,var(--cab-primary)_35%,var(--cab-border))] hover:bg-[var(--cab-hover)] ${erpFocus}`;

function logEntryActivate(onClick: () => void, e: KeyboardEvent<HTMLDivElement>) {
  if (e.key === "Enter" || e.key === " ") {
    e.preventDefault();
    onClick();
  }
}

const TONE_BADGE: Record<GestionaleLogEventTone, string> = {
  create: "bg-emerald-500/15 text-emerald-800 dark:text-emerald-300",
  update: "bg-[color:color-mix(in_srgb,var(--cab-primary)_18%,transparent)] text-[color:var(--cab-primary)]",
  delete: "bg-red-500/15 text-red-800 dark:text-red-300",
  complete: "bg-sky-500/15 text-sky-800 dark:text-sky-300",
  archive: "bg-zinc-500/15 text-zinc-700 dark:text-zinc-300",
  reopen: "bg-indigo-500/15 text-indigo-800 dark:text-indigo-300",
  neutral: "bg-zinc-500/10 text-zinc-600 dark:text-zinc-400",
};

const TONE_DOT: Record<GestionaleLogEventTone, string> = {
  create: "bg-emerald-500",
  update: "bg-[color:var(--cab-primary)]",
  delete: "bg-red-500",
  complete: "bg-sky-500",
  archive: "bg-zinc-400",
  reopen: "bg-indigo-500",
  neutral: "bg-zinc-400",
};

export type LogEntryProps = {
  vm: GestionaleLogViewModel;
  onClick?: () => void;
  title?: string;
  trailing?: ReactNode;
  /** Card inbox notifiche — layout compatto senza dot laterale. */
  variant?: "default" | "inbox";
};

function resolveShellClass(variant: "default" | "inbox", interactive: boolean): string {
  if (variant === "inbox") {
    return `${LOG_ENTRY_INBOX_SHELL_CLASS}${interactive ? ` ${LOG_ENTRY_INBOX_SHELL_INTERACTIVE}` : ""}`;
  }
  return LOG_ENTRY_SHELL_CLASS;
}

function LogEntryBody({
  vm,
  trailing,
  variant = "default",
}: {
  vm: GestionaleLogViewModel;
  trailing?: ReactNode;
  variant?: "default" | "inbox";
}) {
  const voided = vm.annullato === true;
  const rawModifiche = parseModificheLines(vm.modificaRiga);
  let modifiche = filterAuditMetadataModifiche(rawModifiche);
  if (modifiche.length === 0 && rawModifiche.length > 0) {
    modifiche = ["Modifica registrata"];
  }
  const badge = TONE_BADGE[vm.tone];

  if (variant === "inbox") {
    return (
      <div className={`min-w-0 py-3 ${voided ? "opacity-65" : ""}`}>
        <div className="min-w-0 space-y-2">
          <span
            className={`inline-flex max-w-full items-center rounded-md px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${badge}`}
          >
            {vm.tipoRiga}
          </span>

          <p
            className={`text-sm font-semibold leading-snug text-[color:var(--cab-text)] ${voided ? "line-through" : ""}`}
          >
            {sanitizeLogOggettoRiga(vm.oggettoRiga)}
          </p>

          {modifiche.length > 0 ? (
            <p
              className={`text-xs leading-relaxed text-[color:var(--cab-text-muted)] line-clamp-3 ${voided ? "line-through" : ""}`}
            >
              {modifiche.map((l) => l.replace(/^•\s*/, "")).join(" · ")}
            </p>
          ) : null}

          <p className="border-t border-[color:color-mix(in_srgb,var(--cab-border)_70%,transparent)] pt-2 text-[11px] tabular-nums text-[color:var(--cab-text-muted)]">
            {formatGestionaleLogMetaLine(vm.autore, vm.atIso)}
          </p>
        </div>
      </div>
    );
  }

  return (
    <div className={`flex min-w-0 gap-3 py-3 ${voided ? "opacity-65" : ""}`}>
      <span className={`mt-2 h-2 w-2 shrink-0 rounded-full ${TONE_DOT[vm.tone]}`} aria-hidden />
      <div className="min-w-0 flex-1 space-y-2">
        <div className="flex flex-wrap items-start justify-between gap-2">
          <span
            className={`inline-flex max-w-full items-center rounded-md px-2 py-0.5 text-[10px] font-bold uppercase tracking-wide ${badge}`}
          >
            {vm.tipoRiga}
          </span>
          {trailing ? <div className="shrink-0">{trailing}</div> : null}
        </div>

        <p
          className={`text-sm font-semibold leading-snug text-[color:var(--cab-text)] ${voided ? "line-through" : ""}`}
        >
          {sanitizeLogOggettoRiga(vm.oggettoRiga)}
        </p>

        {modifiche.length > 0 ? (
          <ul className={`space-y-1 ${voided ? "line-through" : ""}`}>
            {modifiche.map((line, i) => (
              <li
                key={`${i}-${line.slice(0, 24)}`}
                className="text-sm leading-relaxed text-[color:var(--cab-text-muted)] before:mr-1.5 before:font-semibold before:text-[color:var(--cab-text)] before:content-['•']"
              >
                {line}
              </li>
            ))}
          </ul>
        ) : null}

        <p className="text-[11px] tabular-nums text-[color:var(--cab-text-muted)]">
          {formatGestionaleLogMetaLine(vm.autore, vm.atIso)}
        </p>
      </div>
    </div>
  );
}

function LogEntryInteractive({
  onClick,
  title,
  className = LOG_ENTRY_INTERACTIVE_CLASS,
  children,
}: {
  onClick: () => void;
  title?: string;
  className?: string;
  children: ReactNode;
}) {
  const interactive = (
    <div
      role="button"
      tabIndex={0}
      onClick={onClick}
      onKeyDown={(e) => logEntryActivate(onClick, e)}
      className={className}
    >
      {children}
    </div>
  );

  if (title?.trim()) {
    return <Tooltip content={title}>{interactive}</Tooltip>;
  }

  return interactive;
}

/** Voce log strutturata: tipo → oggetto → modifiche → meta. */
export const LogEntry = memo(function LogEntry({
  vm,
  onClick,
  title,
  trailing,
  variant = "default",
}: LogEntryProps) {
  const inbox = variant === "inbox";
  const shellClass = resolveShellClass(variant, Boolean(onClick));

  if (trailing) {
    const content = onClick ? (
      <LogEntryInteractive onClick={onClick} title={title} className={inbox ? `w-full ${erpFocus}` : undefined}>
        <LogEntryBody vm={vm} variant={variant} />
      </LogEntryInteractive>
    ) : (
      <LogEntryBody vm={vm} variant={variant} />
    );

    return (
      <div className={`${shellClass} group relative`}>
        <div className={inbox ? "pr-8" : "pr-7"}>{content}</div>
        <div className={`absolute z-[1] ${inbox ? "right-2 top-2" : "right-1.5 top-1.5"}`}>{trailing}</div>
      </div>
    );
  }

  if (onClick) {
    return (
      <LogEntryInteractive
        onClick={onClick}
        title={title}
        className={`${shellClass} ${inbox ? erpFocus : LOG_ENTRY_INTERACTIVE_CLASS}`}
      >
        <LogEntryBody vm={vm} variant={variant} />
      </LogEntryInteractive>
    );
  }

  return (
    <div className={shellClass}>
      <LogEntryBody vm={vm} variant={variant} />
    </div>
  );
});

/** @deprecated Usare `LogEntry`. */
export const LogEntryRenderer = LogEntry;

"use client";

import {
  cloneElement,
  isValidElement,
  useEffect,
  useRef,
  type FocusEvent,
  type MouseEvent,
  type PointerEvent,
  type ReactElement,
  type ReactNode,
  type TouchEvent,
} from "react";
import { createPortal } from "react-dom";
import { dsTooltipContent, dsTooltipContentMultiline, dsZTooltip } from "@/lib/ui/design-system";
import { tooltipFixedStyle, tooltipTransformOrigin, type TooltipSide } from "@/lib/ui/tooltip-portal";
import { useTooltip } from "@/components/design-system/use-tooltip";

/** Prima lettera maiuscola per etichette tooltip (accessibilità e UI coerente). */
function tooltipDisplayContent(content: string): string {
  const trimmed = content.trim();
  if (!trimmed) return trimmed;
  const first = trimmed.charAt(0);
  if (first >= "a" && first <= "z") {
    return first.toLocaleUpperCase("it-IT") + trimmed.slice(1);
  }
  return trimmed;
}

export type TooltipProps = {
  /** Testo breve (1–3 parole). */
  content?: string;
  children: ReactElement;
  side?: TooltipSide;
  disabled?: boolean;
  delayMs?: number;
  /** Default `true`. Impostare `false` su controlli che restano focalizzati dopo il click (es. toggle tema). */
  showOnFocus?: boolean;
  /** Default `true`. Impostare `false` su handle drag (mousedown avvia il trascinamento). */
  dismissOnPointerDown?: boolean;
  /** Supporta `\n` nel contenuto (es. tooltip celle timesheet). */
  multiline?: boolean;
};

function mergeRefs<T>(...refs: Array<React.Ref<T> | undefined>): (node: T | null) => void {
  return (node) => {
    for (const ref of refs) {
      if (!ref) continue;
      if (typeof ref === "function") ref(node);
      else (ref as React.MutableRefObject<T | null>).current = node;
    }
  };
}

function mergeHandler<E>(
  ours: ((e: E) => void) | undefined,
  theirs: ((e: E) => void) | undefined,
): ((e: E) => void) | undefined {
  if (!ours) return theirs;
  if (!theirs) return ours;
  return (e) => {
    ours(e);
    theirs(e);
  };
}

export function Tooltip({
  content,
  children,
  side = "top",
  disabled = false,
  delayMs,
  showOnFocus = true,
  dismissOnPointerDown = true,
  multiline = false,
}: TooltipProps) {
  const anchorRef = useRef<HTMLElement | null>(null);
  const contentRef = useRef<HTMLDivElement | null>(null);
  const displayContent = multiline
    ? content?.trim() || content
    : content?.trim()
      ? tooltipDisplayContent(content)
      : content;
  const { open, visible, coords, triggerProps, hideImmediate } = useTooltip({
    content: displayContent,
    disabled,
    delayMs,
    side,
    showOnFocus,
    dismissOnPointerDown,
    anchorRef,
    contentRef,
  });

  useEffect(() => () => hideImmediate(), [hideImmediate]);

  if (!isValidElement(children)) {
    return children as ReactNode;
  }

  const child = children as ReactElement<Record<string, unknown>>;
  const childProps = child.props as Record<string, unknown>;
  const childRef = childProps.ref as React.Ref<HTMLElement> | undefined;

  const trigger = cloneElement(child, {
    ref: mergeRefs(childRef, anchorRef),
    title: undefined,
    onMouseEnter: mergeHandler(triggerProps.onMouseEnter, childProps.onMouseEnter as ((e: MouseEvent<HTMLElement>) => void) | undefined),
    onMouseLeave: mergeHandler(triggerProps.onMouseLeave, childProps.onMouseLeave as ((e: MouseEvent<HTMLElement>) => void) | undefined),
    onFocus: mergeHandler(triggerProps.onFocus, childProps.onFocus as ((e: FocusEvent<HTMLElement>) => void) | undefined),
    onBlur: mergeHandler(triggerProps.onBlur, childProps.onBlur as ((e: FocusEvent<HTMLElement>) => void) | undefined),
    onPointerDown: mergeHandler(
      triggerProps.onPointerDown,
      childProps.onPointerDown as ((e: PointerEvent<HTMLElement>) => void) | undefined,
    ),
    onPointerUp: mergeHandler(
      triggerProps.onPointerUp,
      childProps.onPointerUp as ((e: PointerEvent<HTMLElement>) => void) | undefined,
    ),
    onPointerCancel: mergeHandler(
      triggerProps.onPointerCancel,
      childProps.onPointerCancel as ((e: PointerEvent<HTMLElement>) => void) | undefined,
    ),
    onTouchStart: mergeHandler(triggerProps.onTouchStart, childProps.onTouchStart as ((e: TouchEvent<HTMLElement>) => void) | undefined),
    onTouchEnd: mergeHandler(triggerProps.onTouchEnd, childProps.onTouchEnd as ((e: TouchEvent<HTMLElement>) => void) | undefined),
    onTouchCancel: mergeHandler(triggerProps.onTouchCancel, childProps.onTouchCancel as ((e: TouchEvent<HTMLElement>) => void) | undefined),
    onTouchMove: mergeHandler(triggerProps.onTouchMove, childProps.onTouchMove as ((e: TouchEvent<HTMLElement>) => void) | undefined),
  });

  const panel =
    open && displayContent?.trim() && typeof document !== "undefined"
      ? createPortal(
          <div
            ref={contentRef}
            role="tooltip"
            className={`${multiline ? dsTooltipContentMultiline : dsTooltipContent} ${dsZTooltip} ${visible ? "scale-100 opacity-100" : "scale-95 opacity-0"}`}
            style={{
              ...tooltipFixedStyle(coords ?? { top: -9999, left: -9999, side }),
              transformOrigin: tooltipTransformOrigin(coords?.side ?? side),
              backgroundColor: "var(--cab-card)",
            }}
          >
            {displayContent}
          </div>,
          document.body,
        )
      : null;

  return (
    <>
      {trigger}
      {panel}
    </>
  );
}

"use client";

import {
  useCallback,
  useEffect,
  useLayoutEffect,
  useRef,
  useState,
  type FocusEvent,
  type MouseEvent,
  type PointerEvent,
  type RefObject,
  type TouchEvent,
} from "react";
import {
  computeTooltipCoords,
  type TooltipCoords,
  type TooltipSide,
} from "@/lib/ui/tooltip-portal";

const DEFAULT_SHOW_DELAY_MS = 150;
const HIDE_DELAY_MS = 100;
const TOUCH_HOLD_MS = 400;
/** Dopo un tap touch, ignora mouseenter sintetici (ghost events). */
const TOUCH_GHOST_MOUSE_MS = 500;

function isCoarsePointerDevice(): boolean {
  if (typeof window === "undefined" || typeof window.matchMedia !== "function") return false;
  return window.matchMedia("(hover: none), (pointer: coarse)").matches;
}

export function useTooltip({
  content,
  disabled = false,
  delayMs = DEFAULT_SHOW_DELAY_MS,
  side = "top",
  showOnFocus = true,
  dismissOnPointerDown = true,
  anchorRef,
  contentRef,
}: {
  content?: string;
  disabled?: boolean;
  delayMs?: number;
  side?: TooltipSide;
  /** Tooltip su focus tastiera (`:focus-visible`). Disabilitare per azioni che restano focalizzate al click. */
  showOnFocus?: boolean;
  /** Default `true`. Impostare `false` su handle drag (mousedown avvia il drag, non un click). */
  dismissOnPointerDown?: boolean;
  anchorRef: RefObject<HTMLElement | null>;
  contentRef: RefObject<HTMLElement | null>;
}): {
  open: boolean;
  visible: boolean;
  coords: TooltipCoords | null;
  hideImmediate: () => void;
  triggerProps: {
    onMouseEnter: (e: MouseEvent<HTMLElement>) => void;
    onMouseLeave: (e: MouseEvent<HTMLElement>) => void;
    onFocus: (e: FocusEvent<HTMLElement>) => void;
    onBlur: (e: FocusEvent<HTMLElement>) => void;
    onPointerDown: (e: PointerEvent<HTMLElement>) => void;
    onPointerUp: (e: PointerEvent<HTMLElement>) => void;
    onPointerCancel: (e: PointerEvent<HTMLElement>) => void;
    onTouchStart: (e: TouchEvent<HTMLElement>) => void;
    onTouchEnd: (e: TouchEvent<HTMLElement>) => void;
    onTouchCancel: (e: TouchEvent<HTMLElement>) => void;
    onTouchMove: (e: TouchEvent<HTMLElement>) => void;
  };
} {
  const [open, setOpen] = useState(false);
  const [visible, setVisible] = useState(false);
  const [coords, setCoords] = useState<TooltipCoords | null>(null);
  const showTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const hideTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const touchTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const touchGhostTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);
  const activeRef = useRef(false);
  const pointerActivatedRef = useRef(false);
  const touchGhostRef = useRef(false);
  const coarsePointerRef = useRef(false);

  const canShow = Boolean(content?.trim()) && !disabled;

  const clearShowTimer = useCallback(() => {
    if (showTimerRef.current) {
      clearTimeout(showTimerRef.current);
      showTimerRef.current = null;
    }
  }, []);

  const clearHideTimer = useCallback(() => {
    if (hideTimerRef.current) {
      clearTimeout(hideTimerRef.current);
      hideTimerRef.current = null;
    }
  }, []);

  const clearTouchTimer = useCallback(() => {
    if (touchTimerRef.current) {
      clearTimeout(touchTimerRef.current);
      touchTimerRef.current = null;
    }
  }, []);

  const clearTouchGhostTimer = useCallback(() => {
    if (touchGhostTimerRef.current) {
      clearTimeout(touchGhostTimerRef.current);
      touchGhostTimerRef.current = null;
    }
  }, []);

  const armTouchGhostMouseGuard = useCallback(() => {
    touchGhostRef.current = true;
    clearTouchGhostTimer();
    touchGhostTimerRef.current = setTimeout(() => {
      touchGhostRef.current = false;
      touchGhostTimerRef.current = null;
    }, TOUCH_GHOST_MOUSE_MS);
  }, [clearTouchGhostTimer]);

  const updateCoords = useCallback(() => {
    const anchor = anchorRef.current;
    const panel = contentRef.current;
    if (!anchor || !panel) return;
    setCoords(computeTooltipCoords(anchor, panel, side));
  }, [anchorRef, contentRef, side]);

  const scheduleHide = useCallback(() => {
    clearHideTimer();
    hideTimerRef.current = setTimeout(() => {
      setVisible(false);
      hideTimerRef.current = setTimeout(() => {
        setOpen(false);
        setCoords(null);
      }, HIDE_DELAY_MS);
    }, 0);
  }, [clearHideTimer]);

  const show = useCallback(() => {
    if (!canShow) return;
    activeRef.current = true;
    clearHideTimer();
    clearShowTimer();
    showTimerRef.current = setTimeout(() => {
      if (!activeRef.current) return;
      setOpen(true);
      requestAnimationFrame(() => setVisible(true));
    }, delayMs);
  }, [canShow, clearHideTimer, clearShowTimer, delayMs]);

  const hide = useCallback(() => {
    activeRef.current = false;
    clearShowTimer();
    clearTouchTimer();
    scheduleHide();
  }, [clearShowTimer, clearTouchTimer, scheduleHide]);

  const hideImmediate = useCallback(() => {
    activeRef.current = false;
    clearShowTimer();
    clearTouchTimer();
    clearHideTimer();
    setVisible(false);
    setOpen(false);
    setCoords(null);
  }, [clearShowTimer, clearTouchTimer, clearHideTimer]);

  useEffect(() => {
    coarsePointerRef.current = isCoarsePointerDevice();
    if (typeof window === "undefined" || typeof window.matchMedia !== "function") return;
    const mq = window.matchMedia("(hover: none), (pointer: coarse)");
    const onChange = () => {
      coarsePointerRef.current = mq.matches;
      if (mq.matches) hideImmediate();
    };
    mq.addEventListener?.("change", onChange);
    return () => {
      mq.removeEventListener?.("change", onChange);
    };
  }, [hideImmediate]);

  useLayoutEffect(() => {
    if (!open) return;
    updateCoords();
  }, [open, visible, content, updateCoords]);

  useEffect(() => {
    if (!open) return;
    const onReposition = () => updateCoords();
    window.addEventListener("resize", onReposition);
    window.addEventListener("scroll", onReposition, true);
    return () => {
      window.removeEventListener("resize", onReposition);
      window.removeEventListener("scroll", onReposition, true);
    };
  }, [open, updateCoords]);

  useEffect(() => {
    return () => {
      clearShowTimer();
      clearHideTimer();
      clearTouchTimer();
      clearTouchGhostTimer();
    };
  }, [clearShowTimer, clearHideTimer, clearTouchTimer, clearTouchGhostTimer]);

  const onMouseEnter = useCallback(
    (_e: MouseEvent<HTMLElement>) => {
      if (coarsePointerRef.current) return;
      if (touchGhostRef.current) return;
      show();
    },
    [show],
  );

  const onMouseLeave = useCallback(
    (_e: MouseEvent<HTMLElement>) => {
      if (coarsePointerRef.current) return;
      pointerActivatedRef.current = false;
      hide();
    },
    [hide],
  );

  const onFocus = useCallback(
    (e: FocusEvent<HTMLElement>) => {
      if (!showOnFocus || pointerActivatedRef.current) return;
      if (e.target instanceof HTMLElement && e.target.matches(":focus-visible")) {
        show();
      }
    },
    [show, showOnFocus],
  );

  const onBlur = useCallback(
    (_e: FocusEvent<HTMLElement>) => {
      pointerActivatedRef.current = false;
      hide();
    },
    [hide],
  );

  const onPointerDown = useCallback(
    (e: PointerEvent<HTMLElement>) => {
      if (e.pointerType === "mouse" || e.pointerType === "touch" || e.pointerType === "pen") {
        pointerActivatedRef.current = true;
      }
      if (dismissOnPointerDown) hideImmediate();
    },
    [dismissOnPointerDown, hideImmediate],
  );

  const onPointerUp = useCallback(() => {
    // Il flag pointer resta fino a mouse leave / blur per non riaprire su :focus-visible da click.
  }, []);

  const onPointerCancel = useCallback(() => {
    pointerActivatedRef.current = false;
    hideImmediate();
  }, [hideImmediate]);

  const onTouchStart = useCallback(
    (_e: TouchEvent<HTMLElement>) => {
      if (!canShow) return;
      clearTouchTimer();
      touchTimerRef.current = setTimeout(() => {
        show();
      }, TOUCH_HOLD_MS);
    },
    [canShow, clearTouchTimer, show],
  );

  const onTouchEnd = useCallback(
    (_e: TouchEvent<HTMLElement>) => {
      clearTouchTimer();
      armTouchGhostMouseGuard();
      hide();
    },
    [armTouchGhostMouseGuard, clearTouchTimer, hide],
  );

  const onTouchCancel = useCallback(
    (_e: TouchEvent<HTMLElement>) => {
      clearTouchTimer();
      armTouchGhostMouseGuard();
      hide();
    },
    [armTouchGhostMouseGuard, clearTouchTimer, hide],
  );

  const onTouchMove = useCallback(
    (_e: TouchEvent<HTMLElement>) => {
      clearTouchTimer();
    },
    [clearTouchTimer],
  );

  return {
    open,
    visible,
    coords,
    hideImmediate,
    triggerProps: {
      onMouseEnter,
      onMouseLeave,
      onFocus,
      onBlur,
      onPointerDown,
      onPointerUp,
      onPointerCancel,
      onTouchStart,
      onTouchEnd,
      onTouchCancel,
      onTouchMove,
    },
  };
}

"use client";

import { useCallback, useState } from "react";
import { dsBtnNeutral, dsBtnPrimary } from "@/lib/ui/design-system";

export function CaptureDryRunSummary(props: {
  captureId: string;
  applicationId: string | null;
  captureStatus?: string;
}) {
  const [message, setMessage] = useState<string | null>(null);
  const [busy, setBusy] = useState(false);

  const apply = useCallback(async () => {
    if (!props.applicationId || busy) return;
    setBusy(true);
    setMessage(null);
    try {
      const res = await fetch(`/api/document-capture/${props.captureId}/apply`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ applicationId: props.applicationId }),
      });
      const body = (await res.json().catch(() => ({}))) as { error?: string; code?: string; lavorazioneId?: string };
      if (res.status === 409 && body.code === "PLAN_STALE") {
        setMessage("Piano obsoleto — ripetere dry-run.");
        return;
      }
      if (res.status === 409 && body.code === "APPLY_IN_PROGRESS") {
        setMessage("Apply già in corso — attendere.");
        return;
      }
      if (!res.ok) {
        setMessage(body.error ?? "Apply fallito");
        return;
      }
      setMessage(`Apply completato. Lavorazione: ${body.lavorazioneId ?? "—"}`);
    } finally {
      setBusy(false);
    }
  }, [busy, props.applicationId, props.captureId]);

  const resume = useCallback(async () => {
    if (!props.applicationId || busy) return;
    setBusy(true);
    setMessage(null);
    try {
      const res = await fetch(`/api/document-capture/${props.captureId}/resume`, {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ applicationId: props.applicationId }),
      });
      const body = (await res.json().catch(() => ({}))) as { error?: string; lavorazioneId?: string };
      if (!res.ok) {
        setMessage(body.error ?? "Resume fallito");
        return;
      }
      setMessage(`Resume completato. Lavorazione: ${body.lavorazioneId ?? "—"}`);
    } finally {
      setBusy(false);
    }
  }, [busy, props.applicationId, props.captureId]);

  const canResume = props.captureStatus === "failed";

  return (
    <div className="space-y-3 text-sm">
      <p>Riepilogo dry-run pronto. Conferma apply gestionale.</p>
      <div className="flex flex-wrap gap-2">
        <button type="button" className={dsBtnPrimary} disabled={!props.applicationId || busy} onClick={() => void apply()}>
          {busy ? "Apply…" : "Applica"}
        </button>
        {canResume ? (
          <button type="button" className={dsBtnNeutral} disabled={!props.applicationId || busy} onClick={() => void resume()}>
            Riprendi apply fallito
          </button>
        ) : null}
      </div>
      {message ? <p>{message}</p> : null}
    </div>
  );
}

