"use client";

import Link from "next/link";
import { usePathname } from "next/navigation";
import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState, type MouseEvent as ReactMouseEvent, type ReactNode } from "react";
import { CloseButton } from "@/components/design-system";
import { useAuth } from "@/context/auth-context";
import { useGlobalLoading } from "@/context/global-loading-context";
import { GLOBAL_LOADING_MESSAGES } from "@/lib/ui/global-loading-messages";
import { erpFocus } from "@/lib/ui/erp-tokens";
import { resolveGestionaleNav, type GestionaleNavResolvedItem } from "@/components/gestionale/gestionale-nav-config";
import { CLIENTE_HOME_PATH, isClienteRole } from "@/lib/auth/rbac";
import { useRbac } from "@/src/hooks/use-rbac";
import { useRbacNavAccess } from "@/src/hooks/use-rbac-nav-access";
import { SidebarNavSkeleton } from "@/components/gestionale/sidebar-nav-skeleton";
import { CabLogo, CAB_APP_PRODUCT_NAME } from "@/components/gestionale/cab-logo";
import { SidebarSessionPanel } from "@/components/gestionale/sidebar-session-panel";
import { SidebarNavRow } from "@/components/gestionale/sidebar-nav-row";
import {
  sidebarAsideWidthCollapsedClass,
  sidebarAsideWidthExpandedClass,
  sidebarNavCountBadgeClass,
} from "@/lib/ui/sidebar-layout";
import { ProfileSheetProvider } from "@/components/profile/profile-sheet-context";
import {
  dsGestionaleContentMax,
  dsGestionaleContentRail,
  dsZModalHigh,
} from "@/lib/ui/design-system";
import { layoutPageRoot, layoutResponsiveCoreScope } from "@/lib/ui/responsive-layout-core";
import { gestionaleShellContentGutterClass } from "@/lib/ui/gestionale-shell-layout";
import { useGestionaleShellLayoutSync } from "@/lib/ui/use-gestionale-shell-layout-sync";
import { GestionaleShellLayoutProvider } from "@/context/gestionale-shell-layout-context";
import dynamic from "next/dynamic";

const DevAuditMounts = dynamic(
  () => import("@/components/gestionale/dev-audit-mounts").then((m) => m.DevAuditMounts),
  { ssr: false },
);
const ReactRenderAuditProfiler = dynamic(
  () =>
    import("@/components/gestionale/react-render-audit-profiler").then((m) => m.ReactRenderAuditProfiler),
  { ssr: false },
);
import {
  isNavTargetCurrent,
  isSidebarNavLinkCurrent,
  ROUTE_LOADING_FAILSAFE_MS,
  ROUTE_TRANSITION_CANCEL_EVENT,
  scheduleRouteTransitionBegin,
} from "@/src/lib/navigation/route-transition";
import { useGestionaleMainScrollLock } from "@/lib/ui/use-body-scroll-lock";
import { useGestionaleScrollEnd } from "@/lib/ui/use-gestionale-scroll-end";
import { dsGestionaleScrollEndPadFade } from "@/lib/ui/scroll-system";
import { useOverlayBackHandler } from "@/lib/ui/use-overlay-back-handler";
import { healBodyScrollLockState } from "@/lib/ui/body-scroll-lock-manager";
import { cabAppViewportFillClass } from "@/lib/ui/viewport-fill-sync";
import { useSidebarHoverExpand } from "@/lib/ui/use-sidebar-collapsed";
import { recordHealthMetric } from "@/lib/observability/runtime-health";
import { isBootInvestigationEnabled, logBoot, trackRedirect, trackStoreUpdate } from "@/lib/observability/boot-investigation";
import { useBootInvestigationMount } from "@/lib/observability/use-boot-investigation-mount";
import { resolveDrawerAsideClasses } from "@/lib/ui/modal-max-width-class";

const mobileNavOpenBtnClass = `inline-flex min-h-11 min-w-11 shrink-0 items-center justify-center rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] text-lg shadow-[var(--cab-shadow-sm)] hover:bg-[var(--cab-hover)] dark:border-[color:var(--cab-border-strong)] ${erpFocus}`;

const shellTopBarClass =
  "flex h-14 shrink-0 items-center border-b border-[color:var(--cab-border)]";

function NavLink({
  href,
  label,
  Icon,
  collapsed,
  disabled,
  badge,
  onNavigate,
  onExpandIntent,
  onActiveNavClick,
}: {
  href: string;
  label: string;
  Icon: (p: { className?: string }) => ReactNode;
  collapsed: boolean;
  disabled?: boolean;
  badge?: string | null;
  onNavigate?: (href: string) => void;
  onExpandIntent?: () => void;
  onActiveNavClick?: () => void;
}) {
  const pathname = usePathname();
  const active = isNavTargetCurrent(pathname, href);

  const navPointerIntentProps = collapsed && !active
    ? {
        onPointerEnter: () => onExpandIntent?.(),
        onFocus: () => onExpandIntent?.(),
      }
    : {};

  const suppressActiveRailFocus = collapsed && active && !disabled;

  const trailing = badge ? (
    <span className={`${sidebarNavCountBadgeClass}`}>{badge}</span>
  ) : undefined;

  const sharedProps = {
    active,
    collapsed,
    icon: <Icon className="h-4 w-4" />,
    label,
    trailing,
    ...navPointerIntentProps,
  };

  const row = disabled ? (
    <SidebarNavRow
      as="div"
      disabled
      active={active}
      collapsed={collapsed}
      icon={sharedProps.icon}
      label={label}
      trailing={trailing}
      railTooltip={badge ? "Non disponibile" : label}
      {...navPointerIntentProps}
    />
  ) : (
    <SidebarNavRow
      as="link"
      href={href}
      active={active}
      collapsed={collapsed}
      icon={sharedProps.icon}
      label={label}
      trailing={trailing}
      railTooltip={label}
      onMouseDown={(e: ReactMouseEvent<HTMLAnchorElement>) => {
        if (suppressActiveRailFocus) e.preventDefault();
      }}
      onClick={(e: ReactMouseEvent<HTMLAnchorElement>) => {
        if (isNavTargetCurrent(pathname, href)) {
          e.preventDefault();
          onActiveNavClick?.();
          return;
        }
        scheduleRouteTransitionBegin(e, () => onNavigate?.(href));
      }}
      {...navPointerIntentProps}
    />
  );

  return row;
}

function MobileNavRow({
  item,
  pathname,
  onClose,
  onNavigate,
}: {
  item: GestionaleNavResolvedItem;
  pathname: string;
  onClose: () => void;
  onNavigate?: (href: string) => void;
}) {
  const active = isNavTargetCurrent(pathname, item.href);
  const Icon = item.Icon;
  if (item.disabled) {
    return (
      <div
        className={`flex min-h-[3.25rem] items-center gap-3 rounded-xl px-3 text-base font-semibold text-zinc-400 dark:text-zinc-500 ${
          active ? "bg-zinc-100/80 dark:bg-zinc-800/50" : ""
        }`}
        aria-disabled
      >
        <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-lg bg-zinc-100 text-zinc-500 dark:bg-zinc-800 dark:text-zinc-400">
          <Icon className="h-5 w-5" />
        </span>
        <span className="min-w-0 flex-1 truncate">{item.label}</span>
        {item.badge ? (
          <span className="shrink-0 rounded bg-zinc-200 px-1.5 py-0.5 text-[9px] font-bold uppercase tracking-wide text-zinc-600 dark:bg-zinc-700 dark:text-zinc-200">
            {item.badge}
          </span>
        ) : null}
      </div>
    );
  }
  return (
    <Link
      href={item.href}
      onClick={(e) => {
        if (isNavTargetCurrent(pathname, item.href)) return;
        scheduleRouteTransitionBegin(e, () => {
          onNavigate?.(item.href);
          onClose();
        });
      }}
      className={`flex min-h-[3.25rem] items-center gap-3 rounded-xl px-3 text-base font-semibold ${
        active
          ? "bg-[color:color-mix(in_srgb,var(--cab-primary)_16%,var(--cab-card))] text-[color:color-mix(in_srgb,var(--cab-primary)_8%,var(--cab-text))] shadow-[inset_0_0_0_1px_color-mix(in_srgb,var(--cab-primary)_28%,transparent)] dark:text-white"
          : "text-zinc-800 hover:bg-zinc-100 dark:text-zinc-100 dark:hover:bg-zinc-800"
      } ${erpFocus}`}
    >
      <span
        className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-lg ${
          active
            ? "bg-[color:color-mix(in_srgb,var(--cab-primary)_28%,var(--cab-card))] text-[color:var(--cab-primary)]"
            : "bg-zinc-100 text-zinc-600 dark:bg-zinc-800 dark:text-zinc-300"
        }`}
        aria-hidden
      >
        <Icon className="h-5 w-5" />
      </span>
      <span className="min-w-0 flex-1 truncate">{item.label}</span>
    </Link>
  );
}

const NAV_DRAWER_MS = 240;

function navDrawerAnimMs(): number {
  if (typeof window === "undefined") return NAV_DRAWER_MS;
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches ? 1 : NAV_DRAWER_MS;
}

function MobileNavDrawer({
  open,
  onClose,
  navItems,
  onNavigate,
  isCompactShell,
  isNavLoading,
}: {
  open: boolean;
  onClose: () => void;
  navItems: GestionaleNavResolvedItem[];
  onNavigate?: (href: string) => void;
  isCompactShell: boolean;
  isNavLoading: boolean;
}) {
  const pathname = usePathname();
  const [mounted, setMounted] = useState(false);
  const [closing, setClosing] = useState(false);
  const panelState = closing ? "closing" : "open";

  useEffect(() => {
    if (open) {
      setMounted(true);
      setClosing(false);
    }
  }, [open]);

  useEffect(() => {
    if (!mounted || open) return;
    setClosing(true);
    const id = window.setTimeout(() => {
      setMounted(false);
      setClosing(false);
    }, navDrawerAnimMs());
    return () => window.clearTimeout(id);
  }, [mounted, open]);

  useGestionaleMainScrollLock(mounted, "MobileNavDrawer");
  useOverlayBackHandler(mounted && open && !closing, onClose, "MobileNavDrawer");

  useEffect(() => {
    if (isCompactShell) return;
    setClosing(false);
    setMounted(false);
    onClose();
  }, [isCompactShell, onClose]);

  useEffect(() => {
    if (!mounted || closing || !open) return;
    function onKey(e: KeyboardEvent) {
      if (e.key !== "Escape") return;
      const target = e.target;
      if (target instanceof HTMLElement) {
        const tag = target.tagName;
        if (tag === "INPUT" || tag === "TEXTAREA" || tag === "SELECT" || target.isContentEditable) return;
      }
      onClose();
    }
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [mounted, closing, open, onClose]);

  if (!mounted || !isCompactShell) return null;

  return (
    <div className={`fixed inset-0 ${dsZModalHigh} overscroll-none`} role="presentation">
      <button
        type="button"
        className="cab-nav-drawer-backdrop absolute inset-0 touch-none bg-black/50 backdrop-blur-[1px] touch-manipulation"
        data-state={panelState}
        aria-label="Chiudi menu"
        onClick={onClose}
      />
      <div
        className={`cab-nav-drawer-panel ${resolveDrawerAsideClasses("drawerNav")}`}
        data-state={panelState}
        role="dialog"
        aria-modal="true"
        aria-label="Menu principale"
        onMouseDown={(e) => e.stopPropagation()}
      >
        <div className={`${shellTopBarClass} shrink-0 grid grid-cols-[1fr_auto_1fr] items-center px-4`}>
          <span className="min-w-0" aria-hidden />
          <CabLogo height={32} className="shrink-0" sizes="112px" priority />
          <div className="flex min-w-0 items-center justify-end">
            <CloseButton onClick={onClose} />
          </div>
        </div>
        <SidebarSessionPanel variant="drawer" placement="brand" onOpenInbox={onClose} />
        <nav
          className="cab-sidebar-nav gestionale-scrollbar flex min-h-0 min-w-0 flex-1 flex-col p-3 pb-0"
          aria-label="Sezioni principali"
        >
          <div className="gestionale-scrollbar flex min-h-0 min-w-0 flex-1 flex-col gap-1 overflow-y-auto overflow-x-hidden overscroll-contain touch-pan-y [-webkit-overflow-scrolling:touch]">
            {isNavLoading ? (
              <SidebarNavSkeleton />
            ) : (
              navItems.map((item) => (
                <MobileNavRow key={item.href} item={item} pathname={pathname} onClose={onClose} onNavigate={onNavigate} />
              ))
            )}
          </div>
        </nav>
      </div>
    </div>
  );
}

export function AppShell({ children }: { children: React.ReactNode }) {
  useBootInvestigationMount("AppShell");
  const [mobileOpen, setMobileOpen] = useState(false);
  const shellRef = useRef<HTMLDivElement>(null);
  const sidebarAsideRef = useRef<HTMLElement>(null);
  const shellColRef = useRef<HTMLDivElement>(null);
  const mainScrollRef = useRef<HTMLElement | null>(null);
  const shellLayout = useGestionaleShellLayoutSync({
    shellRef,
    shellColRef,
    mainRef: mainScrollRef,
  });
  const { isCompactShell, tier: shellTier, contentWidth: shellContentWidth } = shellLayout;
  const showMobileNavOpen = isCompactShell && shellContentWidth > 0;
  const contentGutter = gestionaleShellContentGutterClass(shellTier);
  useGestionaleScrollEnd(mainScrollRef);
  const {
    collapsed,
    sidebarExpanded,
    collapseSidebar,
    onSidebarMouseEnter,
    onSidebarMouseLeave,
    onSidebarNavIntent,
    onSidebarFocusCapture,
    onSidebarBlurCapture,
  } = useSidebarHoverExpand();
  const [routeLoading, setRouteLoading] = useState(false);
  const routeTransitionStartRef = useRef<number | null>(null);
  const { user } = useAuth();
  const pathname = usePathname();
  const suppressGlobalScrollEndPad = pathname.startsWith("/impostazioni");
  const rbac = useRbac();
  const { navAccess, isNavLoading } = useRbacNavAccess();
  const clienteOnly = isClienteRole(user);
  const homePath = clienteOnly ? CLIENTE_HOME_PATH : "/dashboard";
  useGlobalLoading(routeLoading ? GLOBAL_LOADING_MESSAGES.navigation : null);

  const prevRouteLoadingRef = useRef(false);
  useEffect(() => {
    if (!isBootInvestigationEnabled()) return;
    if (prevRouteLoadingRef.current === routeLoading) return;
    trackStoreUpdate("routeLoading", prevRouteLoadingRef.current, routeLoading, { pathname });
    logBoot("RENDER", "AppShell", { routeLoading, pathname }, routeLoading ? "route_loading_on" : "route_loading_off");
    prevRouteLoadingRef.current = routeLoading;
  }, [routeLoading, pathname]);

  useLayoutEffect(() => {
    healBodyScrollLockState("app-shell-mount");
  }, []);

  const navItems = useMemo(() => {
    if (!navAccess) return [] as GestionaleNavResolvedItem[];
    return resolveGestionaleNav({
      hideHref: (href) => navAccess.shouldHideHref(href),
    });
  }, [navAccess]);

  useEffect(() => {
    if (routeTransitionStartRef.current != null) {
      const durationMs = Math.round(performance.now() - routeTransitionStartRef.current);
      recordHealthMetric("routeTransitionMs", durationMs);
      routeTransitionStartRef.current = null;
    }
    setRouteLoading(false);
    setMobileOpen(false);
    collapseSidebar();
  }, [pathname, collapseSidebar]);

  useEffect(() => {
    if (!routeLoading) return;
    const timeoutId = window.setTimeout(() => setRouteLoading(false), ROUTE_LOADING_FAILSAFE_MS);
    return () => window.clearTimeout(timeoutId);
  }, [routeLoading]);

  useEffect(() => {
    function onCancelRouteTransition() {
      setRouteLoading(false);
    }
    function onPopState() {
      setRouteLoading(false);
    }
    function onPageShow() {
      setRouteLoading(false);
    }
    function onVisibilityChange() {
      if (document.visibilityState === "visible") setRouteLoading(false);
    }
    window.addEventListener(ROUTE_TRANSITION_CANCEL_EVENT, onCancelRouteTransition);
    window.addEventListener("popstate", onPopState);
    window.addEventListener("pageshow", onPageShow);
    document.addEventListener("visibilitychange", onVisibilityChange);
    return () => {
      window.removeEventListener(ROUTE_TRANSITION_CANCEL_EVENT, onCancelRouteTransition);
      window.removeEventListener("popstate", onPopState);
      window.removeEventListener("pageshow", onPageShow);
      document.removeEventListener("visibilitychange", onVisibilityChange);
    };
  }, []);

  const beginRouteTransition = useCallback(
    (href: string) => {
      if (isNavTargetCurrent(pathname, href)) {
        setRouteLoading(false);
        return;
      }
      collapseSidebar();
      routeTransitionStartRef.current = performance.now();
      setRouteLoading(true);
    },
    [pathname, collapseSidebar],
  );

  const onHeaderHomeClick = useCallback(
    (e: ReactMouseEvent<HTMLAnchorElement>) => {
      if (pathname === homePath) {
        e.preventDefault();
        setRouteLoading(false);
        collapseSidebar();
        (e.currentTarget as HTMLElement).blur();
        window.scrollTo({ top: 0, behavior: "smooth" });
        return;
      }
      scheduleRouteTransitionBegin(e, () => beginRouteTransition(homePath));
    },
    [beginRouteTransition, collapseSidebar, pathname, homePath],
  );

  const asideWidthClass = sidebarExpanded ? sidebarAsideWidthExpandedClass : sidebarAsideWidthCollapsedClass;
  const asideW = sidebarExpanded ? `${asideWidthClass} z-50` : asideWidthClass;
  const mainPad = isCompactShell ? "" : "pl-[4.25rem]";
  const sidebarTopOffset =
    "top-0 supports-[padding:max(0px)]:pt-[env(safe-area-inset-top)]";

  return (
    <GestionaleShellLayoutProvider value={shellLayout}>
    <ProfileSheetProvider>
    <div
      ref={shellRef}
      className={`cab-app-shell flex min-h-0 flex-col ${cabAppViewportFillClass} max-w-full overflow-hidden bg-[var(--cab-bg-app)] text-[color:var(--cab-text)]`}
    >
      {showMobileNavOpen ? (
          <button
            type="button"
            data-testid="smoke-nav-drawer-open"
            className={`cab-mobile-nav-open fixed left-3 top-[max(0.75rem,env(safe-area-inset-top))] z-30 ${mobileNavOpenBtnClass}`}
            aria-label="Apri menu"
            onClick={() => setMobileOpen(true)}
          >
            ☰
          </button>
      ) : null}

      <aside
        ref={sidebarAsideRef}
        data-sidebar-collapsed={collapsed ? "" : undefined}
        data-sidebar-hover-expanded={sidebarExpanded ? "" : undefined}
        onMouseEnter={onSidebarMouseEnter}
        onMouseLeave={onSidebarMouseLeave}
        onFocusCapture={(event) => {
          if (isSidebarNavLinkCurrent(event.target, pathname)) return;
          onSidebarFocusCapture();
        }}
        onBlurCapture={onSidebarBlurCapture}
        className={`cab-sidebar fixed bottom-0 left-0 z-40 flex-col overflow-x-hidden border-r border-[color:var(--cab-border)] bg-[var(--cab-card)] transition-[width,box-shadow] duration-[var(--cab-sidebar-width-motion)] ease-[var(--cab-sidebar-ease-out)] ${sidebarTopOffset} ${
          isCompactShell ? "hidden" : `flex ${asideW}`
        }`}
      >
        <div className="cab-sidebar-brand shrink-0">
          <Link
            href={homePath}
            onClick={onHeaderHomeClick}
            aria-label={CAB_APP_PRODUCT_NAME}
            className={`${erpFocus} flex w-full min-h-10 min-w-0 items-center justify-center overflow-hidden rounded-lg transition-opacity duration-200 hover:opacity-90`}
          >
            <CabLogo height={28} className="shrink-0" sizes="112px" priority />
          </Link>
        </div>
        {!isCompactShell ? (
          <SidebarSessionPanel
            variant="sidebar"
            placement="brand"
            sidebarCollapsed={collapsed && !sidebarExpanded}
            onSidebarExpandIntent={onSidebarNavIntent}
          />
        ) : null}
        <nav
          className="cab-sidebar-nav gestionale-scrollbar flex min-h-0 min-w-0 flex-1 flex-col p-3 pb-0"
          aria-label="Sezioni principali"
          onPointerEnter={(event) => {
            if (!collapsed) return;
            if (isSidebarNavLinkCurrent(event.target, pathname)) return;
            if (event.target instanceof Element && event.target.closest(".cab-sidebar-nav-row")) {
              onSidebarNavIntent();
            }
          }}
        >
          <div className="gestionale-scrollbar flex min-h-0 min-w-0 flex-1 flex-col gap-1 overflow-y-auto overflow-x-hidden overscroll-contain [-webkit-overflow-scrolling:touch]">
            {isNavLoading ? (
              <SidebarNavSkeleton />
            ) : (
              navItems.map((item) => (
                <NavLink
                  key={item.href}
                  href={item.href}
                  label={item.label}
                  Icon={item.Icon}
                  collapsed={collapsed}
                  disabled={item.disabled}
                  badge={item.badge}
                  onNavigate={beginRouteTransition}
                  onExpandIntent={onSidebarNavIntent}
                  onActiveNavClick={() => {
                    if (sidebarExpanded) collapseSidebar();
                  }}
                />
              ))
            )}
          </div>
        </nav>
      </aside>

      <div
        ref={shellColRef}
        className={`flex min-h-0 min-w-0 flex-1 flex-col transition-[padding] duration-[var(--cab-sidebar-width-motion)] ease-out ${mainPad}`}
      >
        <MobileNavDrawer
          open={mobileOpen}
          onClose={() => setMobileOpen(false)}
          navItems={navItems}
          onNavigate={beginRouteTransition}
          isCompactShell={isCompactShell}
          isNavLoading={isNavLoading}
        />

        {process.env.NODE_ENV === "development" ? <DevAuditMounts /> : null}

        <div className={dsGestionaleContentRail}>
          <main
            ref={mainScrollRef}
            className={`gestionale-scroll-y gestionale-scrollbar w-full ${layoutResponsiveCoreScope} min-h-0 min-w-0 flex-1 pt-0 ${
              isCompactShell
                ? "pb-[max(0.75rem,env(safe-area-inset-bottom))]"
                : "pb-[max(1rem,env(safe-area-inset-bottom))]"
            }`}
          >
            <div className={`${dsGestionaleContentMax} ${layoutPageRoot} ${contentGutter}`}>
              {process.env.NODE_ENV === "development" ? (
                <ReactRenderAuditProfiler>{children}</ReactRenderAuditProfiler>
              ) : (
                children
              )}
              {!suppressGlobalScrollEndPad ? (
                <div aria-hidden className={dsGestionaleScrollEndPadFade} />
              ) : null}
            </div>
          </main>
        </div>
      </div>
    </div>
    </ProfileSheetProvider>
    </GestionaleShellLayoutProvider>
  );
}

"use client";

import { useMemo } from "react";
import { buildMonthDays, formatMonthLabel } from "@/lib/dipendenti/timesheet-month";
import { computeMonthTotals, entryToCellValue } from "@/lib/dipendenti/timesheet-totals";
import type { TipoAssenzaConfig } from "@/lib/dipendenti/tipi-assenza-model";
import type {
  DipendenteTimesheetEmployeeRow,
  DipendenteTimesheetEntryRow,
  TimesheetMonthKey,
} from "@/lib/dipendenti/types";
import { GestionaleModalScrollBody } from "@/components/gestionale/mobile-modal-scroll-body";
import { GestionaleModalShell } from "@/components/gestionale/gestionale-modal";
import { erpBtnAccent, erpBtnNeutral } from "@/components/report/report-buttons";
import { GlobalTableHead } from "@/components/gestionale/global-table";
import { gestionaleListTableTd } from "@/lib/ui/gestionale-list-table";

export function DipendenteDetailModal({
  open,
  onClose,
  employee,
  monthKey,
  entries,
  tipiAssenza: _tipiAssenza,
}: {
  open: boolean;
  onClose: () => void;
  employee: DipendenteTimesheetEmployeeRow | null;
  monthKey: TimesheetMonthKey;
  entries: readonly DipendenteTimesheetEntryRow[];
  tipiAssenza: readonly TipoAssenzaConfig[];
}) {
  const days = useMemo(() => buildMonthDays(monthKey), [monthKey]);
  const empEntries = useMemo(
    () => (employee ? entries.filter((e) => e.dipendente_id === employee.id) : []),
    [employee, entries],
  );
  const totals = useMemo(() => computeMonthTotals(empEntries), [empEntries]);

  if (!open || !employee) return null;

  return (
    <GestionaleModalShell
      modalSize="info"
      onRequestClose={onClose}
      title={employee.display_name}
      subtitle={formatMonthLabel(monthKey)}
    >
      <GestionaleModalScrollBody className="py-3">
        <div className="mb-4 grid grid-cols-2 gap-2 text-center sm:grid-cols-4">
          <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2">
            <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">Ordinarie</p>
            <p className="text-lg font-semibold tabular-nums">{totals.oreOrdinarie} h</p>
          </div>
          <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2">
            <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">Straordinarie</p>
            <p className="text-lg font-semibold tabular-nums">{totals.oreStraordinarie} h</p>
          </div>
          <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2">
            <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">Assenze</p>
            <p className="text-lg font-semibold tabular-nums">{totals.oreAssenza} h</p>
          </div>
          <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2">
            <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">Lavorato</p>
            <p className="text-lg font-semibold tabular-nums">{totals.totaleLavorato} h</p>
          </div>
        </div>
        <table className="w-full text-xs">
          <GlobalTableHead>
            <tr className="border-b border-[color:var(--cab-border)] text-left text-[color:var(--cab-text-muted)]">
              <th className="py-1.5 pr-2">Giorno</th>
              <th className="py-1.5 px-1 text-center">Ord.</th>
              <th className="py-1.5 px-1 text-center">Str.</th>
              <th className="py-1.5 px-1 text-center">Ass.</th>
              <th className="py-1.5 pl-2">Tipo / Note</th>
            </tr>
          </GlobalTableHead>
          <tbody>
            {days.map((d) => {
              const cell = entryToCellValue(empEntries.find((e) => e.work_date === d.dateYmd));
              const hasData = cell.oreOrdinarie > 0 || cell.oreStraordinarie > 0 || cell.oreAssenza > 0;
              return (
                <tr key={d.dateYmd} className="border-b border-[color:color-mix(in_srgb,var(--cab-border)_60%,transparent)]">
                  <td className={gestionaleListTableTd}>
                    {String(d.day).padStart(2, "0")} {d.weekdayShort}
                  </td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreOrdinarie || "—"}</td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreStraordinarie || "—"}</td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreAssenza || "—"}</td>
                  <td className={gestionaleListTableTd}>
                    {hasData
                      ? [cell.tipoAssenzaLabel, cell.motivoCustom, cell.note].filter(Boolean).join(" · ") || "—"
                      : "—"}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </GestionaleModalScrollBody>
      <div className="flex shrink-0 min-w-0 justify-end gap-2 border-t border-[color:var(--cab-border)] px-4 py-3 sm:px-5">
        <button type="button" className={erpBtnNeutral} onClick={onClose}>
          Chiudi
        </button>
        <button type="button" className={erpBtnAccent} onClick={onClose}>
          OK
        </button>
      </div>
    </GestionaleModalShell>
  );
}

"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { DipendentiEmptyState } from "@/components/gestionale/dipendenti/dipendenti-empty-state";
import {
  TimesheetCellEditor,
  timesheetCellEditorValid,
} from "@/components/gestionale/dipendenti/timesheet-cell-editor";
import { GestionaleListTable, GestionaleListTableRow, GlobalTableHeadLabel } from "@/components/gestionale/global-table";
import { cellValueToUpsert } from "@/lib/dipendenti/timesheet-entry-map";
import { buildMonthDays } from "@/lib/dipendenti/timesheet-month";
import { isCellEmpty } from "@/lib/dipendenti/timesheet-totals";
import type { TipoAssenzaConfig } from "@/lib/dipendenti/tipi-assenza-model";
import type {
  DipendenteTimesheetEmployeeRow,
  TimesheetCellValue,
  TimesheetEntryUpsert,
  TimesheetMonthKey,
} from "@/lib/dipendenti/types";
import { gestionaleListTableTd } from "@/lib/ui/gestionale-list-table";
import { dsSurfaceCard, dsTypoSmall } from "@/lib/ui/design-system";
import { useGestionaleListLayout } from "@/lib/ui/use-gestionale-list-layout";

function DayInserimentoRow({
  dateYmd,
  dayLabel,
  weekdayShort,
  isWeekend,
  value,
  tipiAssenza,
  readOnly,
  onChange,
  onBlurSave,
}: {
  dateYmd: string;
  dayLabel: string;
  weekdayShort: string;
  isWeekend: boolean;
  value: TimesheetCellValue;
  tipiAssenza: readonly TipoAssenzaConfig[];
  readOnly?: boolean;
  onChange: (dateYmd: string, next: TimesheetCellValue) => void;
  onBlurSave: (dateYmd: string, value: TimesheetCellValue) => void;
}) {
  return (
    <GestionaleListTableRow className={isWeekend ? "opacity-90" : undefined}>
      <td className={`${gestionaleListTableTd} whitespace-nowrap tabular-nums`}>
        <span className="font-medium">{dayLabel}</span>
        <span className="ml-2 text-[color:var(--cab-text-muted)]">{weekdayShort}</span>
      </td>
      <td className={gestionaleListTableTd} colSpan={1}>
        <div
          onBlur={(e) => {
            if (!e.currentTarget.contains(e.relatedTarget as Node | null)) {
              onBlurSave(dateYmd, value);
            }
          }}
        >
          <TimesheetCellEditor
            value={value}
            onChange={(next) => onChange(dateYmd, next)}
            tipiAssenza={tipiAssenza}
            readOnly={readOnly}
            compact
          />
        </div>
      </td>
    </GestionaleListTableRow>
  );
}

export function DipendentiInserimentoSection({
  monthKey,
  employees,
  filterEmployeeId,
  getCellValue,
  tipiAssenza,
  readOnly,
  hasAddetti,
  onScheduleSave,
  onSaveNow,
}: {
  monthKey: TimesheetMonthKey;
  employees: readonly DipendenteTimesheetEmployeeRow[];
  filterEmployeeId: string;
  getCellValue: (dipendenteId: string, workDate: string) => TimesheetCellValue;
  tipiAssenza: readonly TipoAssenzaConfig[];
  readOnly?: boolean;
  hasAddetti: boolean;
  onScheduleSave: (input: TimesheetEntryUpsert) => void;
  onSaveNow: (input: TimesheetEntryUpsert) => void | Promise<void>;
}) {
  const { containerRef: listLayoutRef, layout: listLayout, layoutClassName: listLayoutClassName } =
    useGestionaleListLayout({ tier: "md" });
  const days = useMemo(() => buildMonthDays(monthKey), [monthKey]);

  const targetEmployee = useMemo(() => {
    if (filterEmployeeId) {
      const selected = employees.find((e) => e.id === filterEmployeeId);
      return selected?.in_settings ? selected : selected ?? null;
    }
    return employees.find((e) => e.in_settings) ?? null;
  }, [employees, filterEmployeeId]);

  const [localByDate, setLocalByDate] = useState<Map<string, TimesheetCellValue>>(new Map());

  useEffect(() => {
    setLocalByDate(new Map());
  }, [monthKey, targetEmployee?.id]);

  const getValue = useCallback(
    (dateYmd: string): TimesheetCellValue => {
      if (!targetEmployee) return getCellValue("", dateYmd);
      return localByDate.get(dateYmd) ?? getCellValue(targetEmployee.id, dateYmd);
    },
    [localByDate, getCellValue, targetEmployee],
  );

  const tryPersist = useCallback(
    (dateYmd: string, value: TimesheetCellValue, immediate: boolean) => {
      if (!targetEmployee || readOnly) return;
      const upsert = cellValueToUpsert(targetEmployee.id, dateYmd, value, tipiAssenza);
      if (isCellEmpty(value)) {
        if (immediate) void onSaveNow(upsert);
        else onScheduleSave(upsert);
        return;
      }
      if (!timesheetCellEditorValid(value, tipiAssenza)) return;
      if (immediate) void onSaveNow(upsert);
      else onScheduleSave(upsert);
    },
    [targetEmployee, readOnly, tipiAssenza, onSaveNow, onScheduleSave],
  );

  const handleChange = useCallback(
    (dateYmd: string, next: TimesheetCellValue) => {
      setLocalByDate((prev) => new Map(prev).set(dateYmd, next));
      tryPersist(dateYmd, next, false);
    },
    [tryPersist],
  );

  const handleBlurSave = useCallback(
    (dateYmd: string, value: TimesheetCellValue) => {
      tryPersist(dateYmd, value, true);
    },
    [tryPersist],
  );

  if (!hasAddetti) {
    return <DipendentiEmptyState variant="no-addetti" />;
  }

  if (employees.length === 0) {
    return <DipendentiEmptyState variant="no-employees" readOnly={readOnly} />;
  }

  if (!targetEmployee) {
    return <DipendentiEmptyState variant="select-employee" />;
  }

  return (
    <div ref={listLayoutRef} className={`space-y-4 min-w-0 max-w-full ${listLayoutClassName}`.trim()}>
      <div className="flex min-w-0 flex-col gap-1 sm:flex-row sm:items-center sm:justify-between">
        <p className="text-sm text-[color:var(--cab-text)]">
          Dipendente: <strong>{targetEmployee.display_name}</strong>
          {!filterEmployeeId ? (
            <span className="ml-1 text-[color:var(--cab-text-muted)]">(filtra nella toolbar per cambiare)</span>
          ) : null}
        </p>
        <p className={`${dsTypoSmall} text-[color:var(--cab-text-muted)]`}>
          Compila ore e assenze — salvataggio automatico
        </p>
      </div>

      {listLayout === "desktop" ? (
      <div>
        <GestionaleListTable
          masterScrollScope
          colSpan={2}
          headRow={
            <>
              <GlobalTableHeadLabel label="Giorno" thClassName="min-w-[6rem]" />
              <GlobalTableHeadLabel label="Ore / assenza / note" />
            </>
          }
        >
          {days.map((d) => (
            <DayInserimentoRow
              key={d.dateYmd}
              dateYmd={d.dateYmd}
              dayLabel={String(d.day).padStart(2, "0")}
              weekdayShort={d.weekdayShort}
              isWeekend={d.isWeekend}
              value={getValue(d.dateYmd)}
              tipiAssenza={tipiAssenza}
              readOnly={readOnly}
              onChange={handleChange}
              onBlurSave={handleBlurSave}
            />
          ))}
        </GestionaleListTable>
      </div>
      ) : null}

      {listLayout === "mobile" ? (
      <ul className="max-h-[min(60vh,32rem)] space-y-2 overflow-y-auto gestionale-scrollbar">
        {days.map((d) => (
          <li key={d.dateYmd}>
            <div className={`${dsSurfaceCard} px-3 py-3`}>
              <p className="mb-2 text-sm font-medium tabular-nums text-[color:var(--cab-text)]">
                {String(d.day).padStart(2, "0")}{" "}
                <span className="font-normal text-[color:var(--cab-text-muted)]">{d.weekdayShort}</span>
              </p>
              <div
                onBlur={(e) => {
                  if (!e.currentTarget.contains(e.relatedTarget as Node | null)) {
                    handleBlurSave(d.dateYmd, getValue(d.dateYmd));
                  }
                }}
              >
                <TimesheetCellEditor
                  value={getValue(d.dateYmd)}
                  onChange={(next) => handleChange(d.dateYmd, next)}
                  tipiAssenza={tipiAssenza}
                  readOnly={readOnly}
                  compact
                />
              </div>
            </div>
          </li>
        ))}
      </ul>
      ) : null}
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { DipendentiEmptyState } from "@/components/gestionale/dipendenti/dipendenti-empty-state";
import { DipendentiStoricoSection } from "@/components/gestionale/dipendenti/dipendenti-storico-section";
import { buildMonthDays, formatMonthLabel } from "@/lib/dipendenti/timesheet-month";
import { computeDipendenteSchedaStats } from "@/lib/dipendenti/timesheet-scheda-stats";
import { computeMonthTotals, entryToCellValue } from "@/lib/dipendenti/timesheet-totals";
import { formatCellShortLabel } from "@/lib/dipendenti/timesheet-cell-display";
import type { TipoAssenzaConfig } from "@/lib/dipendenti/tipi-assenza-model";
import type {
  DipendenteTimesheetEmployeeRow,
  DipendenteTimesheetEntryRow,
  TimesheetMonthKey,
} from "@/lib/dipendenti/types";
import { GlobalTableHead, GlobalTableHeadLabel } from "@/components/gestionale/global-table";
import { gestionaleListTableClass, gestionaleListTableTd } from "@/lib/ui/gestionale-list-table";
import { dsPageToolbarBtn } from "@/lib/ui/design-system";

export function DipendentiSchedaSection({
  monthKey,
  employees,
  filterEmployeeId,
  entries,
  tipiAssenza,
  hasAddetti,
  onOpenDetail,
}: {
  monthKey: TimesheetMonthKey;
  employees: readonly DipendenteTimesheetEmployeeRow[];
  filterEmployeeId: string;
  entries: readonly DipendenteTimesheetEntryRow[];
  tipiAssenza: readonly TipoAssenzaConfig[];
  hasAddetti: boolean;
  onOpenDetail: (employee: DipendenteTimesheetEmployeeRow) => void;
}) {
  const employee = useMemo(
    () => (filterEmployeeId ? employees.find((e) => e.id === filterEmployeeId) ?? null : null),
    [employees, filterEmployeeId],
  );

  const empEntries = useMemo(
    () => (employee ? entries.filter((e) => e.dipendente_id === employee.id) : []),
    [employee, entries],
  );

  const totals = useMemo(() => computeMonthTotals(empEntries), [empEntries]);
  const schedaStats = useMemo(() => computeDipendenteSchedaStats(empEntries), [empEntries]);
  const days = useMemo(() => buildMonthDays(monthKey), [monthKey]);

  const entryByDate = useMemo(() => {
    const map = new Map<string, DipendenteTimesheetEntryRow>();
    for (const e of empEntries) map.set(e.work_date, e);
    return map;
  }, [empEntries]);

  if (!hasAddetti) {
    return <DipendentiEmptyState variant="no-addetti" />;
  }

  if (employees.length === 0) {
    return <DipendentiEmptyState variant="no-employees" readOnly />;
  }

  if (!employee) {
    return <DipendentiEmptyState variant="select-employee" />;
  }

  const maxBar = Math.max(1, schedaStats.giorniLavorati, schedaStats.giorniAssenza);

  return (
    <div className="space-y-6">
      <div className="flex min-w-0 flex-wrap items-center justify-between gap-2">
        <div>
          <p className="text-sm font-semibold text-[color:var(--cab-text)]">{employee.display_name}</p>
          <p className="text-xs text-[color:var(--cab-text-muted)]">{formatMonthLabel(monthKey)}</p>
        </div>
        <button type="button" className={dsPageToolbarBtn} onClick={() => onOpenDetail(employee)}>
          Apri dettaglio
        </button>
      </div>

      <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
        <StatChip label="Ordinarie" value={String(totals.oreOrdinarie)} />
        <StatChip label="Straordinarie" value={String(totals.oreStraordinarie)} />
        <StatChip label="Assenze (h)" value={String(totals.oreAssenza)} unit="" />
        <StatChip label="Lavorato" value={String(totals.totaleLavorato)} />
      </div>

      <div className="grid gap-4 sm:grid-cols-2">
        <div className="space-y-2 rounded-[var(--ds-radius-lg)] border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-3">
          <p className="text-[10px] font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)]">
            Giorni lavorati vs assenza
          </p>
          <div className="space-y-2">
            <BarRow label="Giorni lavorati" value={schedaStats.giorniLavorati} max={maxBar} color="var(--cab-success)" />
            <BarRow label="Giorni assenza" value={schedaStats.giorniAssenza} max={maxBar} color="var(--cab-danger)" />
          </div>
          <p className="text-xs text-[color:var(--cab-text-muted)]">
            Media ore/giorno lavorato:{" "}
            <strong className="text-[color:var(--cab-text)]">{schedaStats.mediaOreGiorno} h</strong>
          </p>
        </div>

        <div className="rounded-[var(--ds-radius-lg)] border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-3">
          <p className="mb-2 text-[10px] font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)]">
            Assenze per motivo
          </p>
          {schedaStats.motiviAssenza.length === 0 ? (
            <p className="text-sm text-[color:var(--cab-text-muted)]">Nessuna assenza nel mese.</p>
          ) : (
            <ul className="space-y-1.5 text-sm">
              {schedaStats.motiviAssenza.map((m) => (
                <li key={m.label} className="flex min-w-0 justify-between gap-2">
                  <span className="text-[color:var(--cab-text)]">{m.label}</span>
                  <span className="tabular-nums text-[color:var(--cab-text-muted)]">
                    {m.oreAssenza} h · {m.giorni} gg
                  </span>
                </li>
              ))}
            </ul>
          )}
        </div>
      </div>

      <div className="overflow-x-auto">
        <table className={gestionaleListTableClass}>
          <GlobalTableHead>
              <GlobalTableHeadLabel label="Giorno" />
              <GlobalTableHeadLabel label="Riepilogo" align="center" />
              <GlobalTableHeadLabel label="Ord." align="center" />
              <GlobalTableHeadLabel label="Str." align="center" />
              <GlobalTableHeadLabel label="Ass." align="center" />
          </GlobalTableHead>
          <tbody>
            {days.map((d) => {
              const entry = entryByDate.get(d.dateYmd);
              const cell = entryToCellValue(entry);
              const badge = formatCellShortLabel(cell, tipiAssenza);
              if (!entry && !badge) return null;
              return (
                <tr key={d.dateYmd} className="border-b border-[color:var(--cab-border)]">
                  <td className={gestionaleListTableTd}>
                    {String(d.day).padStart(2, "0")}{" "}
                    <span className="text-[color:var(--cab-text-muted)]">{d.weekdayShort}</span>
                  </td>
                  <td className={`${gestionaleListTableTd} text-center font-semibold tabular-nums`}>{badge || "—"}</td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreOrdinarie || "—"}</td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreStraordinarie || "—"}</td>
                  <td className={`${gestionaleListTableTd} text-center tabular-nums`}>{cell.oreAssenza || "—"}</td>
                </tr>
              );
            })}
          </tbody>
        </table>
      </div>

      <div className="border-t border-[color:var(--cab-border)] pt-4">
        <p className="mb-3 text-sm font-semibold text-[color:var(--cab-text)]">Andamento annuale</p>
        <DipendentiStoricoSection
          monthKey={monthKey}
          employees={employees}
          filterEmployeeId={filterEmployeeId}
          hasAddetti={hasAddetti}
          onOpenDetail={onOpenDetail}
        />
      </div>
    </div>
  );
}

function StatChip({ label, value, unit = "h" }: { label: string; value: string; unit?: string }) {
  return (
    <div className="rounded-[var(--ds-radius-lg)] border border-[color:var(--cab-border)] bg-[var(--cab-surface)] p-2 text-center">
      <p className="text-[10px] uppercase text-[color:var(--cab-text-muted)]">{label}</p>
      <p className="text-lg font-semibold tabular-nums text-[color:var(--cab-text)]">
        {value}
        {unit ? <span className="ml-0.5 text-xs font-normal text-[color:var(--cab-text-muted)]">{unit}</span> : null}
      </p>
    </div>
  );
}

function BarRow({
  label,
  value,
  max,
  color,
}: {
  label: string;
  value: number;
  max: number;
  color: string;
}) {
  const pct = max > 0 ? Math.round((value / max) * 100) : 0;
  return (
    <div>
      <div className="mb-0.5 flex min-w-0 justify-between text-xs">
        <span className="text-[color:var(--cab-text-muted)]">{label}</span>
        <span className="font-semibold tabular-nums text-[color:var(--cab-text)]">{value}</span>
      </div>
      <div className="h-2 overflow-hidden rounded-full bg-[color:color-mix(in_srgb,var(--cab-text-muted)_12%,transparent)]">
        <div className="h-full rounded-full" style={{ width: `${pct}%`, backgroundColor: color }} />
      </div>
    </div>
  );
}

"use client";

import { useMemo } from "react";
import { DipendentiEmptyState, DipendentiQueryErrorBanner } from "@/components/gestionale/dipendenti/dipendenti-empty-state";
import { formatMonthLabel } from "@/lib/dipendenti/timesheet-month";
import type { DipendenteTimesheetEmployeeRow, TimesheetMonthKey } from "@/lib/dipendenti/types";
