"use client";

import { useCallback, useEffect, useRef, useState } from "react";
import { PageHeader } from "@/components/gestionale/page-header";
import { DipendentiPdfToolbar } from "@/components/gestionale/dipendenti/dipendenti-pdf-toolbar";
import { GestionaleSectionGate } from "@/components/gestionale/gestionale-section-gate";
import { ShellCard } from "@/components/gestionale/shell-card";
import {
  defaultDayDate,
  defaultWeekAnchor,
  TimesheetHeader,
} from "@/components/gestionale/dipendenti/timesheet-header";
import { TimesheetEditorModal } from "@/components/gestionale/dipendenti/timesheet-editor-modal";
import { DipendenteDetailModal } from "@/components/gestionale/dipendenti/dipendente-detail-modal";
import { TimesheetEmptyState } from "@/components/gestionale/dipendenti/timesheet-empty-state";
import { TimesheetLoadError } from "@/components/gestionale/dipendenti/timesheet-load-error";
import { TimesheetTableView } from "@/components/gestionale/dipendenti/timesheet-table-view";
import { LoadingDipendentiSkeleton } from "@/components/design-system";
import { GestionaleConfirmDialog } from "@/components/gestionale/gestionale-confirm-dialog";
import {
  buildDipendentiPdfContext,
  openDipendentiPdfComplessivoInNewTab,
  openDipendentiPdfDipendenteInNewTab,
} from "@/lib/dipendenti/pdf/dipendenti-pdf-export";
import { buildEmptyDay8hUpserts } from "@/lib/dipendenti/timesheet-bulk-fill-day";
import {
  currentMonthKey,
  isDateInMonthKey,
  monthKeyFromDate,
  shiftMonthKey,
  todayDateYmd,
} from "@/lib/dipendenti/timesheet-month";
import type { TimesheetEditorTarget, TimesheetEntryUpsert, TimesheetMonthKey, DipendenteTimesheetEmployeeRow } from "@/lib/dipendenti/types";
import type { TimesheetPeriodMode } from "@/lib/dipendenti/timesheet-month";
import { dsFocus, dsPageToolbarIconBtn, dsStackPage } from "@/lib/ui/design-system";
import {
  CalendarNavChevronLeft,
  CalendarNavChevronRight,
} from "@/components/gestionale/global-input/calendar-nav-icons";
import { useGestionaleListLayout } from "@/lib/ui/use-gestionale-list-layout";
import { layoutPageRoot } from "@/lib/ui/responsive-layout-core";
import { useDipendentiTimesheet } from "@/src/hooks/use-dipendenti-timesheet";
import { useGestionaleToast } from "@/src/hooks/use-gestionale-toast";
import { usePermissions } from "@/src/hooks/use-permissions";
import { GESTIONALE_TOAST } from "@/src/lib/ux/gestionale-toast-messages";

/** Evidenziazione colonna «Oggi» — hold + fade-out (allineato a CSS --timesheet-today-*). */
const TIMESHEET_TODAY_ACCENT_HOLD_MS = 900;
const TIMESHEET_TODAY_ACCENT_FADE_MS = 360;

function formatWorkDateIt(dateYmd: string): string {
  const [y, m, d] = dateYmd.split("-");
  return `${d}/${m}/${y}`;
}

export function DipendentiView() {
  const { containerRef: listLayoutRef, layout: listLayout, layoutClassName: listLayoutClassName } = useGestionaleListLayout({ tier: "md" });
  const [monthKey, setMonthKey] = useState<TimesheetMonthKey>(() => monthKeyFromDate(new Date()));
  const [periodMode] = useState<TimesheetPeriodMode>("month");
  const [weekAnchor, setWeekAnchor] = useState(() => defaultWeekAnchor(monthKeyFromDate(new Date())));
  const [dayDate, setDayDate] = useState(() => defaultDayDate(monthKeyFromDate(new Date())));
  const [filterEmployeeId, setFilterEmployeeId] = useState("");
  const [editorTarget, setEditorTarget] = useState<TimesheetEditorTarget | null>(null);
  const [detailEmployee, setDetailEmployee] = useState<DipendenteTimesheetEmployeeRow | null>(null);
  const [bootstrapPending, setBootstrapPending] = useState(false);
  const [pdfExporting, setPdfExporting] = useState(false);
  const [accentDateYmd, setAccentDateYmd] = useState<string | null>(null);
  const [accentFadingOut, setAccentFadingOut] = useState(false);
  const [fillToday8hPending, setFillToday8hPending] = useState(false);
  const [fillToday8hConfirmOpen, setFillToday8hConfirmOpen] = useState(false);
  const [fillToday8hUpserts, setFillToday8hUpserts] = useState<TimesheetEntryUpsert[]>([]);
  const accentClearTimerRef = useRef<ReturnType<typeof setTimeout> | null>(null);

  useEffect(() => {
    return () => {
      if (accentClearTimerRef.current) clearTimeout(accentClearTimerRef.current);
    };
  }, []);

  const perm = usePermissions("dipendenti");
  const { validation: toastValidation, successOnce, errorOnce } = useGestionaleToast();
  const ts = useDipendentiTimesheet({ monthKey, periodMode, weekAnchor, dayDate });

  useEffect(() => {
    if (!filterEmployeeId) return;
    if (!ts.displayEmployees.some((e) => e.id === filterEmployeeId)) {
      setFilterEmployeeId("");
    }
  }, [filterEmployeeId, ts.displayEmployees]);

  const readOnly = !perm.canWrite;

  const editorEmployee =
    editorTarget != null
      ? (ts.displayEmployees.find((e) => e.id === editorTarget.dipendenteId) ?? null)
      : null;

  const editorDateLabel = (() => {
    if (!editorTarget) return "";
    const day = ts.periodDays.find((d) => d.dateYmd === editorTarget.workDate);
    if (!day) return editorTarget.workDate;
    return `${String(day.day).padStart(2, "0")}/${monthKey.split("-")[1]}/${monthKey.split("-")[0]} (${day.weekdayShort})`;
  })();

  const handleSaveEntry = useCallback(
    async (input: TimesheetEntryUpsert) => {
      if (readOnly) return;
      await ts.saveNow(input);
    },
    [readOnly, ts],
  );

  const handleCopyDayToAll = useCallback(
    async (upserts: TimesheetEntryUpsert[]) => {
      if (readOnly || upserts.length === 0) return;
      await Promise.all(upserts.map((input) => ts.saveNow(input)));
      successOnce("dip-copy-day-all", GESTIONALE_TOAST.dipendentiCopyDayToAllSuccess);
    },
    [readOnly, ts, successOnce],
  );

  const handleScheduleSave = useCallback(
    (input: TimesheetEntryUpsert) => {
      if (readOnly) return;
      ts.scheduleSave(input);
    },
    [readOnly, ts],
  );

  const handleCellClick = useCallback((dipendenteId: string, workDate: string) => {
    setDetailEmployee(null);
    setEditorTarget({ dipendenteId, workDate });
  }, []);

  const pdfContext = useCallback(
    () =>
      buildDipendentiPdfContext({
        monthKey,
        employees: ts.displayEmployees,
        entries: ts.entries,
        tipiAssenza: ts.tipiAssenza,
        addettiRecords: ts.addettiRecords,
      }),
    [monthKey, ts.displayEmployees, ts.entries, ts.tipiAssenza, ts.addettiRecords],
  );

  const handleExportPdfComplessivo = useCallback(() => {
    if (pdfExporting || ts.displayEmployees.length === 0) return;
    void (async () => {
      setPdfExporting(true);
      try {
        await openDipendentiPdfComplessivoInNewTab(pdfContext());
      } finally {
        setPdfExporting(false);
      }
    })();
  }, [pdfExporting, pdfContext, ts.displayEmployees.length]);

  const handleExportPdfDipendente = useCallback(() => {
    if (pdfExporting) return;
    if (!filterEmployeeId) {
      toastValidation(GESTIONALE_TOAST.dipendentiSelectAddettoForPdf);
      return;
    }
    const employee = ts.displayEmployees.find((e) => e.id === filterEmployeeId);
    if (!employee) {
      toastValidation(GESTIONALE_TOAST.dipendentiSelectAddettoForPdf);
      return;
    }
    void (async () => {
      setPdfExporting(true);
      try {
        await openDipendentiPdfDipendenteInNewTab(pdfContext(), employee);
      } finally {
        setPdfExporting(false);
      }
    })();
  }, [pdfExporting, pdfContext, ts.displayEmployees, filterEmployeeId, toastValidation]);

  const handleBootstrap = useCallback(async () => {
    setBootstrapPending(true);
    try {
      await ts.bootstrapEmployees();
      ts.refetchEmployees();
    } finally {
      setBootstrapPending(false);
    }
  }, [ts]);

  const handleMonthKey = useCallback((key: TimesheetMonthKey) => {
    setMonthKey(key);
    setWeekAnchor(defaultWeekAnchor(key));
    setDayDate(defaultDayDate(key));
    setAccentDateYmd((prev) => (prev && !isDateInMonthKey(prev, key) ? null : prev));
    setAccentFadingOut(false);
    setEditorTarget(null);
    setDetailEmployee(null);
  }, []);

  const handleGoToToday = useCallback(() => {
    if (accentClearTimerRef.current) clearTimeout(accentClearTimerRef.current);
    handleMonthKey(currentMonthKey());
    setAccentFadingOut(false);
    setAccentDateYmd(todayDateYmd());
    accentClearTimerRef.current = setTimeout(() => {
      setAccentFadingOut(true);
      accentClearTimerRef.current = setTimeout(() => {
        setAccentDateYmd(null);
        setAccentFadingOut(false);
        accentClearTimerRef.current = null;
      }, TIMESHEET_TODAY_ACCENT_FADE_MS);
    }, TIMESHEET_TODAY_ACCENT_HOLD_MS);
  }, [handleMonthKey]);

  const todayYmd = todayDateYmd();
  const todayInViewedMonth = isDateInMonthKey(todayYmd, monthKey);

  const fillToday8hDisabled =
    readOnly ||
    ts.entriesDegraded ||
    ts.loadPhase !== "ready" ||
    ts.displayEmployees.length === 0 ||
    !todayInViewedMonth ||
    fillToday8hPending ||
    ts.upsertPending;

  const fillToday8hDisabledReason = readOnly
    ? "Permessi insufficienti per modificare le presenze"
    : ts.entriesDegraded
      ? "Presenze in sola lettura: aggiorna i dati prima di compilare"
      : ts.loadPhase !== "ready" || ts.displayEmployees.length === 0
        ? "Registro presenze non pronto"
        : !todayInViewedMonth
          ? GESTIONALE_TOAST.dipendentiFillToday8hNotInMonth
          : fillToday8hPending || ts.upsertPending
            ? "Salvataggio in corso"
            : undefined;

  const handleFillToday8h = useCallback(() => {
    if (readOnly || ts.entriesDegraded || fillToday8hPending || ts.upsertPending) return;
    const workDate = todayDateYmd();
    if (!isDateInMonthKey(workDate, monthKey)) {
      toastValidation(GESTIONALE_TOAST.dipendentiFillToday8hNotInMonth);
      return;
    }
    const upserts = buildEmptyDay8hUpserts(ts.displayEmployees, workDate, ts.getCellValue);
    if (upserts.length === 0) {
      toastValidation(GESTIONALE_TOAST.dipendentiFillToday8hNoEmpty);
      return;
    }
    setFillToday8hUpserts(upserts);
    setFillToday8hConfirmOpen(true);
  }, [
    readOnly,
    ts.entriesDegraded,
    ts.upsertPending,
    ts.displayEmployees,
    ts.getCellValue,
    monthKey,
    fillToday8hPending,
    toastValidation,
  ]);

  const handleConfirmFillToday8h = useCallback(async () => {
    if (fillToday8hUpserts.length === 0) {
      setFillToday8hConfirmOpen(false);
      return;
    }
    setFillToday8hPending(true);
    try {
      await Promise.all(fillToday8hUpserts.map((input) => ts.saveNow(input)));
      successOnce("dip-fill-today-8h", GESTIONALE_TOAST.dipendentiFillToday8hSuccess);
      setFillToday8hConfirmOpen(false);
      setFillToday8hUpserts([]);
    } catch (e) {
      errorOnce("dip-fill-today-8h", e, { module: "dipendenti", action: "update" });
    } finally {
      setFillToday8hPending(false);
    }
  }, [fillToday8hUpserts, ts, successOnce, errorOnce]);

  if (perm.isLoading) {
    return <LoadingDipendentiSkeleton />;
  }

  const showRegistryEmpty =
    ts.loadPhase !== "error" && ts.hasRealAddetti && ts.displayEmployees.length === 0 && !ts.isSyncing;
  const showNoAddetti = ts.loadPhase !== "error" && ts.addettiReady && !ts.hasRealAddetti;
  const settingsLoading = ts.addettiSource !== "app_settings" && !ts.addettiReady;

  return (
    <GestionaleSectionGate module="dipendenti">
      <div ref={listLayoutRef} className={`${layoutPageRoot} ${listLayoutClassName}`.trim()}>
        <PageHeader
          title="Dipendenti"
          actions={
            <DipendentiPdfToolbar
              filterEmployeeId={filterEmployeeId}
              exporting={pdfExporting}
              onExportComplessivo={handleExportPdfComplessivo}
              onExportDipendente={handleExportPdfDipendente}
            />
          }
        />
        <div className={`${dsStackPage} flex-safe-col min-w-0 max-w-full`}>
          <TimesheetHeader
            periodMode={periodMode}
            monthKey={monthKey}
            onMonthKey={handleMonthKey}
            weekAnchor={weekAnchor}
            onWeekAnchor={setWeekAnchor}
            dayDate={dayDate}
            onDayDate={setDayDate}
            employees={ts.displayEmployees}
            filterEmployeeId={filterEmployeeId}
            onFilterEmployeeId={setFilterEmployeeId}
            saveStatus={ts.saveStatus}
            showBackgroundSync={ts.showBackgroundSyncInToolbar}
            onGoToToday={handleGoToToday}
            onFillToday8h={readOnly ? undefined : handleFillToday8h}
            fillToday8hPending={fillToday8hPending}
            fillToday8hDisabled={fillToday8hDisabled}
            fillToday8hDisabledReason={fillToday8hDisabledReason}
            monthKeysWithData={ts.monthKeysWithData}
          />

          <TimesheetLoadError
            loadPhase={ts.loadPhase}
            errorKind={ts.errorKind}
            employeesError={ts.employeesError}
            entriesError={ts.entriesError}
            syncError={ts.syncError}
            onRetryEmployees={ts.refetchEmployees}
            onRetryEntries={ts.refetchEntries}
          />

          {settingsLoading || ts.isInitialLoading ? (
            <LoadingDipendentiSkeleton embedded />
          ) : showNoAddetti ? (
            <TimesheetEmptyState variant="no-addetti" />
          ) : showRegistryEmpty ? (
            <TimesheetEmptyState
              variant="no-employees"
              onBootstrap={() => void handleBootstrap()}
              bootstrapPending={bootstrapPending || ts.isSyncing}
              bootstrapError={ts.syncError}
              readOnly={readOnly}
            />
          ) : ts.loadPhase === "ready" ? (
            <ShellCard
              title="Tabella presenze"
              headerActions={
                <div className="flex items-center gap-1" role="group" aria-label="Navigazione mese">
                  <button
                    type="button"
                    className={`${dsPageToolbarIconBtn} ${dsFocus} shrink-0`}
                    aria-label="Mese precedente"
                    onClick={() => handleMonthKey(shiftMonthKey(monthKey, -1))}
                  >
                    <CalendarNavChevronLeft />
                  </button>
                  <button
                    type="button"
                    className={`${dsPageToolbarIconBtn} ${dsFocus} shrink-0`}
                    aria-label="Mese successivo"
                    onClick={() => handleMonthKey(shiftMonthKey(monthKey, 1))}
                  >
                    <CalendarNavChevronRight />
                  </button>
                </div>
              }
            >
              {ts.entriesDegraded ? (
                <div
                  className="mb-3 rounded-lg border border-amber-200 bg-amber-50 px-3 py-2 text-sm text-amber-900 dark:border-amber-900/50 dark:bg-amber-950/40 dark:text-amber-100"
                  role="status"
                >
                  Presenze non aggiornate: visualizzazione in sola lettura con dati in cache.
                  <button
                    type="button"
                    className="ml-2 font-semibold underline"
                    onClick={() => void ts.refetchEntries()}
                  >
                    Riprova
                  </button>
                </div>
              ) : null}
              <TimesheetTableView
                listLayout={listLayout}
                monthKey={monthKey}
                periodDays={ts.periodDays}
                employees={ts.displayEmployees}
                filterEmployeeId={filterEmployeeId}
                getCellValue={ts.getCellValue}
                onCellClick={handleCellClick}
                onEmployeeClick={(emp) => {
                  setEditorTarget(null);
                  setDetailEmployee(emp);
                }}
                entries={ts.entries}
                tipiAssenza={ts.tipiAssenza}
                addettiRecords={ts.addettiRecords}
                readOnly={readOnly || ts.entriesDegraded}
                accentDateYmd={accentDateYmd}
                accentFadingOut={accentFadingOut}
              />
            </ShellCard>
          ) : null}
        </div>

        {editorTarget && editorEmployee ? (
          <TimesheetEditorModal
            key={`${editorTarget.dipendenteId}|${editorTarget.workDate}`}
            open
            onClose={() => setEditorTarget(null)}
            anchorLabel={`${editorEmployee.display_name} · ${editorDateLabel}`}
            dipendenteId={editorTarget.dipendenteId}
            workDate={editorTarget.workDate}
            initialValue={ts.getCellValue(editorTarget.dipendenteId, editorTarget.workDate)}
            tipiAssenza={ts.tipiAssenza}
            readOnly={readOnly}
            employees={ts.displayEmployees}
            onSave={handleSaveEntry}
            onCopyToAll={readOnly || ts.entriesDegraded ? undefined : handleCopyDayToAll}
            onScheduleSave={handleScheduleSave}
            saving={ts.upsertPending}
          />
        ) : null}

        <DipendenteDetailModal
          open={detailEmployee != null}
          onClose={() => setDetailEmployee(null)}
          employee={detailEmployee}
          monthKey={monthKey}
          entries={ts.entries}
          tipiAssenza={ts.tipiAssenza}
        />

        <GestionaleConfirmDialog
          open={fillToday8hConfirmOpen}
          title="Imposta 8 ore per oggi"
          message={
            fillToday8hUpserts.length > 0
              ? `Compilare 8 ore ordinarie per ${fillToday8hUpserts.length} addett${
                  fillToday8hUpserts.length === 1 ? "o" : "i"
                } con cella vuota il ${formatWorkDateIt(todayYmd)}? Le celle già compilate non verranno modificate.`
              : undefined
          }
          confirmLabel={fillToday8hPending ? "Salvataggio…" : "Conferma"}
          pending={fillToday8hPending}
          onCancel={() => {
            if (fillToday8hPending) return;
            setFillToday8hConfirmOpen(false);
            setFillToday8hUpserts([]);
          }}
          onConfirm={() => void handleConfirmFillToday8h()}
        />
      </div>
    </GestionaleSectionGate>
  );
}

"use client";

import { useMemo } from "react";
import type { DipendenteTimesheetEmployeeRow, TimesheetMonthKey } from "@/lib/dipendenti/types";
import { buildTimesheetYearSelectOptions } from "@/lib/dipendenti/timesheet-available-periods";
import {
  dateYmdFromDate,
  monthKeyFromParts,
  monthOptionsForYear,
  parseMonthKey,
  setMonthKeyParts,
  shiftDayDate,
  shiftMonthKey,
  shiftWeekAnchor,
  type TimesheetPeriodMode,
} from "@/lib/dipendenti/timesheet-month";
import { GlobalSelect } from "@/components/gestionale/global-input";
import { ShellCard } from "@/components/gestionale/shell-card";
import { PageToolbarResultCount } from "@/components/design-system/page-toolbar";
import { GlobalLoadingSpinner } from "@/components/design-system/loading";
import {
  ToolbarGroup,
  ToolbarGroupBody,
  ToolbarGroupMetaRow,
  ToolbarGroupPrimaryRow,
} from "@/components/design-system/toolbar-group";
import {
  dsInput,
  dsPageToolbarBtn,
  dsPageToolbarMetaChip,
  dsTypoSmall,
} from "@/lib/ui/design-system";

/**
 * Azioni affiancate nella toolbar mese: stesso padding e hover via bordo
 * (il ring di `dsPageToolbarBtn` su una sola cella crea asimmetria visiva).
 */
const timesheetMonthActionBtnClass = [
  dsPageToolbarBtn,
  "w-full min-w-0 flex-1 whitespace-nowrap px-2.5 sm:px-3",
  "isolate",
  "ring-0 hover:ring-0",
  "hover:border-[color:var(--cab-border-strong)]",
  "hover:shadow-[var(--cab-shadow-sm)]",
].join(" ");

function TimesheetPeriodNav({
  periodLabel,
  onPrevious,
  onNext,
}: {
  periodLabel: string;
  onPrevious: () => void;
  onNext: () => void;
}) {
  return (
    <div className="flex shrink-0 items-center gap-2" role="group" aria-label="Navigazione periodo">
      <button type="button" className={dsPageToolbarBtn} onClick={onPrevious} aria-label="Periodo precedente">
        ←
      </button>
      <span className="min-w-[9rem] px-1 text-center text-sm font-medium tabular-nums text-[color:var(--cab-text)]">
        {periodLabel}
      </span>
      <button type="button" className={dsPageToolbarBtn} onClick={onNext} aria-label="Periodo successivo">
        →
      </button>
    </div>
  );
}

export function TimesheetHeader({
  periodMode,
  monthKey,
  onMonthKey,
  weekAnchor,
  onWeekAnchor,
  dayDate,
  onDayDate,
  employees,
  filterEmployeeId,
  onFilterEmployeeId,
  saveStatus,
  showBackgroundSync,
  onGoToToday,
  onFillToday8h,
  fillToday8hPending,
  fillToday8hDisabled,
  fillToday8hDisabledReason,
  monthKeysWithData = [],
}: {
  periodMode: TimesheetPeriodMode;
  monthKey: TimesheetMonthKey;
  onMonthKey: (k: TimesheetMonthKey) => void;
  weekAnchor: string;
  onWeekAnchor: (ymd: string) => void;
  dayDate: string;
  onDayDate: (ymd: string) => void;
  employees: readonly DipendenteTimesheetEmployeeRow[];
  filterEmployeeId: string;
  onFilterEmployeeId: (id: string) => void;
  saveStatus: "idle" | "pending" | "saved" | "error";
  /** Solo sync in background a pagina già caricata; il primo caricamento usa skeleton/error. */
  showBackgroundSync?: boolean;
  onGoToToday: () => void;
  onFillToday8h?: () => void;
  fillToday8hPending?: boolean;
  fillToday8hDisabled?: boolean;
  fillToday8hDisabledReason?: string;
  monthKeysWithData?: readonly TimesheetMonthKey[];
}) {
  const { year, month } = parseMonthKey(monthKey);
  const yearItems = useMemo(
    () =>
      buildTimesheetYearSelectOptions(monthKeysWithData, year).map((o) => ({
        value: String(o.value),
        label: o.label,
      })),
    [monthKeysWithData, year],
  );
  const monthItems = monthOptionsForYear(year).map((o) => ({
    value: String(o.value),
    label: o.label,
  }));

  const employeeItems = useMemo(
    () => [
      { value: "", label: "Tutti i dipendenti" },
      ...employees.map((e) => ({
        value: e.id,
        label: e.in_settings ? e.display_name : `${e.display_name} (storico — non in addetti)`,
      })),
    ],
    [employees],
  );

  const filtersActive = Boolean(filterEmployeeId);
  const filteredCount = filterEmployeeId ? 1 : employees.length;

  const saveLabel =
    saveStatus === "pending"
      ? "Salvataggio in corso…"
      : saveStatus === "saved"
        ? "Salvato"
        : saveStatus === "error"
          ? "Errore salvataggio"
          : null;

  const saveClass =
    saveStatus === "error"
      ? "text-[color:color-mix(in_srgb,var(--cab-danger)_88%,var(--cab-text))]"
      : saveStatus === "saved"
        ? "text-[color:color-mix(in_srgb,var(--cab-success)_88%,var(--cab-text))]"
        : "text-[color:var(--cab-text-muted)]";

  const periodLabel =
    periodMode === "week" ? `Settimana · ${weekAnchor}` : `Giorno · ${dayDate}`;

  const goPreviousPeriod = () => {
    if (periodMode === "week") onWeekAnchor(shiftWeekAnchor(weekAnchor, -1));
    else onDayDate(shiftDayDate(dayDate, -1));
  };

  const goNextPeriod = () => {
    if (periodMode === "week") onWeekAnchor(shiftWeekAnchor(weekAnchor, 1));
    else onDayDate(shiftDayDate(dayDate, 1));
  };

  const filterLabelClass = `${dsTypoSmall} font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)] pointer-events-none select-none`;

  return (
    <ShellCard>
      <section aria-label="Filtri timesheet" className="min-w-0">
        <ToolbarGroup>
          <ToolbarGroupBody>
            <ToolbarGroupPrimaryRow className="items-end gap-2 sm:flex-nowrap sm:justify-start">
              {periodMode !== "month" ? (
                <TimesheetPeriodNav
                  periodLabel={periodLabel}
                  onPrevious={goPreviousPeriod}
                  onNext={goNextPeriod}
                />
              ) : null}
              <div
                className={`grid min-w-0 w-full flex-1 grid-cols-1 gap-2 ${periodMode === "month" ? "sm:grid-cols-4" : "sm:grid-cols-3"}`}
              >
                <div className="flex min-w-0 flex-col gap-1">
                  <span className={filterLabelClass}>Anno</span>
                  <GlobalSelect
                    selectOnly
                    exclusiveGroup="dipendenti-timesheet-filters"
                    value={String(year)}
                    onChange={(v) => onMonthKey(setMonthKeyParts(monthKey, Number(v), month))}
                    items={yearItems}
                    aria-label="Seleziona anno"
                  />
                </div>
                <div className="flex min-w-0 flex-col gap-1">
                  <span className={filterLabelClass}>Mese</span>
                  <GlobalSelect
                    selectOnly
                    preserveItemOrder
                    exclusiveGroup="dipendenti-timesheet-filters"
                    value={String(month)}
                    onChange={(v) => onMonthKey(monthKeyFromParts(year, Number(v)))}
                    items={monthItems}
                    aria-label="Seleziona mese"
                  />
                </div>
                <div className="flex min-w-0 flex-col gap-1">
                  <span className={filterLabelClass}>Dipendente</span>
                  <GlobalSelect
                    selectOnly
                    preserveItemOrder
                    exclusiveGroup="dipendenti-timesheet-filters"
                    value={filterEmployeeId}
                    onChange={onFilterEmployeeId}
                    items={employeeItems}
                    placeholder="Tutti i dipendenti"
                    aria-label="Seleziona dipendente"
                  />
                </div>
                {periodMode === "day" ? (
                  <div className="flex min-w-0 flex-col gap-1 sm:col-span-3">
                    <span className={filterLabelClass}>Giorno</span>
                    <input
                      type="date"
                      className={dsInput}
                      value={dayDate}
                      onChange={(e) => onDayDate(e.target.value || dayDate)}
                      aria-label="Seleziona giorno"
                    />
                  </div>
                ) : null}
                {periodMode === "month" ? (
                  <div
                    className="flex min-w-0 flex-col gap-1"
                    role="group"
                    aria-label="Azioni giorno corrente"
                  >
                    <span className={`${filterLabelClass} hidden min-w-0 sm:block invisible`} aria-hidden="true">
                      &#8203;
                    </span>
                    <div className="flex min-w-0 flex-col gap-2 sm:flex-row sm:items-stretch">
                      <button
                        type="button"
                        className={timesheetMonthActionBtnClass}
                        onClick={onGoToToday}
                        title="Vai al mese corrente e evidenzia la colonna di oggi"
                      >
                        Oggi
                      </button>
                      {onFillToday8h ? (
                        <button
                          type="button"
                          className={timesheetMonthActionBtnClass}
                          onClick={onFillToday8h}
                          disabled={fillToday8hDisabled || fillToday8hPending}
                          aria-busy={fillToday8hPending}
                          title={
                            fillToday8hDisabled && fillToday8hDisabledReason
                              ? fillToday8hDisabledReason
                              : "Imposta 8 ore ordinarie per oggi su tutte le celle vuote degli addetti visibili"
                          }
                        >
                          <span className="sm:hidden">{fillToday8hPending ? "…" : "8h oggi"}</span>
                          <span className="hidden min-w-0 truncate sm:inline">
                            {fillToday8hPending ? "Salvataggio…" : "8h per tutti (oggi)"}
                          </span>
                        </button>
                      ) : null}
                    </div>
                  </div>
                ) : null}
              </div>
            </ToolbarGroupPrimaryRow>
            <ToolbarGroupMetaRow className="!justify-start gap-2">
              <PageToolbarResultCount
                count={filteredCount}
                filtersActive={filtersActive}
                singularLabel="dipendente"
                pluralLabel="dipendenti"
                onFilterReset={filtersActive ? () => onFilterEmployeeId("") : undefined}
              />
              {saveLabel ? (
                <p role="status" aria-live="polite" className={`text-xs font-medium ${saveClass}`}>
                  {saveLabel}
                </p>
              ) : null}
              {showBackgroundSync ? (
                <span className={dsPageToolbarMetaChip} role="status" aria-live="polite">
                  <GlobalLoadingSpinner size="sm" className="shrink-0" label="Registro in aggiornamento" />
                  <span>Registro in aggiornamento</span>
                </span>
              ) : null}
            </ToolbarGroupMetaRow>
          </ToolbarGroupBody>
        </ToolbarGroup>
      </section>
    </ShellCard>
  );
}

export function defaultWeekAnchor(monthKey: TimesheetMonthKey): string {
  return `${monthKey}-01`;
}

export function defaultDayDate(monthKey: TimesheetMonthKey): string {
  const today = dateYmdFromDate(new Date());
  return today.startsWith(monthKey) ? today : `${monthKey}-01`;
}

"use client";

import {
  GlobalHierarchyMarcaSelect,
  GlobalHierarchyModelloSelect,
} from "@/components/gestionale/global-input";
import { GlobalSelect } from "@/components/gestionale/global-input/global-select";
import { globalInputFieldFilter } from "@/lib/ui/global-input";
import { erpFocus } from "@/components/gestionale/lavorazioni/lavorazioni-shared";
import {
  FILTER_ALL,
  type DocumentiAdvancedFilters,
} from "@/lib/documenti/documenti-advanced-filters";
import type { DocumentoGestionale } from "@/lib/types/gestionale";
import type { DocumentiSortKey, DocumentiSortPhase } from "@/components/gestionale/documenti/documenti-helpers";

const filterInputClass = `${globalInputFieldFilter} h-10 py-0 text-sm`;

export function DocumentiAdvancedFilterPanel({
  filters,
  onChange,
  sortSelectValue,
  onSortSelect,
}: {
  filters: DocumentiAdvancedFilters;
  onChange: (patch: Partial<DocumentiAdvancedFilters>) => void;
  sortSelectValue: string;
  onSortSelect: (v: string) => void;
}) {
  return (
    <div className="border-t border-[color:var(--cab-border)] pt-3" aria-label="Filtri documenti">
      <div className="grid gap-3 sm:grid-cols-2 lg:grid-cols-4">
        <div>
          <label className="mb-1 block text-[10px] font-bold uppercase tracking-wide text-zinc-500 dark:text-zinc-400">
            Marca
          </label>
          <GlobalHierarchyMarcaSelect
            tree="attrezzature"
            variant="filter"
            inputClassName={filterInputClass}
            value={filters.marca === FILTER_ALL ? "" : filters.marca}
            onChange={(v) => {
              const marca = v.trim() ? v : FILTER_ALL;
              onChange({ marca, modello: FILTER_ALL });
            }}
            allowAdd={false}
            placeholder="Cerca e seleziona…"
            aria-label="Filtra per marca"
          />
        </div>
        <div>
          <label className="mb-1 block text-[10px] font-bold uppercase tracking-wide text-zinc-500 dark:text-zinc-400">
            Modello
          </label>
          <GlobalHierarchyModelloSelect
            tree="attrezzature"
            variant="filter"
            inputClassName={filterInputClass}
            marcaNome={filters.marca === FILTER_ALL ? "" : filters.marca}
            value={filters.modello === FILTER_ALL ? "" : filters.modello}
            onChange={(v) => onChange({ modello: v.trim() ? v : FILTER_ALL })}
            allowAdd={false}
            disabled={filters.marca === FILTER_ALL}
            placeholder={filters.marca === FILTER_ALL ? "Seleziona prima la marca" : "Cerca e seleziona…"}
            aria-label="Filtra per modello"
          />
        </div>
        <div>
          <label
            htmlFor="doc-filter-sort"
            className="mb-1 block cursor-default text-[10px] font-bold uppercase tracking-wide text-zinc-500 dark:text-zinc-400"
          >
            Ordinamento
          </label>
          <GlobalSelect
            id="doc-filter-sort"
            variant="filter"
            inputClassName={filterInputClass}
            items={[
              { value: "natural", label: "Archivio (marca → modello)" },
              { value: "nome:asc", label: "Nome A → Z" },
              { value: "nome:desc", label: "Nome Z → A" },
              { value: "caricatoIl:desc", label: "Data più recente" },
              { value: "caricatoIl:asc", label: "Data meno recente" },
              { value: "categoria:asc", label: "Categoria A → Z" },
              { value: "marca:asc", label: "Marca A → Z" },
              { value: "macchina:asc", label: "Modello A → Z" },
            ]}
            value={sortSelectValue}
            onChange={onSortSelect}
            strictFromList
            selectOnly
            aria-label="Ordinamento"
          />
        </div>
        <div className="sm:col-span-2 lg:col-span-4">
          <p className="mb-2 text-[10px] font-bold uppercase tracking-wide text-zinc-500 dark:text-zinc-400">
            Categoria
          </p>
          <div className="flex min-w-0 flex-wrap gap-2">
            {(
              [
                [FILTER_ALL, "Tutte"],
                ["listini", "Listini"],
                ["cataloghi", "Cataloghi"],
                ["manuali", "Manuali"],
                ["certificazioni", "Certificazioni"],
                ["altro", "Altro"],
              ] as const
            ).map(([value, label]) => {
              const on = filters.categoria === value;
              return (
                <button
                  key={value}
                  type="button"
                  aria-pressed={on}
                  onClick={() => onChange({ categoria: value as DocumentiAdvancedFilters["categoria"] })}
                  className={`min-h-11 rounded-[var(--ds-radius-lg)] border px-3 py-2 text-xs font-semibold transition-colors ${
                    on
                      ? "border-[color:color-mix(in_srgb,var(--cab-primary)_45%,var(--cab-border))] bg-[color:color-mix(in_srgb,var(--cab-primary)_12%,var(--cab-surface))] text-[color:var(--cab-text)] shadow-[var(--cab-shadow-sm)]"
                      : "border-[color:var(--cab-border)] bg-[var(--cab-surface)] text-[color:var(--cab-text)] hover:border-[color:var(--cab-border-strong)] hover:bg-[var(--cab-hover)]"
                  } ${erpFocus}`}
                >
                  {label}
                </button>
              );
            })}
          </div>
        </div>
      </div>
    </div>
  );
}

export function documentiSortSelectValue(
  sortColumn: DocumentiSortKey | null,
  sortPhase: DocumentiSortPhase,
): string {
  if (sortColumn === null || sortPhase === "natural") return "natural";
  return `${sortColumn}:${sortPhase}`;
}

export function applyDocumentiSortSelect(
  v: string,
  setSortColumn: (k: DocumentiSortKey | null) => void,
  setSortPhase: (p: DocumentiSortPhase) => void,
): void {
  if (!v.trim() || v === "natural") {
    setSortColumn(null);
    setSortPhase("natural");
    return;
  }
  const [col, ph] = v.split(":") as [DocumentiSortKey, DocumentiSortPhase];
  setSortColumn(col);
  setSortPhase(ph === "desc" ? "desc" : "asc");
}

import type { CatalogMacchina, CatalogMarca } from "@/lib/documenti/documenti-catalog-types";
import {
  documentoFileAccessBlockLabel,
  documentoFileOpenFailureMessage,
  getDocumentoFileAccessState,
  type DocumentoFileAccessState,
  type DocumentoFileOpenResult,
} from "@/lib/documenti/documento-file-access";
import { archiveDocumentDeliveryUrl } from "@/lib/documents/document-delivery-url";
import type { DocumentoRow } from "@/src/types/supabase-tables";
import {
  formatDocumentoRigaSintetica,
  labelApplicabilitaBreve,
  legacyAssocRefs,
  resolveDocumentoApplicazione,
} from "@/lib/documenti/documenti-applicabilita";
import {
  inferTipoFileFromNome,
  resolveDocumentoTipoFile,
} from "@/lib/documenti/documento-tipo-file";
import type { DocumentoAssocRef, DocumentoGestionale, DocumentoTipoFile } from "@/lib/types/gestionale";

export { inferTipoFileFromNome, resolveDocumentoTipoFile };
import type { MezzoGestito } from "@/lib/mezzi/types";

export function labelCategoria(c: DocumentoGestionale["categoria"]): string {
  switch (c) {
    case "listini":
      return "Listini";
    case "cataloghi":
      return "Cataloghi";
    case "manuali":
      return "Manuali";
    case "certificazioni":
      return "Certificazioni";
    default:
      return "Altro";
  }
}

export function labelTipoFile(t: DocumentoTipoFile): string {
  switch (t) {
    case "pdf":
      return "PDF";
    case "immagine":
      return "Immagine";
    case "excel":
      return "Excel";
    case "word":
      return "Word";
    case "testo":
      return "Testo";
    default:
      return "Altro";
  }
}

export function getDocAssocRefs(doc: DocumentoGestionale, catalog: CatalogMarca[]): DocumentoAssocRef[] {
  return legacyAssocRefs(doc, catalog);
}

export function assocPairLabel(catalog: CatalogMarca[], ref: DocumentoAssocRef): string {
  const mar = catalog.find((m) => m.id === ref.marcaId);
  const mac = mar?.macchine.find((x) => x.id === ref.macchinaId);
  if (!mar || !mac) return "—";
  return `${mar.nome} ${mac.nome}`;
}

export type DocumentiSortKey = "nome" | "marca" | "macchina" | "caricatoIl" | "categoria";
export type DocumentiSortPhase = "natural" | "asc" | "desc";

import {
  documentoCertificazioneSenzaMarca,
  documentoHaMarcaAssegnata,
  documentoSenzaMarca,
  documentoSenzaMarcaConAvviso,
} from "@/lib/documenti/documenti-senza-marca-classify";

export {
  documentoCertificazioneSenzaMarca,
  documentoHaMarcaAssegnata,
  documentoSenzaMarca,
  documentoSenzaMarcaConAvviso,
};

function compareSenzaMarcaPrima(a: DocumentoGestionale, b: DocumentoGestionale): number {
  const sa = documentoSenzaMarca(a) ? 0 : 1;
  const sb = documentoSenzaMarca(b) ? 0 : 1;
  return sa - sb;
}

export function compareDocs(
  a: DocumentoGestionale,
  b: DocumentoGestionale,
  key: DocumentiSortKey | null,
  phase: DocumentiSortPhase,
  opts?: { skipSenzaMarcaPartition?: boolean },
): number {
  const ra = resolveDocumentoApplicazione(a);
  const rb = resolveDocumentoApplicazione(b);
  if (!opts?.skipSenzaMarcaPartition) {
    const senzaMarcaCmp = compareSenzaMarcaPrima(a, b);
    if (senzaMarcaCmp !== 0) return senzaMarcaCmp;
  }
  if (phase === "natural" || key === null) {
    const m = (ra.marcaKey ?? ra.marca).localeCompare(rb.marcaKey ?? rb.marca, "it");
    if (m !== 0) return m;
    const mac = (ra.modelloKey ?? ra.macchina).localeCompare(rb.modelloKey ?? rb.macchina, "it");
    if (mac !== 0) return mac;
    return a.nome.localeCompare(b.nome, "it");
  }
  const dir = phase === "asc" ? 1 : -1;
  switch (key) {
    case "nome":
      return a.nome.localeCompare(b.nome, "it") * dir;
    case "marca":
      return (ra.marcaKey ?? ra.marca).localeCompare(rb.marcaKey ?? rb.marca, "it") * dir;
    case "macchina":
      return (ra.modelloKey ?? ra.macchina).localeCompare(rb.modelloKey ?? rb.macchina, "it") * dir;
    case "caricatoIl":
      return (a.caricatoIl.localeCompare(b.caricatoIl, "it") || a.nome.localeCompare(b.nome, "it")) * dir;
    case "categoria":
      return (a.categoria.localeCompare(b.categoria, "it") || a.nome.localeCompare(b.nome, "it")) * dir;
    default:
      return 0;
  }
}

export type ArchiveDocModelloNode = { modello: CatalogMacchina; files: DocumentoGestionale[] };
export type ArchiveDocMarcaNode = { marca: CatalogMarca; filesMarca: DocumentoGestionale[]; modelli: ArchiveDocModelloNode[] };

/** Conteggio documenti per id marca (da elenco filtrato, non paginato). */
export function buildDocumentiCountByMarcaId(
  docs: DocumentoGestionale[],
  catalog: CatalogMarca[],
): Map<string, number> {
  const counts = new Map<string, number>();
  for (const m of catalog) counts.set(m.id, 0);
  for (const d of docs) {
    if (documentoSenzaMarca(d)) continue;
    const r = resolveDocumentoApplicazione(d);
    const mar = catalog.find((m) => sameMarca(m.nome, r.marcaKey ?? r.marca));
    if (mar) counts.set(mar.id, (counts.get(mar.id) ?? 0) + 1);
  }
  return counts;
}

/** Solo presentazione UI: listini di marca vs altri documenti con applicabilità «marca». */
export function partitionMarcaLevelDocs(filesMarca: DocumentoGestionale[]): {
  listini: DocumentoGestionale[];
  altriMarca: DocumentoGestionale[];
} {
  const listini = filesMarca.filter((d) => d.categoria === "listini");
  const altriMarca = filesMarca.filter((d) => d.categoria !== "listini");
  return { listini, altriMarca };
}

function normalizeKey(value: string): string {
  return value
    .trim()
    .toLowerCase()
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();
}

function sameMarca(a: string, b: string): boolean {
  return normalizeKey(a) === normalizeKey(b);
}

function removeMarcaPrefix(modelName: string, marcaName: string): string {
  const model = modelName.trim();
  const marca = marcaName.trim();
  if (!model || !marca) return model;
  const modelNorm = normalizeKey(model);
  const marcaNorm = normalizeKey(marca);
  if (!modelNorm.startsWith(marcaNorm)) return model;
  const re = new RegExp(`^${marca.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s*[-:]?\\s*`, "i");
  return model.replace(re, "").trim();
}

function sameModello(a: string, b: string, marcaName?: string): boolean {
  const left = normalizeKey(a);
  const right = normalizeKey(b);
  if (left === right) return true;
  if (!marcaName?.trim()) return false;
  const leftNoBrand = normalizeKey(removeMarcaPrefix(a, marcaName));
  const rightNoBrand = normalizeKey(removeMarcaPrefix(b, marcaName));
  return leftNoBrand.length > 0 && rightNoBrand.length > 0 && leftNoBrand === rightNoBrand;
}

/**
 * True se il documento ha un posto nell’albero (marca in catalogo da impostazioni/mezzi e, se serve, modello o mezzo coerente).
 * I documenti che restano fuori vanno mostrati nella sezione “senza collocazione”.
 */
export function documentoCollocatoInCatalogo(
  doc: DocumentoGestionale,
  catalog: CatalogMarca[],
  _mezzi: MezzoGestito[],
): boolean {
  if (documentoSenzaMarca(doc)) return false;
  const r = resolveDocumentoApplicazione(doc);
  const marcaNome = (r.marcaKey ?? r.marca).trim();
  const mar = catalog.find((m) => sameMarca(m.nome, marcaNome));
  if (!mar) return false;
  if (r.applicabilita === "marca") return true;
  const modNome = (r.modelloKey ?? r.macchina).trim();
  if (r.applicabilita === "modello") {
    if (!modNome || modNome === "—") return false;
    return mar.macchine.some((mac) => sameModello(mac.nome, modNome, mar.nome));
  }
  return false;
}

/** Albero: marca → (documenti intera marca) → modello → (documenti modello). */
export function buildDocumentiViewTree(
  catalog: CatalogMarca[],
  _mezzi: MezzoGestito[],
  sortedDocs: DocumentoGestionale[],
  sortColumn: DocumentiSortKey | null,
  sortPhase: DocumentiSortPhase,
): ArchiveDocMarcaNode[] {
  const out: ArchiveDocMarcaNode[] = [];
  for (const marca of catalog) {
    const filesMarca: DocumentoGestionale[] = [];
    const modelli: ArchiveDocModelloNode[] = [];

    for (const d of sortedDocs) {
      if (documentoSenzaMarca(d)) continue;
      const r = resolveDocumentoApplicazione(d);
      if (r.applicabilita === "marca" && sameMarca(r.marcaKey ?? r.marca, marca.nome)) filesMarca.push(d);
    }
    filesMarca.sort((a, b) => compareDocs(a, b, sortColumn, sortPhase, { skipSenzaMarcaPartition: true }));

    for (const mac of marca.macchine) {
      const filesModello: DocumentoGestionale[] = [];
      for (const d of sortedDocs) {
        if (documentoSenzaMarca(d)) continue;
        const r = resolveDocumentoApplicazione(d);
        if (r.applicabilita !== "modello") continue;
        if (!sameMarca(r.marcaKey ?? r.marca, marca.nome)) continue;
        if (!sameModello(r.modelloKey ?? r.macchina, mac.nome, marca.nome)) continue;
        filesModello.push(d);
      }
      filesModello.sort((a, b) => compareDocs(a, b, sortColumn, sortPhase, { skipSenzaMarcaPartition: true }));

      if (filesModello.length > 0) {
        modelli.push({
          modello: mac,
          files: filesModello,
        });
      }
    }

    if (filesMarca.length === 0 && modelli.length === 0) continue;
    out.push({ marca, filesMarca, modelli });
  }
  return out;
}

/** Conteggio documenti in un nodo marca dell'albero (marca + modelli). */
export function countDocsInMarcaNode(node: ArchiveDocMarcaNode): number {
  return node.filesMarca.length + node.modelli.reduce((n, m) => n + m.files.length, 0);
}

export function getDocumentoFileAccess(doc: DocumentoGestionale): DocumentoFileAccessState {
  return getDocumentoFileAccessState(doc);
}

export function canOpenDocumento(doc: DocumentoGestionale): boolean {
  return getDocumentoFileAccessState(doc).canOpen;
}

export function documentoFileUnavailableLabel(doc: DocumentoGestionale): string | null {
  const access = getDocumentoFileAccessState(doc);
  if (access.canOpen || !access.blockReason) return null;
  return documentoFileAccessBlockLabel(access.blockReason);
}

/** Apre il file via proxy server (RBAC + cache) o blob locale pre-save. */
export async function openDocumentoFile(
  doc: DocumentoGestionale,
  _row?: Pick<DocumentoRow, "url_file">,
): Promise<DocumentoFileOpenResult> {
  const access = getDocumentoFileAccessState(doc);
  if (access.hasLocalBlob && doc.urlBlob?.trim()) {
    window.open(doc.urlBlob.trim(), "_blank", "noopener,noreferrer");
    return { ok: true, href: doc.urlBlob.trim() };
  }
  if (!access.canOpen || !doc.id) {
    const code =
      access.blockReason === "legacy_url_unparsed"
        ? "legacy_unparsed"
        : access.blockReason === "no_file_linked"
          ? "no_path"
          : "unknown";
    return {
      ok: false,
      code,
      message: access.blockReason ? documentoFileAccessBlockLabel(access.blockReason) : documentoFileOpenFailureMessage("no_path"),
    };
  }
  const href = archiveDocumentDeliveryUrl(doc.id, "preview", doc.caricatoIl || doc.ultimaModifica);
  window.open(href, "_blank", "noopener,noreferrer");
  return { ok: true, href };
}

export { documentoFileOpenFailureMessage };

export function extractFileExtension(fileName: string): string {
  const i = fileName.lastIndexOf(".");
  if (i <= 0 || i === fileName.length - 1) return "";
  return fileName.slice(i).toLowerCase();
}

/** Nome file senza estensione (per precompilazione campo «Nome file»). */
export function stripFileExtension(fileName: string): string {
  const i = fileName.lastIndexOf(".");
  if (i <= 0) return fileName.trim();
  return fileName.slice(0, i).trim();
}

export { formatDocumentoRigaSintetica, labelApplicabilitaBreve, resolveDocumentoApplicazione };

