"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { GestionaleAiActionButton, LoadingButton } from "@/components/design-system";
import { LavorazioniModalShell } from "@/components/gestionale/lavorazioni/lavorazioni-modals";
import { GestionaleModalScrollBody } from "@/components/gestionale/mobile-modal-scroll-body";
import { GlobalSelect } from "@/components/gestionale/global-input";
import { erpBtnAccent } from "@/components/gestionale/lavorazioni/lavorazioni-shared";
import {
  executeListinoImportRequest,
  fetchListinoImportPreview,
} from "@/lib/magazzino/listino-import/listino-import-client";
import type {
  ListinoImportAction,
  ListinoImportDecision,
  ListinoImportExecuteResult,
  ListinoImportPreviewResult,
} from "@/lib/magazzino/listino-import/listino-import-types";
import { cabModalLayerClass } from "@/lib/ui/mobile-modal-behavior";
import { gestionaleModalBodyFlexClass } from "@/lib/ui/modal-max-width-class";
import { dsScrollX } from "@/lib/ui/scroll-system";
import { useGestionaleToast } from "@/src/hooks/use-gestionale-toast";

const ACTION_LABELS: Record<ListinoImportAction, string> = {
  create: "Crea",
  skip: "Salta",
  update: "Aggiorna",
};

type RowState = ListinoImportPreviewResult["rows"][number] & { action: ListinoImportAction };

function toDecisions(rows: RowState[]): ListinoImportDecision[] {
  return rows.map((r) => ({
    rowIndex: r.rowIndex,
    action: r.action,
    codice: r.codice,
    descrizione: r.descrizione,
    costo: r.costo,
    marca: r.marca,
    duplicateRicambioId: r.duplicateRicambioId,
  }));
}

export function ListinoImportPreviewModal({
  documentoId,
  onRequestClose,
  onCompleted,
}: {
  documentoId: string;
  onRequestClose: () => void;
  onCompleted?: (result: ListinoImportExecuteResult) => void;
}) {
  const gestToast = useGestionaleToast();
  const [loading, setLoading] = useState(true);
  const [executing, setExecuting] = useState(false);
  const [preview, setPreview] = useState<ListinoImportPreviewResult | null>(null);
  const [rows, setRows] = useState<RowState[]>([]);
  const [error, setError] = useState<string | null>(null);
  const [summary, setSummary] = useState<ListinoImportExecuteResult | null>(null);

  useEffect(() => {
    let cancelled = false;
    setLoading(true);
    setError(null);
    void fetchListinoImportPreview(documentoId)
      .then((data) => {
        if (cancelled) return;
        setPreview(data);
        setRows(data.rows.map((r) => ({ ...r, action: r.suggestedAction })));
      })
      .catch((e) => {
        if (cancelled) return;
        setError(e instanceof Error ? e.message : "Analisi listino non riuscita.");
      })
      .finally(() => {
        if (!cancelled) setLoading(false);
      });
    return () => {
      cancelled = true;
    };
  }, [documentoId]);

  const statsLine = useMemo(() => {
    if (!preview) return "";
    return `${preview.rows.length} righe · ${preview.stats.duplicates} duplicati · metodo ${preview.parseMethod}`;
  }, [preview]);

  const setBulkAction = useCallback((action: ListinoImportAction, onlyDuplicates = false) => {
    setRows((prev) =>
      prev.map((r) => {
        if (onlyDuplicates && !r.duplicateRicambioId) return r;
        if (!onlyDuplicates && r.duplicateRicambioId && action === "create") return r;
        return { ...r, action };
      }),
    );
  }, []);

  async function handleExecute() {
    if (!preview || executing) return;
    setExecuting(true);
    setError(null);
    try {
      const result = await executeListinoImportRequest({
        documentoId: preview.documentoId,
        batchId: preview.batchId,
        decisions: toDecisions(rows),
      });
      setSummary(result);
      gestToast.successOnce(
        "listino-import-done",
        `Import completato: ${result.created} creati, ${result.updated} aggiornati, ${result.skipped} saltati.`,
      );
      onCompleted?.(result);
    } catch (e) {
      const message = e instanceof Error ? e.message : "Import non riuscito.";
      setError(message);
      gestToast.errorOnce("listino-import-fail", message, { module: "magazzino" });
    } finally {
      setExecuting(false);
    }
  }

  return (
    <LavorazioniModalShell
      modalSize="analytics"
      layerClassName={cabModalLayerClass("base")}
      onRequestClose={onRequestClose}
      title="Import listino in magazzino"
      titleId="listino-import-modal-title"
      footer={
        summary ? (
          <button type="button" className={`${erpBtnAccent} min-h-11 w-full`} onClick={onRequestClose}>
            Chiudi
          </button>
        ) : (
          <GestionaleAiActionButton
            type="button"
            className="min-h-11 w-full justify-center"
            loading={executing}
            disabled={loading || !!error || !rows.length}
            onClick={() => void handleExecute()}
          >
            Importa selezionati
          </GestionaleAiActionButton>
        )
      }
    >
      <div className={`${gestionaleModalBodyFlexClass} min-h-0 overflow-hidden`}>
        <GestionaleModalScrollBody className="space-y-3">
          {loading ? (
            <p className="text-sm text-[color:var(--cab-text-muted)]">Analisi listino in corso…</p>
          ) : null}
          {error ? (
            <p className="rounded-lg border border-red-500/40 bg-red-500/10 px-3 py-2 text-sm text-red-200" role="alert">
              {error}
            </p>
          ) : null}
          {preview && !summary ? (
            <>
              <div className="space-y-1">
                <p className="text-sm font-medium text-[color:var(--cab-text)]">{preview.documentoNome}</p>
                <p className="text-xs text-[color:var(--cab-text-muted)]">{statsLine}</p>
                {preview.warnings.map((w) => (
                  <p key={w} className="text-xs text-amber-600 dark:text-amber-300">
                    {w}
                  </p>
                ))}
              </div>
              <div className="flex flex-wrap gap-2">
                <LoadingButton type="button" className="text-xs px-2 py-1" onClick={() => setBulkAction("create")}>
                  Tutti: crea
                </LoadingButton>
                <LoadingButton type="button" className="text-xs px-2 py-1" onClick={() => setBulkAction("skip")}>
                  Tutti: salta
                </LoadingButton>
                <LoadingButton
                  type="button"
                  className="text-xs px-2 py-1"
                  onClick={() => setBulkAction("update", true)}
                >
                  Duplicati: aggiorna
                </LoadingButton>
              </div>
              <div className={`${dsScrollX} rounded-lg border border-[color:var(--cab-border)]`}>
                <table className="min-w-full text-left text-xs">
                  <thead className="bg-[var(--cab-surface-2)]/80 text-[color:var(--cab-text-muted)]">
                    <tr>
                      <th className="px-2 py-2">Codice</th>
                      <th className="px-2 py-2">Descrizione</th>
                      <th className="px-2 py-2">Costo</th>
                      <th className="px-2 py-2">Azione</th>
                    </tr>
                  </thead>
                  <tbody>
                    {rows.map((row) => (
                      <tr key={row.rowIndex} className="border-t border-[color:var(--cab-border)]">
                        <td className="px-2 py-1.5 font-mono">{row.codice}</td>
                        <td className="max-w-[16rem] truncate px-2 py-1.5">{row.descrizione}</td>
                        <td className="px-2 py-1.5 whitespace-nowrap">{row.costo.toFixed(2)} €</td>
                        <td className="px-2 py-1.5">
                          <GlobalSelect
                            items={[
                              { value: "create", label: ACTION_LABELS.create },
                              { value: "skip", label: ACTION_LABELS.skip },
                              { value: "update", label: ACTION_LABELS.update },
                            ]}
                            value={row.action}
                            onChange={(v) =>
                              setRows((prev) =>
                                prev.map((r) =>
                                  r.rowIndex === row.rowIndex ? { ...r, action: v as ListinoImportAction } : r,
                                ),
                              )
                            }
                            selectOnly
                            strictFromList
                            aria-label={`Azione riga ${row.codice}`}
                            className="min-w-[7rem]"
                          />
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </>
          ) : null}
          {summary ? (
            <div className="rounded-lg border border-[color:var(--cab-border)] bg-[var(--cab-surface-2)]/50 px-3 py-2 text-sm">
              <p className="font-medium text-[color:var(--cab-text)]">Import completato</p>
              <p className="mt-1 text-[color:var(--cab-text-muted)]">
                Creati: {summary.created} · Aggiornati: {summary.updated} · Saltati: {summary.skipped}
              </p>
              {summary.errors.length ? (
                <p className="mt-1 text-amber-600 dark:text-amber-300">
                  {summary.errors.length} righe con errori.
                </p>
              ) : null}
            </div>
          ) : null}
        </GestionaleModalScrollBody>
      </div>
    </LavorazioniModalShell>
  );
}

"use client";

import type { FocusEvent, FormEvent, KeyboardEvent, ReactNode } from "react";
import { flushSync } from "react-dom";
import { IOS_SUBMIT_GUARD_TARGET_ATTR } from "@/lib/forms/form-engine/ios-submit-guard";
import { gestionaleAdvanceFocusOnEnter } from "@/lib/ui/gestionale-focus-navigation";

/** Props SSOT per textarea multiriga: Enter inserisce newline, non avanza il focus. */
export const gestionaleMultilineEnterProps = { "data-gestionale-enter": "ignore" } as const;

export type GestionaleFormFocusScopeProps = {
  children: ReactNode;
  className?: string;
  /** Attributo scope per delimitare l'ordine tab (default: div). */
  as?: "div" | "form" | "section";
};

/**
 * Abilita ENTER → focus sul campo successivo per input/textarea nativi nel subtree.
 * I combobox globali (`GlobalSelect`, ricerca con suggerimenti) gestiscono ENTER autonomamente.
 */
function onScopeKeyDown(e: KeyboardEvent) {
  if (e.defaultPrevented) return;
  gestionaleAdvanceFocusOnEnter(e);
}

/** Capture: drain batch React; combobox flush centralizzato in prepareFormSubmitAsync post-guard. */
function onScopeSubmitCapture(_e: FormEvent<HTMLFormElement>) {
  flushSync(() => {});
}

/** Traccia ultimo input testuale nel form per iosSubmitGuard quando Salva sposta il focus (iOS). */
function onScopeFocusCapture(e: FocusEvent<HTMLElement>) {
  const target = e.target;
  if (!(target instanceof HTMLInputElement || target instanceof HTMLTextAreaElement)) return;
  const scope = e.currentTarget;
  scope.querySelectorAll(`[${IOS_SUBMIT_GUARD_TARGET_ATTR}]`).forEach((el) => {
    el.removeAttribute(IOS_SUBMIT_GUARD_TARGET_ATTR);
  });
  target.setAttribute(IOS_SUBMIT_GUARD_TARGET_ATTR, "true");
}

export function GestionaleFormFocusScope({
  children,
  className = "",
  as: Tag = "div",
}: GestionaleFormFocusScopeProps) {
  return (
    <Tag className={className} data-gestionale-focus-scope onKeyDown={onScopeKeyDown}>
      {children}
    </Tag>
  );
}

/** Props da spalmare su `<form>` esistenti (modali, wizard). */
export function gestionaleFormFocusScopeProps(): {
  "data-gestionale-focus-scope": true;
  onKeyDown: (e: KeyboardEvent<HTMLElement>) => void;
  onFocusCapture: (e: FocusEvent<HTMLElement>) => void;
  onSubmitCapture: (e: FormEvent<HTMLFormElement>) => void;
} {
  return {
    "data-gestionale-focus-scope": true,
    onKeyDown: onScopeKeyDown,
    onFocusCapture: onScopeFocusCapture,
    onSubmitCapture: onScopeSubmitCapture,
  };
}

"use client";

/** @deprecated Usare `GlobalAsyncSelect` o `GlobalSelect` con opzioni mezzi. Non cablato in produzione. */

import { useCallback, useId, useMemo, useRef, useState } from "react";
import { createPortal } from "react-dom";
import Link from "next/link";
import { GestionaleSearchField } from "@/components/gestionale/gestionale-search-field";
import {
  useDropdownOutsideDismiss,
  useGlobalDropdownPortal,
} from "@/components/gestionale/global-input/use-global-dropdown-portal";
import { mezzoMatchesSmartQuery } from "@/lib/mezzi/identificazione-mezzo";
import type { MezzoGestito } from "@/lib/mezzi/types";
import { dsBtnNeutral, dsLabel } from "@/lib/ui/design-system";
import { globalInputDropdownPortalPanel } from "@/lib/ui/global-input";
import { useMezziListQuery } from "@/src/hooks/gestionale/use-entity-list-queries";
import { debugSelectOptions } from "@/src/shared/selectors";

function mezzoUiLabel(m: MezzoGestito): string {
  const marcaModello = `${m.marca} ${m.modello}`.trim();
  const extra = [m.targa?.trim(), m.matricola?.trim()].filter(Boolean).join(" · ");
  return extra ? `${marcaModello} · ${extra}` : marcaModello;
}

export type GestionaleMezzoAutocompleteProps = {
  value: string;
  onChange: (mezzoId: string) => void;
  disabled?: boolean;
  enabled?: boolean;
  required?: boolean;
  /** Mostra link alla pagina Mezzi per creare un nuovo record. */
  showCreateLink?: boolean;
  className?: string;
};

/**
 * Autocomplete mezzi da archivio Supabase (lista globale, non select statico).
 */
export function GestionaleMezzoAutocomplete({
  value,
  onChange,
  disabled,
  enabled = true,
  required,
  showCreateLink = true,
  className = "",
}: GestionaleMezzoAutocompleteProps) {
  const mezziQ = useMezziListQuery(undefined, { enabled, staleTime: 30_000 });
  const [q, setQ] = useState("");
  const [open, setOpen] = useState(false);
  const [focused, setFocused] = useState(false);
  const wrapRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLUListElement>(null);
  const inputId = useId();

  const mezziUi = useMemo(() => {
    const rows = mezziQ.data ?? [];
    debugSelectOptions("GestionaleMezzoAutocomplete", {
      source: "mezziService.getAll",
      count: rows.length,
      isLoading: mezziQ.isLoading,
    });
    return [...rows].sort((a, b) => mezzoUiLabel(a).localeCompare(mezzoUiLabel(b), "it"));
  }, [mezziQ.data, mezziQ.isLoading]);

  const selected = useMemo(() => mezziUi.find((m) => m.id === value) ?? null, [mezziUi, value]);

  const filtered = useMemo(() => {
    if (!q.trim()) return mezziUi.slice(0, 24);
    return mezziUi.filter((m) => mezzoMatchesSmartQuery(m, q)).slice(0, 24);
  }, [mezziUi, q]);

  const showDropdown = open && focused && q.trim().length > 0 && !disabled && !mezziQ.isLoading;

  const { style: portalStyle, scrollInside, placementOriginClass } = useGlobalDropdownPortal({
    open: showDropdown,
    anchorRef: wrapRef,
    contentRef: panelRef,
    repositionDeps: [filtered.length, q],
  });

  const dismiss = useCallback(() => {
    setOpen(false);
    setFocused(false);
  }, []);

  useDropdownOutsideDismiss(showDropdown, wrapRef, panelRef, dismiss);

  const menu =
    showDropdown && portalStyle ? (
      <ul
        ref={panelRef}
        role="listbox"
        aria-label="Suggerimenti mezzi"
        style={portalStyle}
        className={`${globalInputDropdownPortalPanel} space-y-1 p-1.5 ${placementOriginClass} ${
          scrollInside ? "overflow-y-auto" : "overflow-hidden"
        }`}
      >
        {filtered.length === 0 ? (
          <li className="px-2 py-2 text-xs text-[color:var(--cab-text-muted)]">Nessun mezzo corrispondente.</li>
        ) : (
          filtered.map((m) => (
            <li key={m.id} role="presentation">
              <button
                type="button"
                role="option"
                className="w-full rounded-md px-2 py-1.5 text-left text-xs transition hover:bg-[color:color-mix(in_srgb,var(--cab-primary)_12%,transparent)]"
                onMouseDown={(e) => e.preventDefault()}
                onClick={() => {
                  onChange(m.id);
                  setQ("");
                  dismiss();
                }}
              >
                <span className="font-medium text-[color:var(--cab-text)]">{mezzoUiLabel(m)}</span>
              </button>
            </li>
          ))
        )}
      </ul>
    ) : null;

  return (
    <div className={`block min-w-0 ${className}`.trim()}>
      <span className={dsLabel}>
        Mezzo
        {required ? <span className="text-red-600"> *</span> : null}
      </span>
      {mezziQ.isError ? (
        <p className="mt-1 text-xs text-red-600 dark:text-red-400">{mezziQ.error?.message ?? "Errore caricamento mezzi."}</p>
      ) : null}
      {selected && !q.trim() ? (
        <p className="mt-1 rounded-md border border-[color:var(--cab-border)] bg-[var(--cab-surface-muted)] px-2.5 py-1.5 text-xs text-[color:var(--cab-text)]">
          Selezionato: <span className="font-medium">{mezzoUiLabel(selected)}</span>
          <button
            type="button"
            className="ml-2 text-[color:var(--cab-primary)] underline-offset-2 hover:underline"
            onClick={() => {
              onChange("");
              setQ("");
            }}
            disabled={disabled}
          >
            Cambia
          </button>
        </p>
      ) : (
        <div ref={wrapRef} className="relative mt-1">
          <GestionaleSearchField
            id={inputId}
            value={q}
            onChange={(e) => {
              setQ(e.target.value);
              setOpen(true);
            }}
            onFocus={() => {
              setFocused(true);
              setOpen(true);
            }}
            onBlur={() => {
              setFocused(false);
            }}
            placeholder="Cerca per targa, matricola, cliente, marca…"
            disabled={disabled || mezziQ.isLoading}
            aria-label="Cerca mezzo in archivio"
          />
          {mezziQ.isLoading ? (
            <p className="mt-1 text-xs text-[color:var(--cab-text-muted)]">Caricamento mezzi…</p>
          ) : null}
          {typeof document !== "undefined" && menu ? createPortal(menu, document.body) : null}
        </div>
      )}
      {showCreateLink ? (
        <p className="mt-2 text-[11px] text-[color:var(--cab-text-muted)]">
          Mezzo non in elenco?{" "}
          <Link href="/mezzi" className="font-semibold text-[color:var(--cab-primary)] hover:underline">
            Apri archivio mezzi
          </Link>{" "}
          per registrarne uno nuovo.
        </p>
      ) : null}
      {required && !value.trim() ? (
        <input type="text" required className="sr-only" tabIndex={-1} value="" readOnly aria-hidden />
      ) : null}
    </div>
  );
}

