"use client";

import {
  useCallback,
  useEffect,
  useId,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type ChangeEvent,
  type ClipboardEvent,
} from "react";
import { createPortal } from "react-dom";
import { GlobalCalendarPanel, initialViewFromYmd, parseDisplayToYmd } from "@/components/gestionale/global-input/global-calendar-panel";
import {
  useDropdownOutsideDismiss,
  useGlobalDropdownPortal,
} from "@/components/gestionale/global-input/use-global-dropdown-portal";
import {
  dateInputValueToIso,
  isoToDateInputValue,
  isoToItDisplay,
  ymdToItDisplay,
} from "@/lib/lavorazioni/date-day-only";
import { scheduleFocusNextGestionaleField } from "@/lib/ui/gestionale-focus-navigation";
import {
  applyItalianDateMaskChange,
  applyItalianDateBackspace,
  applyItalianDateForwardDelete,
  normalizeItalianDatePaste,
  parseItalianDayDisplayToIso,
  validateItalianDateInput,
  type ItalianDateYearRange,
} from "@/lib/ui/italian-date-input-mask";
import {
  extractDatePickerShellLayoutClass,
  globalInputCalendarPortalPanel,
  globalInputDatePickerCalendarBtn,
  globalInputDatePickerInput,
  globalInputDatePickerShellDefault,
  globalInputDatePickerShellFilter,
  globalInputInvalidMessage,
  globalInputInvalidRing,
  stripDatePickerFieldChrome,
} from "@/lib/ui/global-input";

export type GlobalDatePickerProps = {
  /** Testo visualizzato gg/mm/aaaa (vuoto = nessuna data). */
  value: string;
  onChange: (display: string) => void;
  variant?: "default" | "filter";
  inputClassName?: string;
  id?: string;
  required?: boolean;
  disabled?: boolean;
  placeholder?: string;
  "aria-label"?: string;
  /** Se impostato, sostituisce la normalizzazione predefinita su blur. */
  onBlur?: () => void;
  /** Range anno per feedback UX (default 1900–2100). */
  yearRange?: ItalianDateYearRange;
};

function shellClassForVariant(variant: "default" | "filter"): string {
  return variant === "filter" ? globalInputDatePickerShellFilter : globalInputDatePickerShellDefault;
}

function inputSegmentClassForVariant(
  variant: "default" | "filter",
  inputClassName?: string,
): string {
  const base =
    variant === "default" ? `${globalInputDatePickerInput} py-2.5` : globalInputDatePickerInput;
  if (!inputClassName?.trim()) return base;
  const extra = stripDatePickerFieldChrome(inputClassName);
  return extra ? `${base} ${extra}` : base;
}

function shellLayoutClassFromInput(inputClassName?: string): string {
  if (!inputClassName?.trim()) return "";
  return extractDatePickerShellLayoutClass(inputClassName);
}

export function GlobalDatePicker({
  value,
  onChange,
  variant = "default",
  inputClassName,
  id: idProp,
  required,
  disabled,
  placeholder = "gg/mm/aaaa",
  "aria-label": ariaLabel,
  onBlur: onBlurProp,
  yearRange,
}: GlobalDatePickerProps) {
  const autoId = useId();
  const inputId = idProp ?? autoId;
  const errorId = `${inputId}-date-error`;
  const inputRef = useRef<HTMLInputElement>(null);
  const pendingCursor = useRef<number | null>(null);
  const wrapRef = useRef<HTMLDivElement>(null);
  const panelRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const selectedYmd = parseDisplayToYmd(value);
  const initial = initialViewFromYmd(selectedYmd);
  const [viewYear, setViewYear] = useState(initial.year);
  const [viewMonth, setViewMonth] = useState(initial.month);

  const validation = useMemo(
    () => validateItalianDateInput(value, { yearRange }),
    [value, yearRange],
  );
  const showInvalid = validation.status === "invalid" && value.trim().length > 0;

  const shellClass = shellClassForVariant(variant);
  const shellLayoutClass = shellLayoutClassFromInput(inputClassName);
  const inputClass = inputSegmentClassForVariant(variant, inputClassName);
  const shellCombined = showInvalid
    ? `${shellClass}${shellLayoutClass ? ` ${shellLayoutClass}` : ""}${globalInputInvalidRing}`
    : `${shellClass}${shellLayoutClass ? ` ${shellLayoutClass}` : ""}`;

  const closeCalendar = useCallback(() => setOpen(false), []);

  const { style: portalStyle, placementOriginClass } = useGlobalDropdownPortal({
    open,
    anchorRef: wrapRef,
    contentRef: panelRef,
    matchAnchorWidth: true,
    maxHeight: 420,
    repositionDeps: [viewYear, viewMonth, selectedYmd],
  });

  useDropdownOutsideDismiss(open, wrapRef, panelRef, closeCalendar);

  useEffect(() => {
    if (!open) return;
    const v = initialViewFromYmd(selectedYmd);
    setViewYear(v.year);
    setViewMonth(v.month);
  }, [open, selectedYmd]);

  useLayoutEffect(() => {
    if (pendingCursor.current === null || !inputRef.current) return;
    const pos = pendingCursor.current;
    pendingCursor.current = null;
    inputRef.current.setSelectionRange(pos, pos);
  });

  const applyMaskedChange = useCallback(
    (nextRaw: string, selectionStart: number) => {
      const { display, cursor } = applyItalianDateMaskChange(value, nextRaw, selectionStart);
      pendingCursor.current = cursor;
      onChange(display);
    },
    [onChange, value],
  );

  const onInputChange = useCallback(
    (e: ChangeEvent<HTMLInputElement>) => {
      applyMaskedChange(e.target.value, e.target.selectionStart ?? 0);
    },
    [applyMaskedChange],
  );

  const onPaste = useCallback(
    (e: ClipboardEvent<HTMLInputElement>) => {
      e.preventDefault();
      const pasted = normalizeItalianDatePaste(e.clipboardData.getData("text"));
      const el = e.currentTarget;
      const selStart = el.selectionStart ?? 0;
      const selEnd = el.selectionEnd ?? selStart;
      const newRaw = value.slice(0, selStart) + pasted + value.slice(selEnd);
      applyMaskedChange(newRaw, selStart + pasted.length);
    },
    [applyMaskedChange, value],
  );

  const applyYmd = useCallback(
    (ymd: string) => {
      if (!ymd) {
        onChange("");
        setOpen(false);
        return;
      }
      const r = dateInputValueToIso(ymd);
      if (r.ok) onChange(isoToItDisplay(r.iso));
      setOpen(false);
    },
    [onChange],
  );

  const onTextBlur = useCallback(() => {
    const trimmed = value.trim();
    if (!trimmed) {
      onChange("");
      return;
    }
    const r = parseItalianDayDisplayToIso(trimmed);
    if (r.ok) onChange(isoToItDisplay(r.iso));
  }, [onChange, value]);

  const calendarPortal =
    open && portalStyle ? (
      <div
        ref={panelRef}
        style={{ ...portalStyle, maxHeight: "none" }}
        className={placementOriginClass}
      >
        <GlobalCalendarPanel
          panelClassName={globalInputCalendarPortalPanel}
          selectedYmd={selectedYmd}
          viewYear={viewYear}
          viewMonth={viewMonth}
          onViewChange={(y, m) => {
            setViewYear(y);
            setViewMonth(m);
          }}
          onSelectYmd={applyYmd}
        />
      </div>
    ) : null;

  return (
    <div className="w-full">
      <div ref={wrapRef} className={shellCombined}>
        <input
          ref={inputRef}
          id={inputId}
          type="text"
          inputMode="numeric"
          autoComplete="off"
          required={required}
          disabled={disabled}
          placeholder={placeholder}
          aria-label={ariaLabel}
          aria-invalid={showInvalid || undefined}
          aria-describedby={showInvalid ? errorId : undefined}
          className={inputClass}
          value={value}
          onChange={onInputChange}
          onPaste={onPaste}
          onBlur={onBlurProp ?? onTextBlur}
          onKeyDown={(e) => {
            if (e.key === "Escape") {
              setOpen(false);
              return;
            }
            if (e.key === "Enter") {
              e.preventDefault();
              if (open) {
                setOpen(false);
              } else {
                (onBlurProp ?? onTextBlur)();
              }
              scheduleFocusNextGestionaleField(e.currentTarget);
              return;
            }
            if (disabled) return;
            const el = e.currentTarget;
            const selStart = el.selectionStart ?? 0;
            const selEnd = el.selectionEnd ?? selStart;
            if (e.key === "Backspace" && !e.ctrlKey && !e.metaKey && !e.altKey) {
              const r = applyItalianDateBackspace(value, selStart, selEnd);
              if (r) {
                e.preventDefault();
                pendingCursor.current = r.cursor;
                onChange(r.display);
              }
              return;
            }
            if (e.key === "Delete" && !e.ctrlKey && !e.metaKey && !e.altKey) {
              const r = applyItalianDateForwardDelete(value, selStart, selEnd);
              if (r) {
                e.preventDefault();
                pendingCursor.current = r.cursor;
                onChange(r.display);
              }
            }
          }}
        />
        <button
          type="button"
          className={globalInputDatePickerCalendarBtn}
          aria-label="Apri calendario"
          aria-expanded={open}
          disabled={disabled}
          onClick={() => setOpen((o) => !o)}
        >
          <svg className="h-4 w-4" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2}>
            <path
              strokeLinecap="round"
              strokeLinejoin="round"
              d="M8 7V3m8 4V3m-9 8h10M5 21h14a2 2 0 002-2V7a2 2 0 00-2-2H5a2 2 0 00-2 2v12a2 2 0 002 2z"
            />
          </svg>
        </button>
      </div>
      {showInvalid && validation.message ? (
        <p id={errorId} className={globalInputInvalidMessage}>
          {validation.message}
        </p>
      ) : null}
      {typeof document !== "undefined" && calendarPortal ? createPortal(calendarPortal, document.body) : null}
    </div>
  );
}

function displayFromYmd(valueYmd: string): string {
  return valueYmd ? ymdToItDisplay(valueYmd) : "";
}

/** Filtri con valore interno `yyyy-mm-dd`. */
export function GlobalDatePickerYmd({
  valueYmd,
  onChangeYmd,
  id,
  placeholder = "gg/mm/aaaa",
  "aria-label": ariaLabel,
  variant = "filter",
  yearRange,
}: {
  valueYmd: string;
  onChangeYmd: (ymd: string) => void;
  id?: string;
  placeholder?: string;
  "aria-label"?: string;
  variant?: "default" | "filter";
  yearRange?: ItalianDateYearRange;
}) {
  const [displayDraft, setDisplayDraft] = useState(() => displayFromYmd(valueYmd));

  useEffect(() => {
    setDisplayDraft(displayFromYmd(valueYmd));
  }, [valueYmd]);

  const commitBlur = useCallback(() => {
    const trimmed = displayDraft.trim();
    if (!trimmed) {
      setDisplayDraft("");
      onChangeYmd("");
      return;
    }
    const r = parseItalianDayDisplayToIso(trimmed);
    if (r.ok) {
      const display = isoToItDisplay(r.iso);
      const ymd = isoToDateInputValue(r.iso);
      setDisplayDraft(display);
      onChangeYmd(ymd);
      return;
    }
    setDisplayDraft(trimmed);
  }, [displayDraft, onChangeYmd]);

  return (
    <GlobalDatePicker
      id={id}
      variant={variant}
      value={displayDraft}
      placeholder={placeholder}
      aria-label={ariaLabel}
      yearRange={yearRange}
      onChange={(next) => {
        setDisplayDraft(next);
        if (!next.trim()) {
          onChangeYmd("");
          return;
        }
        const r = parseItalianDayDisplayToIso(next);
        if (r.ok) onChangeYmd(isoToDateInputValue(r.iso));
      }}
      onBlur={commitBlur}
    />
  );
}

/** Alias per filtri toolbar (compatibilità `LavorazioniFilterDateField`). */
export const GlobalFilterDateField = GlobalDatePickerYmd;

"use client";

/**
 * Select a elenco fisso (senza ricerca): pill colorata + menu a tendina.
 * Standard globale per stato, priorità, addetto in tabella/card Lavorazioni e casi analoghi.
 * Per elenchi con ricerca/fuzzy/aggiunta valori usare `GlobalSelect`.
 */

import {
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
  type CSSProperties,
} from "react";
import { createPortal } from "react-dom";
import { dsFocus } from "@/lib/ui/design-system";
import { globalFixedListPillMenuPanel } from "@/lib/ui/global-input";
import {
  useDropdownOutsideDismiss,
  useGlobalDropdownPortal,
} from "@/components/gestionale/global-input/use-global-dropdown-portal";
import { GestionaleSearchableSheetSelect } from "@/components/gestionale/global-input/gestionale-searchable-sheet-select";
import { useDropdownFocusRestore } from "@/lib/ui/use-dropdown-focus-restore";
import { useClientHydrated } from "@/lib/ui/use-client-hydrated";
import { useMaxMdDown } from "@/lib/ui/use-max-md-down";
import { armSelectorGhostClickGuard } from "@/lib/selector-interaction/suppress-selector-ghost-click";

export type FixedListPillOption = {
  value: string;
  label: string;
  /** Colori pill per voce (es. stato/priorità/addetto da impostazioni). */
  pillStyle?: CSSProperties;
};

const pillChevron = (
  <svg className="h-3.5 w-3.5 shrink-0" fill="none" viewBox="0 0 24 24" stroke="currentColor" strokeWidth={2.5} aria-hidden>
    <path strokeLinecap="round" strokeLinejoin="round" d="M19 9l-7 7-7-7" />
  </svg>
);

export const fixedListPillTextClass = "text-[13px] font-medium leading-tight tracking-wide";

export const fixedListPillMinH = "min-h-8";

export function GlobalFixedListPillSelect({
  value,
  onChange,
  options,
  ariaLabel,
  disabled,
  title,
  /** Classi layout pill (bordo, ombra, focus ring) — un solo contenitore visivo. */
  shellClass,
  /** Stile pill selezionata se le opzioni non definiscono `pillStyle`. */
  fallbackPillStyle,
  mobileSheet = true,
  sheetTitle,
}: {
  value: string;
  onChange: (next: string) => void;
  options: readonly FixedListPillOption[];
  ariaLabel: string;
  disabled?: boolean;
  title?: string;
  shellClass?: string;
  fallbackPillStyle?: CSSProperties;
  /** Bottom sheet mobile senza ricerca (default: true). */
  mobileSheet?: boolean;
  /** Titolo sheet mobile (default: ariaLabel). */
  sheetTitle?: string;
}) {
  const listId = useId();
  const triggerRef = useRef<HTMLButtonElement>(null);
  const menuRef = useRef<HTMLUListElement>(null);
  const shellRef = useRef<HTMLDivElement>(null);
  const sheetListScrollRef = useRef<HTMLDivElement>(null);
  const [open, setOpen] = useState(false);
  const [activeIndex, setActiveIndex] = useState(-1);
  const hydrated = useClientHydrated();
  const isMobile = useMaxMdDown();
  const useMobileSheet = hydrated && isMobile && mobileSheet;
  const { restoreFocus, captureFocus } = useDropdownFocusRestore(open);
  const selected = options.find((o) => o.value === value);
  const triggerStyle = selected?.pillStyle ?? fallbackPillStyle;
  const resolvedSheetTitle = sheetTitle ?? ariaLabel;

  const close = useCallback(() => {
    setOpen(false);
    setActiveIndex(-1);
    restoreFocus();
  }, [restoreFocus]);

  const anchorRef = shellRef;

  const { style: portalStyle, scrollInside, placementOriginClass } = useGlobalDropdownPortal({
    open: open && !useMobileSheet,
    anchorRef,
    contentRef: menuRef,
    repositionDeps: [options.length],
  });

  useDropdownOutsideDismiss(open && !useMobileSheet, shellRef, menuRef, close);

  useEffect(() => {
    if (!open) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") {
        close();
        return;
      }
      if (options.length === 0) return;
      if (e.key === "ArrowDown") {
        e.preventDefault();
        setActiveIndex((i) => (i + 1) % options.length);
        return;
      }
      if (e.key === "ArrowUp") {
        e.preventDefault();
        setActiveIndex((i) => (i <= 0 ? options.length - 1 : i - 1));
        return;
      }
      if (e.key === "Enter" && activeIndex >= 0 && activeIndex < options.length) {
        e.preventDefault();
        onChange(options[activeIndex]!.value);
        close();
      }
    };
    document.addEventListener("keydown", onKey);
    return () => document.removeEventListener("keydown", onKey);
  }, [open, close, options, activeIndex, onChange]);

  const renderOption = (opt: FixedListPillOption, idx: number, variant: "dropdown" | "sheet") => {
    const active = opt.value === value;
    const highlighted = idx === activeIndex;
    const optStyle = opt.pillStyle ?? fallbackPillStyle;
    const touchMinH = variant === "sheet" ? "min-h-11" : "min-h-11 sm:min-h-0";
    const touchPy = variant === "sheet" ? "py-2.5" : "py-2.5 sm:py-1.5";
    return (
      <li key={opt.value} role="presentation" className={variant === "sheet" ? "px-2 py-1" : "py-0.5"}>
        <button
          type="button"
          role="option"
          aria-selected={active}
          style={optStyle}
          className={`w-full ${touchMinH} cursor-pointer rounded-md border px-2 ${touchPy} text-center ${fixedListPillTextClass} transition-[filter,box-shadow] duration-150 hover:brightness-[1.06] ${dsFocus} ${
            active ? "ring-2 ring-inset ring-white/35 shadow-sm" : ""
          }${highlighted && !active ? " ring-2 ring-inset ring-white/20" : ""}`}
          onMouseEnter={() => setActiveIndex(idx)}
          onPointerDown={
            variant === "sheet"
              ? (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  armSelectorGhostClickGuard();
                  onChange(opt.value);
                  close();
                }
              : undefined
          }
          onClick={
            variant === "dropdown"
              ? () => {
                  onChange(opt.value);
                  close();
                }
              : (e) => {
                  e.preventDefault();
                  e.stopPropagation();
                }
          }
        >
          {opt.label}
        </button>
      </li>
    );
  };

  const menu =
    open && portalStyle && !useMobileSheet ? (
      <ul
        ref={menuRef}
        id={listId}
        role="listbox"
        aria-label={ariaLabel}
        style={portalStyle}
        className={`${globalFixedListPillMenuPanel} ${placementOriginClass} ${
          scrollInside ? "overflow-y-auto" : "overflow-hidden"
        }`}
      >
        {options.map((opt, idx) => renderOption(opt, idx, "dropdown"))}
      </ul>
    ) : null;

  return (
    <div ref={shellRef} className={`relative flex w-full ${fixedListPillMinH} items-stretch`}>
      <button
        ref={triggerRef}
        type="button"
        style={triggerStyle}
        className={`flex min-h-8 w-full min-w-0 cursor-pointer items-center justify-center gap-1 px-2 py-1 text-center ${fixedListPillTextClass} outline-none transition-[filter,box-shadow,background-color,border-color,color] duration-150 hover:brightness-[1.04] disabled:cursor-not-allowed disabled:opacity-60 ${dsFocus} ${shellClass ?? "rounded-lg border border-black/10 shadow-sm dark:border-white/10"}`}
        aria-label={ariaLabel}
        aria-haspopup="listbox"
        aria-expanded={open}
        aria-controls={listId}
        disabled={disabled}
        title={title}
        onClick={() => {
          if (disabled) return;
          if (useMobileSheet) {
            captureFocus();
            setOpen(true);
            setActiveIndex(-1);
            return;
          }
          setOpen((o) => !o);
          setActiveIndex(-1);
        }}
      >
        <span className="min-w-0 truncate">{selected?.label ?? value}</span>
        {pillChevron}
      </button>
      {typeof document !== "undefined" && menu ? createPortal(menu, document.body) : null}
      <GestionaleSearchableSheetSelect
        open={open && useMobileSheet}
        onOpenChange={(next) => {
          if (!next) close();
          else setOpen(true);
        }}
        title={resolvedSheetTitle}
        showSearch={false}
        searchValue=""
        onSearchChange={() => {}}
        listScrollRef={sheetListScrollRef}
      >
        <ul id={listId} role="listbox" aria-label={ariaLabel}>
          {options.map((opt, idx) => renderOption(opt, idx, "sheet"))}
        </ul>
      </GestionaleSearchableSheetSelect>
    </div>
  );
}

"use client";

import { memo, useCallback, useMemo, useState } from "react";
import { GlobalSelect } from "@/components/gestionale/global-input/global-select";
import { dsFocus } from "@/lib/ui/design-system";
import {
  globalMultiSelectChipClass,
  globalMultiSelectChipRemoveClass,
  globalMultiSelectEmbeddedInputClass,
  globalMultiSelectShellClass,
} from "@/lib/ui/global-input";
import type { SelectorDomain } from "@/lib/selector-core/types";

type SelectedChip = { value: string; label?: string; title?: string };

export const GlobalMultiSelect = memo(function GlobalMultiSelect({
  ariaLabel,
  placeholder = "Cerca…",
  disabled,
  options,
  selected,
  onAdd,
  onRemove,
  className = "",
  emptyMessage = "Nessun risultato",
  allowAdd = false,
  canAdd = true,
  addPending = false,
  onAddToList,
  selectorDomain,
}: {
  ariaLabel: string;
  placeholder?: string;
  disabled?: boolean;
  options: readonly string[];
  selected: readonly SelectedChip[];
  onAdd: (value: string) => void;
  onRemove: (value: string) => void;
  className?: string;
  emptyMessage?: string;
  allowAdd?: boolean;
  canAdd?: boolean;
  addPending?: boolean;
  onAddToList?: (value: string) => Promise<string | null> | string | null;
  selectorDomain?: SelectorDomain;
}) {
  const [draft, setDraft] = useState("");

  const selectedSet = useMemo(() => new Set(selected.map((s) => s.value)), [selected]);
  const filteredOptions = useMemo(() => options.filter((o) => !selectedSet.has(o)), [options, selectedSet]);

  const addValue = useCallback(
    async (v: string) => {
      const clean = v.trim();
      if (!clean) return;
      if (selectedSet.has(clean)) {
        setDraft("");
        return;
      }

      const inOptions = options.some((o) => o.trim().toLowerCase() === clean.toLowerCase());
      let canonical = clean;
      if (!inOptions && onAddToList) {
        try {
          const added = await onAddToList(clean);
          if (!added) return;
          canonical = added;
        } catch {
          return;
        }
      } else if (!inOptions && !allowAdd) {
        return;
      }

      if (selectedSet.has(canonical)) {
        setDraft("");
        return;
      }
      onAdd(canonical);
      setDraft("");
    },
    [allowAdd, onAdd, onAddToList, options, selectedSet],
  );

  const handleSelectChange = useCallback(
    (next: string) => {
      void addValue(next);
    },
    [addValue],
  );

  const handleAddToListCommit = useCallback(
    (v: string) => {
      void addValue(v);
    },
    [addValue],
  );

  const selectedSummary =
    selected.length === 1 ? "1 selezionato" : `${selected.length} selezionati`;

  return (
    <div className={className} role="group" aria-label={ariaLabel}>
      <div className={globalMultiSelectShellClass}>
        {selected.length > 0 ? (
          <div
            className="flex min-w-0 flex-wrap gap-1.5 border-b border-[color:var(--cab-border)] px-2.5 pb-1.5 pt-2"
            role="list"
            aria-label={selectedSummary}
          >
            {selected.map((s) => {
              const chipLabel = s.label ?? s.value;
              const chipTitle = s.title ?? chipLabel;
              return (
                <span key={s.value} role="listitem" className={globalMultiSelectChipClass}>
                  <span className="truncate" title={chipTitle}>
                    {chipLabel}
                  </span>
                  <button
                    type="button"
                    title={`Rimuovi ${chipTitle}`}
                    aria-label={`Rimuovi ${chipTitle}`}
                    onMouseDown={(e) => {
                      e.preventDefault();
                      e.stopPropagation();
                    }}
                    onClick={(e) => {
                      e.stopPropagation();
                      onRemove(s.value);
                    }}
                    className={`${dsFocus} ${globalMultiSelectChipRemoveClass}`}
                    disabled={disabled}
                  >
                    <span aria-hidden>×</span>
                  </button>
                </span>
              );
            })}
          </div>
        ) : null}
        <GlobalSelect
          value={draft}
          onChange={handleSelectChange}
          options={filteredOptions}
          placeholder={placeholder}
          disabled={disabled}
          allowAdd={allowAdd}
          canAdd={canAdd}
          addPending={addPending}
          onAddToList={onAddToList ? handleAddToListCommit : undefined}
          strictFromList={!allowAdd}
          emptyMessage={emptyMessage}
          invalidMessage="Seleziona un valore esistente"
          aria-label={ariaLabel}
          selectorDomain={selectorDomain}
          inputClassName={globalMultiSelectEmbeddedInputClass}
        />
      </div>
    </div>
  );
});

