"use client";

import {
  autoUpdate,
  flip,
  offset,
  shift,
  size,
  useFloating,
  type Placement,
} from "@floating-ui/react-dom";
import {
  useCallback,
  useLayoutEffect,
  useMemo,
  useState,
  type CSSProperties,
  type RefObject,
} from "react";
import {
  CAB_FIELD_LABEL_ATTR,
  findGestionaleFieldContainer,
} from "@/lib/ui/mobile-modal-behavior";
import { subscribeGestionaleViewport } from "@/lib/ui/gestionale-viewport-orchestrator";
import {
  GLOBAL_DROPDOWN_MAX_HEIGHT,
  GLOBAL_DROPDOWN_MENU_GAP,
  GLOBAL_DROPDOWN_PORTAL_Z,
  globalDropdownPortalDetectOverflowOptions,
  globalDropdownPlacementOriginClass,
  type GlobalDropdownCoords,
  type GlobalDropdownPlacement,
} from "@/lib/ui/global-dropdown-portal";

export type UseGlobalDropdownPortalOptions = {
  open: boolean;
  anchorRef: RefObject<HTMLElement | null>;
  contentRef?: RefObject<HTMLElement | null>;
  repositionDeps?: readonly unknown[];
  placement?: Placement;
  /** Larghezza pannello = anchor (default true). */
  matchAnchorWidth?: boolean;
  /** Larghezza fissa (es. calendario). */
  panelWidth?: number;
  maxHeight?: number;
};

export type UseGlobalDropdownPortalResult = {
  coords: GlobalDropdownCoords | null;
  style: CSSProperties | undefined;
  /** True quando Floating UI ha calcolato x/y (evita flash in posizione errata). */
  isPositioned: boolean;
  /** Callback ref per il pannello portal — sincronizza `contentRef` e `refs.setFloating`. */
  floatingRef: (node: HTMLElement | null) => void;
  scrollInside: boolean;
  placement: Placement;
  placementOriginClass: string;
};

function placementAxis(placement: Placement): GlobalDropdownPlacement {
  return placement.startsWith("top") ? "top" : "bottom";
}

export function useGlobalDropdownPortal({
  open,
  anchorRef,
  contentRef,
  repositionDeps = [],
  placement = "bottom-start",
  matchAnchorWidth = true,
  panelWidth,
  maxHeight = GLOBAL_DROPDOWN_MAX_HEIGHT,
}: UseGlobalDropdownPortalOptions): UseGlobalDropdownPortalResult {
  const [scrollInside, setScrollInside] = useState(false);
  const portalOverflow = globalDropdownPortalDetectOverflowOptions();

  const {
    refs,
    floatingStyles,
    placement: resolvedPlacement,
    update,
    isPositioned: floatingIsPositioned,
  } = useFloating({
    open,
    placement,
    strategy: "fixed",
    /** `top`/`left` invece di `transform` — evita conflitto con animazioni CSS sui menu portal. */
    transform: false,
    middleware: [
      offset(GLOBAL_DROPDOWN_MENU_GAP),
      flip({
        ...portalOverflow,
        fallbackPlacements: ["top-start", "bottom-start", "top-end", "bottom-end"],
      }),
      shift({ ...portalOverflow, crossAxis: true }),
      size({
        ...portalOverflow,
        apply({ availableHeight, availableWidth, rects, elements }) {
          const capped = Math.min(maxHeight, Math.max(80, availableHeight));
          const width =
            panelWidth != null
              ? Math.min(panelWidth, availableWidth)
              : matchAnchorWidth
                ? rects.reference.width
                : undefined;
          Object.assign(elements.floating.style, {
            maxHeight: `${capped}px`,
            ...(width != null ? { width: `${width}px` } : { maxWidth: `${availableWidth}px` }),
          });
        },
      }),
    ],
    whileElementsMounted: open
      ? (reference, floating, updateFn) =>
          autoUpdate(reference, floating, updateFn, {
            ancestorScroll: true,
            ancestorResize: true,
            elementResize: true,
            layoutShift: true,
          })
      : undefined,
  });

  const floatingRef = useCallback(
    (node: HTMLElement | null) => {
      if (contentRef) {
        (contentRef as { current: HTMLElement | null }).current = node;
      }
      refs.setFloating(node);
    },
    [contentRef, refs],
  );

  useLayoutEffect(() => {
    if (!open) {
      refs.setReference(null);
      refs.setFloating(null);
      return;
    }
    const anchor = anchorRef.current;
    if (anchor) refs.setReference(anchor);
  }, [open, anchorRef, refs, ...repositionDeps]);

  useLayoutEffect(() => {
    if (!open) return;
    const panel = contentRef?.current;
    if (panel) refs.setFloating(panel);
  }, [open, contentRef, refs, floatingIsPositioned, ...repositionDeps]);

  useLayoutEffect(() => {
    if (!open) return;
    update();
  }, [open, update, ...repositionDeps]);

  useLayoutEffect(() => {
    if (!open) return;
    return subscribeGestionaleViewport(() => {
      update();
    });
  }, [open, update]);

  useLayoutEffect(() => {
    if (!open || !contentRef?.current) {
      setScrollInside(false);
      return;
    }
    const el = contentRef.current;
    const measure = () => {
      setScrollInside(el.scrollHeight > el.clientHeight + 1);
    };
    measure();
    const ro = typeof ResizeObserver !== "undefined" ? new ResizeObserver(measure) : null;
    ro?.observe(el);
    return () => ro?.disconnect();
  }, [open, contentRef, floatingStyles, ...repositionDeps]);

  const isPositioned = open && floatingIsPositioned;

  const style: CSSProperties | undefined = useMemo(() => {
    if (!open) return undefined;
    return {
      ...floatingStyles,
      zIndex: GLOBAL_DROPDOWN_PORTAL_Z,
      visibility: isPositioned ? "visible" : "hidden",
      pointerEvents: isPositioned ? undefined : "none",
    };
  }, [open, floatingStyles, isPositioned]);

  const coords: GlobalDropdownCoords | null = useMemo(() => {
    if (!open || !anchorRef.current) return null;
    const anchorRect = anchorRef.current.getBoundingClientRect();
    const floatingRect = contentRef?.current?.getBoundingClientRect();
    const width = panelWidth ?? (matchAnchorWidth ? anchorRect.width : floatingRect?.width ?? anchorRect.width);
    return {
      top: floatingRect?.top ?? anchorRect.bottom + GLOBAL_DROPDOWN_MENU_GAP,
      left: floatingRect?.left ?? anchorRect.left,
      width,
      maxHeight,
      scrollInside,
      placement: placementAxis(resolvedPlacement),
    };
  }, [
    open,
    anchorRef,
    contentRef,
    panelWidth,
    matchAnchorWidth,
    maxHeight,
    scrollInside,
    resolvedPlacement,
  ]);

  const placementOriginClass = globalDropdownPlacementOriginClass(resolvedPlacement);

  return {
    coords,
    style,
    isPositioned,
    floatingRef,
    scrollInside,
    placement: resolvedPlacement,
    placementOriginClass,
  };
}

function isPointerInsidePanel(e: PointerEvent, panel: HTMLElement): boolean {
  if (panel.contains(e.target as Node)) return true;
  const rect = panel.getBoundingClientRect();
  if (rect.width <= 0 || rect.height <= 0) return false;
  return (
    e.clientX >= rect.left &&
    e.clientX <= rect.right &&
    e.clientY >= rect.top &&
    e.clientY <= rect.bottom
  );
}

function isFieldCaptionElement(el: HTMLElement): boolean {
  if (el.tagName === "LABEL") return true;
  if (el.hasAttribute(CAB_FIELD_LABEL_ATTR)) return true;
  if (el.tagName === "P" || el.tagName === "SPAN") {
    const cls = typeof el.className === "string" ? el.className : "";
    return cls.includes("font-medium");
  }
  return false;
}

/** True se il pointer è sull'etichetta associata al controllo (evita dismiss+reopen flash). */
export function isPointerOnAssociatedFieldLabel(target: Node, anchor: HTMLElement): boolean {
  const wrappingLabel = anchor.closest("label");
  if (wrappingLabel?.contains(target)) return true;

  if (target instanceof Element) {
    const forLabel = target.closest("label[for]");
    if (forLabel) {
      const forId = forLabel.getAttribute("for");
      if (forId) {
        for (const el of anchor.querySelectorAll("[id]")) {
          if (el instanceof HTMLElement && el.id === forId) return true;
        }
      }
    }
  }

  const container = findGestionaleFieldContainer(anchor);
  if (container && target instanceof Element) {
    for (const ch of container.children) {
      if (!(ch instanceof HTMLElement)) continue;
      if (ch === anchor || anchor.contains(ch)) continue;
      if (!ch.contains(target) && ch !== target) continue;
      if (isFieldCaptionElement(ch)) return true;
    }
  }

  return false;
}

export type UseDropdownOutsideDismissOptions = {
  /** false: listener disattivato (es. pannello non ancora posizionato). */
  when?: boolean;
};

/** Chiude il menu se il tap/click è fuori da anchor e pannello portal. */
export function useDropdownOutsideDismiss(
  open: boolean,
  anchorRef: RefObject<HTMLElement | null>,
  panelRef: RefObject<HTMLElement | null>,
  onDismiss: () => void,
  options?: UseDropdownOutsideDismissOptions,
): void {
  const when = options?.when ?? true;
  const onDismissStable = useCallback(() => onDismiss(), [onDismiss]);

  useLayoutEffect(() => {
    if (!open || !when) return;
    function onDocPointerDown(e: PointerEvent) {
      const target = e.target as Node;
      const anchor = anchorRef.current;
      if (anchor?.contains(target)) return;
      if (anchor && isPointerOnAssociatedFieldLabel(target, anchor)) return;
      const panel = panelRef.current;
      if (panel && isPointerInsidePanel(e, panel)) return;
      onDismissStable();
    }
    document.addEventListener("pointerdown", onDocPointerDown, true);
    return () => document.removeEventListener("pointerdown", onDocPointerDown, true);
  }, [open, when, anchorRef, panelRef, onDismissStable]);
}

"use client";

import {
  isValidElement,
  useLayoutEffect,
  useRef,
  useState,
  type ReactNode,
  type RefObject,
} from "react";
import { useVirtualizer } from "@tanstack/react-virtual";
import { dsScrollbar } from "@/lib/ui/design-system";
import {
  globalTableBase,
  globalTableEmptyCell,
  globalTableFixed,
  globalTableRow,
  globalTableWrap,
  globalTableTbodyInset,
} from "@/lib/ui/global-table";
import { GlobalTableHead } from "@/components/gestionale/global-table/global-table-header";

export type GlobalTableVirtualRows = {
  rowCount: number;
  renderRow: (index: number) => ReactNode;
  estimateRowHeight?: number;
  overscan?: number;
};

export type GlobalTableProps = {
  /** Celle `<th>` dentro la riga header (wrappa automaticamente `<thead><tr>`). */
  headRow: ReactNode;
  /** Righe `<tr>` del body. */
  children: ReactNode;
  colgroup?: ReactNode;
  /** `table-fixed` + colgroup consigliato per liste dense. */
  fixed?: boolean;
  className?: string;
  wrapClassName?: string;
  /** Es. `hidden md:block` per desktop-only accanto a card mobile. */
  visibilityClass?: string;
  stickyHead?: boolean;
  empty?: boolean;
  emptyMessage?: string;
  colSpan?: number;
  /** Virtualizza il tbody — riduce DOM su liste paginate dense (pilot Magazzino). */
  virtualRows?: GlobalTableVirtualRows;
};

function normalizeColgroup(node: ReactNode): ReactNode {
  if (node == null) return null;
  if (isValidElement(node) && node.type === "colgroup") return node;
  return <colgroup>{node}</colgroup>;
}

function VirtualTableBody({
  scrollRef,
  virtualRows,
  colSpan,
}: {
  scrollRef: RefObject<HTMLDivElement | null>;
  virtualRows: GlobalTableVirtualRows;
  colSpan: number;
}) {
  const [, setMeasureTick] = useState(0);
  const [renderFallback, setRenderFallback] = useState(false);

  const virtualizer = useVirtualizer({
    count: virtualRows.rowCount,
    getScrollElement: () => scrollRef.current,
    estimateSize: () => virtualRows.estimateRowHeight ?? 52,
    overscan: virtualRows.overscan ?? 8,
  });

  useLayoutEffect(() => {
    if (virtualRows.rowCount === 0) {
      setRenderFallback(false);
      return;
    }

    setRenderFallback(false);
    let cancelled = false;
    let rafId = 0;
    let ro: ResizeObserver | null = null;
    let attempts = 0;
    const maxAttempts = 24;

    const remeasure = () => {
      if (cancelled) return;
      const before = virtualizer.getVirtualItems().length;
      virtualizer.measure();
      if (virtualizer.getVirtualItems().length !== before) {
        setMeasureTick((tick) => tick + 1);
      }
    };

    const bind = () => {
      if (cancelled || attempts >= maxAttempts) {
        const el = scrollRef.current;
        if (
          !cancelled &&
          virtualizer.getVirtualItems().length === 0 &&
          virtualRows.rowCount > 0 &&
          el &&
          el.clientHeight > 0
        ) {
          setRenderFallback(true);
        }
        return;
      }
      attempts += 1;
      const el = scrollRef.current;
      if (!el) {
        rafId = requestAnimationFrame(bind);
        return;
      }
      if (!ro) {
        ro = new ResizeObserver(remeasure);
        ro.observe(el);
      }
      remeasure();
      if (virtualizer.getVirtualItems().length === 0 && el.clientHeight > 0) {
        rafId = requestAnimationFrame(bind);
      }
    };

    bind();

    return () => {
      cancelled = true;
      cancelAnimationFrame(rafId);
      ro?.disconnect();
    };
  }, [scrollRef, virtualRows.rowCount, virtualizer]);

  const items = virtualizer.getVirtualItems();

  if (renderFallback && virtualRows.rowCount > 0) {
    return (
      <tbody className={globalTableTbodyInset}>
        {Array.from({ length: virtualRows.rowCount }, (_, index) => virtualRows.renderRow(index))}
      </tbody>
    );
  }

  const paddingTop = items.length > 0 ? items[0]!.start : 0;
  const paddingBottom =
    items.length > 0 ? virtualizer.getTotalSize() - items[items.length - 1]!.end : 0;

  return (
    <tbody className={globalTableTbodyInset}>
      {paddingTop > 0 ? (
        <tr className={globalTableRow} aria-hidden>
          <td colSpan={colSpan} style={{ height: paddingTop, padding: 0, border: 0 }} />
        </tr>
      ) : null}
      {items.map((item) => virtualRows.renderRow(item.index))}
      {paddingBottom > 0 ? (
        <tr className={globalTableRow} aria-hidden>
          <td colSpan={colSpan} style={{ height: paddingBottom, padding: 0, border: 0 }} />
        </tr>
      ) : null}
    </tbody>
  );
}

/**
 * Shell tabella gestionale — design globale (header Preventivi).
 * Logica sorting/filtri/paginazione resta nelle pagine; qui solo layout/UI.
 */
export function GlobalTable({
  headRow,
  children,
  colgroup,
  fixed = true,
  className = "",
  wrapClassName = "",
  visibilityClass = "",
  stickyHead = false,
  empty,
  emptyMessage = "Nessun risultato.",
  colSpan = 1,
  virtualRows,
}: GlobalTableProps) {
  const scrollRef = useRef<HTMLDivElement>(null);
  const tableClass = `${fixed ? globalTableFixed : globalTableBase} ${className}`.trim();
  const useVirtual = Boolean(virtualRows && !empty && virtualRows.rowCount > 0);

  return (
    <div
      ref={scrollRef}
      className={`${globalTableWrap} ${dsScrollbar} ${visibilityClass} ${wrapClassName}`.trim()}
    >
      <table className={tableClass}>
        {normalizeColgroup(colgroup)}
        <GlobalTableHead sticky={stickyHead}>{headRow}</GlobalTableHead>
        {useVirtual && virtualRows ? (
          <VirtualTableBody scrollRef={scrollRef} virtualRows={virtualRows} colSpan={colSpan} />
        ) : (
          <tbody className={globalTableTbodyInset}>
            {empty ? (
              <tr className={globalTableRow}>
                <td colSpan={colSpan} className={globalTableEmptyCell}>
                  {emptyMessage}
                </td>
              </tr>
            ) : (
              children
            )}
          </tbody>
        )}
      </table>
    </div>
  );
}

