        const resolved = await waitForConcurrencyResolution(res);
        setConcurrencyDialog(null);
        if (!resolved) {
          if (snapshot !== undefined) rollbackSchedeStore(qc, snapshot);
          return { ok: false, kind: "error", error: "Salvataggio annullato." };
