"use client";

import { useCallback, useEffect, useState } from "react";
import type { AttrezzaturaGestita } from "@/lib/attrezzature/types";
import { attrezzatureForMezzo } from "@/lib/mezzi/mezzi-db-ui-adapter";
import { attrezzatureService } from "@/src/services/attrezzature.service";
import type { AttrezzaturaRow } from "@/src/types/supabase-tables";
import { MezziHubList, MezziHubListItem, MezziHubListMeta, MezziHubListTitle, MezziHubTabEmpty } from "@/components/gestionale/mezzi/mezzi-hub-ui";
import { dsInput } from "@/lib/ui/design-system";
import { LoadingButton } from "@/components/design-system";
import { sliceInputValue, TEXT_SHORT } from "@/lib/validation/text-field-limits";

export function MezziHubAttrezzaturePanel({
  mezzoId,
  canEdit,
}: {
  mezzoId: string;
  canEdit: boolean;
}) {
  const [rows, setRows] = useState<AttrezzaturaGestita[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [marca, setMarca] = useState("");
  const [modello, setModello] = useState("");
  const [matricola, setMatricola] = useState("");
  const [pending, setPending] = useState(false);

  const reload = useCallback(async () => {
    setLoading(true);
    setError(null);
    const res = await attrezzatureService.listByMezzo(mezzoId);
    if (!res.success) {
      setError(res.error ?? "Errore caricamento attrezzature");
      setRows([]);
    } else {
      setRows(attrezzatureForMezzo(res.data as AttrezzaturaRow[], mezzoId));
    }
    setLoading(false);
  }, [mezzoId]);

  useEffect(() => {
    void reload();
  }, [reload]);

  async function handleCreate() {
    if (!marca.trim()) return;
    setPending(true);
    const res = await attrezzatureService.create({
      mezzo_id: mezzoId,
      marca: marca.trim(),
      modello: modello.trim(),
      matricola: matricola.trim() || null,
      tipo_attrezzatura: null,
      portata: null,
      anno: null,
      note: null,
    });
    setPending(false);
    if (!res.success) {
      setError(res.error ?? "Errore creazione attrezzatura");
      return;
    }
    setMarca("");
    setModello("");
    setMatricola("");
    await reload();
  }

  async function handleRemove(id: string) {
    setPending(true);
    const res = await attrezzatureService.remove(id);
    setPending(false);
    if (!res.success) {
      setError(res.error ?? "Errore eliminazione attrezzatura");
      return;
    }
    await reload();
  }

  if (loading) return <MezziHubTabEmpty message="Caricamento attrezzature…" />;
  if (error) return <MezziHubTabEmpty message={error} />;

  return (
    <div className="space-y-3">
      {canEdit ? (
        <div className="grid gap-2 rounded-lg border border-[var(--cab-border)] p-3 sm:grid-cols-4">
          <input
            className={dsInput}
            placeholder="Marca"
            value={marca}
            maxLength={TEXT_SHORT}
            disabled={pending}
            onChange={(e) => setMarca(sliceInputValue(e.target.value, TEXT_SHORT))}
          />
          <input
            className={dsInput}
            placeholder="Modello"
            value={modello}
            maxLength={TEXT_SHORT}
            disabled={pending}
            onChange={(e) => setModello(sliceInputValue(e.target.value, TEXT_SHORT))}
          />
          <input
            className={dsInput}
            placeholder="Matricola"
            value={matricola}
            maxLength={TEXT_SHORT}
            disabled={pending}
            onChange={(e) => setMatricola(sliceInputValue(e.target.value, TEXT_SHORT))}
          />
          <LoadingButton type="button" loading={pending} disabled={!marca.trim()} onClick={() => void handleCreate()}>
            Aggiungi
          </LoadingButton>
        </div>
      ) : null}

      {rows.length === 0 ? (
        <MezziHubTabEmpty message="Nessuna attrezzatura installata su questo mezzo." />
      ) : (
        <MezziHubList>
          {rows.map((a) => (
            <MezziHubListItem
              key={a.id}
              actions={
                canEdit ? (
                  <button
                    type="button"
                    className="text-xs font-semibold text-red-600 hover:underline"
                    disabled={pending}
                    onClick={() => void handleRemove(a.id)}
                  >
                    Elimina
                  </button>
                ) : null
              }
            >
              <MezziHubListTitle>
                {[a.marca, a.modello].filter(Boolean).join(" ")}
              </MezziHubListTitle>
              <MezziHubListMeta>
                {[a.tipoAttrezzatura !== "—" ? a.tipoAttrezzatura : null, a.matricola !== "Non assegnata" ? a.matricola : null]
                  .filter(Boolean)
                  .join(" · ") || "—"}
              </MezziHubListMeta>
            </MezziHubListItem>
          ))}
        </MezziHubList>
      )}
    </div>
  );
}

"use client";

import Link from "next/link";
import { useEffect, useMemo, useState } from "react";
import { TablePagination } from "@/components/gestionale/table-pagination";
import { erpBtnSoftOrange } from "@/components/gestionale/lavorazioni/lavorazioni-shared";
import {
  GestionaleLogEmpty,
  GestionaleLogEntryFourLines,
  GestionaleLogList,
  buildMezziGestionaleLogViewModel,
} from "@/components/gestionale/gestionale-log-ui";
import { canOpenDocumento, formatDocumentoRigaSintetica, openDocumentoFile } from "@/components/gestionale/documenti/documenti-helpers";
import { RecordImageManager } from "@/components/gestionale/media/record-image-manager";
import { GestionaleModalScrollBody } from "@/components/gestionale/mobile-modal-scroll-body";
import { buildPreventiviArchivioFilterHref, buildPreventiviLavorazioneFocusHref } from "@/lib/preventivi/preventivi-lavorazione-href";
import { importPreventiviPdf } from "@/lib/pdf/lazy-pdf-modules";
import { Q_PREVENTIVI_OPEN } from "@/lib/preventivi/preventivi-query";
import { ultimaLavorazioneLabel } from "@/lib/mezzi/mezzi-helpers";
import { hubPanoramicaDisplayValue } from "@/components/design-system/hub-modal-panoramica";
import type { MezzoGestito } from "@/lib/mezzi/types";
import { openUrlInNewTab } from "@/lib/pdf/open-url-new-tab";
import { useMezzoHub } from "@/src/hooks/gestionale/use-mezzo-hub";
import { useClientPagination } from "@/lib/ui/use-client-pagination";
import { useResponsiveListPageSize } from "@/lib/ui/use-responsive-list-page-size";
import { GlobalTableHead, GlobalTableHeadLabel } from "@/components/gestionale/global-table";
import { LavorazioniModalHeader, LavorazioniModalShell } from "@/components/gestionale/lavorazioni/lavorazioni-modals";
import { HubModalTab, HubModalTabBar } from "@/components/design-system/hub-modal-tab-bar";
import { GestionaleInfoCard } from "@/components/design-system/gestionale-info-card";
import {
  HubModalPanoramicaField,
  HubModalPanoramicaFieldGrid,
  HubModalPanoramicaFieldGroup,
  HubModalPanoramicaPanel,
  HubModalPanoramicaSummary,
  HubModalPanoramicaSummaryItem,
} from "@/components/design-system/hub-modal-panoramica";
import {
  MEZZI_HUB_TAB_ORDER,
  MezziHubErrorBanner,
  MezziHubFooter,
  MezziHubList,
  MezziHubListItem,
  MezziHubListMeta,
  MezziHubListSubtitle,
  MezziHubListTitle,
  MezziHubQuickLinks,
  MezziHubSyntheticBanner,
  MezziHubTabEmpty,
  MezziHubTabJumpButton,
  MezziHubTimelineKindBadge,
  fmtMezziHubDt,
  type MezziHubTabId,
} from "@/components/gestionale/mezzi/mezzi-hub-ui";
import { MezziHubAttrezzaturePanel } from "@/components/gestionale/mezzi/mezzi-hub-attrezzature-panel";
import {
  dsScrollbar,
  dsTable,
  dsTableRow,
  dsTableWrap,
  dsBtnDanger,
  dsTableActionTextBtn,
  dsTableActionTextBtnPrimary,
} from "@/lib/ui/design-system";
import { READONLY_PERMISSION_HINT } from "@/src/lib/auth/permissions";
import type { CSSProperties } from "react";

const lavorazioneAttivaPillStyle = (active: boolean): CSSProperties | undefined =>
  active
    ? {
        background: "color-mix(in srgb, var(--cab-success) 22%, var(--cab-card))",
        color: "color-mix(in srgb, var(--cab-success) 92%, var(--cab-text))",
      }
    : {
        background: "color-mix(in srgb, var(--cab-surface-2) 88%, var(--cab-card))",
        color: "var(--cab-text-muted)",
      };

export function MezziHubDetailModal({
  mezzo,
  onClose,
  onEdit,
  onDelete,
  canEdit = true,
}: {
  mezzo: MezzoGestito;
  onClose: () => void;
  onEdit: () => void;
  onDelete?: () => void;
  canEdit?: boolean;
}) {
  const [tab, setTab] = useState<MezziHubTabId>("panoramica");

  const hubQuery = useMezzoHub(mezzo.id);
  const hubData = hubQuery.data;
  const interventi = hubData?.interventi ?? [];
  const preventivi = hubData?.preventivi ?? [];
  const documenti = hubData?.documenti ?? [];
  const hubLogEntries = hubData?.log ?? [];
  const timeline = hubData?.timeline ?? [];

  const nPv = hubData?.preventivi.length ?? 0;
  const nDoc = hubData?.documenti.length ?? 0;
  const nTimeline = hubData?.timeline.length ?? 0;

  const sortedLav = useMemo(() => {
    const rows = [...interventi];
    rows.sort((a, b) => new Date(b.dataIngresso).getTime() - new Date(a.dataIngresso).getTime());
    return rows;
  }, [interventi]);

  const sortedPv = useMemo(() => {
    const rows = [...preventivi];
    rows.sort((a, b) => new Date(b.dataCreazione).getTime() - new Date(a.dataCreazione).getTime());
    return rows;
  }, [preventivi]);

  const listPageSize = useResponsiveListPageSize();

  const {
    page: lavPage,
    setPage: setLavPage,
    pageCount: lavPageCount,
    sliceItems: sliceLav,
    showPager: showLavPager,
    label: lavPagerLabel,
    resetPage: resetLavPage,
  } = useClientPagination(sortedLav.length, listPageSize);
  useEffect(() => {
    resetLavPage();
  }, [mezzo.id, sortedLav.length, listPageSize, resetLavPage]);
  const pagedLav = useMemo(() => sliceLav(sortedLav), [sortedLav, sliceLav, lavPage]);

  const {
    page: pvPage,
    setPage: setPvPage,
    pageCount: pvPageCount,
    sliceItems: slicePv,
    showPager: showPvPager,
    label: pvPagerLabel,
    resetPage: resetPvPage,
  } = useClientPagination(sortedPv.length, listPageSize);
  useEffect(() => {
    resetPvPage();
  }, [mezzo.id, sortedPv.length, listPageSize, resetPvPage]);
  const pagedPv = useMemo(() => slicePv(sortedPv), [sortedPv, slicePv, pvPage]);

  const {
    page: docPage,
    setPage: setDocPage,
    pageCount: docPageCount,
    sliceItems: sliceDoc,
    showPager: showDocPager,
    label: docPagerLabel,
    resetPage: resetDocPage,
  } = useClientPagination(documenti.length, listPageSize);
  useEffect(() => {
    resetDocPage();
  }, [mezzo.id, documenti.length, listPageSize, resetDocPage]);
  const pagedDoc = useMemo(() => sliceDoc(documenti), [documenti, sliceDoc, docPage]);

  const {
    page: hubLogPage,
    setPage: setHubLogPage,
    pageCount: hubLogPageCount,
    sliceItems: sliceHubLog,
    showPager: showHubLogPager,
    label: hubLogPagerLabel,
    resetPage: resetHubLogPage,
  } = useClientPagination(hubLogEntries.length, listPageSize);
  useEffect(() => {
    resetHubLogPage();
  }, [mezzo.id, hubLogEntries.length, listPageSize, resetHubLogPage]);
  const pagedHubLog = useMemo(() => sliceHubLog(hubLogEntries), [hubLogEntries, sliceHubLog, hubLogPage]);

  const {
    page: tlPage,
    setPage: setTlPage,
    pageCount: tlPageCount,
    sliceItems: sliceTl,
    showPager: showTlPager,
    label: tlPagerLabel,
    resetPage: resetTlPage,
  } = useClientPagination(timeline.length, listPageSize);
  useEffect(() => {
    resetTlPage();
  }, [mezzo.id, timeline.length, listPageSize, resetTlPage]);
  const pagedTimeline = useMemo(() => sliceTl(timeline), [timeline, sliceTl, tlPage]);

  const mezzoTabPanelId = `mezzi-hub-panel-${tab}`;
  const mezzoTabLabel = (id: MezziHubTabId) => {
    switch (id) {
      case "panoramica":
        return "Panoramica";
      case "attrezzature":
        return "Attrezzature";
      case "foto":
        return "Foto";
      case "lavorazioni":
        return `Lavorazioni (${interventi.length})`;
      case "timeline":
        return `Timeline (${nTimeline})`;
      case "preventivi":
        return `Preventivi (${nPv})`;
      case "documenti":
        return `Documenti (${nDoc})`;
      case "log":
        return `Log (${hubLogEntries.length})`;
    }
  };

  const mezzoTitolo = `${mezzo.marca} ${mezzo.modello !== "—" ? mezzo.modello : ""}`.trim();
  const mezzoSottotitolo = [
    mezzo.cliente?.trim() && mezzo.cliente !== "—" ? mezzo.cliente : null,
    mezzo.cantiere?.trim() ? mezzo.cantiere : null,
    mezzo.targa?.trim() && mezzo.targa !== "—" ? mezzo.targa : null,
    mezzo.matricola?.trim() && mezzo.matricola !== "—" ? mezzo.matricola : null,
    mezzo.numeroScuderia?.trim() ? `sc. ${mezzo.numeroScuderia}` : null,
  ]
    .filter(Boolean)
    .join(" · ");

  const footerNode = <MezziHubFooter tab={tab} mezzo={mezzo} onClose={onClose} />;

  return (
    <LavorazioniModalShell
      modalSize="formLarge"
      onRequestClose={onClose}
      titleId="mezzi-hub-title"
      footer={footerNode ?? undefined}
      header={
        <LavorazioniModalHeader
          title={mezzoTitolo || "Mezzo"}
          subtitle={mezzoSottotitolo || undefined}
          titleId="mezzi-hub-title"
          onRequestClose={onClose}
          actions={
            <>
              <button
                type="button"
                className={erpBtnSoftOrange}
                onClick={onEdit}
                disabled={Boolean(mezzo.hubSynthetic) || !canEdit}
                title={
                  !canEdit
                    ? READONLY_PERMISSION_HINT
                    : mezzo.hubSynthetic
                      ? "Registra il mezzo in anagrafica per abilitare la modifica"
                      : undefined
                }
              >
                Modifica
              </button>
              {onDelete && !mezzo.hubSynthetic ? (
                <button type="button" className={dsBtnDanger} onClick={onDelete} disabled={!canEdit}>
                  Elimina
                </button>
              ) : null}
            </>
          }
        />
      }
    >
      {hubQuery.isError ? (
        <MezziHubErrorBanner message={hubQuery.error?.message ?? "Errore caricamento hub mezzo."} />
      ) : null}

      <HubModalTabBar aria-label="Sezioni dettaglio mezzo">
        {MEZZI_HUB_TAB_ORDER.map((id) => (
          <HubModalTab
            key={id}
            id={`mezzi-hub-tab-${id}`}
            panelId={tab === id ? mezzoTabPanelId : undefined}
            label={mezzoTabLabel(id)}
            active={tab === id}
            onSelect={() => setTab(id)}
          />
        ))}
      </HubModalTabBar>

      <GestionaleModalScrollBody
        className="p-4"
        role="tabpanel"
        id={mezzoTabPanelId}
        aria-labelledby={`mezzi-hub-tab-${tab}`}
      >
        {hubQuery.isLoading && !hubData ? (
          <p className="text-sm text-[color:var(--cab-text-muted)]">Caricamento dati mezzo…</p>
        ) : null}

        {tab === "panoramica" ? (
          <HubModalPanoramicaPanel>
            {mezzo.hubSynthetic ? <MezziHubSyntheticBanner /> : null}
            {hubData ? (
              <HubModalPanoramicaSummary>
                <MezziHubTabJumpButton onJump={() => setTab("lavorazioni")}>
                  <HubModalPanoramicaSummaryItem
                    label="Lavorazioni"
                    value={String(hubData.kpi.totaleLavorazioni)}
                  />
                </MezziHubTabJumpButton>
                <HubModalPanoramicaSummaryItem
                  label="Lavorazione attiva"
                  value={hubData.kpi.lavorazioneAttiva ? "Sì" : "No"}
                  pillStyle={lavorazioneAttivaPillStyle(hubData.kpi.lavorazioneAttiva)}
                />
                <MezziHubTabJumpButton onJump={() => setTab("preventivi")}>
                  <HubModalPanoramicaSummaryItem label="Preventivi" value={String(hubData.kpi.preventiviCount)} />
                </MezziHubTabJumpButton>
                <MezziHubTabJumpButton onJump={() => setTab("documenti")}>
                  <HubModalPanoramicaSummaryItem label="Documenti" value={String(hubData.kpi.documentiCount)} />
                </MezziHubTabJumpButton>
              </HubModalPanoramicaSummary>
            ) : null}

            <HubModalPanoramicaFieldGroup title="Anagrafica">
              <HubModalPanoramicaFieldGrid>
                <HubModalPanoramicaField label="Cliente" value={hubPanoramicaDisplayValue(mezzo.cliente)} />
                <HubModalPanoramicaField label="Cantiere" value={hubPanoramicaDisplayValue(mezzo.cantiere)} />
                <HubModalPanoramicaField label="Utilizzatore" value={hubPanoramicaDisplayValue(mezzo.utilizzatore)} />
                <HubModalPanoramicaField label="Tipo attrezzatura" value={hubPanoramicaDisplayValue(mezzo.tipoAttrezzatura)} />
                <HubModalPanoramicaField
                  label="Telaio"
                  value={hubPanoramicaDisplayValue(
                    [mezzo.marcaTelaio, mezzo.modelloTelaio].filter((v) => v?.trim() && v !== "—").join(" ") || undefined,
                  )}
                />
                <HubModalPanoramicaField label="Ultima lavorazione" value={ultimaLavorazioneLabel(interventi)} />
              </HubModalPanoramicaFieldGrid>
            </HubModalPanoramicaFieldGroup>

            {mezzo.note?.trim() ? (
              <GestionaleInfoCard title="Note mezzo">
                <p className="whitespace-pre-wrap text-xs leading-snug text-[color:var(--cab-text)]">{mezzo.note.trim()}</p>
              </GestionaleInfoCard>
            ) : null}

            <MezziHubQuickLinks mezzo={mezzo} onClose={onClose} onGoTab={setTab} />
          </HubModalPanoramicaPanel>
        ) : null}

        {tab === "attrezzature" ? (
          <MezziHubAttrezzaturePanel mezzoId={mezzo.id} canEdit={canEdit} />
        ) : null}
        {tab === "foto" ? (
          <RecordImageManager
            scope="mezzi"
            recordId={mezzo.id}
            title="Foto mezzo"
            hubCardLayout
            hubCardShowTitle
            canEdit={canEdit && !mezzo.hubSynthetic}
            onImageEvent={() => void hubQuery.refetch()}
          />
        ) : null}

        {tab === "lavorazioni" ? (
          <GestionaleInfoCard
            title="Lavorazioni collegate"
            subtitle={`${sortedLav.length} ${sortedLav.length === 1 ? "record" : "record"}`}
            collapsible
            defaultCollapsed={sortedLav.length === 0}
            actions={
              sortedLav.length > 0 ? (
                <Link
                  href={buildPreventiviLavorazioneFocusHref(sortedLav[0]!.id, sortedLav[0]!.origine)}
                  className={dsTableActionTextBtn}
                  onClick={onClose}
                >
                  Ultima lavorazione
                </Link>
              ) : null
            }
          >
            <div className={`${dsTableWrap} ${dsScrollbar}`}>
              <table className={`${dsTable} min-w-[640px] text-xs`}>
                <GlobalTableHead>
                  <GlobalTableHeadLabel label="Ingresso" />
                  <GlobalTableHeadLabel label="Stato" />
                  <GlobalTableHeadLabel label="Descrizione" />
                  <GlobalTableHeadLabel label="" thClassName="w-28" align="right" />
                </GlobalTableHead>
                <tbody>
                  {sortedLav.length === 0 ? (
                    <tr>
                      <td colSpan={4} className="px-2 py-6 text-center text-[color:var(--cab-text-muted)]">
                        Nessuna lavorazione collegata.
                      </td>
                    </tr>
                  ) : (
                    pagedLav.map((r) => (
                      <tr key={r.id} className={dsTableRow}>
                        <td className="whitespace-nowrap px-2 py-2 font-mono text-[11px] text-[color:var(--cab-text-muted)]">
                          {fmtMezziHubDt(r.dataIngresso)}
                        </td>
                        <td className="px-2 py-2 text-[color:var(--cab-text)]">{r.statoFinale}</td>
                        <td className="max-w-[280px] px-2 py-2 text-[color:var(--cab-text-muted)]">{r.descrizione || "—"}</td>
                        <td className="whitespace-nowrap px-2 py-2 text-right">
                          <div className="flex flex-nowrap justify-end gap-1">
                            <Link
                              href={buildPreventiviLavorazioneFocusHref(r.id, r.origine)}
                              className={dsTableActionTextBtnPrimary}
                              onClick={onClose}
                            >
                              Apri
                            </Link>
                            <Link
                              href={buildPreventiviArchivioFilterHref(r.id, r.origine)}
                              className={dsTableActionTextBtn}
                              onClick={onClose}
                            >
                              Preventivi
                            </Link>
                          </div>
                        </td>
                      </tr>
                    ))
                  )}
                </tbody>
              </table>
              {showLavPager ? (
                <TablePagination page={lavPage} pageCount={lavPageCount} onPageChange={setLavPage} label={lavPagerLabel} />
              ) : null}
            </div>
          </GestionaleInfoCard>
        ) : null}

        {tab === "timeline" ? (
          <GestionaleInfoCard
            title="Timeline"
            subtitle={`${timeline.length} eventi ordinati per data`}
            collapsible
            defaultCollapsed={timeline.length === 0}
          >
            {pagedTimeline.length === 0 ? (
              <MezziHubTabEmpty message="Nessun evento in timeline per questo mezzo." />
            ) : (
              <MezziHubList>
                {pagedTimeline.map((ev) => (
                  <MezziHubListItem
                    key={ev.id}
                    actions={
                      ev.ref?.lavorazioneId && ev.ref.origine ? (
                        <>
                          <Link
                            href={buildPreventiviLavorazioneFocusHref(ev.ref.lavorazioneId, ev.ref.origine)}
                            className={dsTableActionTextBtnPrimary}
                            onClick={onClose}
                          >
                            Apri
                          </Link>
                          <Link
                            href={buildPreventiviArchivioFilterHref(ev.ref.lavorazioneId, ev.ref.origine)}
                            className={dsTableActionTextBtn}
                            onClick={onClose}
                          >
                            Preventivi
                          </Link>
                        </>
                      ) : null
                    }
                  >
                    <div className="flex min-w-0 items-start gap-2">
                      <MezziHubTimelineKindBadge kind={ev.kind} />
                      <div className="min-w-0 flex-1">
                        <MezziHubListMeta>{fmtMezziHubDt(ev.at)}</MezziHubListMeta>
                        <MezziHubListTitle>
                          {ev.title}
                          {ev.targetBadge ? (
                            <span className="ml-2 rounded bg-[var(--cab-surface-2)] px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-[var(--cab-text-muted)]">
                              {ev.targetBadge}
                            </span>
                          ) : null}
                        </MezziHubListTitle>
                        {ev.subtitle ? <MezziHubListSubtitle>{ev.subtitle}</MezziHubListSubtitle> : null}
                      </div>
                    </div>
                  </MezziHubListItem>
                ))}
              </MezziHubList>
            )}
            {showTlPager ? (
              <TablePagination page={tlPage} pageCount={tlPageCount} onPageChange={setTlPage} label={tlPagerLabel} />
            ) : null}
          </GestionaleInfoCard>
        ) : null}

        {tab === "preventivi" ? (
          <GestionaleInfoCard
            title="Preventivi"
            subtitle={`${sortedPv.length} collegati al mezzo`}
            collapsible
            defaultCollapsed={sortedPv.length === 0}
          >
            {sortedPv.length === 0 ? (
              <MezziHubTabEmpty message="Nessun preventivo collegato a questo mezzo." />
            ) : (
              <MezziHubList>
                {pagedPv.map((p) => (
                  <MezziHubListItem
                    key={p.id}
                    actions={
                      <>
                        <button
                          type="button"
                          className={dsTableActionTextBtn}
                          onClick={() => {
                            const sp = new URLSearchParams();
                            sp.set(Q_PREVENTIVI_OPEN, p.id);
                            openUrlInNewTab(`/preventivi?${sp.toString()}`);
                          }}
                        >
                          Dettaglio
                        </button>
                        <button
                          type="button"
                          className={dsTableActionTextBtnPrimary}
                          onClick={() =>
                            void importPreventiviPdf().then(({ openPreventivoPdfInNewTab }) =>
                              openPreventivoPdfInNewTab(p, "Gestionale"),
                            )
                          }
                        >
                          PDF
                        </button>
                      </>
                    }
                  >
                    <MezziHubListTitle>
                      {p.numero} · {fmtMezziHubDt(p.dataCreazione)}
                    </MezziHubListTitle>
                    <MezziHubListSubtitle>{p.cliente}</MezziHubListSubtitle>
                  </MezziHubListItem>
                ))}
              </MezziHubList>
            )}
            {showPvPager ? <TablePagination page={pvPage} pageCount={pvPageCount} onPageChange={setPvPage} label={pvPagerLabel} /> : null}
          </GestionaleInfoCard>
        ) : null}

        {tab === "documenti" ? (
          <GestionaleInfoCard
            title="Documenti"
            subtitle={`${documenti.length} file collegati`}
            collapsible
            defaultCollapsed={documenti.length === 0}
          >
            {documenti.length === 0 ? (
              <MezziHubTabEmpty message="Nessun documento collegato a questo mezzo." />
            ) : (
              <MezziHubList>
                {pagedDoc.map((d) => {
                  const canOpen = canOpenDocumento(d);
                  return (
                    <MezziHubListItem
                      key={d.id}
                      actions={
                        canOpen ? (
                          <button
                            type="button"
                            className={dsTableActionTextBtnPrimary}
                            onClick={() => void openDocumentoFile(d)}
                          >
                            Apri
                          </button>
                        ) : (
                          <span className="text-xs text-[color:var(--cab-text-muted)]">—</span>
                        )
                      }
                    >
                      <p className="text-[10px] font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)]">
                        {formatDocumentoRigaSintetica(d)}
                      </p>
                      <MezziHubListTitle>{d.nome}</MezziHubListTitle>
                    </MezziHubListItem>
                  );
                })}
              </MezziHubList>
            )}
            {showDocPager ? <TablePagination page={docPage} pageCount={docPageCount} onPageChange={setDocPage} label={docPagerLabel} /> : null}
          </GestionaleInfoCard>
        ) : null}

        {tab === "log" ? (
          <GestionaleInfoCard
            title="Log anagrafica"
            subtitle={`${hubLogEntries.length} eventi`}
            collapsible
            defaultCollapsed
          >
            {hubQuery.isLoading && !hubData ? (
              <p className="text-sm text-[color:var(--cab-text-muted)]">Caricamento log…</p>
            ) : hubLogEntries.length === 0 ? (
              <GestionaleLogEmpty message="Nessuna modifica anagrafica registrata per questo mezzo." />
            ) : (
              <>
                <GestionaleLogList>
                  {pagedHubLog.map((e) => {
                    const vm = buildMezziGestionaleLogViewModel({
                      tipo: e.tipo,
                      mezzo: e.mezzo,
                      riepilogo: e.riepilogo,
                      autore: e.autore,
                      at: e.at,
                      changes: e.changes,
                    });
                    return (
                      <li key={e.id}>
                        <GestionaleLogEntryFourLines vm={vm} />
                      </li>
                    );
                  })}
                </GestionaleLogList>
                {showHubLogPager ? (
                  <TablePagination
                    page={hubLogPage}
                    pageCount={hubLogPageCount}
                    onPageChange={setHubLogPage}
                    label={hubLogPagerLabel}
                  />
                ) : null}
              </>
            )}
          </GestionaleInfoCard>
        ) : null}
      </GestionaleModalScrollBody>
    </LavorazioniModalShell>
  );
}

"use client";

import Link from "next/link";
import type { ReactNode } from "react";
import {
  hrefDocumentiPerMezzo,
  hrefLavorazioniPerMezzo,
  hrefPreventiviPerMezzo,
} from "@/lib/mezzi/mezzi-helpers";
import type { MezzoGestito } from "@/lib/mezzi/types";
import { dsBtnNeutral, dsBtnPrimary } from "@/lib/ui/design-system";

export type MezziHubTabId =
  | "panoramica"
  | "attrezzature"
  | "foto"
  | "lavorazioni"
  | "timeline"
  | "preventivi"
  | "documenti"
  | "log";

export const MEZZI_HUB_TAB_ORDER: readonly MezziHubTabId[] = [
  "panoramica",
  "attrezzature",
  "foto",
  "lavorazioni",
  "timeline",
  "preventivi",
  "documenti",
  "log",
];

export function fmtMezziHubDt(iso: string) {
  try {
    return new Date(iso).toLocaleString("it-IT", {
      day: "2-digit",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
    });
  } catch {
    return iso;
  }
}

export function MezziHubTabEmpty({ message }: { message: string }) {
  return (
    <div className="rounded-[var(--ds-radius-lg)] border border-dashed border-[color:var(--cab-border)] bg-[color:color-mix(in_srgb,var(--cab-surface-2)_55%,var(--cab-card))] px-4 py-6 text-center">
      <p className="text-sm font-medium text-[color:var(--cab-text)]">{message}</p>
    </div>
  );
}

export function MezziHubErrorBanner({ message }: { message: string }) {
  return (
    <div className="shrink-0 border-b border-red-200 bg-red-50 px-3 py-2 text-xs text-red-900 dark:border-red-900/40 dark:bg-red-950/40 dark:text-red-100">
      {message}
    </div>
  );
}

export function MezziHubSyntheticBanner() {
  return (
    <p className="rounded-[var(--ds-radius-lg)] border border-amber-300/75 bg-amber-50/80 px-3 py-2 text-xs leading-snug text-amber-950 dark:border-amber-800/70 dark:bg-amber-950/35 dark:text-amber-100">
      Riga sintetica: crea il mezzo in anagrafica con gli stessi identificativi (targa / matricola) per unificare il parco e
      abilitare la modifica.
    </p>
  );
}

const hubListClass = "min-w-0 divide-y divide-[color:var(--cab-border)]";
const hubListRowClass = "flex min-w-0 items-start justify-between gap-3 py-3 first:pt-0 last:pb-0";

export function MezziHubList({ children }: { children: ReactNode }) {
  return <ul className={hubListClass}>{children}</ul>;
}

export function MezziHubListItem({
  children,
  actions,
}: {
  children: ReactNode;
  actions?: ReactNode;
}) {
  return (
    <li className={hubListRowClass}>
      <div className="min-w-0 flex-1">{children}</div>
      {actions ? <div className="flex shrink-0 flex-nowrap items-center gap-1 sm:flex-wrap">{actions}</div> : null}
    </li>
  );
}

export function MezziHubListMeta({ children }: { children: ReactNode }) {
  return <p className="font-mono text-[11px] leading-snug text-[color:var(--cab-text-muted)]">{children}</p>;
}

export function MezziHubListTitle({ children }: { children: ReactNode }) {
  return <p className="mt-0.5 text-sm font-medium leading-snug text-[color:var(--cab-text)]">{children}</p>;
}

export function MezziHubListSubtitle({ children }: { children: ReactNode }) {
  return <p className="mt-0.5 text-xs leading-snug text-[color:var(--cab-text-muted)]">{children}</p>;
}

export function MezziHubTimelineKindBadge({
  kind,
}: {
  kind: "lavorazione" | "log" | "movimento" | "lifecycle";
}) {
  const label =
    kind === "lavorazione"
      ? "Lavorazione"
      : kind === "movimento"
        ? "Magazzino"
        : kind === "lifecycle"
          ? "Asset"
          : "Anagrafica";
  const tone =
    kind === "lavorazione"
      ? "border-[color:color-mix(in_srgb,var(--cab-primary)_35%,var(--cab-border))] bg-[color:color-mix(in_srgb,var(--cab-primary)_12%,var(--cab-card))] text-[color:color-mix(in_srgb,var(--cab-primary)_90%,var(--cab-text))]"
      : kind === "movimento"
        ? "border-[color:color-mix(in_srgb,var(--cab-border)_90%,transparent)] bg-[color:color-mix(in_srgb,var(--cab-surface-2)_70%,var(--cab-card))] text-[color:var(--cab-text-muted)]"
        : "border-[color:var(--cab-border)] bg-[var(--cab-surface-2)] text-[color:var(--cab-text-muted)]";
  return (
    <span
      className={`inline-flex shrink-0 items-center rounded-md border px-1.5 py-0.5 text-[10px] font-semibold uppercase tracking-wide ${tone}`}
    >
      {label}
    </span>
  );
}

/** Pulsante che porta a un’altra tab dello stesso hub (es. KPI in Panoramica). */
export function MezziHubTabJumpButton({
  children,
  onJump,
  className = "",
}: {
  children: ReactNode;
  onJump: () => void;
  className?: string;
}) {
  return (
    <button
      type="button"
      onClick={onJump}
      className={`min-w-0 rounded-[var(--ds-radius-lg)] border border-transparent bg-transparent p-1.5 text-left transition-colors hover:border-[color:var(--cab-border)] hover:bg-[var(--cab-hover)] focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[color:color-mix(in_srgb,var(--cab-primary)_42%,transparent)] ${className}`}
    >
      {children}
    </button>
  );
}

export function MezziHubQuickLinks({
  mezzo,
  onClose,
  onGoTab,
}: {
  mezzo: MezzoGestito;
  onClose: () => void;
  onGoTab: (tab: MezziHubTabId) => void;
}) {
  const linkClass = `${dsBtnNeutral} inline-flex no-underline`;
  return (
    <div className="flex min-w-0 flex-col gap-2">
      <p className="text-[10px] font-bold uppercase tracking-wide text-[color:var(--cab-text-muted)]">Collegamenti rapidi</p>
      <div className="flex min-w-0 flex-wrap gap-2">
        <button type="button" className={dsBtnNeutral} onClick={() => onGoTab("lavorazioni")}>
          Lavorazioni in hub
        </button>
        <button type="button" className={dsBtnNeutral} onClick={() => onGoTab("preventivi")}>
          Preventivi in hub
        </button>
        <button type="button" className={dsBtnNeutral} onClick={() => onGoTab("documenti")}>
          Documenti in hub
        </button>
        <Link href={hrefLavorazioniPerMezzo(mezzo)} className={linkClass} onClick={onClose}>
          Pagina lavorazioni
        </Link>
        <Link href={hrefPreventiviPerMezzo(mezzo)} className={linkClass} onClick={onClose}>
          Pagina preventivi
        </Link>
        <Link href={hrefDocumentiPerMezzo(mezzo)} className={linkClass} onClick={onClose}>
          Pagina documenti
        </Link>
      </div>
    </div>
  );
}

export function MezziHubFooter({
  tab,
  mezzo,
  onClose,
}: {
  tab: MezziHubTabId;
  mezzo: MezzoGestito;
  onClose: () => void;
}) {
  const linkPrimary = `${dsBtnPrimary} inline-flex w-full justify-center no-underline sm:w-auto`;
  const linkNeutral = `${dsBtnNeutral} inline-flex w-full justify-center no-underline sm:w-auto`;

  if (tab === "foto" || tab === "log") {
    return null;
  }

  if (tab === "lavorazioni") {
    return (
      <Link href={hrefLavorazioniPerMezzo(mezzo)} className={linkPrimary} onClick={onClose}>
        Apri tutte le lavorazioni del mezzo
      </Link>
    );
  }

  if (tab === "preventivi") {
    return (
      <Link href={hrefPreventiviPerMezzo(mezzo)} className={linkPrimary} onClick={onClose}>
        Apri archivio preventivi
      </Link>
    );
  }

  if (tab === "documenti") {
    return (
      <Link href={hrefDocumentiPerMezzo(mezzo)} className={linkPrimary} onClick={onClose}>
        Documenti (pagina completa)
      </Link>
    );
  }

  if (tab === "timeline") {
    return (
      <div className="flex min-w-0 flex-wrap justify-end gap-2">
        <Link href={hrefLavorazioniPerMezzo(mezzo)} className={linkNeutral} onClick={onClose}>
          Lavorazioni
        </Link>
        <Link href={hrefDocumentiPerMezzo(mezzo)} className={linkNeutral} onClick={onClose}>
          Documenti
        </Link>
      </div>
    );
  }

  return (
    <div className="flex min-w-0 flex-wrap justify-end gap-2">
      <Link href={hrefLavorazioniPerMezzo(mezzo)} className={linkNeutral} onClick={onClose}>
        Lavorazioni
      </Link>
      <Link href={hrefPreventiviPerMezzo(mezzo)} className={linkNeutral} onClick={onClose}>
        Preventivi
      </Link>
      <Link href={hrefDocumentiPerMezzo(mezzo)} className={linkPrimary} onClick={onClose}>
        Documenti
      </Link>
    </div>
  );
}

