"use client";

import { createPortal } from "react-dom";
import { useCallback, useEffect, useRef, useState, type RefObject } from "react";
import { ADDETTO_COLOR_POOL } from "@/lib/lavorazioni/addetto-colors-assign";
import { normalizeHex } from "@/lib/lavorazioni/color-utils";
import { CloseButton } from "@/components/design-system";
import { GLOBAL_DROPDOWN_PORTAL_Z } from "@/lib/ui/global-dropdown-portal";
import { useGlobalDropdownPortal } from "@/components/gestionale/global-input/use-global-dropdown-portal";
import { dsFocus, dsInput, dsTableActionBtnColorSwatch } from "@/lib/ui/design-system";

const PRESET_SWATCH_CLASS =
  "inline-flex h-9 w-9 shrink-0 items-center justify-center rounded-lg border-2 p-0 shadow-[var(--cab-shadow-sm)] transition-[border-color,box-shadow,transform] duration-150 hover:scale-[1.04] active:scale-[0.98] touch-manipulation [-webkit-tap-highlight-color:transparent]";

/** Contenuto pannello (12 swatch + hex + native picker) — sopra il default dropdown 320px. */
const COLOR_PICKER_PANEL_MAX_HEIGHT = 520;

const COLOR_PICKER_PANEL_CLASS =
  "flex min-w-[14rem] max-w-full min-h-0 flex-col gap-2 overflow-y-auto overscroll-contain rounded-[var(--ds-radius-lg)] border border-[color:var(--cab-border)] bg-[var(--cab-card)] p-3 shadow-[var(--cab-shadow-md)] gestionale-scrollbar";

function commitHexDraft(raw: string, onChange: (hex: string) => void): string | null {
  const nh = normalizeHex(raw);
  if (!nh) return null;
  onChange(nh);
  return nh;
}

/** Campione cliccabile — apre il selettore colori nativo del sistema (stessa shell dello swatch riga). */
function SettingsNativeColorPickerButton({
  value,
  ariaLabel,
  onChange,
}: {
  value: string;
  ariaLabel: string;
  onChange: (hex: string) => void;
}) {
  const hex = normalizeHex(value) ?? "#52525b";

  return (
    <label
      className={`${dsTableActionBtnColorSwatch} relative shrink-0 touch-manipulation`}
      style={{ backgroundColor: hex }}
      title="Selettore colori di sistema"
    >
      <input
        type="color"
        value={hex}
        aria-label={ariaLabel}
        className="absolute inset-0 z-[1] h-full w-full cursor-pointer opacity-0"
        onChange={(e) => {
          const nh = normalizeHex(e.target.value);
          if (!nh) return;
          onChange(nh);
        }}
      />
    </label>
  );
}

export function SettingsColorPickerPopover({
  open,
  anchorRef,
  value,
  ariaLabel,
  onChange,
  onClose,
}: {
  open: boolean;
  anchorRef: RefObject<HTMLElement | null>;
  value: string;
  ariaLabel: string;
  onChange: (hex: string) => void;
  onClose: () => void;
}) {
  const panelRef = useRef<HTMLDivElement>(null);
  const hexInputRef = useRef<HTMLInputElement>(null);
  const [mounted, setMounted] = useState(false);
  const hex = normalizeHex(value) ?? "#52525b";
  const [hexDraft, setHexDraft] = useState(hex);

  const { style } = useGlobalDropdownPortal({
    open: open && mounted,
    anchorRef,
    contentRef: panelRef,
    placement: "bottom-end",
    matchAnchorWidth: false,
    panelWidth: 224,
    maxHeight: COLOR_PICKER_PANEL_MAX_HEIGHT,
  });

  useEffect(() => {
    setMounted(true);
  }, []);

  useEffect(() => {
    if (!open) return;
    setHexDraft(hex);
  }, [hex, open]);

  const applyHexDraft = useCallback(() => {
    const next = commitHexDraft(hexDraft, onChange);
    if (next) setHexDraft(next);
  }, [hexDraft, onChange]);

  useEffect(() => {
    if (!open) return;
    function onDoc(ev: MouseEvent) {
      const t = ev.target as Node;
      if (anchorRef.current?.contains(t)) return;
      if (panelRef.current?.contains(t)) return;
      onClose();
    }
    document.addEventListener("mousedown", onDoc, true);
    return () => document.removeEventListener("mousedown", onDoc, true);
  }, [open, onClose, anchorRef]);

  useEffect(() => {
    if (!open) return;
    function onKey(ev: KeyboardEvent) {
      if (ev.key === "Escape") onClose();
    }
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [open, onClose]);

  if (!open || !mounted || typeof document === "undefined") return null;

  return createPortal(
    <div
      ref={panelRef}
      role="dialog"
      aria-label={ariaLabel}
      className={COLOR_PICKER_PANEL_CLASS}
      style={{ ...style, zIndex: GLOBAL_DROPDOWN_PORTAL_Z }}
      onMouseDown={(e) => e.stopPropagation()}
    >
      <div className="flex items-center justify-between gap-2 min-w-0">
        <p className="min-w-0 truncate text-[10px] font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)]">
          Scegli colore
        </p>
        <CloseButton onClick={onClose} label="Chiudi" />
      </div>

      <div
        className="grid grid-cols-4 gap-1.5"
        role="listbox"
        aria-label={`Palette colori per ${ariaLabel}`}
      >
        {ADDETTO_COLOR_POOL.map((preset) => {
          const nh = normalizeHex(preset) ?? preset;
          const selected = nh === hex;
          return (
            <button
              key={nh}
              type="button"
              role="option"
              aria-selected={selected}
              aria-label={`Colore ${nh}`}
              className={`${PRESET_SWATCH_CLASS} ${dsFocus} ${
                selected
                  ? "border-[color:var(--cab-primary)] ring-2 ring-[color:color-mix(in_srgb,var(--cab-primary)_35%,transparent)]"
                  : "border-[color:var(--cab-border)]"
              }`}
              style={{ backgroundColor: nh }}
              onClick={() => {
                onChange(nh);
                setHexDraft(nh);
              }}
            />
          );
        })}
      </div>

      <div className="block min-w-0">
        <span className="text-[10px] font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)]">
          Personalizza
        </span>
        <div className="mt-1.5 flex items-stretch gap-1.5">
          <input
            ref={hexInputRef}
            type="text"
            inputMode="text"
            autoComplete="off"
            spellCheck={false}
            value={hexDraft}
            aria-label={`Codice hex ${ariaLabel}`}
            placeholder="#2563eb"
            className={`${dsInput} ${dsFocus} min-h-10 min-w-0 flex-1 font-mono text-xs uppercase tabular-nums`}
            onChange={(e) => setHexDraft(e.target.value)}
            onBlur={applyHexDraft}
            onKeyDown={(e) => {
              if (e.key === "Enter") {
                e.preventDefault();
                applyHexDraft();
                hexInputRef.current?.blur();
              }
            }}
          />
          <SettingsNativeColorPickerButton
            value={hex}
            ariaLabel={`Selettore colore ${ariaLabel}`}
            onChange={(nh) => {
              onChange(nh);
              setHexDraft(nh);
            }}
          />
        </div>
      </div>
    </div>,
    document.body,
  );
}

"use client";

import Link from "next/link";
import { forwardRef } from "react";
import type { ComponentPropsWithoutRef, ReactElement, ReactNode } from "react";
import { Tooltip } from "@/components/design-system";
import type { TooltipSide } from "@/lib/ui/tooltip-portal";
import { erpFocus } from "@/lib/ui/erp-tokens";
import {
  sidebarActiveIndicatorClass,
  sidebarNavIconShellClass,
  sidebarNavIconShellInactiveClass,
  sidebarNavRowClass,
  sidebarNavRowDisabledClass,
  sidebarNavRowIconTrackClass,
  sidebarNavRowInactiveClass,
  sidebarNavRowLabelClass,
  sidebarNavRowTrailingClass,
} from "@/lib/ui/sidebar-layout";

export function SidebarSessionExpandChevron({ active = false }: { active?: boolean }) {
  return (
    <svg
      className={`cab-sidebar-session-expand-chevron h-3.5 w-3.5 shrink-0 transition-[opacity,transform,color] duration-200 ease-out ${
        active
          ? "translate-x-0 text-[color:var(--cab-primary)] opacity-100"
          : "text-[color:var(--cab-text-muted)] opacity-55 group-hover:translate-x-0.5 group-hover:opacity-90"
      }`}
      viewBox="0 0 16 16"
      fill="none"
      stroke="currentColor"
      strokeWidth={2}
      aria-hidden
    >
      <path strokeLinecap="round" strokeLinejoin="round" d="M6 4l4 4-4 4" />
    </svg>
  );
}

function SidebarActiveIndicator({ active, collapsed }: { active: boolean; collapsed: boolean }) {
  if (!active) return null;
  return (
    <span
      className={`${sidebarActiveIndicatorClass} ${
        collapsed ? "cab-sidebar-active-indicator--rail" : "cab-sidebar-active-indicator--row"
      }`}
      aria-hidden
    />
  );
}

export function SidebarNavIconWrap({
  shellClass,
  children,
  dimmed,
  className = "",
}: {
  shellClass: string;
  children: ReactNode;
  dimmed?: boolean;
  className?: string;
}) {
  return (
    <span
      className={`${sidebarNavIconShellClass} ${shellClass} ${dimmed ? "opacity-60" : ""} ${className}`.trim()}
      aria-hidden
    >
      {children}
    </span>
  );
}

type SidebarNavRowCommonProps = {
  icon: ReactNode;
  label: ReactNode;
  trailing?: ReactNode;
  active?: boolean;
  disabled?: boolean;
  /** Rail stretta (label/trailing nascosti via CSS sull'aside). */
  collapsed?: boolean;
  open?: boolean;
  className?: string;
  rowClassName?: string;
  /** Tooltip su rail collassata — avvolge il nodo nativo (link/button), non il wrapper forwardRef. */
  railTooltip?: string;
  railTooltipSide?: TooltipSide;
  /** Override shell icona (es. avatar profilo senza sfondo zinc). */
  iconShellClass?: string;
};

type SidebarNavRowAsLink = SidebarNavRowCommonProps &
  Omit<ComponentPropsWithoutRef<typeof Link>, "children"> & {
    as?: "link";
  };

type SidebarNavRowAsButton = SidebarNavRowCommonProps &
  Omit<ComponentPropsWithoutRef<"button">, "children"> & {
    as: "button";
  };

type SidebarNavRowAsDiv = SidebarNavRowCommonProps &
  Omit<ComponentPropsWithoutRef<"div">, "children"> & {
    as: "div";
  };

export type SidebarNavRowProps = SidebarNavRowAsLink | SidebarNavRowAsButton | SidebarNavRowAsDiv;

function rowClassNames(props: SidebarNavRowCommonProps): string {
  const { active, disabled, open, className = "", rowClassName = "" } = props;
  return [
    sidebarNavRowClass,
    rowClassName,
    disabled ? sidebarNavRowDisabledClass : sidebarNavRowInactiveClass,
    active ? "cab-sidebar-nav-row--active" : "",
    open ? "cab-sidebar-session-item--open" : "",
    erpFocus,
    className,
  ]
    .filter(Boolean)
    .join(" ");
}

function RowContent({
  icon,
  label,
  trailing,
  active = false,
  collapsed = false,
  disabled = false,
  iconShellClass,
}: SidebarNavRowCommonProps) {
  const shellClass = iconShellClass ?? sidebarNavIconShellInactiveClass;

  return (
    <>
      <SidebarActiveIndicator active={active && !disabled} collapsed={collapsed} />
      <span className={sidebarNavRowIconTrackClass}>
        <SidebarNavIconWrap shellClass={shellClass} dimmed={disabled}>
          {icon}
        </SidebarNavIconWrap>
      </span>
      <span className={sidebarNavRowLabelClass}>{label}</span>
      {trailing ? <span className={sidebarNavRowTrailingClass}>{trailing}</span> : null}
    </>
  );
}

function wrapRailTooltip(
  node: ReactElement,
  tooltip: string | undefined,
  collapsed: boolean,
  side: TooltipSide = "right",
): ReactElement {
  if (!tooltip || !collapsed) return node;
  return <Tooltip content={tooltip} side={side}>{node}</Tooltip>;
}

export const SidebarNavRow = forwardRef<HTMLButtonElement | HTMLAnchorElement | HTMLDivElement, SidebarNavRowProps>(
  function SidebarNavRow(props, ref) {
  const {
    as = "link",
    icon,
    label,
    trailing,
    active,
    disabled,
    collapsed = false,
    open,
    railTooltip,
    railTooltipSide = "right",
    iconShellClass,
    className: _c,
    rowClassName: _r,
    ...rest
  } = props;

  const contentProps = { icon, label, trailing, active, disabled, collapsed, open, iconShellClass };

  if (as === "button") {
    const { as: _a, ...buttonRest } = rest as SidebarNavRowAsButton;
    return wrapRailTooltip(
      <button
        ref={ref as React.Ref<HTMLButtonElement>}
        type="button"
        disabled={disabled}
        className={rowClassNames(props)}
        {...buttonRest}
      >
        <RowContent {...contentProps} />
      </button>,
      railTooltip,
      collapsed,
      railTooltipSide,
    );
  }

  if (as === "div") {
    const { as: _a, ...divRest } = rest as SidebarNavRowAsDiv;
    return wrapRailTooltip(
      <div
        ref={ref as React.Ref<HTMLDivElement>}
        role="link"
        aria-disabled={disabled ? "true" : undefined}
        className={rowClassNames(props)}
        {...divRest}
      >
        <RowContent {...contentProps} />
      </div>,
      railTooltip,
      collapsed,
      railTooltipSide,
    );
  }

  const { as: _a, href = "#", ...linkRest } = rest as SidebarNavRowAsLink;
  if (disabled) {
    return wrapRailTooltip(
      <div ref={ref as React.Ref<HTMLDivElement>} role="link" aria-disabled="true" className={rowClassNames(props)}>
        <RowContent {...contentProps} />
      </div>,
      railTooltip,
      collapsed,
      railTooltipSide,
    );
  }

  return wrapRailTooltip(
    <Link ref={ref as React.Ref<HTMLAnchorElement>} href={href} className={rowClassNames(props)} {...linkRest}>
      <RowContent {...contentProps} />
    </Link>,
    railTooltip,
    collapsed,
    railTooltipSide,
  );
},
);

"use client";

import { erpFocus } from "@/components/gestionale/lavorazioni/lavorazioni-shared";
import { dsBtnNeutral, dsPageToolbarBtn } from "@/lib/ui/design-system";

type Props = {
  page: number;
  pageCount: number;
  onPageChange: (p: number) => void;
  label: string;
  className?: string;
};

function visibleNumberedPages(page: number, pageCount: number) {
  if (pageCount <= 1) {
    return {
      mid: [1],
      showFirst: false,
      showFirstGap: false,
      showLast: false,
      showLastGap: false,
    };
  }
  const maxSpan = 5;
  if (pageCount <= maxSpan) {
    const mid = Array.from({ length: pageCount }, (_, i) => i + 1);
    return { mid, showFirst: false, showFirstGap: false, showLast: false, showLastGap: false };
  }
  const delta = 2;
  let start = page - delta;
  let end = page + delta;
  if (start < 1) {
    end += 1 - start;
    start = 1;
  }
  if (end > pageCount) {
    start -= end - pageCount;
    end = pageCount;
  }
  start = Math.max(1, start);
  const mid: number[] = [];
  for (let i = start; i <= end; i += 1) mid.push(i);
  const first = mid[0]!;
  const last = mid[mid.length - 1]!;
  return {
    mid,
    showFirst: first > 1,
    showFirstGap: first > 2,
    showLast: last < pageCount,
    showLastGap: last < pageCount - 1,
  };
}

const pageBtnBase = `${dsBtnNeutral} min-h-9 min-w-9 shrink-0 px-0 text-xs font-semibold sm:min-h-9 sm:min-w-9`;
const pageBtnActive =
  "border-[color:color-mix(in_srgb,var(--cab-primary)_55%,var(--cab-border))] bg-[color:color-mix(in_srgb,var(--cab-primary)_12%,var(--cab-surface))] text-[color:color-mix(in_srgb,var(--cab-primary)_92%,var(--cab-text))] ring-1 ring-[color:color-mix(in_srgb,var(--cab-primary)_28%,transparent)]";

export function TablePagination({ page, pageCount, onPageChange, label, className }: Props) {
  if (pageCount <= 1) return null;

  const { mid, showFirst, showFirstGap, showLast, showLastGap } = visibleNumberedPages(page, pageCount);

  const iconBtn = `${pageBtnBase} text-base leading-none sm:text-sm`;
  const mobileStepBtn = `${dsPageToolbarBtn} h-11 min-h-11 w-full touch-manipulation sm:hidden`;

  return (
    <div
      className={`flex min-w-0 max-w-full flex-col gap-3 border-t border-[color:var(--cab-border)] px-2 py-3 pb-[max(0.75rem,env(safe-area-inset-bottom))] sm:flex-row sm:items-center sm:justify-between sm:gap-2 sm:pb-3 ${className ?? ""}`}
    >
      <p className="text-center text-xs leading-snug text-[color:var(--cab-text-muted)] sm:text-left">{label}</p>

      <nav
        className="grid w-full grid-cols-[minmax(0,1fr)_auto_minmax(0,1fr)] items-center gap-2 sm:hidden"
        aria-label="Paginazione"
      >
        <button
          type="button"
          className={`${mobileStepBtn} ${erpFocus}`}
          aria-label="Pagina precedente"
          disabled={page <= 1}
          onClick={() => onPageChange(page - 1)}
        >
          ‹ Prec.
        </button>
        <span className="inline-flex h-11 min-w-[4.5rem] shrink-0 items-center justify-center rounded-[var(--ds-radius-lg)] border border-[color:var(--cab-border)] bg-[var(--cab-surface)] px-3 text-sm font-semibold tabular-nums text-[color:var(--cab-text)] shadow-[var(--cab-shadow-sm)]">
          {page}
          <span className="mx-1 text-[color:var(--cab-text-muted)]">/</span>
          {pageCount}
        </span>
        <button
          type="button"
          className={`${mobileStepBtn} ${erpFocus}`}
          aria-label="Pagina successiva"
          disabled={page >= pageCount}
          onClick={() => onPageChange(page + 1)}
        >
          Succ. ›
        </button>
      </nav>

      <nav
        className="hidden min-w-0 shrink-0 flex-wrap items-center justify-end gap-1 sm:flex"
        aria-label="Paginazione"
      >
        <button
          type="button"
          className={`${iconBtn} ${erpFocus}`}
          aria-label="Prima pagina"
          disabled={page <= 1}
          onClick={() => onPageChange(1)}
        >
          ≪
        </button>
        <button
          type="button"
          className={`${iconBtn} ${erpFocus}`}
          aria-label="Pagina precedente"
          disabled={page <= 1}
          onClick={() => onPageChange(page - 1)}
        >
          ‹
        </button>
        {showFirst ? (
          <button type="button" className={`${pageBtnBase} ${erpFocus}`} onClick={() => onPageChange(1)}>
            1
          </button>
        ) : null}
        {showFirstGap ? <span className="px-0.5 text-xs text-[color:var(--cab-text-muted)]">…</span> : null}
        {mid.map((p) => (
          <button
            key={p}
            type="button"
            className={`${pageBtnBase} ${erpFocus} ${p === page ? pageBtnActive : ""}`}
            aria-current={p === page ? "page" : undefined}
            onClick={() => onPageChange(p)}
          >
            {p}
          </button>
        ))}
        {showLastGap ? <span className="px-0.5 text-xs text-[color:var(--cab-text-muted)]">…</span> : null}
        {showLast ? (
          <button type="button" className={`${pageBtnBase} ${erpFocus}`} onClick={() => onPageChange(pageCount)}>
            {pageCount}
          </button>
        ) : null}
        <button
          type="button"
          className={`${iconBtn} ${erpFocus}`}
          aria-label="Pagina successiva"
          disabled={page >= pageCount}
          onClick={() => onPageChange(page + 1)}
        >
          ›
        </button>
        <button
          type="button"
          className={`${iconBtn} ${erpFocus}`}
          aria-label="Ultima pagina"
          disabled={page >= pageCount}
          onClick={() => onPageChange(pageCount)}
        >
          ≫
        </button>
      </nav>
    </div>
  );
}

