  const { filters, searchInput, setSearchInput, patchFilters, resetFilters } = persistence;
  const l0 = contract.l0;
  const schedeStore = contract.l1?.schedeStore ?? {};

  const statiOpts = useMemo(
    () => filterClientPortalStatiOptions(l0?.statiOpts ?? []),
    [l0?.statiOpts],
  );
  const statoOrderIds = useMemo(() => statiOpts.map((s) => s.id), [statiOpts]);
  const addettiGlobali = l0?.addettiGlobali ?? [];
  const addettiRecords = l0?.addettiRecords ?? [];
  const colStyles = useLavorazioniListTableColStyles(statiOpts, [], addettiGlobali);
  const addettoColors = l0?.addettoColors ?? {};

  useEffect(() => {
    const t = window.setTimeout(() => patchFilters({ search: searchInput.trim() }), SEARCH_DEBOUNCE_MS);
    return () => window.clearTimeout(t);
  }, [searchInput, patchFilters]);

  const [qrRow, setQrRow] = useState<LavorazioneListRow | null>(null);
  const [ingressoRow, setIngressoRow] = useState<LavorazioneListRow | null>(null);
  const [contattaciOpen, setContattaciOpen] = useState(false);
  const [filtriEspansi, setFiltriEspansi] = useState(false);

  const [sortInCorsoCol, setSortInCorsoCol] = useState<ClientPortalSortKey | null>(null);
  const [sortInCorsoPhase, setSortInCorsoPhase] = useState<GlobalTableSortPhase>("natural");
  const [sortArchivioCol, setSortArchivioCol] = useState<ClientPortalSortKey | null>(null);
  const [sortArchivioPhase, setSortArchivioPhase] = useState<GlobalTableSortPhase>("natural");

  const filtersActive = clientPortalFiltersActive(filters);

  const allInCorsoBundles = useMemo(
    () => buildRowBundles(l0?.inCorsoRows ?? [], schedeStore, addettiGlobali, addettiRecords),
    [l0?.inCorsoRows, schedeStore, addettiGlobali, addettiRecords],
  );

  const allArchivioBundles = useMemo(
    () => buildRowBundles(l0?.archivioRows ?? [], schedeStore, addettiGlobali, addettiRecords),
    [l0?.archivioRows, schedeStore, addettiGlobali, addettiRecords],
  );

  const defaultAddetto = addettiGlobali[0] ?? "";

  const filterCatalog = useMemo(() => {
    return buildClientPortalFilterCatalog(
      [...allInCorsoBundles, ...allArchivioBundles],
      schedeStore,
      addettiGlobali,
      defaultAddetto,
    );
  }, [allInCorsoBundles, allArchivioBundles, schedeStore, addettiGlobali, defaultAddetto]);

  const inCorsoBundles = useMemo(
    () => filterClientPortalBundles(allInCorsoBundles, filters, schedeStore, defaultAddetto, "in_corso"),
    [allInCorsoBundles, filters, schedeStore, defaultAddetto],
  );

  const archivioBundles = useMemo(
    () => filterClientPortalBundles(allArchivioBundles, filters, schedeStore, defaultAddetto, "archivio"),
    [allArchivioBundles, filters, schedeStore, defaultAddetto],
  );

  useEffect(() => {
    if (accessDenied || !l0) return;
    logClientPortalPipelineDebug({
      inCorsoRaw: l0.inCorsoRows.length,
      archivioRaw: l0.archivioRows.length,
      bundlesInCorso: allInCorsoBundles.length,
      bundlesArchivio: allArchivioBundles.length,
      filteredInCorso: inCorsoBundles.length,
      filteredArchivio: archivioBundles.length,
      filters,
      filtersActive,
    });
  }, [
    accessDenied,
    allArchivioBundles.length,
    allInCorsoBundles.length,
    filters,
    filtersActive,
    inCorsoBundles.length,
    archivioBundles.length,
    l0,
  ]);

  const sortedInCorsoBundles = useMemo(
    () =>
      sortClientPortalBundles(inCorsoBundles, sortInCorsoCol, sortInCorsoPhase, "active", statoOrderIds),
    [inCorsoBundles, sortInCorsoCol, sortInCorsoPhase, statoOrderIds],
  );

  const sortedArchivioBundles = useMemo(
    () =>
      sortClientPortalBundles(archivioBundles, sortArchivioCol, sortArchivioPhase, "archive", statoOrderIds),
    [archivioBundles, sortArchivioCol, sortArchivioPhase, statoOrderIds],
  );

  const onSortInCorso = useCallback(
    (k: ClientPortalSortKey) =>
      cycleLavorazioniTableSort(sortInCorsoCol, setSortInCorsoCol, setSortInCorsoPhase, k),
    [sortInCorsoCol],
  );

  const onSortArchivio = useCallback(
    (k: ClientPortalSortKey) =>
      cycleLavorazioniTableSort(sortArchivioCol, setSortArchivioCol, setSortArchivioPhase, k),
    [sortArchivioCol],
  );

  const showInCorso = filters.section !== "archivio";
  const showArchivio = filters.section !== "in_corso";

  const totalResults =
    (showInCorso ? inCorsoBundles.length : 0) + (showArchivio ? archivioBundles.length : 0);

  const resetRicerca = useCallback(() => {
    setSearchInput("");
    patchFilters({ search: "" });
  }, [patchFilters, setSearchInput]);

  const resetFiltri = useCallback(() => {
    resetFilters();
    setFiltriEspansi(false);
  }, [resetFilters]);

  if (accessDenied) {
    return (
      <>
        <PageHeader title={PORTALE_CLIENTI_LABEL} />
        <div className={dsStackPage}>
          <ShellCard>
            <p className="text-sm text-zinc-600 dark:text-zinc-400">
              Non hai permesso per consultare il portale clienti. Contatta un amministratore per assegnare il ruolo Cliente.
            </p>
            <Link href={CLIENTE_HOME_PATH} className={`mt-4 inline-flex ${dsBtnNeutral}`}>
              Torna al portale
            </Link>
          </ShellCard>
        </div>
      </>
    );
  }

  const listError = contract.l0Status === "error" ? contract.error : null;

  let bodyContent: ReactNode;
  if (!canRender) {
    bodyContent = <ClientLavorazioniLoadingSkeleton />;
  } else if (listError) {
    bodyContent = (
      <ShellCard>
        <LoadingErrorState
          title="Impossibile caricare le lavorazioni"
          description="Controlla la connessione e riprova."
          onRetry={() => {
            void contract.retryL0();
          }}
        />
      </ShellCard>
    );
  } else {
    bodyContent = (
      <>
        {showInCorso ? (
          <ShellCard
            title={`Lavorazioni in corso (${sortedInCorsoBundles.length})`}
            collapsible
            defaultCollapsed={false}
          >
            <LavorazioniSection
              listLayout={listLayout}
              sectionLabel="Lavorazioni in corso"
              bundles={sortedInCorsoBundles}
              variant="active"
              statiOpts={statiOpts}
              colStyles={colStyles}
              addettoColors={addettoColors}
              schedeStore={schedeStore}
              emptyDefault="Nessuna lavorazione in corso."
              filtersActive={filtersActive}
              sortColumn={sortInCorsoCol}
              sortPhase={sortInCorsoPhase}
              onSort={onSortInCorso}
              onIngresso={setIngressoRow}
              onQr={setQrRow}
            />
          </ShellCard>
        ) : null}
        {showArchivio ? (
          <ShellCard
            title={`Lavorazioni completate (${sortedArchivioBundles.length})`}
            collapsible
            defaultCollapsed
          >
            <LavorazioniSection
              listLayout={listLayout}
              sectionLabel="Lavorazioni completate"
              bundles={sortedArchivioBundles}
              variant="archive"
              statiOpts={statiOpts}
              colStyles={colStyles}
              addettoColors={addettoColors}
              schedeStore={schedeStore}
              emptyDefault="Nessuna lavorazione in archivio."
              filtersActive={filtersActive}
              sortColumn={sortArchivioCol}
              sortPhase={sortArchivioPhase}
              onSort={onSortArchivio}
              onIngresso={setIngressoRow}
              onQr={setQrRow}
            />
          </ShellCard>
        ) : null}
      </>
    );
  }

  return (
    <div ref={listLayoutRef} className={`lavorazioni-scroll-scope ${layoutPageRoot} ${listLayoutClassName}`.trim()}>
    <>
      <PageHeader
        title={PORTALE_CLIENTI_LABEL}
        actions={
          <div className={gestionalePageToolbarActionsInnerClass}>
            <GestionaleRefreshToolbarButton busy={refreshBusy} onClick={() => void refreshClientData()} />
          </div>
        }
      />

      <div className={dsStackPage}>
        <ShellCard>
          <section aria-label="Azioni e filtri lavorazioni clienti">
            <PageToolbar
              primaryAction={
                <ClientContattaciButton variant="primary" onClick={() => setContattaciOpen(true)} />
              }
              search={
                <GestionaleSearchField
                  id="client-lavorazioni-search"
                  value={searchInput}
                  onChange={(e) => setSearchInput(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") {
                      e.preventDefault();
                      patchFilters({ search: searchInput.trim() });
                    }
                  }}
                  placeholder={GESTIONALE_SEARCH_PLACEHOLDER}
                  aria-label="Cerca lavorazioni clienti"
                  wrapperClassName="min-w-0 flex-1 sm:min-w-[12rem]"
                />
              }
              filtersExpanded={filtriEspansi}
              onFiltersToggle={() => setFiltriEspansi((o) => !o)}
              filtersActive={filtersActive}
              filtersPanel={
                <LavorazioniAdvancedFilterPanel
                  filters={filters}
                  onChange={patchFilters}
                  catalog={filterCatalog}
                  variant="clientPortal"
                />
              }
              onFilterReset={resetFiltri}
              meta={
                <PageToolbarResultCount
                  count={totalResults}
                  filtersActive={lavorazioniAdvancedFiltersActive(filters)}
                  searchActive={filters.search.trim().length > 0 || searchInput.trim().length > 0}
                  onSearchReset={resetRicerca}
                  onFilterReset={resetFiltri}
                />
              }
            />
          </section>
        </ShellCard>

        {bodyContent}
      </div>

      {qrRow ? (
        <ClientLavorazioneQrDialog
          open
          onClose={() => setQrRow(null)}
          lavorazioneId={qrRow.id}
          refLabel={lavorazioneRefLabel(qrRow.id, qrRow.codice)}
        />
      ) : null}

      {ingressoRow ? (
        <ClientLavorazioneIngressoDialog
          open
          onClose={() => setIngressoRow(null)}
          row={ingressoRow}
          schedeStore={schedeStore}
          addettiGlobali={addettiGlobali}
          addettiRecords={addettiRecords}
        />
      ) : null}

      {contattaciOpen ? <ClientContattaciDialog open onClose={() => setContattaciOpen(false)} /> : null}
    </>
    </div>
  );
}

"use client";

import { useMemo, useState } from "react";
import { GestionaleInfoCard } from "@/components/design-system/gestionale-info-card";
import { statoPillShellClassDynamic } from "@/components/gestionale/lavorazioni/lavorazioni-shared";
import {
  buildLavorazioneAttivitaFeed,
  filterLavorazioneAttivita,
  statoLabelForAttivita,
  type LavorazioneAttivitaEvent,
  type LavorazioneAttivitaFeedInput,
  type LavorazioneAttivitaFilter,
} from "@/lib/lavorazioni/lavorazione-attivita-feed";
import { statoDisplayColor } from "@/lib/lavorazioni/lavorazioni-theme";
import { readablePillStyleFromHex } from "@/lib/lavorazioni/table-pill-readability";
import { formatGestionaleLogMetaLine, type GestionaleLogEventTone } from "@/lib/gestionale-log/view-model";
import {
  dsFocus,
  dsSegmentedBtnOff,
  dsSegmentedBtnOn,
  dsSegmentedWrap,
} from "@/lib/ui/design-system";

const FILTER_OPTIONS: { id: LavorazioneAttivitaFilter; label: string; shortLabel: string }[] = [
  { id: "all", label: "Tutto", shortLabel: "Tutto" },
  { id: "stati", label: "Solo stati", shortLabel: "Stati" },
  { id: "important", label: "Solo importanti", shortLabel: "Importanti" },
];

const TIMELINE_RING =
  "ring-[color:color-mix(in_srgb,var(--cab-surface-2)_88%,var(--cab-card))]";

const TONE_DOT: Record<GestionaleLogEventTone, string> = {
  create: "bg-emerald-500",
  update: "bg-[color:var(--cab-primary)]",
  delete: "bg-red-500",
  complete: "bg-sky-500",
  archive: "bg-[color:var(--cab-text-muted)]",
  reopen: "bg-indigo-500",
  neutral: "bg-[color:var(--cab-text-muted)]",
};

function timelineDotClass(tier: LavorazioneAttivitaEvent["tier"], tone: GestionaleLogEventTone): string {
  if (tier === "stato") return `h-3 w-3 bg-[color:var(--cab-primary)] ring-[3px] ${TIMELINE_RING}`;
  if (tier === "secondary") return `h-2 w-2 bg-[color:var(--cab-text-muted)] opacity-50 ring-2 ${TIMELINE_RING}`;
  return `h-2.5 w-2.5 ring-2 ${TIMELINE_RING} ${TONE_DOT[tone]}`;
}

function AttivitaEventRow({
  ev,
  index,
  total,
  statiOpts,
}: {
  ev: LavorazioneAttivitaEvent;
  index: number;
  total: number;
  statiOpts: { id: string; label: string; color?: string }[];
}) {
  const statoLabel = ev.statoId ? statoLabelForAttivita(ev.statoId, statiOpts) : null;
  const statoStyle = ev.statoId
    ? readablePillStyleFromHex(statoDisplayColor(ev.statoId, statiOpts))
    : undefined;
  const isStato = ev.tier === "stato";
  const isSecondary = ev.tier === "secondary";

  return (
    <li className="relative flex gap-3 py-3.5 first:pt-0 last:pb-0">
      <div className="relative flex w-5 shrink-0 justify-center pt-1">
        {index < total - 1 ? (
          <span
            className="absolute top-4 bottom-0 left-1/2 w-px -translate-x-1/2 bg-[color:color-mix(in_srgb,var(--cab-border)_90%,transparent)]"
            aria-hidden
          />
        ) : null}
        <span
          className={`relative z-10 shrink-0 rounded-full ${timelineDotClass(ev.tier, ev.tone)}`}
          aria-hidden
        />
      </div>
      <div
        className={`min-w-0 flex-1 ${
          isStato
            ? "rounded-[var(--ds-radius-lg)] border border-[color:color-mix(in_srgb,var(--cab-primary)_22%,var(--cab-border))] bg-[color:color-mix(in_srgb,var(--cab-primary)_6%,var(--cab-surface))] px-2.5 py-2"
            : isSecondary
              ? "opacity-75"
              : ""
        }`}
      >
        <div className="flex min-w-0 flex-wrap items-center gap-x-2 gap-y-1">
          <p
            className={`min-w-0 uppercase tracking-wide ${
              isStato
                ? "text-xs font-bold text-[color:var(--cab-text)]"
                : isSecondary
                  ? "text-[10px] font-semibold text-[color:var(--cab-text-muted)]"
                  : "text-xs font-bold text-[color:var(--cab-text)]"
            }`}
          >
            {ev.title}
          </p>
          {statoLabel && isStato ? (
            <span
              className={`${statoPillShellClassDynamic()} inline-flex px-2 py-0.5 text-[10px] font-semibold whitespace-nowrap`}
              style={statoStyle}
            >
              {statoLabel}
            </span>
          ) : null}
        </div>
        <p
          className={`whitespace-pre-wrap leading-relaxed text-[color:var(--cab-text-muted)] ${
            isSecondary ? "mt-0.5 text-[11px]" : "mt-1 text-sm"
          }`}
        >
          {ev.description}
        </p>
        <p className="mt-1.5 text-[10px] tabular-nums text-[color:var(--cab-text-muted)]">
          {formatGestionaleLogMetaLine(ev.autore, ev.at)}
        </p>
      </div>
    </li>
  );
}

function AttivitaFilterSegmented({
  filter,
  onChange,
}: {
  filter: LavorazioneAttivitaFilter;
  onChange: (next: LavorazioneAttivitaFilter) => void;
}) {
  return (
    <div className="flex min-w-0 flex-col gap-1.5">
      <p className="text-[10px] font-semibold uppercase tracking-wide text-[color:var(--cab-text-muted)]">
        Visualizza
      </p>
      <div
        className={`${dsSegmentedWrap} w-full min-w-0 gap-0.5 p-0.5`}
        role="group"
        aria-label="Filtro attività"
      >
        {FILTER_OPTIONS.map((opt) => {
          const active = filter === opt.id;
          return (
            <button
              key={opt.id}
              type="button"
              className={`flex min-h-10 min-w-0 flex-1 items-center justify-center px-2 text-center text-xs font-semibold sm:min-h-9 sm:px-3 sm:text-sm ${
                active ? dsSegmentedBtnOn : dsSegmentedBtnOff
              } ${dsFocus}`}
              aria-pressed={active}
              title={opt.label}
              onClick={() => onChange(opt.id)}
            >
              <span className="sm:hidden">{opt.shortLabel}</span>
              <span className="hidden sm:inline">{opt.label}</span>
            </button>
          );
        })}
      </div>
    </div>
  );
}

export function LavorazioneAttivitaPanel({
  feedInput,
  emptyMessage = "Nessuna attività registrata per questa lavorazione.",
}: {
  feedInput: LavorazioneAttivitaFeedInput | null;
  emptyMessage?: string;
}) {
  const [filter, setFilter] = useState<LavorazioneAttivitaFilter>("all");

  const allEvents = useMemo(
    () => (feedInput ? buildLavorazioneAttivitaFeed(feedInput) : []),
    [feedInput],
  );

  const events = useMemo(() => filterLavorazioneAttivita(allEvents, filter), [allEvents, filter]);

  const subtitle =
    filter === "all"
      ? allEvents.length === 1
        ? "1 evento registrato"
        : `${allEvents.length} eventi registrati`
      : events.length === 1
        ? `1 di ${allEvents.length} eventi`
        : `${events.length} di ${allEvents.length} eventi`;

  return (
    <GestionaleInfoCard compact title="Attività lavorazione" subtitle={subtitle}>
      <AttivitaFilterSegmented filter={filter} onChange={setFilter} />
      <div className="mt-3.5 border-t border-[color:var(--cab-border)] pt-3.5">
        {events.length === 0 ? (
          <div className="rounded-[var(--ds-radius-lg)] border border-dashed border-[color:var(--cab-border)] bg-[color:color-mix(in_srgb,var(--cab-surface-2)_55%,var(--cab-card))] px-3 py-4 text-center">
            <p className="text-sm font-medium text-[color:var(--cab-text)]">
              {allEvents.length === 0 ? "Nessuna attività" : "Nessun evento per questo filtro"}
            </p>
            <p className="mt-1 text-[11px] leading-snug text-[color:var(--cab-text-muted)]">
              {allEvents.length === 0 ? emptyMessage : "Prova un altro filtro per vedere più eventi."}
            </p>
          </div>
        ) : (
          <ol className="divide-y divide-[color:var(--cab-border)]">
            {events.map((ev, index) => (
              <AttivitaEventRow
                key={ev.id}
                ev={ev}
                index={index}
                total={events.length}
                statiOpts={feedInput?.statiOpts ?? []}
              />
            ))}
          </ol>
        )}
      </div>
    </GestionaleInfoCard>
  );
}

"use client";

import Link from "next/link";
import { buildAgendaFromLavorazioneHref } from "@/lib/navigation/agenda-links";
import { localDateTimeLabel } from "@/lib/workshop-schedule/datetime";
import { PLANNING_STATUS_LABELS } from "@/lib/workshop-schedule/types";
import { erpBtnNeutral, erpBtnSoftOrange } from "@/components/gestionale/lavorazioni/lavorazioni-shared";
import { useWorkshopScheduleByWorkOrder } from "@/src/hooks/use-workshop-schedule-by-work-order";

/**
 * Pannello read-only — lazy-loaded dal dettaglio lavorazione.
 * Chiama solo listByWorkOrder; nessun import da Agenda UI.
 */
export function LavorazionePlanningPanel({ lavorazioneId }: { lavorazioneId: string }) {
  const query = useWorkshopScheduleByWorkOrder(lavorazioneId);
  const sessions = query.data ?? [];

  if (query.isLoading) return <p className="text-xs text-zinc-500">Caricamento pianificazione…</p>;
  if (query.isError) {
    return <p className="text-xs text-amber-700 dark:text-amber-200">Pianificazione non disponibile.</p>;
  }

  return (
    <div className="rounded-lg border border-zinc-200 bg-white p-3 dark:border-zinc-700 dark:bg-zinc-950/40">
      <div className="mb-2 flex flex-wrap items-center justify-between gap-2">
        <p className="text-[10px] font-bold uppercase tracking-wide text-zinc-500">Pianificazione</p>
        <div className="flex flex-wrap gap-2">
          <Link href={buildAgendaFromLavorazioneHref(lavorazioneId)} className={erpBtnNeutral}>
            Apri Agenda →
          </Link>
          <Link href={buildAgendaFromLavorazioneHref(lavorazioneId)} className={erpBtnSoftOrange}>
            + Aggiungi sessione
          </Link>
        </div>
      </div>
      {sessions.length === 0 ? (
        <p className="text-sm text-zinc-500">Nessuna sessione pianificata.</p>
      ) : (
        <ul className="space-y-2 text-sm">
          {sessions.map((s) => (
            <li
              key={s.id}
              className="flex flex-wrap items-center justify-between gap-2 border-b border-zinc-100 pb-2 last:border-0 dark:border-zinc-800"
            >
              <span>
                {localDateTimeLabel(s.startAt)} – {localDateTimeLabel(s.endAt)}
              </span>
              <span className="rounded bg-zinc-100 px-2 py-0.5 text-[10px] font-semibold uppercase dark:bg-zinc-800">
                {PLANNING_STATUS_LABELS[s.planningStatus]}
              </span>
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}

