          label="Priorità"
          value={filters.priorities?.[0] ?? ""}
          onChange={(v) =>
            onChange({
              ...filters,
              priorities: v ? [v as (typeof WORKSHOP_PRIORITIES)[number]] : undefined,
            })
          }
        >
          <option value="">Tutte</option>
          {WORKSHOP_PRIORITIES.map((p) => (
            <option key={p} value={p}>
              {PRIORITY_LABELS[p]}
            </option>
          ))}
