        {filters.workOrderId ? (
          <Tooltip content="Filtro attivo dalla lavorazione collegata">
            <span className={dsBadgeNeutral}>Lavorazione selezionata</span>
          </Tooltip>
        ) : null}
      </div>
    </div>
  );
}

