"use client";

import {
  createContext,
  useCallback,
  useContext,
  useEffect,
  useMemo,
  useRef,
  useState,
  type ReactNode,
} from "react";
import { useToastContext } from "@/context/toast-context";
import { GESTIONALE_TOAST } from "@/src/lib/ux/gestionale-toast-messages";
import { UPLOAD_SUCCESS_VISIBLE_MS } from "@/lib/upload/upload-feedback-messages";
import { humanizeGestionaleError } from "@/src/utils/gestionale-error-messages";
import type {
  RunUploadParams,
  TrackUploadParams,
  UploadFeedbackItem,
  UploadFeedbackPhase,
} from "@/lib/upload/upload-feedback-types";
import {
  createUploadId,
  ensureMinUploadLoading,
  uploadErrorMessage,
} from "@/lib/upload/upload-feedback-utils";

type UploadFeedbackContextValue = {
  items: UploadFeedbackItem[];
  activeCount: number;
  isUploading: boolean;
  trackUpload: <T>(params: TrackUploadParams<T>) => Promise<{ ok: true; data: T } | { ok: false; error: string }>;
  runUpload: <T>(params: RunUploadParams<T>) => Promise<{ ok: true; data: T } | { ok: false; error: string }>;
  setProgress: (id: string, pct: number | null) => void;
  clearItem: (id: string) => void;
};

const UploadFeedbackContext = createContext<UploadFeedbackContextValue | null>(null);

function patchItem(
  prev: UploadFeedbackItem[],
  id: string,
  patch: Partial<UploadFeedbackItem>,
): UploadFeedbackItem[] {
  return prev.map((item) => (item.id === id ? { ...item, ...patch } : item));
}

export function UploadFeedbackProvider({ children }: { children: ReactNode }) {
  const { push: pushToast } = useToastContext();
  const [items, setItems] = useState<UploadFeedbackItem[]>([]);
  const itemsRef = useRef(items);
  itemsRef.current = items;
  const removeTimeoutsRef = useRef<Set<number>>(new Set());

  useEffect(() => {
    const timeouts = removeTimeoutsRef.current;
    return () => {
      for (const t of timeouts) clearTimeout(t);
      timeouts.clear();
    };
  }, []);

  const clearItem = useCallback((id: string) => {
    setItems((prev) => prev.filter((x) => x.id !== id));
  }, []);

  const scheduleRemove = useCallback(
    (id: string, delayMs: number) => {
      const t = window.setTimeout(() => {
        removeTimeoutsRef.current.delete(t);
        setItems((prev) => prev.filter((x) => x.id !== id));
      }, delayMs);
      removeTimeoutsRef.current.add(t);
    },
    [],
  );

  const setPhase = useCallback((id: string, phase: UploadFeedbackPhase, error: string | null = null) => {
    setItems((prev) => patchItem(prev, id, { phase, error }));
  }, []);

  const setProgress = useCallback((id: string, pct: number | null) => {
    setItems((prev) => patchItem(prev, id, { progress: pct }));
  }, []);

  const executeTracked = useCallback(
    async <T,>(
      meta: { id: string; fileName: string; label: string; file: File | null },
      params: {
        run: () => Promise<T>;
        onProgress?: (pct: number) => void;
        onSuccess?: (data: T) => void;
        onError?: (message: string) => void;
        successToast?: string | false;
        showErrorToast?: boolean;
      },
    ): Promise<{ ok: true; data: T } | { ok: false; error: string }> => {
      const startedAt = Date.now();
      setPhase(meta.id, "uploading", null);
      setProgress(meta.id, null);

      const reportProgress = (pct: number) => {
        setProgress(meta.id, pct);
        params.onProgress?.(pct);
      };

      try {
        const data = await params.run();
        reportProgress(100);
        await ensureMinUploadLoading(startedAt);
        setPhase(meta.id, "success", null);
        params.onSuccess?.(data);
        if (params.successToast !== false) {
          pushToast(params.successToast ?? GESTIONALE_TOAST.successUploaded, "success");
        }
        scheduleRemove(meta.id, UPLOAD_SUCCESS_VISIBLE_MS);
        return { ok: true, data };
      } catch (e) {
        const message = uploadErrorMessage(e);
        await ensureMinUploadLoading(startedAt);
        setPhase(meta.id, "error", message);
        params.onError?.(message);
        if (params.showErrorToast !== false) {
          pushToast(humanizeGestionaleError(message), "error");
        }
        return { ok: false, error: message };
      }
    },
    [pushToast, scheduleRemove, setPhase, setProgress],
  );

  const trackUpload = useCallback(
    async <T,>(params: TrackUploadParams<T>): Promise<{ ok: true; data: T } | { ok: false; error: string }> => {
      const id = createUploadId();
      const fileName = params.file.name.trim() || "file";
      const label = params.label?.trim() || fileName;

      const retry = () => {
        const item = itemsRef.current.find((x) => x.id === id);
        const file = item?.file ?? params.file;
        void trackUpload({ ...params, file });
      };

      const item: UploadFeedbackItem = {
        id,
        fileName,
        label,
        phase: "selected",
        error: null,
        startedAt: Date.now(),
        progress: null,
        file: params.file,
        retry,
      };

      setItems((prev) => [...prev, item]);

      return executeTracked(
        { id, fileName, label, file: params.file },
        {
          run: () => params.run(params.file),
          onProgress: params.onProgress,
          onSuccess: params.onSuccess,
          onError: params.onError,
          successToast: params.successToast,
          showErrorToast: params.showErrorToast,
        },
      );
    },
    [executeTracked],
  );

  const runUpload = useCallback(
    async <T,>(params: RunUploadParams<T>): Promise<{ ok: true; data: T } | { ok: false; error: string }> => {
      const id = createUploadId();
      const fileName = params.fileName.trim() || "file";
      const label = params.label?.trim() || fileName;

      const retry = () => {
        void runUpload(params);
      };

      setItems((prev) => [
        ...prev,
        {
          id,
          fileName,
          label,
          phase: "uploading" as const,
          error: null,
          startedAt: Date.now(),
          progress: null,
          file: null,
          retry,
        },
      ]);

      return executeTracked(
        { id, fileName, label, file: null },
        {
          run: params.run,
          onProgress: params.onProgress,
          onSuccess: params.onSuccess,
          onError: params.onError,
          successToast: params.successToast,
          showErrorToast: params.showErrorToast,
        },
      );
    },
    [executeTracked],
  );

  const activeCount = items.filter((x) => x.phase === "uploading" || x.phase === "selected").length;
  const isUploading = items.some((x) => x.phase === "uploading");

  const value = useMemo(
    () => ({
      items,
      activeCount,
      isUploading,
      trackUpload,
      runUpload,
      setProgress,
      clearItem,
    }),
    [items, activeCount, isUploading, trackUpload, runUpload, setProgress, clearItem],
  );

  return <UploadFeedbackContext.Provider value={value}>{children}</UploadFeedbackContext.Provider>;
}

export function useUploadFeedback(): UploadFeedbackContextValue {
  const ctx = useContext(UploadFeedbackContext);
  if (!ctx) {
    throw new Error("useUploadFeedback must be used within UploadFeedbackProvider");
  }
  return ctx;
}

export function useUploadFeedbackOptional(): UploadFeedbackContextValue | null {
  return useContext(UploadFeedbackContext);
}

import { test as base, expect, type Page } from "@playwright/test";

export type SmokeCredentials = {
  email: string;
  password: string;
};

export function adminCredentials(): SmokeCredentials {
  const email = process.env.SMOKE_ADMIN_EMAIL?.trim();
  const password = process.env.SMOKE_ADMIN_PASSWORD?.trim();
  if (!email || !password) {
    throw new Error("SMOKE_ADMIN_EMAIL and SMOKE_ADMIN_PASSWORD are required for Playwright smoke");
  }
  return { email, password };
}

export function operatorCredentials(): SmokeCredentials | null {
  const email = process.env.SMOKE_OPERATOR_EMAIL?.trim();
  const password = process.env.SMOKE_OPERATOR_PASSWORD?.trim();
  if (!email || !password) return null;
  return { email, password };
}

export function clientCredentials(): SmokeCredentials | null {
  const email = process.env.SMOKE_CLIENT_EMAIL?.trim();
  const password = process.env.SMOKE_CLIENT_PASSWORD?.trim();
  if (!email || !password) return null;
  return { email, password };
}

async function ensureAccountMenuVisible(page: Page): Promise<void> {
  const accountMenu = page.getByTestId("smoke-account-menu");
  if (await accountMenu.isVisible()) return;
  const drawerOpen = page.getByTestId("smoke-nav-drawer-open");
  if (await drawerOpen.isVisible()) {
    await drawerOpen.click();
  }
  await expect(accountMenu).toBeVisible({ timeout: 15_000 });
}

export async function loginViaUi(page: Page, creds: SmokeCredentials): Promise<void> {
  await expect(async () => {
    await page.goto("/login");
    await page.getByTestId("smoke-login-identifier").fill(creds.email);
    await page.getByTestId("smoke-login-password").fill(creds.password);
    await page.getByTestId("smoke-login-submit").click();
    await page.waitForURL((url) => !url.pathname.startsWith("/login"), {
      timeout: 45_000,
      waitUntil: "domcontentloaded",
    });
  }).toPass({ timeout: 90_000 });

  await ensureAccountMenuVisible(page);
}

export async function logoutViaUi(page: Page): Promise<void> {
  await ensureAccountMenuVisible(page);
  await page.getByTestId("smoke-account-menu").click();
  await expect(page.getByTestId("profile-sheet")).toBeVisible({ timeout: 10_000 });
  await expect(page.getByTestId("smoke-logout")).toBeVisible({ timeout: 10_000 });
  await page.getByTestId("smoke-logout").click();
  await expect(page.getByTestId("smoke-logout-confirm")).toBeVisible({ timeout: 10_000 });
  await page.getByTestId("smoke-logout-confirm").click();
  await page.waitForURL(/\/login/, { timeout: 30_000 });
}

export const test = base.extend<{ adminCreds: SmokeCredentials }>({
  adminCreds: async ({}, use) => {
    await use(adminCredentials());
  },
});

export { expect } from "@playwright/test";

/**
 * RBAC gestionale — routing, sezioni UI, compat layer.
 * Capability + moduli ERP: @/lib/rbac.ts (single source of truth frontend).
 */

import {
  CANONICAL_ROLES,
  type AppRole,
  type CanonicalRole,
  type Capability,
  type RbacEvaluationContext,
  RBAC_DENIED_MESSAGE,
  resolveCanonicalRole,
  resolveRole,
  ROLE_LABELS,
  type RequiredRbacContext,
} from "@/lib/rbac";
import {
  canReadModule as resolvedCanReadModule,
  canWriteModule as resolvedCanWriteModule,
  hasResolvedCapability,
} from "@/src/lib/rbac/resolve-user-permissions";
import type { GestionalePermissionModule } from "@/src/lib/permissions/gestionale-modules";

export {
  CANONICAL_ROLES,
  type AppRole,
  type CanonicalRole,
  type Capability,
  type RbacEvaluationContext,
  type RequiredRbacContext,
  RBAC_DENIED_MESSAGE,
  resolveCanonicalRole,
  resolveRole,
  ROLE_LABELS,
};
export const APP_ROLES = CANONICAL_ROLES;
export const normalizeRole = resolveRole;

function capFromCtx(ctx: RbacEvaluationContext | undefined, cap: Capability): boolean {
  if (!ctx?.resolved) return false;
  return hasResolvedCapability(ctx.resolved, cap);
}

/** @internal Test-only — documents fail-closed without resolved snapshot. */
export function hasPermissionUnsafe(
  user: RbacUser,
  permission: PermissionKey,
  ctx?: RbacEvaluationContext,
): boolean {
  return hasPermission(user, permission, ctx as RequiredRbacContext);
}

export type PermissionKey =
  | "manageUsers"
  | "manageSecurity"
  | "manageSettings"
  | "editInventory"
  | "editWorkOrders"
  | "editVehicles"
  | "uploadDocuments"
  | "deleteRecords"
  | "viewReports"
  | "viewAuditLogs"
  | "viewClientLavorazioni";

export type RbacSection =
  | "dashboard"
  | "lavorazioni"
  | "lavorazioni_clienti"
  | "preventivi"
  | "documenti"
  | "magazzino"
  | "mezzi"
  | "report"
  | "dipendenti"
  | "fatturazione"
  | "ddt"
  | "ordini_fornitori"
  | "impostazioni"
  | "security";

export type SectionAccess = { read: boolean; write: boolean; delete: boolean };

export type RbacUser =
  | { ruolo?: string | null; id?: string | null }
  | string
  | null
  | undefined;

export type CanAccessPageOptions = {
  clientLavorazioniAllowed?: boolean;
};

export const CLIENTE_HOME_PATH = "/lavorazioni-clienti";
export const SECURITY_HOME_PATH = "/sicurezza";
export const ACCESS_DENIED_PATH = "/acesso-negato";
export const READONLY_PERMISSION_HINT = RBAC_DENIED_MESSAGE;

const SECTION_TO_MODULE: Partial<Record<RbacSection, GestionalePermissionModule>> = {
  magazzino: "magazzino",
  preventivi: "preventivi",
  lavorazioni: "lavorazioni",
  mezzi: "mezzi",
  report: "report",
  documenti: "documenti",
  dipendenti: "dipendenti",
  fatturazione: "fatturazione",
  ddt: "ddt",
  ordini_fornitori: "ordini_fornitori",
};

function moduleSectionAccess(section: RbacSection, ctx?: RbacEvaluationContext): SectionAccess {
  const module = SECTION_TO_MODULE[section];
  if (!module || !ctx?.resolved) {
    return { read: false, write: false, delete: false };
  }
  const read = resolvedCanReadModule(ctx.resolved, module);
  const write = resolvedCanWriteModule(ctx.resolved, module);
  return { read, write, delete: write };
}

function sectionAccess(_user: RbacUser, section: RbacSection, ctx?: RbacEvaluationContext): SectionAccess {
  if (section === "impostazioni") {
    const s = capFromCtx(ctx, "can_manage_settings");
    return { read: s, write: s, delete: s };
  }
  if (section === "security") {
    const s = capFromCtx(ctx, "can_manage_security");
    return { read: s, write: s, delete: s };
  }
  if (section === "lavorazioni_clienti") {
    const r = capFromCtx(ctx, "can_access_client_area");
    return { read: r, write: false, delete: false };
  }
  if (section === "dashboard") {
    const read = capFromCtx(ctx, "can_read_operational");
    const write = capFromCtx(ctx, "can_write_operational");
    return { read, write, delete: write };
  }
  if (SECTION_TO_MODULE[section]) {
    return moduleSectionAccess(section, ctx);
  }
  return { read: false, write: false, delete: false };
}

/** Derivate da capability + matrice moduli. */
export function hasPermission(user: RbacUser, permission: PermissionKey, ctx: RequiredRbacContext): boolean {
  switch (permission) {
    case "manageUsers":
    case "manageSecurity":
      return capFromCtx(ctx, "can_manage_security");
    case "manageSettings":
      return capFromCtx(ctx, "can_manage_settings");
    case "editInventory":
      return canWrite(user, "magazzino", ctx);
    case "editWorkOrders":
      return canWrite(user, "lavorazioni", ctx);
    case "editVehicles":
      return canWrite(user, "mezzi", ctx);
    case "uploadDocuments":
      return canWrite(user, "documenti", ctx);
    case "deleteRecords":
      return capFromCtx(ctx, "can_write_operational") && resolveRole(user) !== "guest";
    case "viewReports":
      return canRead(user, "report", ctx);
    case "viewAuditLogs":
      return capFromCtx(ctx, "can_manage_security");
    case "viewClientLavorazioni":
      return capFromCtx(ctx, "can_access_client_area");
    default:
      return false;
  }
}

export function canRead(user: RbacUser, section: RbacSection, ctx: RequiredRbacContext): boolean {
  return sectionAccess(user, section, ctx).read;
}

export function canWrite(user: RbacUser, section: RbacSection, ctx: RequiredRbacContext): boolean {
  return sectionAccess(user, section, ctx).write;
}

export function canDelete(user: RbacUser, section: RbacSection, ctx: RequiredRbacContext): boolean {
  return sectionAccess(user, section, ctx).delete;
}

export function resolveClientLavorazioniPortalAccess(
  _role: string | null | undefined,
  _userId?: string | null | undefined,
  _settingsEnabledUserIds?: string[],
  ctx?: RequiredRbacContext,
): boolean {
  return capFromCtx(ctx, "can_access_client_area");
}

export function isClienteRole(user: RbacUser): boolean {
  return resolveRole(user) === "cliente";
}

export function roleLabel(user: RbacUser): string {
  return ROLE_LABELS[resolveRole(user)];
}

export function defaultHomePathForRole(user: RbacUser): string {
  return isClienteRole(user) ? CLIENTE_HOME_PATH : "/dashboard";
}

export function pathnameToSection(pathname: string): RbacSection | null {
  const path = pathname.split("?")[0]?.replace(/\/+$/, "") || "/";
  if (path === ACCESS_DENIED_PATH) return null;
  if (path === "/login" || path.startsWith("/login/")) return null;
  if (path.startsWith(SECURITY_HOME_PATH)) return "security";
  if (path.startsWith("/dashboard/security")) return "security";
  if (path === "/agenda" || path.startsWith("/agenda/")) return "dashboard";
  if (path === "/dashboard" || path.startsWith("/dashboard/")) return "dashboard";
  if (path.startsWith("/lavorazioni-clienti")) return "lavorazioni_clienti";
  if (path.startsWith("/lavorazioni")) return "lavorazioni";
  if (path.startsWith("/preventivi")) return "preventivi";
  if (path.startsWith("/documenti")) return "documenti";
  if (path.startsWith("/magazzino")) return "magazzino";
  if (path.startsWith("/mezzi")) return "mezzi";
  if (path.startsWith("/report")) return "report";
  if (path.startsWith("/dipendenti")) return "dipendenti";
  if (path.startsWith("/fatturazione")) return "fatturazione";
  if (path.startsWith("/impostazioni")) return "impostazioni";
  return null;
}

export function canAccessPage(
  user: RbacUser,
  pathname: string,
  opts: CanAccessPageOptions | undefined,
  ctx: RequiredRbacContext,
): boolean {
  const section = pathnameToSection(pathname);
  if (!section) return true;

  if (section === "lavorazioni_clienti") {
    if (hasPermission(user, "viewClientLavorazioni", ctx)) return true;
    if (!canRead(user, section, ctx)) return false;
    return opts?.clientLavorazioniAllowed === true;
  }

  if (section === "security") return hasPermission(user, "manageSecurity", ctx);
  if (section === "impostazioni") return hasPermission(user, "manageSettings", ctx);

  return canRead(user, section, ctx);
}

export function accessDeniedRedirectPath(user: RbacUser): string {
  return `${ACCESS_DENIED_PATH}?from=${encodeURIComponent(defaultHomePathForRole(user))}`;
}

export function navHrefToSection(href: string): RbacSection | null {
  return pathnameToSection(href);
}

export type { GestionalePermissionModule } from "@/src/lib/permissions/gestionale-modules";

export function canReadModule(
  user: RbacUser,
  module: GestionalePermissionModule,
  ctx?: RbacEvaluationContext,
): boolean {
  return modulePermissionForRole(user, module, ctx).canRead;
}

export function canWriteModule(
  user: RbacUser,
  module: GestionalePermissionModule,
  ctx?: RbacEvaluationContext,
): boolean {
  return modulePermissionForRole(user, module, ctx).canWrite;
}

export function modulePermissionForRole(
  _user: RbacUser,
  module: GestionalePermissionModule,
  ctx?: RbacEvaluationContext,
): { canRead: boolean; canWrite: boolean } {
  if (!ctx?.resolved) return { canRead: false, canWrite: false };
  return {
    canRead: resolvedCanReadModule(ctx.resolved, module),
    canWrite: resolvedCanWriteModule(ctx.resolved, module),
  };
}

export function isReadOnlyRole(user: RbacUser): boolean {
  const role = resolveRole(user);
  return role === "guest" || role === "cliente";
}

export function canWriteAnyOperational(_user: RbacUser, ctx: RequiredRbacContext): boolean {
  return capFromCtx(ctx, "can_write_operational");
}

export function isPathAllowedForCliente(pathname: string): boolean {
  if (pathname === "/login" || pathname.startsWith("/login/")) return true;
  return pathname === CLIENTE_HOME_PATH || pathname.startsWith(`${CLIENTE_HOME_PATH}/`);
}

export function shouldHideNavHref(
  user: RbacUser,
  href: string,
  opts: { clientLavorazioniAllowed?: boolean } | undefined,
  ctx: RequiredRbacContext,
): boolean {
  const section = pathnameToSection(href);
  if (!section) return false;
  if (section === "lavorazioni_clienti") {
    if (hasPermission(user, "viewClientLavorazioni", ctx)) return false;
    return !opts?.clientLavorazioniAllowed;
  }
  if (section === "security") return !hasPermission(user, "manageSecurity", ctx);
  if (section === "impostazioni") return !hasPermission(user, "manageSettings", ctx);
  return !canRead(user, section, ctx);
}

