function formatEmployeeNamePdfLines(displayName: string): string {
  const parts = displayName.trim().split(/\s+/).filter(Boolean);
  if (parts.length <= 1) return parts[0] ?? "";
  return `${parts[0]}\n${parts.slice(1).join(" ")}`;
}

function cellForDay(
  empEntries: ReturnType<typeof entriesForEmployee>,
  dateYmd: string,
): ReturnType<typeof entryToCellValue> {
  return entryToCellValue(empEntries.find((e) => e.work_date === dateYmd));
}

function pdfTableCellContent(cell: CellInput): string {
  if (typeof cell === "string" || typeof cell === "number") return String(cell);
  if (cell && typeof cell === "object" && "content" in cell) {
    const content = cell.content;
    return content == null ? "" : String(content);
  }
  return "";
}

function pdfWeekendRow(cells: RowInput): RowInput {
  return headRowCellsForPdf(cells).map((c) => pdfMutedCell(pdfTableCellContent(c))) as RowInput;
}

/** PDF singolo dipendente: una riga per giorno, colonne Presenze e Assenze. */
function drawDipendentePresenzeVerticalTable(
  doc: JsPDFDoc,
  ctx: DipendentiPdfContext,
  employee: DipendenteTimesheetEmployeeRow,
  startY: number,
  pageW: number,
  sectionTitle: string,
): number {
  const empEntries = entriesForEmployee(employee.id, ctx.entries);
  const totals = computeMonthTotals(empEntries);
  const days = buildMonthDays(ctx.monthKey);
  const contentW = pdfContentWidth(pageW);

  const headRow: RowInput = [
    { content: "Giorno", styles: { halign: "left", fontSize: 7.5, fontStyle: "bold" } },
    { content: "Presenze", styles: { halign: "center", fontSize: 7.5, fontStyle: "bold" } },
    { content: "Straordinari", styles: { halign: "center", fontSize: 7.5, fontStyle: "bold" } },
    { content: "Assenze", styles: { halign: "center", fontSize: 7.5, fontStyle: "bold" } },
  ];

  const body: RowInput[] = days.map((d) => {
    const cell = cellForDay(empEntries, d.dateYmd);
    const row: RowInput = [
      {
        content: formatTimesheetDayLabelPdf(d),
        styles: { halign: "left", fontSize: 8, valign: "middle" },
      },
      formatOrdinarieCellPdf(cell),
      formatStraordinarieCellPdf(cell),
      formatAbsenceCellDipendentePdf(cell, ctx.tipiAssenza),
    ];
    return d.isWeekend ? pdfWeekendRow(row) : row;
  });

  body.push([
    { content: "Totali", styles: { halign: "left", fontStyle: "bold", fontSize: 8 } },
    fmtOre(totals.oreOrdinarie),
    fmtOre(totals.oreStraordinarie),
    fmtOre(totals.oreAssenza),
  ]);

  const colGiorno = contentW * 0.26;
  const colData = (contentW - colGiorno) / 3;

  return drawGestionaleDataSectionTable(doc, startY, pageW, sectionTitle, headRow, body, {
    0: { cellWidth: colGiorno, halign: "left", overflow: "linebreak", fontSize: 8 },
    1: { cellWidth: colData, halign: "center", overflow: "hidden", fontSize: 8 },
    2: { cellWidth: colData, halign: "center", overflow: "hidden", fontSize: 8 },
    3: { cellWidth: colData, halign: "center", overflow: "hidden", fontSize: 8 },
  });
}

/** Griglia mensile orizzontale (PDF complessivo): 2 righe per dipendente, totali per colonna e per riga. */
function drawPresenzeMonthlyGrid(
  doc: JsPDFDoc,
  ctx: DipendentiPdfContext,
  startY: number,
  pageW: number,
  sectionTitle: string,
  options: PresenzeMonthlyGridOptions = {},
): number {
  const employees = options.employees ?? ctx.employees;
  const showFooterTotals = options.showFooterTotals ?? true;
  const days = buildMonthDays(ctx.monthKey);
  const weekendColumnIndexes = days
    .map((d, index) => (d.isWeekend ? index + 1 : -1))
    .filter((index) => index > 0);
  const { tableW, nameColW, totColW, dayColWidths } = computeTimesheetGridColumnWidths(pageW, days);
  const tableLayout: GestionaleDataSectionTableLayout = {
    marginLeft: TIMESHEET_PDF_SIDE_MARGIN_MM,
    marginRight: TIMESHEET_PDF_SIDE_MARGIN_MM,
    tableWidth: tableW,
    weekendColumnIndexes,
  };
  const headRow: CellInput[] = [
    { content: "Nome", styles: { halign: "left", fontSize: 7.5, fontStyle: "bold", valign: "middle" } },
    ...days.map((d) => ({
      content: formatTimesheetDayHeaderGrid(d),
      styles: {
        halign: "center" as const,
        fontSize: TIMESHEET_PDF_DAY_NUM_FONT_SIZE,
        valign: "middle" as const,
        fontStyle: "bold" as const,
      },
    })),
    {
      content: "Tot.",
      styles: { halign: "center" as const, fontSize: 6.5, fontStyle: "bold" as const, valign: "middle" as const },
    },
  ];
  const colCount = headRow.length;
  const totColIndex = colCount - 1;

  const styles: Record<
    number,
    {
      cellWidth: number;
      halign: "left" | "center";
      overflow: "hidden" | "linebreak";
      fontSize: number;
      valign?: "top" | "middle" | "bottom";
      cellPadding?: typeof TIMESHEET_PDF_DAY_CELL_PAD;
      minCellHeight?: number;
    }
  > = {
    0: {
      cellWidth: nameColW,
      halign: "left",
      overflow: "linebreak",
      fontSize: TIMESHEET_PDF_BODY_FONT_SIZE,
      valign: "middle",
      minCellHeight: TIMESHEET_PDF_MIN_CELL_HEIGHT_MM,
    },
  };
  for (let i = 1; i < totColIndex; i++) {
    styles[i] = {
      cellWidth: dayColWidths[i - 1]!,
      halign: "center",
      overflow: "hidden",
      fontSize: TIMESHEET_PDF_BODY_FONT_SIZE,
      valign: "middle",
      cellPadding: TIMESHEET_PDF_DAY_CELL_PAD,
      minCellHeight: TIMESHEET_PDF_MIN_CELL_HEIGHT_MM,
    };
  }
  styles[totColIndex] = {
    cellWidth: totColW,
    halign: "center",
    overflow: "hidden",
    fontSize: TIMESHEET_PDF_BODY_FONT_SIZE,
    valign: "middle",
    cellPadding: TIMESHEET_PDF_DAY_CELL_PAD,
    minCellHeight: TIMESHEET_PDF_MIN_CELL_HEIGHT_MM,
  };

  const body: RowInput[] = [];

  for (const emp of employees) {
    const empEntries = entriesForEmployee(emp.id, ctx.entries);
    const totals = computeMonthTotals(empEntries);
    const name = pdfEmployeeDisplayName(ctx, emp);

    const workCells = days.map((d) => {
      const cell = cellForDay(empEntries, d.dateYmd);
      return formatWorkCellShortLabel(cell) || "·";
    });
    const absenceCells = days.map((d) => {
      const cell = cellForDay(empEntries, d.dateYmd);
      return formatAbsenceCellShortLabel(cell, ctx.tipiAssenza) || "·";
    });

    body.push([
      {
        content: formatEmployeeNamePdfLines(name),
        rowSpan: 2,
        styles: {
          halign: "left",
          valign: "middle",
          fontSize: TIMESHEET_PDF_BODY_FONT_SIZE,
          overflow: "linebreak",
        },
      },
      ...workCells.map((c) => pdfGridBodyCell(c)),
      pdfGridBodyCell(fmtOre(totals.totaleLavorato)),
    ]);
    body.push([
      ...absenceCells.map((c) => pdfMutedAbsenceLabelCell(c)),
      pdfMutedTotalCell(fmtOre(totals.oreAssenza)),
    ]);
  }

  if (showFooterTotals) {
    const dailyWorkTotals = days.map((d) => {
      let oreOrdinarie = 0;
      let oreStraordinarie = 0;
      for (const emp of employees) {
        const cell = cellForDay(entriesForEmployee(emp.id, ctx.entries), d.dateYmd);
        oreOrdinarie += cell.oreOrdinarie;
        oreStraordinarie += cell.oreStraordinarie;
      }
      return roundOreSum(oreOrdinarie + oreStraordinarie);
    });

    const dailyAbsenceTotals = days.map((d) => {
      let oreAssenza = 0;
      for (const emp of employees) {
        const cell = cellForDay(entriesForEmployee(emp.id, ctx.entries), d.dateYmd);
        oreAssenza += cell.oreAssenza;
      }
      return roundOreSum(oreAssenza);
    });

    const globalTotals = computeMonthTotals(
      employees.flatMap((emp) => entriesForEmployee(emp.id, ctx.entries)),
    );

    body.push([
      {
        content: "Totali",
        rowSpan: 2,
        styles: {
          halign: "left",
          valign: "middle",
          fontSize: TIMESHEET_PDF_BODY_FONT_SIZE,
          fontStyle: "bold",
        },
      },
      ...dailyWorkTotals.map((t) => pdfGridBodyCell(fmtOre(t))),
      pdfGridBodyCell(fmtOre(globalTotals.totaleLavorato)),
    ]);
    body.push([
      ...dailyAbsenceTotals.map((t) => pdfMutedTotalCell(fmtOre(t))),
      pdfMutedTotalCell(fmtOre(globalTotals.oreAssenza)),
    ]);
  }

  return drawGestionaleDataSectionTable(
    doc,
    startY,
    pageW,
    sectionTitle,
    headRow,
    body,
    styles,
    undefined,
    tableLayout,
  );
}

import { formatPeriodMonthLabel } from "@/lib/report/report-manual-entries-map";
import type { TimesheetMonthKey } from "@/lib/dipendenti/types";

export function monthKeyFromDate(d: Date): TimesheetMonthKey {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  return `${y}-${m}`;
}

export function parseMonthKey(key: TimesheetMonthKey): { year: number; month: number } {
  const [y, m] = key.split("-").map(Number);
  return { year: y, month: m };
}

export function monthKeyToFirstDay(key: TimesheetMonthKey): string {
  return `${key}-01`;
}

export function formatMonthLabel(key: TimesheetMonthKey): string {
  return formatPeriodMonthLabel(monthKeyToFirstDay(key));
}

export function daysInMonth(key: TimesheetMonthKey): number {
  const { year, month } = parseMonthKey(key);
  return new Date(year, month, 0).getDate();
}

export type TimesheetDayInfo = {
  day: number;
  dateYmd: string;
  weekdayShort: string;
  weekdayLong: string;
  isWeekend: boolean;
};

const WEEKDAY_SHORT = ["dom", "lun", "mar", "mer", "gio", "ven", "sab"] as const;
const WEEKDAY_LONG = [
  "domenica",
  "lunedì",
  "martedì",
  "mercoledì",
  "giovedì",
  "venerdì",
  "sabato",
] as const;

export function buildMonthDays(key: TimesheetMonthKey): TimesheetDayInfo[] {
  const { year, month } = parseMonthKey(key);
  const count = daysInMonth(key);
  const out: TimesheetDayInfo[] = [];
  for (let day = 1; day <= count; day++) {
    const d = new Date(year, month - 1, day, 12, 0, 0, 0);
    const dow = d.getDay();
    const dateYmd = `${key}-${String(day).padStart(2, "0")}`;
    out.push({
      day,
      dateYmd,
      weekdayShort: WEEKDAY_SHORT[dow] ?? "",
      weekdayLong: WEEKDAY_LONG[dow] ?? "",
      isWeekend: dow === 0 || dow === 6,
    });
  }
  return out;
}

export function shiftMonthKey(key: TimesheetMonthKey, delta: number): TimesheetMonthKey {
  const { year, month } = parseMonthKey(key);
  const d = new Date(year, month - 1 + delta, 1);
  return monthKeyFromDate(d);
}

export function monthOptions(count = 24, anchor: Date = new Date()): { value: TimesheetMonthKey; label: string }[] {
  const out: { value: TimesheetMonthKey; label: string }[] = [];
  const d = new Date(anchor.getFullYear(), anchor.getMonth(), 1);
  for (let i = 0; i < count; i++) {
    const key = monthKeyFromDate(d);
    out.push({ value: key, label: formatMonthLabel(key) });
    d.setMonth(d.getMonth() - 1);
  }
  return out;
}

export function monthDateRange(key: TimesheetMonthKey): { from: string; to: string } {
  const from = monthKeyToFirstDay(key);
  const last = daysInMonth(key);
  const to = `${key}-${String(last).padStart(2, "0")}`;
  return { from, to };
}

export function monthKeyFromParts(year: number, month: number): TimesheetMonthKey {
  return `${year}-${String(month).padStart(2, "0")}`;
}

export function yearFromMonthKey(key: TimesheetMonthKey): number {
  return parseMonthKey(key).year;
}

export function yearDateRange(year: number): { from: string; to: string } {
  return { from: `${year}-01-01`, to: `${year}-12-31` };
}

const MONTH_NAMES_IT = [
  "Gennaio",
  "Febbraio",
  "Marzo",
  "Aprile",
  "Maggio",
  "Giugno",
  "Luglio",
  "Agosto",
  "Settembre",
  "Ottobre",
  "Novembre",
  "Dicembre",
] as const;

export function yearOptions(count = 5, anchor: Date = new Date()): { value: number; label: string }[] {
  const startYear = anchor.getFullYear();
  const out: { value: number; label: string }[] = [];
  for (let i = 0; i < count; i++) {
    const y = startYear - i;
    out.push({ value: y, label: String(y) });
  }
  return out;
}

export function monthOptionsForYear(year: number): { value: number; label: string }[] {
  return MONTH_NAMES_IT.map((label, i) => ({ value: i + 1, label }));
}

export function setMonthKeyParts(key: TimesheetMonthKey, year: number, month: number): TimesheetMonthKey {
  return monthKeyFromParts(year, month);
}

export type TimesheetPeriodMode = "day" | "week" | "month";

export function dateYmdFromDate(d: Date): string {
  const y = d.getFullYear();
  const m = String(d.getMonth() + 1).padStart(2, "0");
  const day = String(d.getDate()).padStart(2, "0");
  return `${y}-${m}-${day}`;
}

export function todayDateYmd(): string {
  return dateYmdFromDate(new Date());
}

export function currentMonthKey(): TimesheetMonthKey {
  return monthKeyFromDate(new Date());
}

export function isDateInMonthKey(dateYmd: string, monthKey: TimesheetMonthKey): boolean {
  return dateYmd.startsWith(`${monthKey}-`);
}

export function parseDateYmd(ymd: string): Date {
  const [y, m, d] = ymd.split("-").map(Number);
  return new Date(y, m - 1, d, 12, 0, 0, 0);
}

export function weekRangeFromAnchor(anchorYmd: string): { from: string; to: string } {
  const d = parseDateYmd(anchorYmd);
  const dow = d.getDay();
  const mondayOffset = dow === 0 ? -6 : 1 - dow;
  const monday = new Date(d);
  monday.setDate(d.getDate() + mondayOffset);
  const sunday = new Date(monday);
  sunday.setDate(monday.getDate() + 6);
  return { from: dateYmdFromDate(monday), to: dateYmdFromDate(sunday) };
}

export function dayRange(dayYmd: string): { from: string; to: string } {
  return { from: dayYmd, to: dayYmd };
}

export function resolvePeriodRange(
  periodMode: TimesheetPeriodMode,
  monthKey: TimesheetMonthKey,
  weekAnchor?: string,
  dayDate?: string,
): { from: string; to: string } {
  if (periodMode === "month") return monthDateRange(monthKey);
  if (periodMode === "week") {
    return weekRangeFromAnchor(weekAnchor ?? monthKeyToFirstDay(monthKey));
  }
  return dayRange(dayDate ?? monthKeyToFirstDay(monthKey));
}

export function buildPeriodDays(
  periodMode: TimesheetPeriodMode,
  monthKey: TimesheetMonthKey,
  weekAnchor?: string,
  dayDate?: string,
): TimesheetDayInfo[] {
  const { from, to } = resolvePeriodRange(periodMode, monthKey, weekAnchor, dayDate);
  const start = parseDateYmd(from);
  const end = parseDateYmd(to);
  const out: TimesheetDayInfo[] = [];
  const cursor = new Date(start);
  while (cursor <= end) {
    const dateYmd = dateYmdFromDate(cursor);
    const dow = cursor.getDay();
    out.push({
      day: cursor.getDate(),
      dateYmd,
      weekdayShort: WEEKDAY_SHORT[dow] ?? "",
      weekdayLong: WEEKDAY_LONG[dow] ?? "",
      isWeekend: dow === 0 || dow === 6,
    });
    cursor.setDate(cursor.getDate() + 1);
  }
  return out;
}

export function shiftWeekAnchor(anchorYmd: string, deltaWeeks: number): string {
  const d = parseDateYmd(anchorYmd);
  d.setDate(d.getDate() + deltaWeeks * 7);
  return dateYmdFromDate(d);
}

export function shiftDayDate(dayYmd: string, deltaDays: number): string {
  const d = parseDateYmd(dayYmd);
  d.setDate(d.getDate() + deltaDays);
  return dateYmdFromDate(d);
}

import { emptySchedaIngressoFields } from "@/lib/domain/intervento-context/build-intervento-context";
import { newRigaId, newSchedaMeta } from "@/lib/schede/schede-ui";
import type {
  LavorazioneSchedeBundle,
  SchedaIngressoFields,
  SchedaLavorazioniDoc,
  SchedaLavorazioniFields,
  SchedaRicambiDoc,
  SchedaRicambiFields,
} from "@/types/schede";

const INGRESSO_KEY_MAP: Record<string, keyof SchedaIngressoFields> = {
  cliente: "cliente",
  cantiere: "cantiere",
  utilizzatore: "utilizzatore",
  dataingresso: "dataIngresso",
  data_ingresso: "dataIngresso",
  tipoattrezzatura: "tipoAttrezzatura",
  tipo_attrezzatura: "tipoAttrezzatura",
  marcaattrezzatura: "marcaAttrezzatura",
  marca_attrezzatura: "marcaAttrezzatura",
  modelloattrezzatura: "modelloAttrezzatura",
  modello_attrezzatura: "modelloAttrezzatura",
  matricola: "matricola",
  nscuderia: "nScuderia",
  numero_scuderia: "nScuderia",
  orelavoro: "oreLavoro",
  ore_lavoro: "oreLavoro",
  tipotelaio: "tipoTelaio",
  tipo_telaio: "tipoTelaio",
  marcatelaio: "marcaTelaio",
  marca_telaio: "marcaTelaio",
  modellotelaio: "modelloTelaio",
  modello_telaio: "modelloTelaio",
  targa: "targa",
  km: "km",
  descrizioneanomalia: "descrizioneAnomalia",
  descrizione_anomalia: "descrizioneAnomalia",
  livellocarburante: "livelloCarburante",
  livello_carburante: "livelloCarburante",
  addettoaccettazione: "addettoAccettazione",
  addetto_accettazione: "addettoAccettazione",
  richiedente: "richiedente",
  noteintervento: "noteIntervento",
  note_intervento: "noteIntervento",
};

function normKey(key: string): string {
  return key.trim().toLowerCase().replace(/^ingresso\./, "");
}

export type CaptureFieldRow = {
  field_key: string;
  confirmed_value: string | null;
  normalized_value: string | null;
};

export function resolveCaptureFieldValue(row: CaptureFieldRow): string {
  const v = row.confirmed_value ?? row.normalized_value ?? "";
  return typeof v === "string" ? v.trim() : "";
}

export function mapCaptureFieldsToIngresso(fields: readonly CaptureFieldRow[]): SchedaIngressoFields {
  const out = emptySchedaIngressoFields();
  for (const row of fields) {
    const mapped = INGRESSO_KEY_MAP[normKey(row.field_key)];
    if (!mapped || mapped === "targetType" || mapped === "attrezzaturaId") continue;
    out[mapped] = resolveCaptureFieldValue(row);
  }
  if (!out.dataIngresso.trim()) {
    out.dataIngresso = new Date().toLocaleDateString("it-IT");
  }
  return out;
}

function emptyLavorazioniFields(): SchedaLavorazioniFields {
  return { identificazioneMacchina: "", righe: [] };
}

function emptyRicambiFields(): SchedaRicambiFields {
  return { identificazioneMacchina: "", righe: [] };
}

export function buildCaptureSchedeBundle(input: {
  lavorazioneId: string;
  fields: readonly CaptureFieldRow[];
  createdBy: string;
  includeLavorazioni?: boolean;
  includeRicambi?: boolean;
}): LavorazioneSchedeBundle {
  const ingressoFields = mapCaptureFieldsToIngresso(input.fields);
  const user = input.createdBy.trim() || "Document Capture";

  const bundle: LavorazioneSchedeBundle = {
    lavorazioneId: input.lavorazioneId,
    codice: null,
    ingresso: {
      ...newSchedaMeta("ingresso", user),
      tipo: "ingresso",
      campi: ingressoFields,
    },
    lavorazioni: null,
    ricambi: null,
  };

  if (input.includeLavorazioni) {
    bundle.lavorazioni = {
      ...newSchedaMeta("lavorazioni", user),
      tipo: "lavorazioni",
      campi: {
        ...emptyLavorazioniFields(),
        identificazioneMacchina:
          [ingressoFields.marcaAttrezzatura, ingressoFields.modelloAttrezzatura, ingressoFields.matricola]
            .filter(Boolean)
            .join(" ")
            .trim() || ingressoFields.targa,
        righe: [
          {
            id: newRigaId(),
            dataLavorazione: ingressoFields.dataIngresso,
            lavorazioniEffettuate: ingressoFields.descrizioneAnomalia || ingressoFields.noteIntervento,
            addettiAssegnati: ingressoFields.addettoAccettazione
              ? [{ addetto: ingressoFields.addettoAccettazione, oreImpiegate: 0 }]
              : [],
          },
        ],
      },
    };
  }

  if (input.includeRicambi) {
    bundle.ricambi = {
      ...newSchedaMeta("ricambi", user),
      tipo: "ricambi",
      campi: {
        ...emptyRicambiFields(),
        identificazioneMacchina:
          [ingressoFields.marcaAttrezzatura, ingressoFields.modelloAttrezzatura].filter(Boolean).join(" ").trim() ||
          ingressoFields.targa,
        righe: [],
      },
    };
  }

  return bundle;
}

import type { CatalogMarca } from "@/lib/documenti/documenti-catalog-types";
import type { DocumentoAssocRef, DocumentoGestionale, DocumentoApplicabilita } from "@/lib/types/gestionale";

/** Tutte le categorie supportano marca intera o modello specifico. */
export function allowedApplicabilitaForCategoria(
  _c: DocumentoGestionale["categoria"],
): DocumentoApplicabilita[] {
  return ["marca", "modello"];
}

/** Categorie che ammettono solo applicabilità «tutta la marca» (no modello in UI). */
export function isDocumentoMarcaOnlyCategoria(c: DocumentoGestionale["categoria"]): boolean {
  return c === "listini" || c === "certificazioni";
}

export function defaultApplicabilitaForCategoria(c: DocumentoGestionale["categoria"]): DocumentoApplicabilita {
  if (c === "listini" || c === "cataloghi" || c === "certificazioni") return "marca";
  return "modello";
}

function inferApplicabilitaFromRow(doc: DocumentoGestionale, marcaNome: string, modelloLegacy: string): DocumentoApplicabilita {
  if (doc.categoria === "listini") return "marca";
  const hasModel = modelloLegacy.length > 0 && modelloLegacy !== "—";
  if (doc.categoria === "cataloghi") return hasModel ? "modello" : "marca";
  if (doc.categoria === "manuali") return hasModel ? "modello" : "marca";
  return hasModel ? "modello" : "marca";
}

const MARCA_NON_ASSEGNATA = new Set(["", "—", "-", "n/a", "na"]);

function marcaAssegnataText(raw: string): boolean {
  const t = raw.trim().toLowerCase();
  return t.length > 0 && !MARCA_NON_ASSEGNATA.has(t);
}

/** Risolve applicabilità e chiavi testuali (marca / modello) con fallback legacy. */
export function resolveDocumentoApplicazione(doc: DocumentoGestionale, catalog?: CatalogMarca[]): DocumentoGestionale {
  const marcaNome = (doc.marcaKey ?? doc.marca).trim() || doc.marca?.trim() || "";
  const modelloLegacy = (doc.modelloKey ?? doc.macchina).trim();

  if (!marcaAssegnataText(marcaNome)) {
    return {
      ...doc,
      applicabilita: doc.applicabilita,
      marcaKey: undefined,
      modelloKey: undefined,
      mezzoId: undefined,
      marca: "",
      macchina: "—",
    };
  }

  let applicabilita = doc.applicabilita;
  const legacyApp = (doc as { applicabilita?: string }).applicabilita;
  if (legacyApp === "macchina") {
    applicabilita = modelloLegacy && modelloLegacy !== "—" ? "modello" : "marca";
  }

  if (applicabilita && marcaNome) {
    const mk = marcaNome;
    const mod = applicabilita === "marca" ? undefined : modelloLegacy || undefined;
    return {
      ...doc,
      applicabilita,
      marcaKey: mk,
      modelloKey: mod,
      mezzoId: undefined,
      marca: mk,
      macchina: applicabilita === "marca" ? "—" : mod ?? "—",
    };
  }

  const inferred = inferApplicabilitaFromRow(doc, marcaNome, modelloLegacy);

  if (doc.categoria === "listini") {
    return {
      ...doc,
      applicabilita: "marca",
      marcaKey: marcaNome,
      modelloKey: undefined,
      mezzoId: undefined,
      marca: marcaNome,
      macchina: "—",
    };
  }

  if (doc.categoria === "cataloghi") {
    const hasModel = modelloLegacy.length > 0 && modelloLegacy !== "—";
    if (hasModel) {
      return {
        ...doc,
        applicabilita: "modello",
        marcaKey: marcaNome,
        modelloKey: modelloLegacy,
        mezzoId: undefined,
        marca: marcaNome,
        macchina: modelloLegacy,
      };
    }
    return {
      ...doc,
      applicabilita: "marca",
      marcaKey: marcaNome,
      modelloKey: undefined,
      mezzoId: undefined,
      marca: marcaNome,
      macchina: "—",
    };
  }

  if (doc.categoria === "manuali") {
    const hasModel = modelloLegacy.length > 0 && modelloLegacy !== "—";
    return {
      ...doc,
      applicabilita: hasModel ? "modello" : inferred,
      marcaKey: marcaNome,
      modelloKey: hasModel ? modelloLegacy : undefined,
      mezzoId: undefined,
      marca: marcaNome,
      macchina: hasModel ? modelloLegacy : "—",
    };
  }

  const hasAssoc = doc.associazioni && doc.associazioni.length > 0 && catalog?.length;
  if (hasAssoc && catalog) {
    const first = doc.associazioni![0]!;
    const mar = catalog.find((m) => m.id === first.marcaId);
    const mac = mar?.macchine.find((x) => x.id === first.macchinaId);
    if (mar && mac) {
      return {
        ...doc,
        applicabilita: "modello",
        marcaKey: mar.nome,
        modelloKey: mac.nome,
        mezzoId: undefined,
        marca: mar.nome,
        macchina: mac.nome,
      };
    }
  }

  const hasModel = modelloLegacy.length > 0 && modelloLegacy !== "—";
  return {
    ...doc,
    applicabilita: inferred,
    marcaKey: marcaNome || "—",
    modelloKey: hasModel ? modelloLegacy : undefined,
    mezzoId: undefined,
    marca: marcaNome || "—",
    macchina: hasModel ? modelloLegacy : "—",
  };
}

export function labelApplicabilitaBreve(a: DocumentoApplicabilita): string {
  switch (a) {
    case "marca":
      return "MARCA";
    case "modello":
      return "MODELLO";
    default:
      return a;
  }
}

const DOC_RIGA_SYNTH_SEP = " · ";

/** Riga sintetica tipo "LISTINO · MERCEDES" o "MANUALE · MERCEDES ACTROS". */
export function formatDocumentoRigaSintetica(doc: DocumentoGestionale): string {
  const cat =
    doc.categoria === "listini"
      ? "LISTINO"
      : doc.categoria === "cataloghi"
        ? "CATALOGO"
        : doc.categoria === "manuali"
          ? "MANUALE"
          : doc.categoria === "certificazioni"
            ? "CERTIFICAZIONE"
            : "ALTRO";
  const r = resolveDocumentoApplicazione(doc);
  const m = r.marcaKey?.trim() || r.marca.trim();
  if (!marcaAssegnataText(m)) {
    if (doc.categoria === "certificazioni") return cat;
    return `${cat}${DOC_RIGA_SYNTH_SEP}Senza marca`;
  }
  if (r.applicabilita === "marca") return `${cat}${DOC_RIGA_SYNTH_SEP}${m}`;
  const mod = r.modelloKey?.trim() || r.macchina.trim();
  return `${cat}${DOC_RIGA_SYNTH_SEP}${m} ${mod}`.replace(/\s+/g, " ").trim();
}

export function legacyAssocRefs(doc: DocumentoGestionale, catalog: CatalogMarca[]): DocumentoAssocRef[] {
  if (doc.associazioni && doc.associazioni.length > 0) return doc.associazioni;
  const mar = catalog.find((m) => m.nome === doc.marca);
  if (!mar) return [];
  const mac = mar.macchine.find((x) => x.nome === doc.macchina);
  if (!mac) return [];
  return [{ marcaId: mar.id, macchinaId: mac.id }];
}

