function isCreateMeta(meta: InterventoWritePlan["meta"]): meta is InterventoWriteCreateMeta {
  return "createdBy" in meta;
}

function runFinalizeStage(idempotencyKey: string, lavorazioneId: string, mezzoId: string): void {
  if (idempotencyKey) {
    if (!shouldSkipInterventoWriteStage(idempotencyKey, "finalize", true)) {
      upsertInterventoWriteLedger(idempotencyKey, {
        lavorazioneId,
        mezzoId,
        completedStage: "finalize",
      });
    }
    clearInterventoWriteLedger(idempotencyKey);
  }
  logInterventoTelemetry("intervento_write_finalized", { lavorazioneId, stage: "finalize" });
}

function wrapShadowDeps(deps: InterventoWriteDeps): InterventoWriteDeps {
  return {
    upsertMezzo: async () => ({ mezzoId: "shadow-noop", created: false, updated: false }),
    createLavorazione: async () => ({ id: "shadow-lav" } as never),
    updateLavorazione: async () => {},
    persistScheda: async () => ({ ok: true as const }),
  };
}

function finishSagaTrace(trace: WriteExecutionTrace | undefined, result: InterventoWriteResult): InterventoWriteResult {
  if (result.ok) {
    recordTraceStep(trace, "v2_saga_start", "completed");
    recordTraceStep(trace, "finalize", "completed");
  } else {
    recordTraceStep(trace, "v2_saga_start", "failed");
    recordTraceStep(trace, "finalize", "failed");
  }
  return result;
}

/** Shadow dry-run: saga con deps no-op, confronto vs risultato v1 authoritative. */
export async function runInterventoWriteShadow(
  plan: InterventoWritePlan,
  deps: InterventoWriteDeps,
  authoritative: InterventoWriteResult,
  trace?: WriteExecutionTrace,
): Promise<void> {
  if (trace?.isFinal) return;

  const shadowKey = `${plan.idempotencyKey}-shadow`;
  const shadowPlan = { ...plan, idempotencyKey: shadowKey };
  const shadowResult = await runInterventoWriteSaga(shadowPlan, wrapShadowDeps(deps));
  clearInterventoWriteLedger(shadowKey);

  if (authoritative.ok !== shadowResult.ok) {
    const lavId = authoritative.ok ? authoritative.lavorazioneId : authoritative.lavorazioneId;
    logInterventoTelemetry("intervento_v2_shadow_mismatch", {
      lavorazioneId: lavId,
      mismatch: true,
      stage: "ok-flag",
    });
    return;
  }
  if (
    authoritative.ok &&
    shadowResult.ok &&
    (authoritative.lavorazioneId !== shadowResult.lavorazioneId ||
      authoritative.mezzoId !== shadowResult.mezzoId)
  ) {
    logInterventoTelemetry("intervento_v2_shadow_mismatch", {
      lavorazioneId: authoritative.lavorazioneId,
      mismatch: true,
      stage: "ids",
      extra: {
        authLav: authoritative.lavorazioneId,
        shadowLav: shadowResult.lavorazioneId,
        authMezzo: authoritative.mezzoId,
        shadowMezzo: shadowResult.mezzoId,
      },
    });
  }
}

export async function runInterventoWriteSaga(
  plan: InterventoWritePlan,
  deps: InterventoWriteDeps,
  trace?: WriteExecutionTrace,
): Promise<InterventoWriteResult> {
  recordTraceStep(trace, "v2_saga_start", "started");
  const { fields, mezziCatalog, idempotencyKey } = plan;
  const createMode = plan.mode === "create";
  let lavorazioneId =
    plan.lavorazioneId?.trim() || getInterventoWriteLedgerEntry(idempotencyKey)?.lavorazioneId?.trim() || null;
  let mezzoId: string | null = getInterventoWriteLedgerEntry(idempotencyKey)?.mezzoId?.trim() || null;
  let attrezzaturaId: string | null = null;
  let targetType: import("@/src/types/supabase-tables").InterventoTargetType = "attrezzatura";

  const resolved = resolveMezzoFromScheda({
    scheda: fields,
    existingMezzi: mezziCatalog,
    preferredMezzoId: createMode
      ? isCreateMeta(plan.meta)
        ? plan.meta.mezzoIdHint
        : null
      : !isCreateMeta(plan.meta)
        ? plan.meta.row.mezzo_id
        : null,
  });

  auditInterventoContext(null, "write-mezzo", {
    stage: "resolve",
    preferredMezzoId: createMode && isCreateMeta(plan.meta) ? plan.meta.mezzoIdHint : !isCreateMeta(plan.meta) ? plan.meta.row.mezzo_id : null,
    resolvedMezzoId: resolved.mezzoId,
    matchKind: resolved.matchKind,
    extra: { phase: "v2-resolve" },
  });

  if (createMode && !lavorazioneId && isInterventoWriteRpcEnabled() && idempotencyKey) {
    recordTraceStep(trace, "rpc_atomic_call", "started");
    const meta = plan.meta as InterventoWriteCreateMeta;
    const rpc = await interventoWriteService.createInterventoAtomic({
      idempotencyKey,
      fields,
      meta,
      existingLavorazioneId: plan.lavorazioneId,
    });
    if (rpc.success && rpc.data?.ok) {
      setTraceMode(trace, "rpc_atomic");
      recordTraceStep(trace, "rpc_atomic_call", "completed");
      recordTraceStep(trace, "v1_create", "skipped");
      recordTraceStep(trace, "v1_persist", "skipped");
      runFinalizeStage(idempotencyKey, rpc.data.lavorazioneId, rpc.data.mezzoId);
      logInterventoTelemetry("intervento_create_completed", { lavorazioneId: rpc.data.lavorazioneId });
      return finishSagaTrace(trace, {
        ok: true,
        lavorazioneId: rpc.data.lavorazioneId,
        mezzoId: rpc.data.mezzoId,
      });
    }
    recordTraceStep(trace, "rpc_atomic_call", "failed");
    if (rpc.error) {
      logInterventoTelemetry("intervento_sync_drift_detected", {
        stage: "rpc-fallback-saga",
        mismatch: true,
      });
    }
  }

  if (createMode && !lavorazioneId) {
    if (!shouldSkipInterventoWriteStage(idempotencyKey, "prepare-mezzo", true)) {
      try {
        const upsert = await deps.upsertMezzo({
          fields,
          preferredMezzoId: isCreateMeta(plan.meta) ? plan.meta.mezzoIdHint : null,
        });
        mezzoId = upsert.mezzoId;
        attrezzaturaId = upsert.attrezzaturaId ?? null;
        targetType = upsert.targetType ?? "attrezzatura";
        auditInterventoContext(null, "write-mezzo", {
          preferredMezzoId: isCreateMeta(plan.meta) ? plan.meta.mezzoIdHint : null,
          resolvedMezzoId: resolved.mezzoId,
          matchKind: resolved.matchKind,
          extra: { phase: "v2-create-pre-upsert" },
        });
      } catch (err) {
        const message = err instanceof Error ? err.message : "Errore upsert mezzo.";
        return finishSagaTrace(trace, { ok: false, stage: "prepare-mezzo", error: message });
      }
    }

    if (!shouldSkipInterventoWriteStage(idempotencyKey, "prepare-lavorazione", true) && deps.createLavorazione) {
      if (!mezzoId) {
        try {
          const upsert = await deps.upsertMezzo({
            fields,
            preferredMezzoId: isCreateMeta(plan.meta) ? plan.meta.mezzoIdHint : null,
          });
          mezzoId = upsert.mezzoId;
          attrezzaturaId = upsert.attrezzaturaId ?? null;
          targetType = upsert.targetType ?? "attrezzatura";
        } catch {
          /* retry path */
        }
      }
      if (!mezzoId) {
        return finishSagaTrace(trace, { ok: false, stage: "prepare-mezzo", error: "Mezzo non risolto." });
      }
      try {
        const meta = plan.meta as InterventoWriteCreateMeta;
        const row = await deps.createLavorazione({
          mezzo_id: mezzoId,
          stato: meta.statoId,
          priorita: meta.priorita,
          data_ingresso: meta.dataIngressoIso,
          note: meta.note,
          created_by: meta.createdBy,
          target_type: targetType,
          attrezzatura_id: targetType === "attrezzatura" ? attrezzaturaId : null,
        });
        lavorazioneId = row.id;
        upsertInterventoWriteLedger(idempotencyKey, { lavorazioneId, mezzoId });
      } catch (err) {
        const message = err instanceof Error ? err.message : "Errore creazione lavorazione.";
        return finishSagaTrace(trace, { ok: false, stage: "prepare-lavorazione", error: message });
      }
    }
  }

  if (!createMode && !isCreateMeta(plan.meta) && deps.upsertMezzo && deps.updateLavorazione) {
    recordTraceStep(trace, "v1_create", "skipped");
    const editMeta = plan.meta as InterventoWriteEditMeta;
    const row = editMeta.row;
    lavorazioneId = row.id;

    if (!fields.cliente.trim() || !fields.marcaAttrezzatura.trim()) {
      recordTraceStep(trace, "v1_persist", "skipped");
      runFinalizeStage(idempotencyKey, row.id, row.mezzo_id ?? "");
      return finishSagaTrace(trace, { ok: true, lavorazioneId: row.id, mezzoId: row.mezzo_id ?? "" });
    }

    const ctx = composeInterventoContext({
      lavorazioneId: row.id,
      lavorazioneRow: row,
      mezzoRow: row.mezzo,
      ingressoCampi: fields,
      ingressoSorgente: "generata",
    });

    auditInterventoContext(ctx, "write-mezzo", {
      contextId: row.id,
      mismatch: ctx.meta.hasIdentMismatch,
      preferredMezzoId: row.mezzo_id,
      resolvedMezzoId: resolved.mezzoId,
      matchKind: resolved.matchKind,
      identDelta: buildIdentDeltaFromContext(ctx),
    });

    recordTraceStep(trace, "v1_persist", "started");
    try {
      const upsert = await deps.upsertMezzo({
        fields,
        preferredMezzoId: row.mezzo_id,
      });
      mezzoId = upsert.mezzoId;
      attrezzaturaId = upsert.attrezzaturaId ?? null;
      targetType = upsert.targetType ?? targetType;

      const note = fields.noteIntervento?.trim() || null;
      const parsedIngresso = parseItalianDayDisplayToIso(fields.dataIngresso.trim());
      const lavPatch: LavorazioneUpdate = {};
      if (note !== (row.note ?? "").trim()) lavPatch.note = note;
      if (parsedIngresso.ok) lavPatch.data_ingresso = parsedIngresso.iso;
      const currentFk = row.mezzo_id?.trim() || "";
      if (mezzoId && mezzoId !== currentFk) lavPatch.mezzo_id = mezzoId;
      if (targetType && targetType !== row.target_type) lavPatch.target_type = targetType;
      const nextAttId = targetType === "attrezzatura" ? attrezzaturaId : null;
      if ((row.attrezzatura_id ?? null) !== nextAttId) lavPatch.attrezzatura_id = nextAttId;

      if (Object.keys(lavPatch).length) {
        await deps.updateLavorazione(row.id, lavPatch);
      }
      recordTraceStep(trace, "v1_persist", "completed");
    } catch (err) {
      const message = err instanceof Error ? err.message : "Errore sync mezzo/lavorazione.";
      recordTraceStep(trace, "v1_persist", "failed");
      return finishSagaTrace(trace, { ok: false, stage: "prepare-lavorazione", error: message });
    }
  }

  if (createMode && deps.persistScheda && lavorazioneId) {
    if (!shouldSkipInterventoWriteStage(idempotencyKey, "persist-scheda", true)) {
      recordTraceStep(trace, "v1_persist", "started");
      try {
        const meta = plan.meta as InterventoWriteCreateMeta;
        const persist = await deps.persistScheda({
          lavorazioneId,
          fields,
          createdBy: meta.createdBy,
        });
        if (!persist.ok) {
          upsertInterventoWriteLedger(idempotencyKey, { lavorazioneId, mezzoId: mezzoId ?? undefined });
          const error =
            persist.kind === "concurrency" ? persist.error : persist.error;
          recordTraceStep(trace, "v1_persist", "failed");
          return finishSagaTrace(trace, {
            ok: false,
            stage: "persist-scheda",
            error,
            lavorazioneId,
          });
        }
        upsertInterventoWriteLedger(idempotencyKey, {
          lavorazioneId,
          mezzoId: mezzoId ?? undefined,
          completedStage: "persist-scheda",
        });
        recordTraceStep(trace, "v1_persist", "completed");
      } catch (err) {
        const message = err instanceof Error ? err.message : "Errore persist scheda.";
        recordTraceStep(trace, "v1_persist", "failed");
        return finishSagaTrace(trace, { ok: false, stage: "persist-scheda", error: message, lavorazioneId });
      }
    } else {
      recordTraceStep(trace, "v1_persist", "skipped");
    }
  }

  if (!lavorazioneId) {
    return finishSagaTrace(trace, { ok: false, stage: "prepare-lavorazione", error: "Lavorazione non disponibile." });
  }

  const finalMezzoId = mezzoId ?? resolved.mezzoId ?? "";
  if (finalMezzoId) {
    try {
      await appendMileageFromScheda({
        mezzoId: finalMezzoId,
        kmText: fields.km,
        lavorazioneId,
      });
    } catch {
      // ponytail: mileage storico non blocca write intervento
    }
  }
  runFinalizeStage(idempotencyKey, lavorazioneId, finalMezzoId);
  return finishSagaTrace(trace, {
    ok: true,
    lavorazioneId,
    mezzoId: finalMezzoId,
  });
}

import type { InterventoDisplay } from "@/lib/domain/intervento-context/intervento-context.types";
import {
  resolveInterventoCanonical,
  type InterventoCanonicalInputs,
} from "@/lib/domain/intervento-context/resolve-intervento-canonical";
import { resolveInterventoIdent } from "@/lib/domain/intervento-context/resolve-intervento-display";
import type { MezzoGestito } from "@/lib/mezzi/types";
import type { LavorazioneListRow } from "@/src/services/lavorazioni.service";
import type { MezzoRow } from "@/src/types/supabase-tables";
import type { LavorazioneSchedeStore, SchedaIngressoFields } from "@/types/schede";

export type InterventoDisplaySurface = "list" | "hub" | "pdf" | "preventivo" | "draft" | "filter";

export type InterventoDisplaySurfaceInputs = {
  lavorazioneRow?: LavorazioneListRow | null;
  mezzoRow?: MezzoRow | MezzoGestito | null;
  ingressoCampi?: SchedaIngressoFields | null;
  schedeStore?: LavorazioneSchedeStore;
  draftFields?: SchedaIngressoFields | null;
  mezzoIdHint?: string | null;
};

function surfaceToCanonicalMode(surface: InterventoDisplaySurface): "ui" | "export" {
  return surface === "pdf" || surface === "preventivo" ? "export" : "ui";
}

function toCanonicalInputs(inputs: InterventoDisplaySurfaceInputs): InterventoCanonicalInputs {
  return {
    lavorazioneRow: inputs.lavorazioneRow,
    schedeStore: inputs.schedeStore,
    ingressoCampi: inputs.ingressoCampi,
    mezzoRow: inputs.mezzoRow,
    draftFields: inputs.draftFields,
  };
}

/** Read SSOT unificato per surface UI/PDF/preventivi. */
export function resolveInterventoDisplayForSurface(
  surface: InterventoDisplaySurface,
  inputs: InterventoDisplaySurfaceInputs,
): InterventoDisplay {
  return resolveInterventoCanonical(surfaceToCanonicalMode(surface), toCanonicalInputs(inputs)).display;
}

export function resolveInterventoIdentForSurface(
  surface: InterventoDisplaySurface,
  inputs: InterventoDisplaySurfaceInputs,
) {
  void surface;
  const display = resolveInterventoDisplayForSurface(surface, inputs);
  return display.ident;
}

/** Campi flat per PDF / preventivi da display canonico. */
export function schedaIngressoFieldsFromDisplay(
  display: InterventoDisplay,
  fallback?: Partial<SchedaIngressoFields>,
): SchedaIngressoFields {
  const base = fallback ?? {};
  return {
    dataIngresso: base.dataIngresso ?? "",
    cliente: display.cliente.value || base.cliente || "",
    cantiere: display.cantiere.value || base.cantiere || "",
    utilizzatore: display.utilizzatore.value || base.utilizzatore || "",
    tipoAttrezzatura: base.tipoAttrezzatura ?? "",
    marcaAttrezzatura: display.marcaModello.value.split(" ")[0] ?? base.marcaAttrezzatura ?? "",
    modelloAttrezzatura:
      display.marcaModello.value.split(" ").slice(1).join(" ") || base.modelloAttrezzatura || "",
    matricola: display.matricola.value || base.matricola || "",
    nScuderia: display.nScuderia.value || base.nScuderia || "",
    oreLavoro: base.oreLavoro ?? "",
    tipoTelaio: base.tipoTelaio ?? "",
    marcaTelaio: base.marcaTelaio ?? "",
    modelloTelaio: base.modelloTelaio ?? "",
    targa: display.targa.value || base.targa || "",
    km: base.km ?? "",
    descrizioneAnomalia: base.descrizioneAnomalia ?? "",
    livelloCarburante: base.livelloCarburante ?? "",
    addettoAccettazione: base.addettoAccettazione ?? "",
    richiedente: base.richiedente ?? "",
    richiedenteFirma: base.richiedenteFirma,
    noteIntervento: base.noteIntervento ?? "",
  };
}

/**
 * Regole backfill legacy mezzi → mezzo (telaio) + attrezzature (1:1).
 * SSOT per migration SQL e test caratterizzazione.
 */

import { parseMezzoMeta, type MezzoAnagraficaMeta } from "@/lib/mezzi/mezzi-meta";
import type { MezzoRow } from "@/src/types/supabase-tables";

export type LegacyMezzoBackfillInput = {
  id: string;
  marca: string;
  modello?: string | null;
  matricola?: string | null;
  tipo_attrezzatura?: string | null;
  anno?: number | null;
  targa?: string | null;
  meta?: MezzoRow["meta"];
};

export type AttrezzaturaBackfillRow = {
  mezzo_id: string;
  marca: string;
  modello: string;
  tipo_attrezzatura: string | null;
  matricola: string | null;
  anno: number | null;
};

export type MezzoTelaioBackfillPatch = {
  marca_telaio: string | null;
  modello_telaio: string | null;
  tipo_telaio: string | null;
  telaio_num: string | null;
  km: number | null;
};

export function trimOrNull(v: string | null | undefined): string | null {
  const t = v?.trim();
  return t && t.length > 0 && t !== "—" ? t : null;
}

/** Una riga attrezzatura per ogni mezzo legacy (1:1). */
export function mapLegacyMezzoToAttrezzatura(row: LegacyMezzoBackfillInput): AttrezzaturaBackfillRow {
  return {
    mezzo_id: row.id,
    marca: row.marca.trim(),
    modello: trimOrNull(row.modello) ?? "—",
    tipo_attrezzatura: trimOrNull(row.tipo_attrezzatura),
    matricola: trimOrNull(row.matricola),
    anno: row.anno ?? null,
  };
}

export function mapMetaToMezzoTelaioPatch(
  meta: MezzoAnagraficaMeta,
  targa: string | null,
): MezzoTelaioBackfillPatch {
  return {
    marca_telaio: trimOrNull(meta.marcaTelaio),
    modello_telaio: trimOrNull(meta.modelloTelaio),
    tipo_telaio: trimOrNull(meta.tipoTelaio),
    telaio_num: null,
    km: meta.km != null && meta.km >= 0 ? meta.km : null,
  };
}

export function buildMezzoTelaioBackfillFromRow(row: LegacyMezzoBackfillInput): MezzoTelaioBackfillPatch {
  const meta = parseMezzoMeta(row.meta);
  return mapMetaToMezzoTelaioPatch(meta, row.targa ?? null);
}

/** Lavorazione legacy → target attrezzatura collegata al mezzo. */
export function defaultLavorazioneTarget(attrezzaturaId: string) {
  return {
    target_type: "attrezzatura" as const,
    attrezzatura_id: attrezzaturaId,
  };
}

import { attrezzaturaRowToGestita, type AttrezzaturaGestita } from "@/lib/attrezzature/types";
import { parseMezzoMeta } from "@/lib/mezzi/mezzi-meta";
import type { MezzoGestito } from "@/lib/mezzi/types";
import type { AttrezzaturaRow, MezzoRow } from "@/src/types/supabase-tables";

function str(v: string | null | undefined, fallback = "—"): string {
  const t = v?.trim();
  return t && t.length > 0 ? t : fallback;
}

function matricolaUi(v: string | null | undefined): string {
  const t = v?.trim();
  return t && t.length > 0 ? t : "Non assegnata";
}

/** Compone `MezzoGestito` da mezzo (telaio) + attrezzatura primaria opzionale. */
export function composeMezzoGestitoFromRows(
  mezzo: MezzoRow,
  primaryAttrezzatura?: AttrezzaturaRow | null,
): MezzoGestito {
  const meta = parseMezzoMeta(mezzo.meta);
  const att = primaryAttrezzatura ? attrezzaturaRowToGestita(primaryAttrezzatura) : null;

  const marcaTelaio = str(mezzo.marca_telaio, "") || meta.marcaTelaio;
  const modelloTelaio = str(mezzo.modello_telaio, "") || meta.modelloTelaio;
  const tipoTelaio = str(mezzo.tipo_telaio, "") || meta.tipoTelaio;
  const km = mezzo.km != null ? Number(mezzo.km) : meta.km;

  return {
    id: mezzo.id,
    cliente: mezzo.cliente,
    utilizzatore: str(mezzo.utilizzatore, "—"),
    marca: att?.marca ?? "—",
    modello: att?.modello ?? "—",
    targa: str(mezzo.targa, "—"),
    matricola: att ? att.matricola : "Non assegnata",
    numeroScuderia: mezzo.numero_scuderia?.trim() || undefined,
    tipoAttrezzatura: att?.tipoAttrezzatura ?? "—",
    cantiere: meta.cantiere,
    tipoTelaio: tipoTelaio || undefined,
    marcaTelaio: marcaTelaio || undefined,
    modelloTelaio: modelloTelaio || undefined,
    anno: att?.anno ?? mezzo.anno ?? new Date().getFullYear(),
    oreKm: meta.oreLavoro ?? 0,
    km,
    statoAttuale: "Operativo",
    dataUltimaUscita: mezzo.updated_at?.slice(0, 10) || "—",
    note: mezzo.note?.trim() || "",
    priorita: "normale",
    hubSynthetic: false,
    ultimaModifica: mezzo.updated_at?.trim() || mezzo.created_at?.trim() || undefined,
  };
}

/** Prima attrezzatura per mezzo (ordine created_at). Liste mezzi senza target lavorazione. */
export function pickPrimaryAttrezzatura(
  rows: readonly AttrezzaturaRow[],
  mezzoId: string,
): AttrezzaturaRow | null {
  const list = rows.filter((a) => a.mezzo_id === mezzoId);
  if (list.length === 0) return null;
  return [...list].sort((a, b) => a.created_at.localeCompare(b.created_at))[0] ?? null;
}

/**
 * SSOT scelta attrezzatura:
 * 1. `preferredAttrezzaturaId` se appartiene al mezzo (contesto lavorazione)
 * 2. altrimenti primary per `created_at` (liste mezzo/report)
 * 3. null → UI "—" (no fallback colonne legacy mezzi)
 */
export function pickAttrezzaturaForContext(
  rows: readonly AttrezzaturaRow[],
  mezzoId: string,
  preferredAttrezzaturaId?: string | null,
): AttrezzaturaRow | null {
  const mid = mezzoId.trim();
  if (!mid) return null;
  const preferred = preferredAttrezzaturaId?.trim();
  if (preferred) {
    const hit = rows.find((a) => a.id === preferred && a.mezzo_id?.trim() === mid);
    if (hit) return hit;
  }
  return pickPrimaryAttrezzatura(rows, mid);
}

/** AttrezzaturaRow minima da embed mezzo già arricchito (post batch join). */
export function attrezzaturaRowFromEnrichedMezzo(
  mezzo: MezzoRow,
  attrezzaturaId: string,
  mezzoId: string,
): AttrezzaturaRow | null {
  const id = attrezzaturaId.trim();
  const mid = mezzoId.trim();
  if (!id || !mid) return null;
  const marca = mezzo.marca?.trim();
  if (!marca || marca === "—") return null;
  return {
    id,
    mezzo_id: mid,
    marca,
    modello: mezzo.modello?.trim() || "—",
    matricola: mezzo.matricola?.trim() || null,
    tipo_attrezzatura: mezzo.tipo_attrezzatura?.trim() || null,
    portata: null,
    anno: mezzo.anno,
    note: null,
    created_at: mezzo.created_at ?? "",
    updated_at: mezzo.updated_at ?? "",
    created_by: null,
  };
}

export function attrezzatureForMezzo(
  rows: readonly AttrezzaturaRow[],
  mezzoId: string,
): AttrezzaturaGestita[] {
  return rows
    .filter((a) => a.mezzo_id === mezzoId)
    .sort((a, b) => a.created_at.localeCompare(b.created_at))
    .map(attrezzaturaRowToGestita);
}

export type MezzoGestitoFromRowOpts = {
  attrezzatura?: AttrezzaturaRow | null;
  attrezzaturaId?: string | null;
  attrezzature?: readonly AttrezzaturaRow[];
};

/** Unico adapter DB / embed arricchito → MezzoGestito (SSOT read V2). */
export function mezzoGestitoFromRow(row: MezzoRow, opts?: MezzoGestitoFromRowOpts): MezzoGestito {
  const mid = row.id?.trim() ?? "";
  let att = opts?.attrezzatura ?? null;
  if (!att && opts?.attrezzature?.length && mid) {
    att = pickAttrezzaturaForContext(opts.attrezzature, mid, opts.attrezzaturaId);
  }
  if (!att && opts?.attrezzaturaId?.trim() && mid) {
    att = attrezzaturaRowFromEnrichedMezzo(row, opts.attrezzaturaId, mid);
  }
  if (!att && row.marca?.trim() && row.marca.trim() !== "—") {
    att = {
      id: opts?.attrezzaturaId?.trim() || "embed",
      mezzo_id: mid,
      marca: row.marca.trim(),
      modello: row.modello?.trim() || "—",
      matricola: row.matricola?.trim() || null,
      tipo_attrezzatura: row.tipo_attrezzatura?.trim() || null,
      portata: null,
      anno: row.anno,
      note: null,
      created_at: row.created_at ?? "",
      updated_at: row.updated_at ?? "",
      created_by: null,
    };
  }
  return composeMezzoGestitoFromRows(row, att);
}

