import { canonicalizeSlug } from "../canonicalize";
import { precedenceForSource } from "./source-precedence";
import type {
  CatalogActivity,
  TkbCategoria,
  TkbComponente,
  TkbDraftBundle,
  TkbEntityKind,
  TkbIntervento,
  TkbProcedure,
  TkbRicambioMapEntry,
  TkbSintomo,
  TkbSourceFragment,
} from "../types";

export type MergeResult = {
  bundle: TkbDraftBundle;
  audit: {
    performed: number;
    duplicatesFound: number;
    conflictsResolved: number;
    added: number;
    updated: number;
    removed: number;
  };
};

type EntityBucket = {
  categoria: Map<string, TkbCategoria>;
  componente: Map<string, TkbComponente>;
  sintomo: Map<string, TkbSintomo>;
  procedure: Map<string, TkbProcedure>;
  intervento: Map<string, TkbIntervento>;
  ricambioMap: Map<string, TkbRicambioMapEntry>;
};

type StoredFragment = TkbSourceFragment & { precedence: number; updatedAt?: string };

function bucketKey(kind: TkbEntityKind, key: string): string {
  return `${kind}:${canonicalizeSlug(key)}`;
}

function mergeStringArrays(a?: string[], b?: string[]): string[] | undefined {
  const set = new Set<string>();
  for (const arr of [a, b]) {
    if (!arr) continue;
    for (const s of arr) {
      const t = s.trim();
      if (t) set.add(t);
    }
  }
  const out = [...set].sort((x, y) => x.localeCompare(y, "it"));
  return out.length ? out : undefined;
}

function mergeComponente(existing: TkbComponente, incoming: TkbComponente): TkbComponente {
  return {
    slug: existing.slug,
    label: incoming.label || existing.label,
    categoriaSlug: incoming.categoriaSlug ?? existing.categoriaSlug,
    synonyms: mergeStringArrays(existing.synonyms, incoming.synonyms),
  };
}

function mergeSintomo(existing: TkbSintomo, incoming: TkbSintomo): TkbSintomo {
  return {
    slug: existing.slug,
    label: incoming.label || existing.label,
    keywords: mergeStringArrays(existing.keywords, incoming.keywords) ?? [],
    relatedComponentiSlugs: mergeStringArrays(existing.relatedComponentiSlugs, incoming.relatedComponentiSlugs),
  };
}

function mergeIntervento(existing: TkbIntervento, incoming: TkbIntervento): TkbIntervento {
  return {
    slug: existing.slug,
    label: incoming.label || existing.label,
    categoriaSlug: incoming.categoriaSlug ?? existing.categoriaSlug,
    keywords: mergeStringArrays(existing.keywords, incoming.keywords) ?? [],
    componentiSlugs: mergeStringArrays(existing.componentiSlugs, incoming.componentiSlugs),
    sintomiSlugs: mergeStringArrays(existing.sintomiSlugs, incoming.sintomiSlugs),
    compatibilita: incoming.compatibilita ?? existing.compatibilita,
    procedureSlugs: mergeStringArrays(existing.procedureSlugs, incoming.procedureSlugs),
    activityOverrides: incoming.activityOverrides ?? existing.activityOverrides,
    attivitaPrincipali:
      incoming.attivitaPrincipali.length > 0 ? incoming.attivitaPrincipali : existing.attivitaPrincipali,
    attivitaComplementari: incoming.attivitaComplementari ?? existing.attivitaComplementari,
    controlliFinali: incoming.controlliFinali ?? existing.controlliFinali,
    publishStatus: existing.publishStatus,
  };
}

function activityCount(bundle: TkbDraftBundle): number {
  let n = 0;
  for (const p of bundle.procedure) {
    n += p.attivita.length + (p.controlliFinali?.length ?? 0);
  }
  for (const i of bundle.interventi) {
    n +=
      i.attivitaPrincipali.length +
      (i.attivitaComplementari?.length ?? 0) +
      (i.controlliFinali?.length ?? 0);
  }
  return n;
}

function toBuckets(fragments: StoredFragment[]): EntityBucket {
  const buckets: EntityBucket = {
    categoria: new Map(),
    componente: new Map(),
    sintomo: new Map(),
    procedure: new Map(),
    intervento: new Map(),
    ricambioMap: new Map(),
  };

  const stored = new Map<string, StoredFragment>();
  let duplicatesFound = 0;
  let conflictsResolved = 0;
  let performed = 0;
  let added = 0;
  let updated = 0;

  for (const frag of fragments) {
    const key = bucketKey(frag.entityKind, frag.entityKey);
    const existing = stored.get(key);
    if (!existing) {
      stored.set(key, frag);
      added++;
      continue;
    }
    duplicatesFound++;
    const win =
      frag.precedence > existing.precedence
        ? frag
        : frag.precedence < existing.precedence
          ? existing
          : (frag.updatedAt ?? "") >= (existing.updatedAt ?? "")
            ? frag
            : existing;
    if (win !== existing) conflictsResolved++;
    stored.set(key, win);
    updated++;
    performed++;
  }

  for (const frag of stored.values()) {
    const slug = canonicalizeSlug(frag.entityKey);
    switch (frag.entityKind) {
      case "categoria":
        buckets.categoria.set(slug, frag.payload as TkbCategoria);
        break;
      case "componente": {
        const incoming = frag.payload as TkbComponente;
        const prev = buckets.componente.get(slug);
        buckets.componente.set(slug, prev ? mergeComponente(prev, incoming) : incoming);
        break;
      }
      case "sintomo": {
        const incoming = frag.payload as TkbSintomo;
        const prev = buckets.sintomo.get(slug);
        buckets.sintomo.set(slug, prev ? mergeSintomo(prev, incoming) : incoming);
        break;
      }
      case "procedure":
        buckets.procedure.set(slug, frag.payload as TkbProcedure);
        break;
      case "intervento": {
        const incoming = frag.payload as TkbIntervento;
        const prev = buckets.intervento.get(slug);
        buckets.intervento.set(slug, prev ? mergeIntervento(prev, incoming) : incoming);
        break;
      }
      case "ricambioMap": {
        const entry = frag.payload as TkbRicambioMapEntry;
        buckets.ricambioMap.set(entry.id, entry);
        break;
      }
      default:
        break;
    }
  }

  return buckets;
}

export function mergeFragments(fragments: TkbSourceFragment[]): MergeResult {
  const stored: StoredFragment[] = fragments.map((f) => ({
    ...f,
    precedence: f.precedence || precedenceForSource(f.sourceId),
    updatedAt: f.provenance.updatedAt,
  }));

  const buckets = toBuckets(stored);
  const bundle: TkbDraftBundle = {
    categorie: [...buckets.categoria.values()],
    componenti: [...buckets.componente.values()],
    sintomi: [...buckets.sintomo.values()],
    procedure: [...buckets.procedure.values()],
    interventi: [...buckets.intervento.values()],
    ricambiMap: [...buckets.ricambioMap.values()],
  };

  return {
    bundle,
    audit: {
      performed: stored.length,
      duplicatesFound: Math.max(0, stored.length - new Set(stored.map((s) => bucketKey(s.entityKind, s.entityKey))).size),
      conflictsResolved: 0,
      added: bundle.categorie.length + bundle.componenti.length + bundle.interventi.length,
      updated: 0,
      removed: 0,
    },
  };
}

export function countActivities(bundle: TkbDraftBundle): number {
  return activityCount(bundle);
}

export function emptyDraftBundle(): TkbDraftBundle {
  return {
    categorie: [],
    componenti: [],
    sintomi: [],
    procedure: [],
    interventi: [],
    ricambiMap: [],
  };
}

/** Merge conservativo: union di array su draft esistente per incremental patch. */
export function patchDraftFromFragments(
  previous: TkbDraftBundle,
  fragments: TkbSourceFragment[],
): MergeResult {
  const merged = mergeFragments([...fragmentsFromDraft(previous), ...fragments]);
  return merged;
}

function fragmentsFromDraft(draft: TkbDraftBundle): TkbSourceFragment[] {
  const out: TkbSourceFragment[] = [];
  const base = { sourceId: "draft_cache", precedence: 5, provenance: { origin: "draft_cache" } };
  for (const c of draft.categorie) {
    out.push({ ...base, entityKind: "categoria", entityKey: c.slug, payload: c });
  }
  for (const c of draft.componenti) {
    out.push({ ...base, entityKind: "componente", entityKey: c.slug, payload: c });
  }
  for (const s of draft.sintomi) {
    out.push({ ...base, entityKind: "sintomo", entityKey: s.slug, payload: s });
  }
  for (const p of draft.procedure) {
    out.push({ ...base, entityKind: "procedure", entityKey: p.slug, payload: p });
  }
  for (const i of draft.interventi) {
    out.push({ ...base, entityKind: "intervento", entityKey: i.slug, payload: i });
  }
  for (const m of draft.ricambiMap) {
    out.push({ ...base, entityKind: "ricambioMap", entityKey: m.id, payload: m });
  }
  return out;
}

export function makeActivity(
  activityId: string,
  text: string,
  sort: number,
  activityType: CatalogActivity["activityType"],
  required = true,
): CatalogActivity {
  return { activityId, text, sort, required, activityType };
}

import type {
  CatalogActivity,
  InterventoActivityOverride,
  TkbIntervento,
  TkbProcedure,
  TkbPublishedSnapshot,
} from "@/lib/domain/technical-knowledge-base/types";

function activityKey(a: CatalogActivity): string {
  return a.activityId;
}

function mergeActivities(base: CatalogActivity[], incoming: CatalogActivity[]): CatalogActivity[] {
  const byId = new Map<string, CatalogActivity>();
  for (const a of base) byId.set(activityKey(a), a);
  for (const a of incoming) byId.set(activityKey(a), a);
  return [...byId.values()].sort((a, b) => a.sort - b.sort || a.activityId.localeCompare(b.activityId));
}

function applyOverrides(
  activities: CatalogActivity[],
  overrides: InterventoActivityOverride[] | undefined,
): CatalogActivity[] {
  if (!overrides?.length) return activities;
  let out = [...activities];
  for (const ov of overrides) {
    if (ov.action === "disable") {
      out = out.filter((a) => a.activityId !== ov.activityId);
    } else if (ov.action === "replace" && ov.replacement) {
      const idx = out.findIndex((a) => a.activityId === ov.activityId);
      if (idx >= 0) {
        out[idx] = { ...ov.replacement, sort: out[idx]!.sort };
      }
    }
  }
  return out;
}

export function resolveInterventoActivities(
  intervento: TkbIntervento,
  snapshot: TkbPublishedSnapshot,
): CatalogActivity[] {
  const procBySlug = new Map(snapshot.procedure.map((p) => [p.slug, p]));
  let merged: CatalogActivity[] = [];

  for (const procSlug of intervento.procedureSlugs ?? []) {
    const proc = procBySlug.get(procSlug);
    if (!proc) continue;
    merged = mergeActivities(merged, [...proc.attivita, ...(proc.controlliFinali ?? [])]);
  }

  merged = applyOverrides(merged, intervento.activityOverrides);
  merged = mergeActivities(merged, [
    ...intervento.attivitaPrincipali,
    ...(intervento.attivitaComplementari ?? []),
    ...(intervento.controlliFinali ?? []),
  ]);

  return merged.sort((a, b) => a.sort - b.sort || a.activityId.localeCompare(b.activityId));
}

export function filterActivitiesByDetailLevel(
  activities: CatalogActivity[],
  detailLevel: import("@/lib/preventivi/description-engine/types").DetailLevel,
): CatalogActivity[] {
  switch (detailLevel) {
    case "compact":
      return activities.filter((a) => a.required);
    case "standard":
      return activities.filter((a) => a.required || a.includeInStandard !== false);
    case "technical":
      return activities;
  }
}

export function operationSortRank(activityType: CatalogActivity["activityType"]): number {
  const map: Record<CatalogActivity["activityType"], number> = {
    diagnosi: 5,
    smontaggio: 10,
    controllo: 25,
    sostituzione: 30,
    pulizia: 35,
    ripristino: 36,
    collaudo: 50,
  };
  return map[activityType] ?? 32;
}

export function sortResolvedActivities(activities: CatalogActivity[]): CatalogActivity[] {
  return [...activities].sort(
    (a, b) =>
      operationSortRank(a.activityType) - operationSortRank(b.activityType) ||
      a.sort - b.sort ||
      a.activityId.localeCompare(b.activityId),
  );
}

import "server-only";

import { validateTkbDraftBundle } from "../tkb-snapshot-builder";
import { runTdeBenchmark } from "../benchmark/run-benchmark";
import { kbStatsFromBuildReport } from "../ingestion/builder";
import { loadQualityGateThresholds } from "./thresholds";
import type { BenchmarkReport, TkbBuildReport, TkbDraftBundle, TkbKbStats } from "../types";

export type QualityGateResult =
  | { ok: true; benchmark: BenchmarkReport; kbStats: TkbKbStats }
  | { ok: false; blockedBy: string[]; details: Record<string, unknown> };

export type QualityGateBaseline = {
  kbCoverage?: number;
  oar?: number;
  thr?: number;
};

export function runQualityGates(
  bundle: TkbDraftBundle,
  baseline?: QualityGateBaseline,
): QualityGateResult {
  const thresholds = loadQualityGateThresholds();
  const blockedBy: string[] = [];
  const details: Record<string, unknown> = {};

  try {
    validateTkbDraftBundle(bundle);
  } catch (e) {
    blockedBy.push("validation");
    details.validation = e instanceof Error ? e.message : String(e);
    return { ok: false, blockedBy, details };
  }

  if (bundle.interventi.length < thresholds.minInterventi && bundle.buildReport?.warnings?.includes("seed:fallback:db_vuoto")) {
    // seed-only DB — skip min counts
  } else {
    if (bundle.interventi.length < thresholds.minInterventi) {
      blockedBy.push("min_interventi");
      details.minInterventi = { required: thresholds.minInterventi, actual: bundle.interventi.length };
    }
    if (bundle.componenti.length < thresholds.minComponenti) {
      blockedBy.push("min_componenti");
      details.minComponenti = { required: thresholds.minComponenti, actual: bundle.componenti.length };
    }
  }

  const benchmark = runTdeBenchmark(bundle);
  details.benchmark = benchmark;

  if (benchmark.thr > thresholds.maxThr) {
    blockedBy.push("thr");
    details.thr = { max: thresholds.maxThr, actual: benchmark.thr };
  }

  if (baseline?.kbCoverage != null && baseline.kbCoverage - benchmark.kbCoverage > thresholds.maxCoverageDrop) {
    blockedBy.push("coverage_regression");
    details.coverage = { baseline: baseline.kbCoverage, actual: benchmark.kbCoverage };
  }

  if (baseline?.oar != null && baseline.oar - benchmark.oar > thresholds.maxOarDrop) {
    blockedBy.push("oar_regression");
    details.oar = { baseline: baseline.oar, actual: benchmark.oar };
  }

  const kbStats = bundle.buildReport
    ? kbStatsFromBuildReport(bundle.buildReport)
    : {
        interventi: bundle.interventi.length,
        componenti: bundle.componenti.length,
        descrizioni: 0,
        categorie: bundle.categorie.length,
        excludedDeleted: 0,
        sourceCoverage: {},
        warnings: [],
      };

  if (blockedBy.length) return { ok: false, blockedBy, details };
  return { ok: true, benchmark, kbStats };
}

import "server-only";

import type { SupabaseClient } from "@supabase/supabase-js";
import { invalidateTkbSnapshotCache } from "./cache/tkb-snapshot-cache.server";
import { publishDraftToDb, loadLatestPublishedSnapshot, type PublishDraftOpts } from "./tkb-repository.server";
import {
  getLatestMemorySnapshot,
  getMemorySnapshotByVersion,
  loadPublishedTkbSnapshot as loadMemorySnapshot,
  publishTkbDraft as publishMemoryDraft,
} from "./tkb-publish";
import type { PublishTkbResult, TkbDraftBundle, TkbPublishedSnapshot } from "./types";

const useMemoryStore = () =>
  process.env.TKB_USE_MEMORY_STORE === "1" || process.env.NODE_ENV === "test";

export async function publishTkbDraftServer(
  supabase: SupabaseClient | null,
  bundle: TkbDraftBundle,
  opts?: PublishDraftOpts,
): Promise<PublishTkbResult> {
  if (useMemoryStore() || !supabase) {
    return publishMemoryDraft(bundle, opts);
  }
  const result = await publishDraftToDb(supabase, bundle, opts);
  if (result.created) invalidateTkbSnapshotCache();
  return result;
}

export async function loadPublishedTkbSnapshotServer(
  supabase: SupabaseClient | null,
  kbVersion?: number,
): Promise<TkbPublishedSnapshot> {
  if (useMemoryStore() || !supabase) {
    return loadMemorySnapshot(kbVersion);
  }
  const { getCachedPublishedSnapshot } = await import("./cache/tkb-snapshot-cache.server");
  const cached = await getCachedPublishedSnapshot(supabase, kbVersion);
  if (cached) return cached;
  throw new Error("Nessuno snapshot TKB published disponibile.");
}

export async function getLatestKbVersionServer(supabase: SupabaseClient | null): Promise<number | null> {
  if (useMemoryStore() || !supabase) {
    return getLatestMemorySnapshot()?.kbVersion ?? null;
  }
  const latest = await loadLatestPublishedSnapshot(supabase);
  return latest?.snapshot.kbVersion ?? null;
}

export { getMemorySnapshotByVersion, getLatestMemorySnapshot };

import { canonicalizeDraftBundle } from "./canonicalize";
import { sha256Canonical } from "./hash";
import type { CatalogActivity, TkbDraftBundle, TkbPublishedSnapshot } from "./types";

const ACTIVITY_ID_RE = /^[a-z0-9_]{4,80}$/;

export class TkbValidationError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "TkbValidationError";
  }
}

function validateActivity(a: CatalogActivity, ctx: string): void {
  if (!ACTIVITY_ID_RE.test(a.activityId)) {
    throw new TkbValidationError(`${ctx}: activityId invalido "${a.activityId}"`);
  }
  if (!a.text.trim()) throw new TkbValidationError(`${ctx}: text vuoto per ${a.activityId}`);
}

export function validateTkbDraftBundle(bundle: TkbDraftBundle): void {
  for (const p of bundle.procedure) {
    for (const a of [...p.attivita, ...(p.controlliFinali ?? [])]) {
      validateActivity(a, `procedure:${p.slug}`);
    }
  }
  for (const i of bundle.interventi) {
    for (const a of [
      ...i.attivitaPrincipali,
      ...(i.attivitaComplementari ?? []),
      ...(i.controlliFinali ?? []),
    ]) {
      validateActivity(a, `intervento:${i.slug}`);
    }
    for (const ov of i.activityOverrides ?? []) {
      if (ov.action === "replace" && !ov.replacement) {
        throw new TkbValidationError(`intervento:${i.slug}: replace senza replacement`);
      }
    }
    for (const procSlug of i.procedureSlugs ?? []) {
      if (!bundle.procedure.some((p) => p.slug === procSlug)) {
        throw new TkbValidationError(`intervento:${i.slug}: procedure mancante ${procSlug}`);
      }
    }
  }
}

export function buildPublishedSnapshot(
  bundle: TkbDraftBundle,
  kbVersion: number,
  publishedAt: string,
): TkbPublishedSnapshot {
  const stripped: TkbDraftBundle = {
    componenti: bundle.componenti,
    sintomi: bundle.sintomi,
    categorie: bundle.categorie,
    procedure: bundle.procedure,
    interventi: bundle.interventi,
    ricambiMap: bundle.ricambiMap,
    searchIndex: bundle.searchIndex,
  };
  validateTkbDraftBundle(stripped);
  return {
    schemaVersion: 1,
    kbVersion,
    publishedAt,
    componenti: stripped.componenti,
    sintomi: stripped.sintomi,
    categorie: stripped.categorie,
    procedure: stripped.procedure.map((p) => ({ ...p, publishStatus: "published" as const })),
    interventi: stripped.interventi.map((i) => ({ ...i, publishStatus: "published" as const })),
    ricambiMap: stripped.ricambiMap.filter((m) => m.active),
    searchIndex: stripped.searchIndex,
  };
}

export function hashDraftBundle(bundle: TkbDraftBundle): string {
  const { buildReport: _r, ...core } = bundle;
  return sha256Canonical(canonicalizeDraftBundle(core));
}

export function hashPublishedSnapshot(snapshot: TkbPublishedSnapshot): string {
  return sha256Canonical(canonicalizeDraftBundle({
    componenti: snapshot.componenti,
    sintomi: snapshot.sintomi,
    categorie: snapshot.categorie,
    procedure: snapshot.procedure,
    interventi: snapshot.interventi,
    ricambiMap: snapshot.ricambiMap,
    searchIndex: snapshot.searchIndex,
  }));
}

