export type FatturazioneListRowContext = {
  links: readonly InvoiceLinkRow[];
  snapshotPiva: string;
  preventivoNums: string;
};

export function invoiceDisplayNumber(row: InvoiceRow): string {
  return `${row.numero}/${row.anno}`;
}

export function invoiceRowSearchHaystack(row: InvoiceRow, ctx: FatturazioneListRowContext): string {
  const snap = row.customer_snapshot && typeof row.customer_snapshot === "object" ? row.customer_snapshot : {};
  const piva = typeof (snap as Record<string, unknown>).partita_iva === "string" ? (snap as Record<string, unknown>).partita_iva : ctx.snapshotPiva;
  return [
    invoiceDisplayNumber(row),
    row.cliente_label,
    piva,
    row.status,
    row.note,
    ctx.preventivoNums,
    String(row.totale),
    String(row.imponibile),
  ]
    .filter((s) => typeof s === "string" && s.trim().length > 0)
    .join(" ")
    .toLowerCase();
}

export function invoiceRowMatchesGlobalSearch(row: InvoiceRow, ctx: FatturazioneListRowContext, query: string): boolean {
  const q = query.trim().toLowerCase();
  if (!q) return true;
  return invoiceRowSearchHaystack(row, ctx).includes(q);
}

export function invoiceRowMatchesPageFilters(
  row: InvoiceRow,
  ctx: FatturazioneListRowContext,
  filters: FatturazionePageFilters,
): boolean {
  if (!invoiceRowMatchesGlobalSearch(row, ctx, filters.search)) return false;
  const { search: _s, ...advanced } = filters;
  return invoiceMatchesAdvancedFilters(row, advanced);
}

export function fatturazionePageFiltersActive(filters: FatturazionePageFilters): boolean {
  return Boolean(filters.search.trim()) || fatturazioneAdvancedFiltersActive(filters);
}

export type FatturazioneSortKey = "numero" | "data" | "cliente" | "totale" | "residuo" | "scadenza" | "status";

export function sortInvoices(
  rows: InvoiceRow[],
  key: FatturazioneSortKey,
  asc: boolean,
): InvoiceRow[] {
  const dir = asc ? 1 : -1;
  return [...rows].sort((a, b) => {
    let cmp = 0;
    switch (key) {
      case "numero":
        cmp = a.anno !== b.anno ? a.anno - b.anno : a.numero - b.numero;
        break;
      case "data":
        cmp = a.data_emissione.localeCompare(b.data_emissione);
        break;
      case "cliente":
        cmp = a.cliente_label.localeCompare(b.cliente_label, "it");
        break;
      case "totale":
        cmp = a.totale - b.totale;
        break;
      case "residuo":
        cmp = a.residuo - b.residuo;
        break;
      case "scadenza":
        cmp = (a.data_scadenza ?? "").localeCompare(b.data_scadenza ?? "");
        break;
      case "status":
        cmp = a.status.localeCompare(b.status);
        break;
    }
    return cmp * dir;
  });
}

export function buildInvoiceListContextMaps(
  links: readonly InvoiceLinkRow[],
): Map<string, FatturazioneListRowContext> {
  const byInvoice = new Map<string, { links: InvoiceLinkRow[] }>();
  for (const link of links) {
    const list = byInvoice.get(link.invoice_id) ?? { links: [] };
    list.links.push(link);
    byInvoice.set(link.invoice_id, list);
  }
  const out = new Map<string, FatturazioneListRowContext>();
  for (const [id, { links: invLinks }] of byInvoice) {
    out.set(id, {
      links: invLinks,
      snapshotPiva: "",
      preventivoNums: invLinks.filter((l) => l.source_type === "preventivo").map((l) => l.source_id.slice(0, 8)).join(" "),
    });
  }
  return out;
}

export function invoiceListContextForRow(
  row: InvoiceRow,
  links: readonly InvoiceLinkRow[],
): FatturazioneListRowContext {
  const invLinks = links.filter((l) => l.invoice_id === row.id);
  const snap = row.customer_snapshot && typeof row.customer_snapshot === "object" ? row.customer_snapshot : {};
  const piva = typeof (snap as Record<string, unknown>).partita_iva === "string" ? String((snap as Record<string, unknown>).partita_iva) : "";
  return {
    links: invLinks,
    snapshotPiva: piva,
    preventivoNums: invLinks.filter((l) => l.source_type === "preventivo").map((l) => l.source_id.slice(0, 8)).join(" "),
  };
}

import { coordinateFormScopedRollback } from "@/lib/form-ux-migration/cross-form-rollback-coordinator";
import { evaluateBoundaryPolicy } from "@/lib/form-ux-migration/form-ux-enforcement-policy";
import {
  getFormUxCollapseAdoptionPhase,
  getFormUxGovernanceDecision,
  runGovernanceShadowPipeline,
} from "@/lib/form-ux-migration/form-ux-governance-collapse-plane";
import {
  orchestrateFieldEvaluation,
  beginOrchestratedSubmit,
} from "@/lib/form-ux-migration/form-ux-orchestrator";
import type { FormUxExecutionToken } from "@/lib/form-ux-migration/form-ux-execution-token";
import {
  recordLegacyBypassAttempt,
  runInsideBoundaryGate,
} from "@/lib/form-ux-migration/form-ux-legacy-guard";
import { getFormUxRegistryEntry } from "@/lib/form-ux-migration/form-ux-registry";
import {
  routeBeginSubmitTransaction,
  routeFormSubmitPayload,
} from "@/lib/form-ux-migration/form-ux-submit-router";
import type { AtomicRolloutTransactionResult } from "@/lib/form-ux-migration/atomic-rollout-transaction";
import type { FormUxFrozenSnapshot } from "@/lib/form-ux-migration/form-ux-snapshot";
import type { RolloutTransitionReason } from "@/lib/form-ux-migration/rollout-rollback-executor";
import type { RolloutState } from "@/lib/form-ux-migration/rollout-state-machine";
import type {
  FormUxFieldId,
  FormUxFormId,
  FormUxInputKind,
} from "@/lib/form-ux-migration/types";

const REGISTERED_FORM_IDS = new Set<FormUxFormId>([
  "ricambio",
  "scheda-ingresso",
  "lavorazioni",
  "mezzi",
  "preventivi",
  "settings",
]);

const FORM_UX_ID_ATTR = "data-form-ux-id";
const BOUNDARY_SEEN_ATTR = "data-form-ux-boundary-seen";

let interceptorsInstalled = false;
const gateSubmitSeen = new Set<string>();

export function resolveFormIdFromDomTarget(target: EventTarget | null): FormUxFormId | null {
  if (target == null || typeof (target as Node).nodeType !== "number") return null;

  const element = target as Element;
  const form = element.closest?.("form");
  if (!form) return null;

  const raw = form.getAttribute(FORM_UX_ID_ATTR);
  if (!raw || !REGISTERED_FORM_IDS.has(raw as FormUxFormId)) return null;
  return raw as FormUxFormId;
}

function markDomBoundarySeen(formId: FormUxFormId): void {
  gateSubmitSeen.add(formId);
  queueMicrotask(() => gateSubmitSeen.delete(formId));
}

export function gateBeginSubmit(formId: FormUxFormId): FormUxExecutionToken {
  runGovernanceShadowPipeline(formId);
  markDomBoundarySeen(formId);
  return runInsideBoundaryGate(() => routeBeginSubmitTransaction(formId));
}

export function gateFormSubmit<T extends Record<string, unknown>>(
  formId: FormUxFormId,
  legacyState: T,
  submitToken?: FormUxExecutionToken,
): T {
  runGovernanceShadowPipeline(formId);
  markDomBoundarySeen(formId);

  if (getFormUxCollapseAdoptionPhase() >= 3) {
    const decision = getFormUxGovernanceDecision(formId);
    if (decision.blocked) {
      recordLegacyBypassAttempt({
        path: "modal_internal_submit",
        formId,
      });
      return legacyState;
    }
  }

  const policy = evaluateBoundaryPolicy({
    operation: "submit",
    formId,
    interceptedPath: "gateFormSubmit",
    isLegacyBypass: false,
  });

  if (policy.action === "block" && policy.reason === "unregistered_form") {
    recordLegacyBypassAttempt({
      path: "modal_internal_submit",
      formId,
    });
    return legacyState;
  }

  return runInsideBoundaryGate(() => routeFormSubmitPayload(formId, legacyState, submitToken));
}

export function gateFieldEvaluation(input: {
  formId: FormUxFormId;
  fieldId: FormUxFieldId;
  kind: FormUxInputKind;
  token: FormUxExecutionToken;
  legacyState?: Record<string, unknown>;
  onCompute: (ctx: FormUxFrozenSnapshot) => void;
}): AtomicRolloutTransactionResult<void> {
  runGovernanceShadowPipeline(input.formId);

  if (getFormUxCollapseAdoptionPhase() >= 3) {
    const decision = getFormUxGovernanceDecision(input.formId);
    if (decision.blocked) {
      recordLegacyBypassAttempt({
        path: "direct_atomicRolloutTransaction",
        formId: input.formId,
      });
      return {
        ok: false,
        stale: true,
        executionToken: input.token,
        snapshotHash: "",
      };
    }
  }

  const policy = evaluateBoundaryPolicy({
    operation: "evaluation",
    formId: input.formId,
    interceptedPath: "gateFieldEvaluation",
    isLegacyBypass: false,
  });

  if (policy.action === "block" && policy.reason === "unregistered_form") {
    recordLegacyBypassAttempt({
      path: "direct_atomicRolloutTransaction",
      formId: input.formId,
    });
    return {
      ok: false,
      stale: true,
      executionToken: input.token,
      snapshotHash: "",
    };
  }

  return runInsideBoundaryGate(() => orchestrateFieldEvaluation(input));
}

export function gateRollbackDispatch(input: {
  formId: FormUxFormId;
  fieldId: FormUxFieldId;
  kind: FormUxInputKind;
  currentState: RolloutState;
  fromState: RolloutState;
  action: "off" | "downgrade_one";
  reason: RolloutTransitionReason;
  rollbackReason?: string;
}): RolloutState | null {
  return runInsideBoundaryGate(() => {
    const result = coordinateFormScopedRollback(input);
    return result;
  });
}

export function installFormUxGlobalInterceptors(): () => void {
  if (typeof document === "undefined") {
    return () => {};
  }
  if (interceptorsInstalled) {
    return () => {};
  }
  interceptorsInstalled = true;

  const handleSubmit = (event: Event) => {
    const formId = resolveFormIdFromDomTarget(event.target);
    if (!formId) {
      const phase = evaluateBoundaryPolicy({
        operation: "submit",
        interceptedPath: "dom_submit_unmarked",
        isLegacyBypass: true,
      });
      if (phase.action !== "passive") {
        recordLegacyBypassAttempt({ path: "dom_submit_unmarked" });
      }
      return;
    }

    const form = (event.target as HTMLFormElement) ?? null;
    if (form) {
      form.setAttribute(BOUNDARY_SEEN_ATTR, "1");
    }

    if (!gateSubmitSeen.has(formId)) {
      const action = recordLegacyBypassAttempt({
        path: "dom_submit_unmarked",
        formId,
      });
      if (action === "block") {
        event.preventDefault();
        event.stopPropagation();
      }
    }
  };

  const handleSubmitClick = (event: Event) => {
    const target = event.target;
    if (!(target instanceof Element)) return;
    const button = target.closest('button[type="submit"], input[type="submit"]');
    if (!button) return;

    const formId = resolveFormIdFromDomTarget(button);
    if (!formId) return;

    if (!gateSubmitSeen.has(formId)) {
      recordLegacyBypassAttempt({
        path: "dom_submit_unmarked",
        formId,
      });
    }
  };

  document.addEventListener("submit", handleSubmit, true);
  document.addEventListener("click", handleSubmitClick, true);

  return () => {
    document.removeEventListener("submit", handleSubmit, true);
    document.removeEventListener("click", handleSubmitClick, true);
    interceptorsInstalled = false;
  };
}

/** Re-export for orchestrated submit when boundary routes explicitly. */
export { beginOrchestratedSubmit };

/** Test helper. */
export function resetFormUxBoundaryGate(): void {
  gateSubmitSeen.clear();
  interceptorsInstalled = false;
}

import {
  atomicFormSubmitTransaction,
  atomicRolloutTransaction,
  type AtomicRolloutTransactionResult,
} from "@/lib/form-ux-migration/atomic-rollout-transaction";
import {
  assertFormUxIsolationBoundary,
  recordSnapshotInContext,
  setContextSubmitToken,
  trackFieldTransactionEnd,
  trackFieldTransactionStart,
} from "@/lib/form-ux-migration/form-ux-execution-context";
import {
  beginSubmitTransaction,
  type FormUxExecutionToken,
} from "@/lib/form-ux-migration/form-ux-execution-token";
import {
  getFormUxRegistryEntry,
  isFormUxRolloutEnabled,
} from "@/lib/form-ux-migration/form-ux-registry";
import {
  resolveConsumerGovernanceView,
  runGovernanceShadowPipeline,
} from "@/lib/form-ux-migration/form-ux-governance-collapse-plane";
import type { FormUxFrozenSnapshot } from "@/lib/form-ux-migration/form-ux-snapshot";
import type { SubmitDivergence } from "@/lib/form-ux-migration/resolve-form-submit-payload";
import { emitFormUxCrossFormEvent } from "@/lib/form-ux-migration/telemetry";
import type { FormUxFieldId, FormUxFormId, FormUxInputKind } from "@/lib/form-ux-migration/types";

function emitOrchestratorEvent(input: {
  formId: FormUxFormId;
  eventType: "orchestrator_eval" | "orchestrator_submit";
  executionToken?: FormUxExecutionToken;
  snapshotHash?: string;
  latencyMs: number;
  shadowMode?: boolean;
  rollbackOccurred?: boolean;
}): void {
  const entry = getFormUxRegistryEntry(input.formId);
  if (!entry) return;

  emitFormUxCrossFormEvent({
    formId: input.formId,
    domain: entry.domain,
    executionToken: input.executionToken ? String(input.executionToken.seq) : undefined,
    eventType: input.eventType,
    rollbackOccurred: input.rollbackOccurred ?? false,
    latencyMs: input.latencyMs,
    snapshotHash: input.snapshotHash,
    shadowMode: input.shadowMode,
    ts: Date.now(),
  });
}

function resolveOrchestratorPhase(formId: FormUxFormId): number {
  return resolveConsumerGovernanceView(formId).phase;
}

function resolveOrchestratorShadowMode(formId: FormUxFormId): boolean {
  return resolveConsumerGovernanceView(formId).mode === "shadow";
}

function shouldRouteThroughOrchestrator(formId: FormUxFormId): boolean {
  return resolveConsumerGovernanceView(formId).routing === "orchestrator";
}

export function beginOrchestratedSubmit(formId: FormUxFormId): FormUxExecutionToken {
  const token = beginSubmitTransaction(formId);
  if (shouldRouteThroughOrchestrator(formId)) {
    setContextSubmitToken(formId, token);
  }
  return token;
}

export function orchestrateFieldEvaluation(input: {
  formId: FormUxFormId;
  fieldId: FormUxFieldId;
  kind: FormUxInputKind;
  token: FormUxExecutionToken;
  legacyState?: Record<string, unknown>;
  onCompute: (ctx: FormUxFrozenSnapshot) => void;
}): AtomicRolloutTransactionResult<void> {
  const { formId, fieldId, kind, token, legacyState, onCompute } = input;
  runGovernanceShadowPipeline(formId);
  const entry = getFormUxRegistryEntry(formId);
  if (!entry) {
    return { ok: false, stale: true, executionToken: token, snapshotHash: "" };
  }

  try {
    assertFormUxIsolationBoundary(formId, formId);
  } catch {
    emitFormUxCrossFormEvent({
      formId,
      domain: entry.domain,
      executionToken: String(token.seq),
      eventType: "isolation_violation_blocked",
      rollbackOccurred: false,
      latencyMs: 0,
      ts: Date.now(),
    });
    return { ok: false, stale: true, executionToken: token, snapshotHash: "" };
  }

  const phase = resolveOrchestratorPhase(formId);
  const start = Date.now();
  const shadowMode = resolveOrchestratorShadowMode(formId);
  const routeActive = shouldRouteThroughOrchestrator(formId);

  if (phase >= 3 && routeActive) {
    trackFieldTransactionStart(formId, fieldId);
  }

  const result = atomicRolloutTransaction({
    formId,
    fieldId,
    kind,
    token,
    legacyState,
    mode: "evaluation",
    onCompute,
  });

  if (phase >= 3 && routeActive) {
    trackFieldTransactionEnd(formId, fieldId);
    if (result.snapshotHash) {
      recordSnapshotInContext(formId, result.snapshotHash, Date.now());
    }
  }

  if (phase >= 2) {
    emitOrchestratorEvent({
      formId,
      eventType: "orchestrator_eval",
      executionToken: token,
      snapshotHash: result.snapshotHash || undefined,
      latencyMs: Date.now() - start,
      shadowMode,
    });
  }

  return result;
}

export function orchestrateSubmitTransaction<T extends Record<string, unknown>>(input: {
  formId: FormUxFormId;
  token: FormUxExecutionToken;
  legacyState: T;
  reportDivergences: (divergences: SubmitDivergence[], snapshotHash: string) => void;
}): AtomicRolloutTransactionResult<{ payload: T; divergences: SubmitDivergence[] }> {
  const { formId, token, legacyState, reportDivergences } = input;
  runGovernanceShadowPipeline(formId);
  const entry = getFormUxRegistryEntry(formId);
  if (!entry) {
    return { ok: false, stale: true, executionToken: token, snapshotHash: "" };
  }

  try {
    assertFormUxIsolationBoundary(formId, formId);
  } catch {
    emitFormUxCrossFormEvent({
      formId,
      domain: entry.domain,
      executionToken: String(token.seq),
      eventType: "isolation_violation_blocked",
      rollbackOccurred: false,
      latencyMs: 0,
      ts: Date.now(),
    });
    return { ok: false, stale: true, executionToken: token, snapshotHash: "" };
  }

  const phase = resolveOrchestratorPhase(formId);
  const start = Date.now();
  const shadowMode = resolveOrchestratorShadowMode(formId);
  const routeActive = shouldRouteThroughOrchestrator(formId);

  if (phase >= 3 && routeActive) {
    setContextSubmitToken(formId, token);
  }

  const result = atomicFormSubmitTransaction({
    formId,
    token,
    legacyState,
    reportDivergences,
  });

  if (phase >= 3 && routeActive && result.snapshotHash) {
    recordSnapshotInContext(formId, result.snapshotHash, Date.now());
  }

  if (phase >= 2) {
    emitOrchestratorEvent({
      formId,
      eventType: "orchestrator_submit",
      executionToken: token,
      snapshotHash: result.snapshotHash || undefined,
      latencyMs: Date.now() - start,
      shadowMode,
    });
  }

  return result;
}

import {
  classifyAllFields,
  classifyMigrationField,
  classifyMigrationFieldLegacy,
  type MigrationRiskProfile,
} from "@/lib/form-ux-migration/form-ux-migration-classifier";
import {
  scanMigrationInventory,
  type MigrationInventoryField,
} from "@/lib/form-ux-migration/form-ux-migration-inventory-core";
import { resolveFormUxMigrationDecisionForField } from "@/lib/form-ux-migration/form-ux-migration-decision-orchestrator";
import { getWaveExclusionReasons } from "@/lib/form-ux-migration/form-ux-wave-exclusion-rules";
import { mineTierPatterns, type TierPatternStat } from "@/lib/form-ux-migration/form-ux-tier-pattern-miner";

export type FalseNegativeEntry = {
  fieldKey: string;
  nominalTier: number;
  tierBand: string;
  waveEligibleBefore: boolean;
  waveEligibleAfter: boolean;
  exclusionReasons: string[];
  recalibrationReasons: string[];
  patternBucket: string;
};

export type FalseNegativeReport = {
  generatedAt: string;
  tier0StrictBefore: number;
  tier0BandAfter: number;
  falseNegativeCount: number;
  entries: FalseNegativeEntry[];
  patternSummary: Record<string, number>;
  patternStats: TierPatternStat[];
};

function wasLegacyWaveEligible(
  field: MigrationInventoryField,
  legacy: ReturnType<typeof classifyMigrationFieldLegacy>,
): boolean {
  return (
    legacy.tier === 0 &&
    legacy.codemodDisposition === "SAFE_AUTO" &&
    field.status === "legacy" &&
    field.formId != null &&
    !field.fieldId.startsWith("field-")
  );
}

function isRecalibratedWaveEligible(
  field: MigrationInventoryField,
  root: string,
): boolean {
  const decision = resolveFormUxMigrationDecisionForField(field, { root });
  return decision.finalDecision === "INCLUDE";
}

function resolvePatternBucket(
  field: MigrationInventoryField,
  patternStats: TierPatternStat[],
  root: string,
): string {
  const match = patternStats.find((p) => p.exampleFieldKeys.includes(field.fieldKey));
  if (match) return match.pattern;
  const profile = classifyMigrationField(field, { root });
  if (profile.softSignals.length > 0) return profile.softSignals[0]!;
  return "unknown";
}

export function analyzeTier0FalseNegatives(options?: {
  root?: string;
}): FalseNegativeReport {
  const root = options?.root ?? process.cwd();
  const { fields } = scanMigrationInventory({ root });
  const profiles = classifyAllFields(fields, { root });
  const profileByKey = new Map(profiles.map((p) => [p.fieldKey, p]));
  const patternStats = mineTierPatterns(fields, { root });

  let tier0StrictBefore = 0;
  let tier0BandAfter = 0;
  const entries: FalseNegativeEntry[] = [];
  const patternSummary: Record<string, number> = {};

  for (const field of fields) {
    const legacy = classifyMigrationFieldLegacy(field, { root });
    const profile = profileByKey.get(field.fieldKey)!;

    if (legacy.tier === 0) tier0StrictBefore += 1;
    if (profile.tierBand === "0" || profile.tierBand === "0B") tier0BandAfter += 1;

    const waveEligibleBefore = wasLegacyWaveEligible(field, legacy);
    const waveEligibleAfter = isRecalibratedWaveEligible(field, root);

    if (!waveEligibleBefore && waveEligibleAfter) {
      const exclusion = getWaveExclusionReasons(field, profile, { root });
      const patternBucket = resolvePatternBucket(field, patternStats, root);
      patternSummary[patternBucket] = (patternSummary[patternBucket] ?? 0) + 1;

      entries.push({
        fieldKey: field.fieldKey,
        nominalTier: profile.tier,
        tierBand: profile.tierBand,
        waveEligibleBefore,
        waveEligibleAfter,
        exclusionReasons: exclusion.reasons,
        recalibrationReasons: profile.recalibrationReasons,
        patternBucket,
      });
    }
  }

  return {
    generatedAt: new Date().toISOString(),
    tier0StrictBefore,
    tier0BandAfter,
    falseNegativeCount: Math.max(0, tier0BandAfter - tier0StrictBefore),
    entries,
    patternSummary,
    patternStats,
  };
}

