"use client";

import {
  useCallback,
  useLayoutEffect,
  useMemo,
  useRef,
  useState,
  type Dispatch,
  type SetStateAction,
} from "react";
import { gestionaleFormFocusScopeProps } from "@/components/gestionale/gestionale-form-focus-scope";
import {
  captureFormSnapshot,
  captureFormSnapshotSections,
} from "@/lib/forms/form-engine/capture-form-snapshot";
import { isFormEngineEnabled } from "@/lib/forms/form-engine/config";
import { prepareFormSubmit, prepareFormSubmitAsync } from "@/lib/forms/form-engine/prepare-form-submit";
import { createSubmitLock, type FormSubmitLock } from "@/lib/forms/form-engine/submit-lock";
import type { FormEngineSections, FormEngineSnapshot, FormStateSnapshot } from "@/lib/forms/form-engine/types";

export type UseFormEngineResult<T> = {
  value: T;
  setValue: Dispatch<SetStateAction<T>>;
  patch: (partial: Partial<T>) => void;
  reset: (next?: T) => void;
  ref: React.RefObject<T>;
  getSnapshot: () => FormStateSnapshot<T>;
  submitLock: FormSubmitLock;
  runSubmit: (
    root: HTMLElement | null,
    handler: (snap: FormStateSnapshot<T>) => void | Promise<void>,
  ) => Promise<void>;
  formProps: ReturnType<typeof gestionaleFormFocusScopeProps>;
};

export function useFormEngine<T extends object>(options: {
  initial: T;
  enabled?: boolean;
}): UseFormEngineResult<T> {
  const enabled = options.enabled ?? isFormEngineEnabled();
  const initialRef = useRef(options.initial);
  initialRef.current = options.initial;
  const [value, setValueState] = useState<T>(options.initial);
  const ref = useRef(value);
  const submitLock = useMemo(() => createSubmitLock(), []);

  const setValue = useCallback((action: SetStateAction<T>) => {
    setValueState((prev) => {
      const resolved = typeof action === "function" ? (action as (p: T) => T)(prev) : action;
      ref.current = resolved;
      return resolved;
    });
  }, []);

  useLayoutEffect(() => {
    ref.current = value;
  }, [value]);

  const patch = useCallback(
    (partial: Partial<T>) => {
      setValue((prev) => ({ ...prev, ...partial }));
    },
    [setValue],
  );

  const reset = useCallback(
    (next?: T) => {
      const resolved = next ?? initialRef.current;
      ref.current = resolved;
      setValueState(resolved);
    },
    [],
  );

  const getSnapshot = useCallback((): FormStateSnapshot<T> => {
    return captureFormSnapshot(() => ref.current);
  }, []);

  const runSubmit = useCallback(
    async (
      root: HTMLElement | null,
      handler: (snap: FormStateSnapshot<T>) => void | Promise<void>,
    ) => {
      if (!submitLock.acquire()) return;
      try {
        if (enabled) {
          await prepareFormSubmitAsync(root);
        } else {
          prepareFormSubmit(root);
        }
        await handler(getSnapshot());
      } finally {
        submitLock.release();
      }
    },
    [enabled, getSnapshot, submitLock],
  );

  const formProps = useMemo(() => gestionaleFormFocusScopeProps(), []);

  return {
    value,
    setValue,
    patch,
    reset,
    ref,
    getSnapshot,
    submitLock,
    runSubmit,
    formProps,
  };
}

type SectionConfig<S extends FormEngineSections> = {
  [K in keyof S]: { initial: S[K] };
};

export type UseFormEngineSectionsResult<S extends FormEngineSections> = {
  values: S;
  setSection: <K extends keyof S>(key: K, value: S[K] | ((prev: S[K]) => S[K])) => void;
  patchSection: <K extends keyof S>(key: K, partial: Partial<S[K]>) => void;
  resetSections: (next?: Partial<S>) => void;
  refs: { [K in keyof S]: React.RefObject<S[K]> };
  getSnapshot: () => FormEngineSnapshot<S>;
  submitLock: FormSubmitLock;
  runSubmit: (
    root: HTMLElement | null,
    handler: (snap: FormEngineSnapshot<S>) => void | Promise<void>,
  ) => Promise<void>;
  formProps: ReturnType<typeof gestionaleFormFocusScopeProps>;
};

export function useFormEngineSections<S extends FormEngineSections>(options: {
  sections: SectionConfig<S>;
  enabled?: boolean;
}): UseFormEngineSectionsResult<S> {
  const enabled = options.enabled ?? isFormEngineEnabled();
  const sectionKeysRef = useRef<(keyof S)[] | null>(null);
  if (!sectionKeysRef.current) {
    sectionKeysRef.current = Object.keys(options.sections) as (keyof S)[];
  }
  const sectionKeys = sectionKeysRef.current;
  const sectionsConfigRef = useRef(options.sections);
  sectionsConfigRef.current = options.sections;

  const buildInitial = useCallback((): S => {
    const out = {} as S;
    for (const key of sectionKeys) {
      out[key] = sectionsConfigRef.current[key].initial;
    }
    return out;
  }, [sectionKeys]);

  const [values, setValuesState] = useState<S>(buildInitial);
  const refsMap = useRef<{ [K in keyof S]?: S[K] }>({});

  const syncAllRefs = useCallback((next: S) => {
    for (const key of sectionKeys) {
      refsMap.current[key] = next[key];
    }
  }, [sectionKeys]);

  syncAllRefs(values);

  useLayoutEffect(() => {
    syncAllRefs(values);
  }, [values, syncAllRefs]);

  const submitLock = useMemo(() => createSubmitLock(), []);

  const setSection = useCallback(
    <K extends keyof S>(key: K, value: S[K] | ((prev: S[K]) => S[K])) => {
      setValuesState((prev) => {
        const resolved =
          typeof value === "function" ? (value as (p: S[K]) => S[K])(prev[key]) : value;
        const next = { ...prev, [key]: resolved };
        refsMap.current[key] = resolved;
        return next;
      });
    },
    [],
  );

  const patchSection = useCallback(
    <K extends keyof S>(key: K, partial: Partial<S[K]>) => {
      setSection(key, (prev) => ({
        ...(prev as Record<string, unknown>),
        ...(partial as Record<string, unknown>),
      }) as S[K]);
    },
    [setSection],
  );

  const resetSections = useCallback(
    (next?: Partial<S>) => {
      const base = buildInitial();
      const merged = next ? ({ ...base, ...next } as S) : base;
      syncAllRefs(merged);
      setValuesState(merged);
    },
    [buildInitial, syncAllRefs],
  );

  const getSnapshot = useCallback((): FormEngineSnapshot<S> => {
    const readers = {} as { [K in keyof S]: () => S[K] };
    for (const key of sectionKeys) {
      readers[key] = () => refsMap.current[key] as S[typeof key];
    }
    return captureFormSnapshotSections(readers);
  }, [sectionKeys]);

  const runSubmit = useCallback(
    async (
      root: HTMLElement | null,
      handler: (snap: FormEngineSnapshot<S>) => void | Promise<void>,
    ) => {
      if (!submitLock.acquire()) return;
      try {
        if (enabled) {
          await prepareFormSubmitAsync(root);
        } else {
          prepareFormSubmit(root);
        }
        await handler(getSnapshot());
      } finally {
        submitLock.release();
      }
    },
    [enabled, getSnapshot, submitLock],
  );

  const formProps = useMemo(() => gestionaleFormFocusScopeProps(), []);

  const refs = useMemo(() => {
    const out = {} as { [K in keyof S]: React.RefObject<S[K]> };
    for (const key of sectionKeys) {
      out[key] = {
        get current() {
          return refsMap.current[key] as S[typeof key];
        },
        set current(v: S[typeof key]) {
          refsMap.current[key] = v;
        },
      };
    }
    return out;
  }, [sectionKeys]);

  return {
    values,
    setSection,
    patchSection,
    resetSections,
    refs,
    getSnapshot,
    submitLock,
    runSubmit,
    formProps,
  };
}

"use client";

import { reconcileLogModificaRows } from "@/lib/gestionale-log/log-event-pipeline";
import {
  buildLogModificaSummary,
  filterAuditMetadataCampoChanges,
  modificheToModificaRiga,
  parseModificheLines,
  type LogModificaSummary,
} from "@/lib/gestionale-log/log-summary";
import { isImageLogAction, type GestionaleLogEventTone, type GestionaleLogViewModel } from "@/lib/gestionale-log/view-model";
import { isLogReverted } from "@/lib/gestionale-log/undo";
import { Q_FOCUS_LAV_ROW, Q_FOCUS_RICAMBIO } from "@/lib/navigation/dashboard-log-links";
import { lavorazioneLogOggettoFromListRow } from "@/lib/lavorazioni/lavorazione-log-oggetto";
import type { StatoLavorazioneConfig } from "@/lib/lavorazioni/types";
import type { LavorazioneListRow } from "@/src/services/lavorazioni.service";
import type { LogModificaRow, LogModificaWithProfileRow } from "@/src/types/supabase-tables";
import type { LavorazioneSchedeStore } from "@/types/schede";

export type LogModificaAutoreSource = LogModificaRow | LogModificaWithProfileRow;

export function isGenericLavorazioneLogOggetto(oggetto: string): boolean {
  const t = oggetto.trim();
  return !t || t === "—" || t === "Lavorazione" || /^Scheda\s·\s/i.test(t);
}

/** Risolve titolo log lavorazioni da payload.context o catalogo locale. */
export function buildLavorazioneLogOggettoResolver(
  lavorazioniById: ReadonlyMap<string, LavorazioneListRow>,
  schedeStore?: LavorazioneSchedeStore,
): (row: LogModificaAutoreSource) => string | undefined {
  return (logRow) => {
    if (logRow.entita !== "lavorazioni") return undefined;
    const fromPayload = logModificaOggettoFromPayload(logRow as LogModificaRow);
    if (fromPayload && fromPayload !== "—") return fromPayload;
    const lav = lavorazioniById.get(logRow.entita_id);
    if (!lav) return undefined;
    const label = lavorazioneLogOggettoFromListRow(lav, schedeStore);
    return label !== "—" ? label : undefined;
  };
}

export function logAutoreLabel(r: LogModificaAutoreSource, currentUserId: string | null, displayName: string): string {
  const profileNome = (r as LogModificaWithProfileRow).profiles?.nome?.trim();
  if (r.autore_id && currentUserId && r.autore_id === currentUserId) {
    return displayName.trim() || profileNome || "Tu";
  }
  if (profileNome) return profileNome;
  if (r.autore_id) return `Utente ${r.autore_id.slice(0, 8)}…`;
  return "Sistema";
}

function summaryToViewModel(summary: LogModificaSummary, autore: string, atIso: string, annullato?: boolean): GestionaleLogViewModel {
  return {
    tone: summary.tone,
    tipoRiga: summary.tipoRiga,
    oggettoRiga: summary.oggettoRiga,
    modificaRiga: modificheToModificaRiga(summary.modifiche),
    autore,
    atIso,
    annullato,
  };
}

/** Vista centralizzata di una riga `log_modifiche` per UI gestionale. */
export function buildLogModificheGestionaleViewModel(
  row: LogModificaRow,
  autore: string,
  statiLavorazione?: StatoLavorazioneConfig[],
): GestionaleLogViewModel {
  const reverted = isLogReverted(row);
  const summary = buildLogModificaSummary({
    entita: row.entita,
    entita_id: row.entita_id,
    azione: reverted ? "UNDO" : row.azione,
    payload: row.payload,
    annullato: reverted,
    statiLavorazione: row.entita === "lavorazioni" ? statiLavorazione : undefined,
  });
  if (isImageLogAction(row.azione) && !reverted) {
    summary.tipoRiga = row.azione === "image_deleted" ? "ELIMINAZIONE FILE" : "CARICAMENTO FILE";
  }
  return summaryToViewModel(summary, autore, row.created_at, reverted);
}

/** Lista log per UI: unisce modifiche rapide allo stesso campo, poi costruisce le view model. */
export type BuildLogModificheDisplayOptions = {
  /** Sostituisce titoli generici (es. «Lavorazione») con etichetta contestuale. */
  resolveOggetto?: (row: LogModificaAutoreSource) => string | undefined;
  /** Etichette stati da impostazioni (lavorazioni). */
  statiLavorazione?: StatoLavorazioneConfig[];
};

export function buildLogModificheDisplayEntries(
  rows: readonly LogModificaAutoreSource[],
  resolveAutore: (row: LogModificaAutoreSource) => string,
  options?: BuildLogModificheDisplayOptions,
): { id: string; row: LogModificaRow; vm: GestionaleLogViewModel }[] {
  const consolidated = reconcileLogModificaRows(rows);
  return consolidated.map((row) => {
    let vm = buildLogModificheGestionaleViewModel(row, resolveAutore(row), options?.statiLavorazione);
    const oggetto =
      options?.resolveOggetto?.(row)?.trim() ?? logModificaOggettoFromPayload(row)?.trim();
    if (oggetto && oggetto !== "—" && isGenericLavorazioneLogOggetto(vm.oggettoRiga)) {
      vm = { ...vm, oggettoRiga: oggetto };
    }
    return { id: row.id, row, vm };
  });
}

export function buildLogModificheDisplayList(
  rows: readonly LogModificaAutoreSource[],
  resolveAutore: (row: LogModificaAutoreSource) => string,
  options?: BuildLogModificheDisplayOptions,
): GestionaleLogViewModel[] {
  return buildLogModificheDisplayEntries(rows, resolveAutore, options).map((e) => e.vm);
}

export function logModificaOggettoFromPayload(row: LogModificaRow): string | undefined {
  const p = row.payload;
  if (!p || typeof p !== "object" || Array.isArray(p)) return undefined;
  const ctx = (p as Record<string, unknown>).context;
  if (ctx && typeof ctx === "object" && !Array.isArray(ctx)) {
    const oggetto = (ctx as Record<string, unknown>).oggetto;
    if (typeof oggetto === "string" && oggetto.trim()) return oggetto.trim();
  }
  return undefined;
}

function lavorazioneIdFromLogRow(row: LogModificaRow): string | null {
  if (row.entita === "lavorazioni") return row.entita_id;
  const p = row.payload;
  if (!p || typeof p !== "object" || Array.isArray(p)) return null;
  const payload = p as Record<string, unknown>;
  for (const rec of [payload.after, payload.snapshot, payload.before]) {
    if (!rec || typeof rec !== "object" || Array.isArray(rec)) continue;
    const lavId = (rec as Record<string, unknown>).lavorazione_id;
    if (typeof lavId === "string" && lavId.trim()) return lavId.trim();
  }
  return null;
}

/** Accorcia elenco modifiche per feed dashboard (prime N righe). */
export function briefLogModificaRiga(modificaRiga: string, maxLines = 3): string {
  const lines = parseModificheLines(modificaRiga);
  if (lines.length <= maxLines) return modificaRiga;
  const head = lines.slice(0, maxLines).map((line) => `• ${line}`);
  return `${head.join("\n")}\n• …`;
}

/** Dettaglio compatto per tabelle admin (security monitoring, audit). */
export function logModificaDetailLine(
  row: LogModificaRow,
  statiLavorazione?: StatoLavorazioneConfig[],
  maxLines = 3,
): string {
  const vm = buildLogModificheGestionaleViewModel(row, "—", statiLavorazione);
  const lines = parseModificheLines(briefLogModificaRiga(vm.modificaRiga, maxLines));
  if (lines.length) {
    return lines.map((line) => `• ${line.replace(/^•\s*/, "")}`).join(" · ");
  }
  const fallback = vm.modificaRiga.trim().replace(/\n/g, " · ");
  if (fallback) return fallback;
  return vm.oggettoRiga !== "—" ? vm.oggettoRiga : vm.tipoRiga || "Evento registrato";
}

/** Deep link da voce log globale a pagina operativa. */
export function buildLogModificheFocusHref(row: LogModificaRow): string | null {
  const lavId = lavorazioneIdFromLogRow(row);
  if (lavId) {
    const sp = new URLSearchParams();
    sp.set(Q_FOCUS_LAV_ROW, lavId);
    return `/lavorazioni?${sp.toString()}`;
  }
  if (row.entita === "magazzino_ricambi") {
    const sp = new URLSearchParams();
    sp.set(Q_FOCUS_RICAMBIO, row.entita_id);
    return `/magazzino?${sp.toString()}`;
  }
  if (row.entita === "mezzi") return `/mezzi`;
  if (row.entita === "preventivi") return `/preventivi`;
  if (row.entita === "documenti") return `/documenti`;
  return null;
}

import { normalizeHex } from "@/lib/lavorazioni/color-utils";
import { addettoThemeColor } from "@/lib/lavorazioni/lavorazioni-theme";

/** Palette base gestionale — 12 colori frequenti (assegnazione automatica + picker impostazioni). */
export const ADDETTO_COLOR_POOL = [
  "#dc2626", // rosso
  "#ea580c", // arancione
  "#ca8a04", // giallo
  "#16a34a", // verde
  "#0d9488", // teal
  "#0891b2", // ciano
  "#2563eb", // blu
  "#4f46e5", // indigo
  "#7c3aed", // viola
  "#c026d3", // fucsia
  "#db2777", // rosa
  "#64748b", // grigio
] as const;

function hslToHex(h: number, s: number, l: number): string {
  const s1 = s / 100;
  const l1 = l / 100;
  const a = s1 * Math.min(l1, 1 - l1);
  const f = (n: number) => {
    const k = (n + h / 30) % 12;
    const col = l1 - a * Math.max(Math.min(k - 3, 9 - k, 1), -1);
    return Math.min(255, Math.max(0, Math.round(255 * col)));
  };
  return `#${[f(0), f(8), f(4)]
    .map((x) => x.toString(16).padStart(2, "0"))
    .join("")}`;
}

function usedHexSet(map: Record<string, string>): Set<string> {
  const u = new Set<string>();
  for (const v of Object.values(map)) {
    const n = normalizeHex(v);
    if (n) u.add(n);
  }
  return u;
}

/** Colore univoco non ancora in `used` (palette mescolata da salt, poi varianti HSL). */
export function nextUniqueAddettoColor(used: Set<string>, salt: number): string {
  const pool = [...ADDETTO_COLOR_POOL];
  for (let i = pool.length - 1; i > 0; i--) {
    const j = Math.abs((salt + i * 31) >>> 0) % (i + 1);
    const t = pool[i]!;
    pool[i] = pool[j]!;
    pool[j] = t;
  }
  for (const c of pool) {
    const n = normalizeHex(c);
    if (n && !used.has(n)) return n;
  }
  for (let step = 0; step < 500; step++) {
    const hue = ((salt >>> 0) + step * 19) % 360;
    const sat = 46 + (step % 6) * 2.5;
    const light = 43 + ((step >> 2) % 5) * 2.2;
    const hex = hslToHex(hue, sat, light);
    const n = normalizeHex(hex);
    if (n && !used.has(n)) return n;
  }
  const fallback = `#${((salt >>> 0) & 0xffffff).toString(16).padStart(6, "0")}`;
  return normalizeHex(fallback) ?? "#52525b";
}

/**
 * Allinea la mappa ai nomi correnti: mantiene colori validi, elimina orfani,
 * assegna colori univoci ai nomi senza voce (o con collisione su stesso hex).
 */
export function syncAddettoColorMap(
  addetti: string[],
  existing: Record<string, string> | undefined,
): Record<string, string> {
  const out: Record<string, string> = {};
  const used = new Set<string>();

  for (const name of addetti) {
    const nh = normalizeHex(existing?.[name]);
    if (nh && !used.has(nh)) {
      out[name] = nh;
      used.add(nh);
    }
  }

  for (const name of addetti) {
    if (out[name]) continue;
    const hex = nextUniqueAddettoColor(used, (name.length + 1) * 1315423911 + addetti.indexOf(name) * 97);
    const n = normalizeHex(hex)!;
    out[name] = n;
    used.add(n);
  }

  return out;
}

/** Colore per UI: da mappa persistita, altrimenti fallback deterministico (righe legacy). */
export function addettoDisplayColor(nome: string, map: Record<string, string>): string {
  const n = normalizeHex(map[nome]);
  if (n) return n;
  return addettoThemeColor(nome);
}

export function assignColorForNewAddetto(prev: Record<string, string>, newName: string): Record<string, string> {
  const used = usedHexSet(prev);
  const salt = (Date.now() + Math.floor(Math.random() * 0x7fffffff)) >>> 0;
  const hex = nextUniqueAddettoColor(used, salt);
  return { ...prev, [newName]: hex };
}

export function renameAddettoInColorMap(
  prev: Record<string, string>,
  previousName: string,
  nextName: string,
): Record<string, string> {
  const col = normalizeHex(prev[previousName]);
  const { [previousName]: _, ...rest } = prev;
  if (col) return { ...rest, [nextName]: col };
  const used = usedHexSet(rest);
  return { ...rest, [nextName]: nextUniqueAddettoColor(used, nextName.length * 999983) };
}

export function removeAddettoFromColorMap(prev: Record<string, string>, name: string): Record<string, string> {
  const { [name]: _, ...rest } = prev;
  return rest;
}

import type { NotificationIntent } from "@/lib/lavorazioni/lavorazione-created-notification-mapper";
import {
  notificationCreatedAt,
  notificationStoreKey,
  wrapLavorazioneNotification,
  type AdminDashboardNotification,
} from "@/lib/notifications/admin-dashboard-notifications";

export type AdminNotificationStoreState = {
  lastSeenAt: string | null;
  items: Record<string, AdminDashboardNotification>;
};

/** Limite voci in localStorage — evita quota exceeded e liste infinite (fase 10 audit). */
/** ponytail: DEPRECATED — sunset quando notifications_v2_mode=on stabile ≥7gg prod; rollback via flag off. */
export const ADMIN_NOTIFICATION_STORE_MAX_ITEMS = 150;

const STORAGE_PREFIX = "cab:admin-dashboard-notifications:";
const LEGACY_STORAGE_PREFIX = "cab:admin-lav-notifications:";

type StoreListener = (userId: string) => void;
const listeners = new Set<StoreListener>();

let storageBridgeAttached = false;

function dispatchStorageKey(key: string): void {
  if (key.startsWith(STORAGE_PREFIX)) {
    const userId = key.slice(STORAGE_PREFIX.length);
    for (const fn of listeners) fn(userId);
    return;
  }
  if (key.startsWith(LEGACY_STORAGE_PREFIX)) {
    const userId = key.slice(LEGACY_STORAGE_PREFIX.length);
    for (const fn of listeners) fn(userId);
  }
}

function onCrossTabStorage(e: StorageEvent): void {
  if (!e.key) return;
  dispatchStorageKey(e.key);
}

function ensureStorageBridgeListener(): void {
  if (storageBridgeAttached || typeof window === "undefined") return;
  storageBridgeAttached = true;
  window.addEventListener("storage", onCrossTabStorage);
}

function storageKey(userId: string): string {
  return `${STORAGE_PREFIX}${userId}`;
}

function legacyStorageKey(userId: string): string {
  return `${LEGACY_STORAGE_PREFIX}${userId}`;
}

function normalizeItem(raw: unknown): AdminDashboardNotification | null {
  if (!raw || typeof raw !== "object") return null;
  const obj = raw as Record<string, unknown>;
  if (obj.kind === "admin_dashboard_test") {
    const id = typeof obj.id === "string" && obj.id.trim() ? obj.id.trim() : `admin-test:${Date.now()}`;
    return {
      kind: "admin_dashboard_test",
      id,
      message: typeof obj.message === "string" ? obj.message : "Notifica di test",
      createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
    };
  }

  if (obj.kind === "dipendenti_presenze_reminder") {
    const dateYmd = typeof obj.dateYmd === "string" ? obj.dateYmd.trim() : "";
    if (!dateYmd) return null;
    const id =
      typeof obj.id === "string" && obj.id.trim() ? obj.id.trim() : `dip-presenze:${dateYmd}`;
    return {
      kind: "dipendenti_presenze_reminder",
      id,
      dateYmd,
      count: typeof obj.count === "number" && obj.count > 0 ? obj.count : 1,
      createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
    };
  }

  if (obj.kind === "dashboard_promemoria_reminder") {
    const promemoriaId = typeof obj.promemoriaId === "string" ? obj.promemoriaId.trim() : "";
    const eventDateYmd = typeof obj.eventDateYmd === "string" ? obj.eventDateYmd.trim() : "";
    const title = typeof obj.title === "string" ? obj.title.trim() : "";
    if (!promemoriaId || !eventDateYmd || !title) return null;
    const id =
      typeof obj.id === "string" && obj.id.trim()
        ? obj.id.trim()
        : `promemoria:${promemoriaId}:${eventDateYmd}`;
    return {
      kind: "dashboard_promemoria_reminder",
      id,
      promemoriaId,
      eventDateYmd,
      title,
      message: typeof obj.message === "string" ? obj.message : title,
      description: typeof obj.description === "string" ? obj.description : null,
      createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
    };
  }

  if (obj.kind === "magazzino_sotto_scorta") {
    const ricambioId = typeof obj.ricambioId === "string" ? obj.ricambioId.trim() : "";
    if (!ricambioId) return null;
    return {
      kind: "magazzino_sotto_scorta",
      id: typeof obj.id === "string" && obj.id.trim() ? obj.id.trim() : ricambioId,
      ricambioId,
      marca: typeof obj.marca === "string" ? obj.marca : "—",
      descrizione: typeof obj.descrizione === "string" ? obj.descrizione : "—",
      scorta: typeof obj.scorta === "number" ? obj.scorta : 0,
      scortaMinima: typeof obj.scortaMinima === "number" ? obj.scortaMinima : 0,
      createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
    };
  }

  const lavorazioneId =
    typeof obj.lavorazioneId === "string"
      ? obj.lavorazioneId.trim()
      : typeof obj.id === "string"
        ? obj.id.trim()
        : "";
  if (!lavorazioneId) return null;

  const intent: NotificationIntent = {
    lavorazioneId,
    titolo: typeof obj.titolo === "string" ? obj.titolo : lavorazioneId,
    cliente: typeof obj.cliente === "string" ? obj.cliente : "",
    mezzo: typeof obj.mezzo === "string" ? obj.mezzo : "",
    targa: typeof obj.targa === "string" ? obj.targa : null,
    createdBy: typeof obj.createdBy === "string" ? obj.createdBy : null,
    createdAt: typeof obj.createdAt === "string" ? obj.createdAt : new Date().toISOString(),
  };
  return wrapLavorazioneNotification(intent);
}

function parseStoreItems(rawItems: unknown): Record<string, AdminDashboardNotification> {
  if (!rawItems || typeof rawItems !== "object") return {};
  const items: Record<string, AdminDashboardNotification> = {};
  for (const [key, value] of Object.entries(rawItems as Record<string, unknown>)) {
    const item = normalizeItem(value);
    if (!item) continue;
    items[notificationStoreKey(item)] = item;
  }
  return items;
}

function migrateLegacyStore(userId: string): AdminNotificationStoreState | null {
  if (typeof window === "undefined" || !userId.trim()) return null;
  try {
    const raw = window.localStorage.getItem(legacyStorageKey(userId));
    if (!raw) return null;
    const parsed = JSON.parse(raw) as AdminNotificationStoreState;
    if (!parsed || typeof parsed !== "object") return null;
    const migrated: AdminNotificationStoreState = {
      lastSeenAt: typeof parsed.lastSeenAt === "string" ? parsed.lastSeenAt : null,
      items: parseStoreItems(parsed.items),
    };
    saveAdminNotificationStore(userId, migrated);
    window.localStorage.removeItem(legacyStorageKey(userId));
    return migrated;
  } catch {
    return null;
  }
}

export function emptyAdminNotificationStore(): AdminNotificationStoreState {
  return { lastSeenAt: null, items: {} };
}

export function loadAdminNotificationStore(userId: string): AdminNotificationStoreState {
  if (typeof window === "undefined" || !userId.trim()) return emptyAdminNotificationStore();
  try {
    const raw = window.localStorage.getItem(storageKey(userId));
    if (!raw) {
      return migrateLegacyStore(userId) ?? emptyAdminNotificationStore();
    }
    const parsed = JSON.parse(raw) as AdminNotificationStoreState;
    if (!parsed || typeof parsed !== "object" || !parsed.items) return emptyAdminNotificationStore();
    return {
      lastSeenAt: typeof parsed.lastSeenAt === "string" ? parsed.lastSeenAt : null,
      items: parseStoreItems(parsed.items),
    };
  } catch {
    return emptyAdminNotificationStore();
  }
}

export function saveAdminNotificationStore(userId: string, state: AdminNotificationStoreState): void {
  if (typeof window === "undefined" || !userId.trim()) return;
  try {
    window.localStorage.setItem(storageKey(userId), JSON.stringify(state));
  } catch {
    /* ignore quota */
  }
  for (const fn of listeners) {
    try {
      fn(userId);
    } catch {
      /* ignore */
    }
  }
}

export function isNotificationUnread(
  state: AdminNotificationStoreState,
  notification: AdminDashboardNotification,
): boolean {
  if (!state.lastSeenAt) return true;
  const seen = new Date(state.lastSeenAt).getTime();
  const created = new Date(notificationCreatedAt(notification)).getTime();
  if (Number.isNaN(seen) || Number.isNaN(created)) return true;
  return created > seen;
}

export function getUnreadCount(state: AdminNotificationStoreState): number {
  return listNotifications(state).filter((item) => isNotificationUnread(state, item)).length;
}

export function listNotifications(state: AdminNotificationStoreState): AdminDashboardNotification[] {
  return Object.values(state.items).sort(
    (a, b) => new Date(notificationCreatedAt(b)).getTime() - new Date(notificationCreatedAt(a)).getTime(),
  );
}

function pruneNotificationStoreItems(state: AdminNotificationStoreState): AdminNotificationStoreState {
  const count = Object.keys(state.items).length;
  if (count <= ADMIN_NOTIFICATION_STORE_MAX_ITEMS) return state;

  const dropCount = count - ADMIN_NOTIFICATION_STORE_MAX_ITEMS;
  const oldestFirst = [...listNotifications(state)].sort(
    (a, b) => new Date(notificationCreatedAt(a)).getTime() - new Date(notificationCreatedAt(b)).getTime(),
  );
  const items = { ...state.items };
  let dropped = 0;

  for (const notification of oldestFirst) {
    if (dropped >= dropCount) break;
    if (isNotificationUnread(state, notification)) continue;
    delete items[notificationStoreKey(notification)];
    dropped++;
  }

  if (dropped < dropCount) {
    for (const notification of oldestFirst) {
      if (dropped >= dropCount) break;
      const key = notificationStoreKey(notification);
      if (!items[key]) continue;
      delete items[key];
      dropped++;
    }
  }

  return { ...state, items };
}

/** Garantisce che un nuovo inserimento risulti non letto anche se createdAt coincide con lastSeenAt (stesso ms). */
function withCreatedAtAfterLastSeen(
  state: AdminNotificationStoreState,
  notification: AdminDashboardNotification,
): AdminDashboardNotification {
  if (!state.lastSeenAt) return notification;
  const seen = new Date(state.lastSeenAt).getTime();
  const created = new Date(notificationCreatedAt(notification)).getTime();
  if (Number.isNaN(seen) || Number.isNaN(created) || created > seen) return notification;
  const bumped = new Date(seen + 1).toISOString();
  return { ...notification, createdAt: bumped };
}

export function upsertAdminNotification(
  userId: string,
  notification: AdminDashboardNotification,
): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const key = notificationStoreKey(notification);
  if (state.items[key]) return state;
  const item = withCreatedAtAfterLastSeen(state, notification);
  const next: AdminNotificationStoreState = {
    ...state,
    items: { ...state.items, [key]: item },
  };
  const pruned = pruneNotificationStoreItems(next);
  saveAdminNotificationStore(userId, pruned);
  return pruned;
}

export function markAllAdminNotificationsRead(userId: string): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const next: AdminNotificationStoreState = {
    ...state,
    lastSeenAt: new Date().toISOString(),
  };
  saveAdminNotificationStore(userId, next);
  return next;
}

/** Segna letta una singola notifica (avanza lastSeenAt fino al suo createdAt). */
export function markAdminNotificationRead(
  userId: string,
  notification: AdminDashboardNotification,
): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  if (!isNotificationUnread(state, notification)) return state;
  const createdMs = new Date(notificationCreatedAt(notification)).getTime();
  if (Number.isNaN(createdMs)) return state;
  const seenMs = state.lastSeenAt ? new Date(state.lastSeenAt).getTime() : 0;
  const nextSeenMs = Math.max(Number.isNaN(seenMs) ? 0 : seenMs, createdMs);
  const next: AdminNotificationStoreState = {
    ...state,
    lastSeenAt: new Date(nextSeenMs).toISOString(),
  };
  saveAdminNotificationStore(userId, next);
  return next;
}

export function removeAdminNotification(
  userId: string,
  notification: AdminDashboardNotification,
): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const key = notificationStoreKey(notification);
  if (!state.items[key]) return state;
  const items = { ...state.items };
  delete items[key];
  const next: AdminNotificationStoreState = { ...state, items };
  saveAdminNotificationStore(userId, next);
  return next;
}

export function removeReadAdminNotifications(userId: string): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const items: Record<string, AdminDashboardNotification> = {};
  for (const [key, item] of Object.entries(state.items)) {
    if (isNotificationUnread(state, item)) {
      items[key] = item;
    }
  }
  const next: AdminNotificationStoreState = { ...state, items };
  saveAdminNotificationStore(userId, next);
  return next;
}

export function countReadAdminNotifications(state: AdminNotificationStoreState): number {
  return listNotifications(state).filter((item) => !isNotificationUnread(state, item)).length;
}

export function clearMagazzinoNotifications(userId: string): AdminNotificationStoreState {
  const state = loadAdminNotificationStore(userId);
  const items: Record<string, AdminDashboardNotification> = {};
  for (const [key, item] of Object.entries(state.items)) {
    if (item.kind !== "magazzino_sotto_scorta") items[key] = item;
  }
  const next: AdminNotificationStoreState = { ...state, items };
  saveAdminNotificationStore(userId, next);
  return next;
}

export function subscribeAdminNotificationStore(listener: StoreListener): () => void {
  listeners.add(listener);
  ensureStorageBridgeListener();
  return () => listeners.delete(listener);
}

