  riskLevel: "LOW" | "MEDIUM" | "HIGH";
  productionReadiness: "YES" | "NO" | "CONDITIONAL";
  categories: Record<CompatReadinessCategory, number>;
  topRisks: CompatReadinessRisk[];
  nonConformPages: string[];
  mustFix: string[];
  shouldFix: string[];
  niceToHave: string[];
  scan: CompatSsotScanResult;
  checkedAt: string;
};

