  ssotConsistency: 0.2,
  dataIntegrity: 0.15,
  renameSafety: 0.1,
  crossPageCoherence: 0.15,
  searchReliability: 0.1,
  cacheCorrectness: 0.15,
  runtimeStability: 0.1,
  legacyElimination: 0.05,
};

