  | { ruolo?: string | null; roleKey?: string | null; id?: string | null }
  | string
  | null
  | undefined;

function rawRoleKey(user: RbacUserInput): string | null {
  if (user == null) return null;
  if (typeof user === "string") return user;
  return user.roleKey ?? user.ruolo ?? null;
}

