  monthRangeFromKey,
  startOfLocalDay,
  weekRangeFromYmd,
  ymdFromDate,
  type DateRange,
} from "@/lib/report/date-ranges";
import { buildKpiPerformanceModel } from "@/lib/report/kpi-performance/build-kpi-performance-model";
