import { SCHEDA_LAVORAZIONE_COLUMNS } from "@/lib/db/table-select-columns";
import { schedaRowsToBundle, schedaRowsToStore } from "@/lib/schede/schede-db-mapper";
import type { LavorazioneSchedeBundle, LavorazioneSchedeStore } from "@/types/schede";
import type { SchedaLavorazioneRow } from "@/src/types/supabase-tables";
import { err, success, type ServiceResult } from "@/src/services/service-result";
import type { SupabaseClient } from "@supabase/supabase-js";

/** Max UUID per singola query `.in()` — evita URL troppo lunghi. */
export const SCHEde_BATCH_IN_CHUNK = 80;

function uniqueIds(lavorazioneIds: readonly string[]): string[] {
  return [...new Set(lavorazioneIds.map((id) => id.trim()).filter(Boolean))];
}

/** Fetch batch righe schede — 1 query Supabase per chunk (sostituisce N× getAll per id). */
export async function fetchSchedeRowsByLavorazioneIds(
  sb: SupabaseClient,
  lavorazioneIds: readonly string[],
): Promise<ServiceResult<SchedaLavorazioneRow[]>> {
  const ids = uniqueIds(lavorazioneIds);
  if (ids.length === 0) return success([]);

  const allRows: SchedaLavorazioneRow[] = [];
  for (let i = 0; i < ids.length; i += SCHEde_BATCH_IN_CHUNK) {
    const chunk = ids.slice(i, i + SCHEde_BATCH_IN_CHUNK);
    const { data, error } = await sb
      .from("scheda_lavorazione")
      .select(SCHEDA_LAVORAZIONE_COLUMNS)
      .in("lavorazione_id", chunk);
    if (error) return err(error.message);
    allRows.push(...((data ?? []) as SchedaLavorazioneRow[]));
  }
  return success(allRows);
}

/** Righe → store bundle per-id (nessun IO). */
export function schedeRowsToBundlesStore(
  rows: readonly SchedaLavorazioneRow[],
  requestedIds: readonly string[],
): LavorazioneSchedeStore {
  const fullStore = schedaRowsToStore(rows);
  const ids = uniqueIds(requestedIds);
  const store: LavorazioneSchedeStore = {};
  for (const id of ids) {
    if (fullStore[id]) store[id] = fullStore[id];
  }
  return store;
}

/** Batch fetch → `LavorazioneSchedeStore` (1–⌈N/80⌉ query). */
export async function fetchSchedeBundlesStore(
  sb: SupabaseClient,
  lavorazioneIds: readonly string[],
  codiciByLavorazioneId?: Readonly<Record<string, string | null | undefined>>,
): Promise<ServiceResult<LavorazioneSchedeStore>> {
  const ids = uniqueIds(lavorazioneIds);
  if (ids.length === 0) return success({});

  const rowsRes = await fetchSchedeRowsByLavorazioneIds(sb, ids);
  if (!rowsRes.success) return err(rowsRes.error ?? "Lettura schede non riuscita.");

  const byLav = new Map<string, SchedaLavorazioneRow[]>();
  for (const row of rowsRes.data ?? []) {
    const list = byLav.get(row.lavorazione_id) ?? [];
    list.push(row);
    byLav.set(row.lavorazione_id, list);
  }

  const store: LavorazioneSchedeStore = {};
  for (const id of ids) {
    const list = byLav.get(id) ?? [];
    const codice = codiciByLavorazioneId?.[id];
    store[id] = schedaRowsToBundle(id, list, codice);
  }
  return success(store);
}

import type { LavorazioneSchedeBundle, LavorazioneSchedeStore } from "@/types/schede";
import type { SchedaLavorazioneRow, TipoSchedaLavorazione } from "@/src/types/supabase-tables";
import type { SchedaInsert, SchedaUpdate } from "@/src/services/schede.service";
import {
  bundleKeyToDbTipo,
  dbTipoToBundleKey,
  normalizeSchedaTipoDb,
  type SchedaBundleKey,
} from "@/lib/schede/scheda-tipo-db-mapper";

function rowToDoc(row: SchedaLavorazioneRow): unknown {
  const c = row.contenuto ?? {};
  if (c && typeof c === "object" && "doc" in (c as object)) {
    return (c as { doc: unknown }).doc;
  }
  return c;
}

/** Calcola revision hint da max(updated_at) righe DB. */
export function computeBundleRevision(rows: readonly SchedaLavorazioneRow[]): string | undefined {
  let maxTs = "";
  for (const row of rows) {
    const ts = row.updated_at?.trim() ?? "";
    if (ts && ts > maxTs) maxTs = ts;
  }
  return maxTs || undefined;
}

export function schedaRowsToBundle(
  lavorazioneId: string,
  rows: readonly SchedaLavorazioneRow[],
  codice?: string | null,
): LavorazioneSchedeBundle {
  const bundle: LavorazioneSchedeBundle = {
    lavorazioneId,
    codice: codice?.trim() || null,
    ingresso: null,
    lavorazioni: null,
    ricambi: null,
    _revision: computeBundleRevision(rows),
    _fetchedAt: Date.now(),
  };
  for (const row of rows) {
    const bundleKey = dbTipoToBundleKey(row.tipo);
    if (!bundleKey) continue;
    const doc = rowToDoc(row);
    if (bundleKey === "ingresso") bundle.ingresso = doc as LavorazioneSchedeBundle["ingresso"];
    if (bundleKey === "lavorazioni") bundle.lavorazioni = doc as LavorazioneSchedeBundle["lavorazioni"];
    if (bundleKey === "ricambi") bundle.ricambi = doc as LavorazioneSchedeBundle["ricambi"];
  }
  return bundle;
}

export function schedaRowsToStore(rows: readonly SchedaLavorazioneRow[]): LavorazioneSchedeStore {
  const byLav = new Map<string, SchedaLavorazioneRow[]>();
  for (const row of rows) {
    const list = byLav.get(row.lavorazione_id) ?? [];
    list.push(row);
    byLav.set(row.lavorazione_id, list);
  }
  const store: LavorazioneSchedeStore = {};
  for (const [lavId, list] of byLav) {
    store[lavId] = schedaRowsToBundle(lavId, list);
  }
  return store;
}

export function bundleToSchedaPayloads(bundle: LavorazioneSchedeBundle): {
  tipo: TipoSchedaLavorazione;
  contenuto: Record<string, unknown>;
  rowId?: string;
}[] {
  const out: { tipo: TipoSchedaLavorazione; contenuto: Record<string, unknown>; rowId?: string }[] = [];
  const pairs: [SchedaBundleKey, unknown][] = [
    ["ingresso", bundle.ingresso],
    ["lavorazioni", bundle.lavorazioni],
    ["ricambi", bundle.ricambi],
  ];
  for (const [key, doc] of pairs) {
    if (!doc) continue;
    const meta = doc as { id?: string };
    out.push({
      tipo: bundleKeyToDbTipo(key),
      contenuto: { doc, bundleKey: key },
      rowId: typeof meta.id === "string" && meta.id.length > 10 ? meta.id : undefined,
    });
  }
  return out;
}

export function schedaInsertFromBundlePart(
  lavorazioneId: string,
  tipo: TipoSchedaLavorazione,
  contenuto: Record<string, unknown>,
): SchedaInsert {
  return { lavorazione_id: lavorazioneId, tipo, contenuto };
}

export function schedaUpdateFromContenuto(contenuto: Record<string, unknown>): SchedaUpdate {
  return { contenuto };
}

export function mergeSchedeStores(
  local: LavorazioneSchedeStore,
  remote: LavorazioneSchedeStore,
  dbPrimary: boolean,
): LavorazioneSchedeStore {
  const keys = new Set([...Object.keys(local), ...Object.keys(remote)]);
  const out: LavorazioneSchedeStore = {};
  for (const id of keys) {
    const l = local[id];
    const r = remote[id];
    if (!l && r) out[id] = r;
    else if (l && !r) out[id] = l;
    else if (l && r) out[id] = dbPrimary ? r : l;
  }
  return out;
}

