"use client";

/**
 * UI OS Backward Adapter — Phase 2 gated opt-in wrapper.
 *
 * Stable UIRenderer tree for opt-in pages (no remount on gate flip).
 * `primary` controls OS activation metadata; shells use `display: contents`.
 */

import { useEffect, useMemo, useState, type ReactNode } from "react";
import { getPageUIMode } from "@/lib/ui-os/ui-os-engine";
import { UiOsErrorBoundary } from "@/lib/ui-os/ui-os-error-boundary";
import { UIRenderer, type UIRendererSlots } from "@/lib/ui-os/ui-renderer";
import {
  runUIOsValidationPipeline,
  type UIOsRenderDecision,
} from "@/lib/ui-os/ui-render-decision";
import { getSuggestedSchema, type UIPageMode, type UIPageSchema } from "@/lib/ui-os/ui-schema";
import { useUIOsPhase2 } from "@/lib/ui-os/use-ui-os-phase2";

export type UIPageFallbackMode = "legacy";

export type UIPageAdapterProps = {
  page?: string;
  /** @deprecated Use `page`. */
  pageId?: string;
  schema?: UIPageSchema;
  mode?: UIPageMode;
  fallback?: UIPageFallbackMode;
  slots?: UIRendererSlots;
  children: ReactNode;
};

function resolvePageId(props: UIPageAdapterProps): string {
  return props.page ?? props.pageId ?? "/";
}

function isOsEligible(pageId: string, mode: UIPageMode, schema: UIPageSchema | undefined): boolean {
  if (process.env.NEXT_PUBLIC_CAB_UI_OS !== "1") return false;
  if (mode !== "os") return false;
  if (getPageUIMode(pageId) !== "os") return false;
  if (!schema) return false;
  return true;
}

export function UIPageAdapter(props: UIPageAdapterProps) {
  const { schema: schemaProp, mode: modeProp, slots, children } = props;
  const pageId = resolvePageId(props);
  const effectiveMode = modeProp ?? getPageUIMode(pageId);

  const schema = useMemo(
    () => schemaProp ?? getSuggestedSchema(pageId),
    [schemaProp, pageId],
  );

  const [decision, setDecision] = useState<UIOsRenderDecision | null>(null);
  const eligible = isOsEligible(pageId, effectiveMode, schema);

  useEffect(() => {
    if (!eligible) {
      setDecision(null);
      return;
    }

    function evaluate() {
      const main = typeof document !== "undefined" ? document.querySelector(".cab-app-shell main") : null;
      setDecision(runUIOsValidationPipeline(pageId, schema, main, effectiveMode));
    }

    evaluate();
    const timer = setTimeout(evaluate, 450);
    return () => clearTimeout(timer);
  }, [eligible, pageId, schema, effectiveMode]);

  useUIOsPhase2(pageId, schema, effectiveMode, [decision?.driftScore, decision?.primary]);

  if (!eligible) {
    return <>{children}</>;
  }

  const primary = decision?.primary ?? "legacy";

  return (
    <UiOsErrorBoundary pageId={pageId} fallback={children}>
      <UIRenderer
        schema={schema}
        pageId={pageId}
        primary={primary}
        slots={{ ...slots, children: slots?.children ?? children }}
      />
    </UiOsErrorBoundary>
  );
}

/**
 * UI OS Phase 2 — render decision pipeline + drift gating.
 */

import { validateFlexSystemPolicy } from "@/lib/ui/flex-system-policy";
import {
  buildShadowReport,
  detectUIContractViolations,
  getPageUIMode,
  validateUISchema,
  type UIOsShadowReport,
} from "@/lib/ui-os/ui-os-engine";
import { schemaMatchScore } from "@/lib/ui-os/ui-migration-layer";
import type { UIPageMode, UIPageSchema } from "@/lib/ui-os/ui-schema";

export { validateFlexSystemPolicy, validateFlexSafety } from "@/lib/ui/flex-system-policy";

export const DRIFT_ALLOW_THRESHOLD = 20;
export const DRIFT_BLOCK_THRESHOLD = 40;

export const UI_OS_PHASE2_LOG_PREFIX = "[ui-os-phase-2]";
export const UI_OS_FALLBACK_LOG_PREFIX = "[ui-os-fallback]";

export type UIOsFallbackReason =
  | "env_disabled"
  | "not_opt_in"
  | "mode_legacy"
  | "missing_schema"
  | "invalid_schema"
  | "contract_violation"
  | "flex_unsafe"
  | "drift_blocked"
  | "drift_high"
  | null;

export type UIOsRenderPrimary = "legacy" | "os";

export type UIOsRenderDecision = {
  primary: UIOsRenderPrimary;
  osAllowed: boolean;
  osBlocked: boolean;
  fallbackReason: UIOsFallbackReason;
  schemaMatchScore: number;
  driftScore: number;
  layoutScore: number;
  contractViolations: number;
  shadowReport: UIOsShadowReport;
  pipelineErrors: string[];
};

export function evaluateRenderDecision(input: {
  pageId: string;
  schema: UIPageSchema | undefined;
  mode?: UIPageMode;
  root?: Element | null;
}): UIOsRenderDecision {
  const { pageId, schema, mode, root = null } = input;
  const effectiveMode = mode ?? getPageUIMode(pageId);
  const suggestedSchema = schema ?? { toolbar: "legacy", table: "legacy", layout: "legacy" };
  const shadowReport = buildShadowReport(pageId, root ?? null);
  const matchScore = schemaMatchScore(shadowReport.detectedSchema, shadowReport.suggestedSchema);
  const pipelineErrors: string[] = [];

  const base: UIOsRenderDecision = {
    primary: "legacy",
    osAllowed: false,
    osBlocked: false,
    fallbackReason: null,
    schemaMatchScore: matchScore,
    driftScore: shadowReport.driftScore,
    layoutScore: shadowReport.layoutScore,
    contractViolations: shadowReport.contractViolations,
    shadowReport,
    pipelineErrors,
  };

  if (process.env.NEXT_PUBLIC_CAB_UI_OS !== "1") {
    return { ...base, fallbackReason: "env_disabled" };
  }

  if (effectiveMode !== "os") {
    return { ...base, fallbackReason: effectiveMode === "legacy" ? "mode_legacy" : "not_opt_in" };
  }

  if (getPageUIMode(pageId) !== "os") {
    return { ...base, fallbackReason: "not_opt_in" };
  }

  if (!schema) {
    return { ...base, fallbackReason: "missing_schema" };
  }

  const schemaValidation = validateUISchema(schema);
  if (!schemaValidation.valid) {
    pipelineErrors.push(...schemaValidation.errors);
    return { ...base, fallbackReason: "invalid_schema", pipelineErrors };
  }

  const contractIssues = detectUIContractViolations(schema);
  if (contractIssues.length > 0) {
    pipelineErrors.push(...contractIssues);
    return { ...base, fallbackReason: "contract_violation", pipelineErrors };
  }

  const flexCheck = validateFlexSystemPolicy(schema);
  if (!flexCheck.safe) {
    pipelineErrors.push(...flexCheck.errors);
    return { ...base, fallbackReason: "flex_unsafe", pipelineErrors };
  }

  // Flex gate precede drift — driftScore non può bypassare flex containment.

  if (shadowReport.driftScore > DRIFT_BLOCK_THRESHOLD) {
    return {
      ...base,
      osBlocked: true,
      fallbackReason: "drift_blocked",
    };
  }

  if (shadowReport.driftScore > DRIFT_ALLOW_THRESHOLD) {
    return { ...base, fallbackReason: "drift_high" };
  }

  return {
    ...base,
    primary: "os",
    osAllowed: true,
    fallbackReason: null,
  };
}

/** Full validation pipeline — schema → contract → flex → drift gating. */
export function runUIOsValidationPipeline(
  pageId: string,
  schema: UIPageSchema | undefined,
  root?: Element | null,
  mode?: UIPageMode,
): UIOsRenderDecision {
  return evaluateRenderDecision({ pageId, schema, mode, root });
}

export function layoutDriftLevel(driftScore: number): "LOW" | "MEDIUM" | "HIGH" {
  if (driftScore <= DRIFT_ALLOW_THRESHOLD) return "LOW";
  if (driftScore <= DRIFT_BLOCK_THRESHOLD) return "MEDIUM";
  return "HIGH";
}

