import { useMemo } from "react";
import { computeDayCapacity, DEFAULT_DAY_BOUNDS, type DayBounds } from "@/lib/workshop-schedule/day-capacity";
import { ymdFromIso } from "@/lib/workshop-schedule/datetime";
import { buildGanttRowsByWorkOrder } from "@/lib/workshop-schedule/intelligence/gantt/gantt-row-by-workorder";
import { buildGanttTimeAxis } from "@/lib/workshop-schedule/intelligence/gantt/gantt-time-axis";
import { computeHeatmapCells, heatmapMemoKey } from "@/lib/workshop-schedule/intelligence/heatmap/compute-heatmap";
import { planAutoSchedule } from "@/lib/workshop-schedule/intelligence/auto-scheduler/plan-auto-schedule";
import type { AutoScheduleInput } from "@/lib/workshop-schedule/intelligence/auto-scheduler/types";
import { computePlannerInsights, insightsMemoKey } from "@/lib/workshop-schedule/intelligence/insights/compute-planner-insights";
import {
  computeWeeklyLoad,
  sessionsFingerprint,
  weeklyLoadMemoKey,
} from "@/lib/workshop-schedule/intelligence/weekly-load/compute-weekly-load";
import type { WorkshopScheduleSessionView } from "@/lib/workshop-schedule/types";

export type WorkshopIntelligenceInput = {
  sessions: readonly WorkshopScheduleSessionView[];
  rangeStartYmd: string;
  rangeEndYmd: string;
  weekStartYmd: string;
  heatmapDates: readonly string[];
  bounds?: DayBounds;
  invalidationKey: string;
};

function addDaysYmd(ymd: string, days: number): string {
  const d = new Date(`${ymd}T12:00:00`);
  d.setDate(d.getDate() + days);
  return ymdFromIso(d.toISOString());
}

export function useWorkshopScheduleIntelligence(input: WorkshopIntelligenceInput) {
  const bounds = input.bounds ?? DEFAULT_DAY_BOUNDS;
  const fingerprint = sessionsFingerprint([...input.sessions]);
  const memoKey = `${input.invalidationKey}|${fingerprint}`;

  const gantt = useMemo(() => {
    const axis = buildGanttTimeAxis(input.rangeStartYmd, input.rangeEndYmd, bounds);
    const rows = buildGanttRowsByWorkOrder(input.sessions);
    return { axis, rows };
  }, [input.sessions, input.rangeStartYmd, input.rangeEndYmd, bounds]);

  const heatmap = useMemo(() => {
    const key = heatmapMemoKey(input.heatmapDates, bounds);
    void key;
    return computeHeatmapCells(input.sessions, input.heatmapDates, bounds);
  }, [input.sessions, input.heatmapDates, bounds, memoKey]);

  const weeklyLoad = useMemo(() => {
    const cacheKey = weeklyLoadMemoKey(input.weekStartYmd, fingerprint);
    return computeWeeklyLoad(input.sessions, input.weekStartYmd, bounds, cacheKey);
  }, [input.sessions, input.weekStartYmd, bounds, fingerprint, memoKey]);

  const insights = useMemo(() => {
    const dates =
      input.heatmapDates.length > 0
        ? [...input.heatmapDates]
        : Array.from({ length: 7 }, (_, i) => addDaysYmd(input.weekStartYmd, i));
    const key = insightsMemoKey(fingerprint, `${bounds.startHour}-${bounds.endHour}`);
    void key;
    return computePlannerInsights(input.sessions, dates, bounds);
  }, [input.sessions, input.heatmapDates, input.weekStartYmd, bounds, fingerprint, memoKey]);

  const planAutoScheduleFor = useMemo(
    () => (autoInput: Omit<AutoScheduleInput, "existingSessions" | "dayCapacityByYmd">) => {
      const dayCapacityByYmd = new Map(
        autoInput.searchDaysYmd.map((d) => [
          d,
          computeDayCapacity(
            d,
            input.sessions.filter((s) => ymdFromIso(s.startAt) === d || ymdFromIso(s.endAt) === d),
            bounds,
          ),
        ]),
      );
      return planAutoSchedule({
        ...autoInput,
        existingSessions: input.sessions,
        dayCapacityByYmd,
        bounds,
      });
    },
    [input.sessions, bounds],
  );

  return { gantt, heatmap, weeklyLoad, insights, planAutoScheduleFor };
}

/**
 * Monitora `next dev`: CPU Node, restart (lock pid), churn .next, errori stdout.
 * Uso: `npm run dev:cpu-probe` (avvia next dev e monitora ~45s).
 */
import { spawn, type ChildProcess } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const ROOT = path.dirname(path.dirname(fileURLToPath(import.meta.url)));
const LOG_PATH = path.join(ROOT, "dev-probe.log");
const MONITOR_MS = Number(process.env.DEV_CPU_PROBE_MS ?? 45_000);
const SAMPLE_MS = 2_000;

type ProbeEvent = {
  runId: string;
  location: string;
  message: string;
  data: Record<string, unknown>;
  timestamp: number;
};

function emit(p: Omit<ProbeEvent, "timestamp">): void {
  const line: ProbeEvent = { ...p, timestamp: Date.now() };
  try {
    fs.appendFileSync(LOG_PATH, `${JSON.stringify(line)}\n`);
  } catch {
    /* ignore */
  }
}

function readLockPid(): number | null {
  const lockPath = path.join(ROOT, ".next", "dev", "lock");
  if (!fs.existsSync(lockPath)) return null;
  try {
    const lock = JSON.parse(fs.readFileSync(lockPath, "utf8")) as { pid?: number };
    return lock.pid ?? null;
  } catch {
    return null;
  }
}

function sampleNodeCpuWindows(): Promise<number | null> {
  return new Promise((resolve) => {
    const ps = spawn(
      "powershell",
      [
        "-NoProfile",
        "-Command",
        "(Get-Process node -EA SilentlyContinue | Measure-Object -Property CPU -Sum).Sum",
      ],
      { windowsHide: true },
    );
    let out = "";
    ps.stdout.on("data", (c) => {
      out += String(c);
    });
    ps.on("close", () => {
      const n = parseFloat(out.trim());
      resolve(Number.isFinite(n) ? n : null);
    });
    ps.on("error", () => resolve(null));
  });
}

async function main(): Promise<void> {
  emit({
    runId: "cpu-crash",
    location: "dev-cpu-crash-probe.ts:start",
    message: "probe start",
    data: {
      hasNextDev: fs.existsSync(path.join(ROOT, ".next", "dev")),
      lockPidBefore: readLockPid(),
      bundler: process.argv.includes("--webpack") ? "webpack" : "turbopack",
    },
  });

  const useWebpack = process.argv.includes("--webpack");
  const child: ChildProcess = spawn(
    "npx",
    useWebpack ? ["next", "dev", "--webpack"] : ["next", "dev"],
    {
    cwd: ROOT,
    shell: true,
    env: { ...process.env },
  });

  let readyCount = 0;
  let compileCount = 0;
  let firstReadyAt: number | null = null;
  let errorLines: string[] = [];
  const stdoutBuf: string[] = [];

  const onChunk = (chunk: Buffer, stream: "stdout" | "stderr"): void => {
    const text = chunk.toString();
    stdoutBuf.push(`[${stream}] ${text}`);
    if (stdoutBuf.length > 80) stdoutBuf.shift();
    for (const line of text.split(/\r?\n/)) {
      if (/Ready in/i.test(line)) {
        readyCount += 1;
        if (firstReadyAt == null) firstReadyAt = Date.now();
      }
      if (/Compiling/i.test(line)) compileCount += 1;
      if (
        /NextSegmentConfig|os error 3|SST|panic|FATAL|crash|ENOMEM|EADDRINUSE/i.test(
          line,
        )
      ) {
        errorLines.push(line.slice(0, 300));
        if (errorLines.length > 20) errorLines.shift();
      }
    }
  };

  child.stdout?.on("data", (c) => onChunk(c as Buffer, "stdout"));
  child.stderr?.on("data", (c) => onChunk(c as Buffer, "stderr"));

  child.on("exit", (code, signal) => {
    emit({
      runId: "cpu-crash",
      location: "dev-cpu-crash-probe.ts:exit",
      message: "next dev process exited",
      data: { code, signal, readyCount, compileCount, errorLines },
    });
  });

  const cpuSamples: { t: number; cpuSum: number | null; lockPid: number | null }[] =
    [];
  let lockPidChanges = 0;
  let lastPid: number | null = readLockPid();
  let nextEvents = 0;
  let nextEventsAfterReady = 0;

  const nextDir = path.join(ROOT, ".next");
  const watcher = fs.existsSync(nextDir)
    ? fs.watch(nextDir, { recursive: true }, () => {
        nextEvents += 1;
        if (firstReadyAt != null) nextEventsAfterReady += 1;
      })
    : null;

  const start = Date.now();
  while (Date.now() - start < MONITOR_MS) {
    await new Promise((r) => setTimeout(r, SAMPLE_MS));
    const cpu = await sampleNodeCpuWindows();
    const lockPid = readLockPid();
    if (lockPid !== lastPid) {
      lockPidChanges += 1;
      lastPid = lockPid;
    }
    cpuSamples.push({ t: Date.now() - start, cpuSum: cpu, lockPid });
  }

  watcher?.close();
  child.kill("SIGTERM");

  const cpus = cpuSamples
    .map((s) => s.cpuSum)
    .filter((v): v is number => v != null);
  const delta =
    cpus.length >= 2 ? (cpus[cpus.length - 1] ?? 0) - (cpus[0] ?? 0) : null;

  emit({
    runId: "cpu-crash",
    location: "dev-cpu-crash-probe.ts:compile",
    message: "stdout compile/ready pattern",
    data: {
      readyCount,
      compileCount,
      readyRestartLoop: readyCount > 2,
      compileStorm: compileCount > 15,
      errorLines,
      tail: stdoutBuf.slice(-8),
    },
  });

  emit({
    runId: "cpu-crash",
    location: "dev-cpu-crash-probe.ts:cpu",
    message: "node cpu samples",
    data: {
      sampleCount: cpuSamples.length,
      lockPidChanges,
      nextEventsInWindow: nextEvents,
      nextEventsAfterReady,
      postReadyChurnPerSec:
        firstReadyAt != null
          ? Math.round(
              (nextEventsAfterReady /
                Math.max(1, (Date.now() - firstReadyAt) / 1000)) *
                10,
            ) / 10
          : null,
      cpuDeltaSeconds: delta,
      lastLockPid: lastPid,
      childExited: child.exitCode != null,
      childExitCode: child.exitCode,
    },
  });

  console.log("[dev:cpu-probe] Done → dev-probe.log");
}

void main();

/**
 * Import MAP telemetry snapshot from exported browser JSON.
 *
 * In dev, copy window.__FORM_UX_MIGRATION__ from the browser console, save as
 * map/telemetry-export.json, then run:
 *   npx tsx scripts/form-ux-map-export-telemetry.ts map/telemetry-export.json
 *
 * Or pipe JSON via stdin:
 *   type map\\telemetry-export.json | npx tsx scripts/form-ux-map-export-telemetry.ts
 */
import fs from "node:fs";
import path from "node:path";
import {
  writeTelemetrySnapshot,
  type MapTelemetryDailySnapshot,
  type MapTelemetryFieldSnapshot,
} from "@/lib/form-ux-migration/form-ux-map-telemetry-store";

type BrowserExport = {
  events?: { formId?: string; fieldId?: string; mismatch?: unknown }[];
  mismatchRateByField?: Record<string, number>;
  enforcementRollbacks?: number;
  mismatchCount?: number;
};

function readInput(fileArg?: string): string {
  if (fileArg && fs.existsSync(fileArg)) {
    return fs.readFileSync(fileArg, "utf8");
  }
  return fs.readFileSync(0, "utf8");
}

const inputPath = process.argv[2];
const raw = readInput(inputPath);
const parsed = JSON.parse(raw) as BrowserExport;

const fieldMap = new Map<string, MapTelemetryFieldSnapshot>();

for (const [fieldKey, rate] of Object.entries(parsed.mismatchRateByField ?? {})) {
  fieldMap.set(fieldKey, {
    fieldKey,
    evaluations: 100,
    mismatches: Math.round(rate * 100),
    mismatchRate: rate,
    rollbacks: 0,
    submitDivergences: 0,
  });
}

for (const event of parsed.events ?? []) {
  if (!event.formId || !event.fieldId) continue;
  const fieldKey = `${event.formId}.${event.fieldId}`;
  const existing = fieldMap.get(fieldKey) ?? {
    fieldKey,
    evaluations: 0,
    mismatches: 0,
    mismatchRate: 0,
    rollbacks: 0,
    submitDivergences: 0,
  };
  existing.evaluations += 1;
  if (event.mismatch != null) existing.mismatches += 1;
  existing.mismatchRate =
    existing.evaluations > 0 ? existing.mismatches / existing.evaluations : 0;
  fieldMap.set(fieldKey, existing);
}

const totalEvaluations = [...fieldMap.values()].reduce((s, f) => s + f.evaluations, 0);
const totalMismatches = [...fieldMap.values()].reduce((s, f) => s + f.mismatches, 0);

const snapshot: MapTelemetryDailySnapshot = {
  date: new Date().toISOString().slice(0, 10),
  exportedAt: new Date().toISOString(),
  globalMismatchRate: totalEvaluations > 0 ? totalMismatches / totalEvaluations : 0,
  globalRollbackRate:
    totalEvaluations > 0 ? (parsed.enforcementRollbacks ?? 0) / totalEvaluations : 0,
  fields: [...fieldMap.values()],
};

const out = writeTelemetrySnapshot(snapshot);
console.log(`MAP telemetry snapshot written: ${out}`);
console.log(`Fields: ${snapshot.fields.length}`);

/**
 * Generate lib/ui/ui-final-stability-manifest.json — frozen UI stability scores.
 * Usage: npx tsx scripts/generate-ui-final-stability-manifest.ts [--update]
 *
 * Update requires UI_FINAL_STABILITY_APPROVED=1
 */
import fs from "node:fs";
import path from "node:path";
import {
  buildUiFinalStabilityManifest,
  isUiFinalStabilityUpdateApproved,
  UI_FINAL_STABILITY_MANIFEST_PATH,
  UI_FINAL_STABILITY_UPDATE_ENV,
  verifyUiFinalStabilityManifest,
  type UiFinalStabilityManifest,
} from "@/lib/ui/ui-final-stability-manifest";
import { FLEX_SYSTEM_ABSOLUTE_FINAL_STATE } from "@/lib/ui/flex-system-freeze";

const ROOT = process.cwd();
const MANIFEST_PATH = path.join(ROOT, UI_FINAL_STABILITY_MANIFEST_PATH);

function main(): void {
  if (!FLEX_SYSTEM_ABSOLUTE_FINAL_STATE) {
    console.error("generate-ui-final-stability-manifest: FLEX_SYSTEM_ABSOLUTE_FINAL_STATE must be true");
    process.exit(1);
  }

  const update = process.argv.includes("--update");
  const live = buildUiFinalStabilityManifest();

  if (update || !fs.existsSync(MANIFEST_PATH)) {
    if (update && !isUiFinalStabilityUpdateApproved()) {
      console.error(`Manifest update requires ${UI_FINAL_STABILITY_UPDATE_ENV}=1`);
      process.exit(1);
    }

    const prevVersion = fs.existsSync(MANIFEST_PATH)
      ? (JSON.parse(fs.readFileSync(MANIFEST_PATH, "utf8")) as UiFinalStabilityManifest).version
      : 0;
    const nextVersion = update && prevVersion > 0 ? prevVersion + 1 : 1;
    const payload = buildUiFinalStabilityManifest(undefined, nextVersion);

    fs.writeFileSync(MANIFEST_PATH, `${JSON.stringify(payload, null, 2)}\n`, "utf8");
    console.log(`Wrote ${UI_FINAL_STABILITY_MANIFEST_PATH} (v${nextVersion}, checksum ${payload.checksum.slice(0, 12)}…)`);
    return;
  }

  const manifest = JSON.parse(fs.readFileSync(MANIFEST_PATH, "utf8")) as UiFinalStabilityManifest;
  const verification = verifyUiFinalStabilityManifest(manifest);
  if (!verification.valid) {
    console.error("ui-final-stability-manifest drift detected:");
    for (const e of verification.errors) console.error(`  ${e}`);
    process.exit(1);
  }

  console.log(`ui-final-stability-manifest OK (v${manifest.version})`);
}

main();

import { execFileSync } from "node:child_process";
import { join } from "node:path";

/** Load budgets from TypeScript SSOT via export CLI. */
export function loadPerformanceBudgets(cwd = process.cwd()) {
  const raw = execFileSync("npx", ["tsx", "scripts/ops/export-performance-budgets.ts"], {
    cwd,
    encoding: "utf8",
    maxBuffer: 2 * 1024 * 1024,
    shell: true,
  });
  const parsed = JSON.parse(raw);
  return parsed.budgets ?? [];
}

/**
 * Performance snapshot — baseline for regression guard.
 * Usage: node scripts/ops/performance-snapshot.mjs
 */
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";
import { buildExplainQueries } from "./lib/explain-queries.mjs";
import { loadPerformanceBudgets } from "./lib/load-performance-budgets.mjs";
import { runExplainQuery } from "./lib/parseExplain.mjs";
import { runRestBenchmarkSubset } from "./lib/rest-benchmark-subset.mjs";
import { canRunLinkedDb, runSql } from "./lib/runSql.mjs";

const ROOT = process.cwd();
const RESULTS_DIR = join(ROOT, "test-results");
const OUTPUT = join(RESULTS_DIR, "performance-snapshot.json");
const BASELINE = join(RESULTS_DIR, "performance-snapshot-baseline.json");

function loadJson(path) {
  if (!existsSync(path)) return null;
  return JSON.parse(readFileSync(path, "utf8").replace(/^\uFEFF/, ""));
}

function loadPlaywrightHydration() {
  const perfDir = join(ROOT, "e2e", "test-results", "perf-playwright");
  if (!existsSync(perfDir)) return {};
  const out = {};
  for (const file of ["perf-snapshot-admin.json", "perf-snapshot.json"]) {
    const p = join(perfDir, file);
    const data = loadJson(p);
    if (!data?.snapshots) continue;
    for (const s of data.snapshots) {
      if (s.mode !== "cold") continue;
      const route = s.route?.startsWith("/") ? s.route : `/${s.route ?? ""}`;
      out[route] = s.interactiveMs ?? s.domContentLoadedMs ?? s.navigationMs ?? null;
    }
  }
  return out;
}

function loadBundleMetrics() {
  const synthetic = loadJson(join(RESULTS_DIR, "perf-audit-synthetic.json"));
  if (synthetic?.bundleKb) return { firstLoadJsKb: synthetic.bundleKb, routeChunks: synthetic.routeChunks ?? {} };
  return { firstLoadJsKb: null, routeChunks: {} };
}

function loadCacheHitRatio() {
  const counts = loadJson(join(RESULTS_DIR, "cache-fetch-counts.json"));
  if (!Array.isArray(counts) || counts.length === 0) return null;
  const total = counts.reduce((s, r) => s + (r.fetches ?? 0), 0);
  const ssrScopes = counts.filter((r) => {
    const k = String(r.queryKey);
    return k.includes("lavorazioni") || k.includes("mezzi") || k.includes("magazzino");
  });
  const ssrFetches = ssrScopes.reduce((s, r) => s + (r.fetches ?? 0), 0);
  if (total === 0) return 1;
  return Math.round((1 - ssrFetches / total) * 1000) / 1000;
}

async function main() {
  const warnings = [];
  const budgets = loadPerformanceBudgets();
  const hydrationByRoute = loadPlaywrightHydration();
  const bundle = loadBundleMetrics();
  const cacheHitRatio = loadCacheHitRatio();

  const linkedDb = canRunLinkedDb();
  const explainQueries = buildExplainQueries();
  const explainById = Object.fromEntries(explainQueries.map((q) => [q.id, q]));

  let explainSummary = [];
  if (linkedDb) {
    explainSummary = explainQueries.map((q) => {
      const withRls = runExplainQuery(runSql, q, true);
      return {
        id: q.id,
        label: q.label,
        executionTimeMs: withRls.executionTimeMs ?? null,
        seqScan: withRls.seqScan ?? null,
      };
    });
  } else {
    const fallback = loadJson(join(RESULTS_DIR, "slow-query-audit.json"));
    if (fallback?.explainResults) {
      explainSummary = fallback.explainResults;
      warnings.push("EXPLAIN from slow-query-audit.json fallback");
    } else {
      warnings.push("Linked DB unavailable — serverExecutionMs may be null");
    }
  }

  const restBenchmark = await runRestBenchmarkSubset();
  if (!restBenchmark.ok) warnings.push(`REST: ${restBenchmark.error}`);

  const restById = Object.fromEntries((restBenchmark.results ?? []).map((r) => [r.id, r]));

  const routes = budgets.map((budget) => {
    const explain = budget.explainId ? explainSummary.find((e) => e.id === budget.explainId) : null;
    const rest = budget.restProxyId ? restById[budget.restProxyId] : null;
    return {
      route: budget.route,
      label: budget.label,
      payloadKb: rest?.bytesKb ?? null,
      queryCount: budget.maxQueries,
      serverExecutionMs: explain?.executionTimeMs ?? null,
      hydrationMs: hydrationByRoute[budget.route] ?? null,
      clientComputeMs: null,
      bundleKb: bundle.firstLoadJsKb,
      cacheHitRatio,
      budget: {
        maxPayloadKb: budget.maxPayloadKb,
        maxQueries: budget.maxQueries,
        maxServerMs: budget.maxServerMs,
        maxHydrationMs: budget.maxHydrationMs,
        maxClientMs: budget.maxClientMs,
      },
      sources: {
        rest: rest?.id ?? null,
        explain: budget.explainId ?? null,
      },
    };
  });

  const snapshot = {
    generatedAt: new Date().toISOString(),
    linkedDbAvailable: linkedDb,
    warnings,
    routes,
    bundle,
    explainSummary,
    restBenchmark: restBenchmark.results ?? [],
    slowQueryAuditRef: existsSync(join(RESULTS_DIR, "slow-query-audit.json"))
      ? "test-results/slow-query-audit.json"
      : null,
    cacheHitRatio,
  };

  mkdirSync(RESULTS_DIR, { recursive: true });
  writeFileSync(OUTPUT, JSON.stringify(snapshot, null, 2));

  if (!existsSync(BASELINE)) {
    writeFileSync(BASELINE, JSON.stringify({ ...snapshot, isBaseline: true }, null, 2));
    warnings.push("Created performance-snapshot-baseline.json");
  }

  console.log(`performance-snapshot: wrote ${OUTPUT}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});

/**
 * REST benchmark: service role vs admin vs operatore (RLS impact).
 * Usage: node scripts/ops/rest-benchmark-roles.mjs > test-results/rest-benchmark-roles.json
 *
 * Requires .env.local: NEXT_PUBLIC_SUPABASE_URL, NEXT_PUBLIC_SUPABASE_ANON_KEY,
 * SUPABASE_SERVICE_ROLE_KEY, SMOKE_ADMIN_EMAIL/PASSWORD, SMOKE_OPERATOR_EMAIL/PASSWORD
 */
import { createClient } from "@supabase/supabase-js";
import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const LAVORAZIONI_COLUMNS =
  "id, mezzo_id, stato, priorita, data_ingresso, data_uscita, note, created_by, created_at, updated_at, updated_by, archived, archived_at, deleted_at, codice";
