function userRowFrom(
  profile: ProfileRow | undefined,
  authUser?: AuthUserBanFields & {
    id: string;
    email?: string | null;
    created_at?: string;
    last_sign_in_at?: string | null;
  },
): SecurityUserAdminRow {
  const givenName = profile?.nome?.trim() || authUser?.email?.split("@")[0]?.trim() || "Utente";
  const cognome =
    typeof profile?.cognome === "string" && profile.cognome.trim() ? profile.cognome.trim() : null;
  return {
    id: profile?.id ?? authUser?.id ?? "",
    nome: givenName,
    cognome,
    username: profile?.username?.trim() || null,
    email: authUser?.email ?? "",
    ruolo: resolveRole(profile?.role_key),
    clienteRef: normalizeClienteRef(profile?.cliente_ref),
    createdAt: authUser?.created_at ?? profile?.created_at ?? null,
    lastSignInAt: authUser?.last_sign_in_at ?? null,
    accountEnabled: accountEnabledFromAuthUser(authUser),
    bannedUntil: bannedUntilFromAuthUser(authUser),
  };
}
/**
 * Crea utente Auth + profilo (trigger) + permessi pieni se ruolo admin.
 * Richiede sessione admin e `SUPABASE_SERVICE_ROLE_KEY` sul server.
 */
export async function createUserByAdminAction(input: CreateUserByAdminInput): Promise<CreateUserByAdminResult> {
  const nome = input.nome?.trim() ?? "";
  const cognome = input.cognome?.trim() || null;
  const username = normalizeUsername(input.username ?? "");
  const email = input.email?.trim().toLowerCase() ?? "";
  const password = input.password ?? "";
  const ruolo = resolveRole(input.ruolo);
  const clienteRef = normalizeClienteRef(input.clienteRef);

  const validationErr = validateCreateUserInput({ nome, username, email, password, ruolo });
  if (validationErr) return { ok: false, message: validationErr };

  if (!nome) return { ok: false, message: "Il nome è obbligatorio." };
  const usernameErr = usernameFieldError(username);
  if (usernameErr) {
    return { ok: false, message: usernameErr };
  }
  if (!email || !isValidEmail(email)) return { ok: false, message: "Email non valida." };
  if (!RUOLI.includes(ruolo)) return { ok: false, message: "Ruolo non valido." };

  const caller = await assertAdminCaller();
  if (!caller.ok) return { ok: false, message: caller.message };
  const admin = serviceAdmin(caller.url, caller.serviceKey);

  const sbCaller = await createSupabaseServerUserClient();
  const { data: callerProfile, error: callerProfileErr } = await sbCaller
    .from("profiles")
    .select("company_id")
    .eq("id", caller.callerId)
    .maybeSingle();
  if (callerProfileErr) return { ok: false, message: callerProfileErr.message };
  if (!callerProfile?.company_id) {
    return {
      ok: false,
      message: "Impossibile creare utente: tenant admin non configurato. Assegna company_id al profilo admin.",
    };
  }
  const callerCompanyId = callerProfile.company_id;

  let knownClienti: Set<string>;
  try {
    knownClienti = await loadKnownClientiSetFromMezzi(admin);
  } catch (e) {
    return {
      ok: false,
      message: e instanceof Error ? e.message : "Errore caricamento anagrafica clienti.",
    };
  }
  const clienteRefErr = validateClienteAssociationForRole(ruolo, clienteRef, knownClienti);
  if (clienteRefErr) return { ok: false, message: clienteRefErr };

  const { data: usernameTaken } = await admin.from("profiles").select("id").eq("username", username).maybeSingle();
  if (usernameTaken) return { ok: false, message: "Username già utilizzato." };

  const { data: created, error: createErr } = await admin.auth.admin.createUser({
    email,
    password,
    email_confirm: true,
    app_metadata: {
      cab_nome: nome,
      cab_cognome: cognome,
      cab_ruolo: ruolo,
      cab_username: username,
    },
  });

  if (createErr || !created.user) {
    const msg = createErr?.message ?? "Creazione utente non riuscita.";
    return { ok: false, message: msg };
  }

  const userId = created.user.id;

  try {
    if (ruolo === "admin") {
      await seedAdminPermissions(admin, userId);
    }
    await writeSecurityLog(admin, { targetUserId: userId, actorUserId: caller.callerId, nome, role: ruolo, actorName: caller.callerName });
  } catch (e) {
    const detail = e instanceof Error ? e.message : "Errore sconosciuto";
    try {
      await admin.auth.admin.deleteUser(userId);
    } catch {
      /* best effort */
    }
    return {
      ok: false,
      message: `Utente creato ma permessi admin non salvati (${detail}). L'utente è stato annullato.`,
    };
  }

  const { data: row, error: verifyErr } = await admin
    .from("profiles")
    .select("id, nome, role_key, username")
    .eq("id", userId)
    .maybeSingle();
  if (verifyErr || !row) {
    return {
      ok: false,
      message:
        "Utente Auth creato ma il profilo non risulta presente. Verifica trigger `handle_new_user` e migrazioni; potrebbe essere necessario aggiornare il profilo da Supabase Dashboard.",
    };
  }

  if (clienteRef != null || ruolo === "cliente") {
    const { error: clienteErr } = await admin.from("profiles").update({ cliente_ref: clienteRef }).eq("id", userId);
    if (clienteErr) return { ok: false, message: clienteErr.message };
  }

  if (row.username !== username) {
    const { error: usernameErr } = await admin.from("profiles").update({ username }).eq("id", userId);
    if (usernameErr) {
      const msg = usernameErr.message.includes("unique") || usernameErr.message.includes("duplicate")
        ? "Username già utilizzato."
        : usernameErr.message;
      try {
        await admin.auth.admin.deleteUser(userId);
      } catch {
        /* best effort */
      }
      return { ok: false, message: msg };
    }
  }

  const { error: companyErr } = await admin
    .from("profiles")
    .update({ company_id: callerCompanyId })
    .eq("id", userId);
  if (companyErr) {
    try {
      await admin.auth.admin.deleteUser(userId);
    } catch {
      /* best effort */
    }
    return { ok: false, message: companyErr.message };
  }

  return { ok: true, userId };
}

/** Verifica disponibilità username (solo admin sicurezza, case-insensitive). */
export async function checkUsernameAvailabilityAction(input: {
  username: string;
  excludeUserId?: string | null;
}): Promise<CheckUsernameAvailabilityResult> {
  const username = normalizeUsername(input.username ?? "");
  if (usernameFieldError(username)) {
    return { ok: true, available: false };
  }

  const caller = await assertAdminCaller();
  if (!caller.ok) return { ok: false, message: caller.message };

  const sb = await createSupabaseServerUserClient();
  const { data, error } = await sb.rpc("check_username_available", {
    p_username: username,
    p_exclude_user_id: input.excludeUserId ?? null,
  });

  if (error) {
    return { ok: false, message: "Impossibile verificare il nome utente. Riprova." };
  }
  return { ok: true, available: data === true };
}

export async function listUsersByAdminAction(): Promise<ListUsersByAdminResult> {
  const caller = await assertAdminCaller();
  if (!caller.ok) return { ok: false, message: caller.message };
  const admin = serviceAdmin(caller.url, caller.serviceKey);

  const { data: profiles, error: profilesErr } = await admin.from("profiles").select(PROFILES_COLUMNS);
  if (profilesErr) return { ok: false, message: profilesErr.message };
  const profileRows = (profiles ?? []) as ProfileRow[];
  const profileById = new Map(profileRows.map((p) => [p.id, p]));

  const users: SecurityUserAdminRow[] = [];
  let page = 1;
  const perPage = 1000;
  while (page <= 10) {
    const { data, error } = await admin.auth.admin.listUsers({ page, perPage });
    if (error) return { ok: false, message: error.message };
    const batch = data.users ?? [];
    for (const u of batch) {
      users.push(userRowFrom(profileById.get(u.id), u));
      profileById.delete(u.id);
    }
    if (batch.length < perPage) break;
    page += 1;
  }

  for (const profile of profileById.values()) {
    users.push(userRowFrom(profile));
  }

  users.sort((a, b) => a.nome.localeCompare(b.nome, "it"));
  return { ok: true, users };
}

export async function deleteUserByAdminAction(userId: string): Promise<DeleteUserByAdminResult> {
  const caller = await assertAdminCaller();
  if (!caller.ok) return { ok: false, message: caller.message };

  const parsed = validateDeleteUserByAdminInput(userId, caller.callerId);
  if (!parsed.ok) return { ok: false, message: parsed.message };

  const admin = serviceAdmin(caller.url, caller.serviceKey);

  const { data: profile, error: profileErr } = await admin
    .from("profiles")
    .select("id, nome, role_key")
    .eq("id", parsed.userId)
    .maybeSingle();
  if (profileErr) return { ok: false, message: profileErr.message };
  if (!profile) return { ok: false, message: "Profilo non trovato." };

  const targetRole = resolveRole((profile as ProfileRow).role_key);
  const lastAdminErr = await validateLastAdminTarget(admin, parsed.userId, targetRole, "delete");
  if (lastAdminErr) return { ok: false, message: lastAdminErr };

  const nome = (profile as ProfileRow).nome?.trim() || "Utente";
  await writeSecurityDeleteLog(admin, {
    targetUserId: parsed.userId,
    actorUserId: caller.callerId,
    nome,
    role: targetRole,
    actorName: caller.callerName,
  });

  const { error: deleteErr } = await admin.auth.admin.deleteUser(parsed.userId);
  if (deleteErr) {
    return { ok: false, message: deleteErr.message || "Eliminazione utente non riuscita." };
  }

  clearServerAuthSnapshotCacheForUser(parsed.userId);
  invalidateRbacTruthServer();
  return { ok: true };
}

export async function resetGlobalChangeLogsByAdminAction(): Promise<ResetGlobalChangeLogsResult> {
  const ctx = await assertAdminCaller();
  if (!ctx.ok) return { ok: false, message: ctx.message };
  try {
    const admin = serviceAdmin(ctx.url, ctx.serviceKey);
    const { count, error } = await admin.from("log_modifiche").delete({ count: "exact" }).neq("id", "00000000-0000-0000-0000-000000000000");
    if (error) return { ok: false, message: error.message };
    await admin.from("log_modifiche").insert({
      entita: "security",
      entita_id: ctx.callerId,
      azione: "RESET_LOG_MODIFICHE",
      autore_id: ctx.callerId,
      payload: {
        event: "RESET LOG MODIFICHE",
        actor: ctx.callerName,
        deletedCount: count,
        compact: `(RESET LOG MODIFICHE, ${ctx.callerName}, ${new Date().toLocaleString("it-IT", { dateStyle: "short", timeStyle: "short" })})`,
      },
    });
    return { ok: true, deletedCount: count };
  } catch (e) {
    return { ok: false, message: e instanceof Error ? e.message : "Reset log non riuscito." };
  }
}

/** Invia email reset password (admin). Messaggio sempre generico — no leak email. */
export async function sendPasswordResetByAdminAction(userId: string): Promise<SendPasswordResetByAdminResult> {
  const caller = await assertAdminCaller();
  if (!caller.ok) return { ok: false, message: caller.message };

  const idErr = validateUserId(userId);
  if (idErr) return { ok: false, message: idErr };

  const origin = resolvePasswordResetOriginFromEnv();
  if (!origin) {
    return {
      ok: false,
      message: "Reset password non configurato sul server (manca NEXT_PUBLIC_SITE_URL).",
    };
  }

  const admin = serviceAdmin(caller.url, caller.serviceKey);
  const authLookup = await admin.auth.admin.getUserById(userId.trim());
  if (authLookup.error || !authLookup.data.user?.email) {
    await writeSecurityAuditLog(admin, {
      actorUserId: caller.callerId,
      targetUserId: userId.trim(),
      action: "RESET_PASSWORD_ADMIN",
      result: "failure",
    });
    return { ok: true };
  }

  const sbUser = await createSupabaseServerUserClient();
  const redirectTo = resolvePasswordResetRedirectUrl(origin);
  const res = await sendPasswordResetEmail(sbUser, authLookup.data.user.email, redirectTo);

  await writeSecurityAuditLog(admin, {
    actorUserId: caller.callerId,
    targetUserId: userId.trim(),
    action: "RESET_PASSWORD_ADMIN",
    result: res.ok ? "success" : "failure",
  });

  if (!res.ok) {
    return { ok: false, message: "Impossibile completare la richiesta. Riprova tra poco." };
  }
  return { ok: true };
}

/** Disattiva/riattiva account via Supabase ban_duration (Auth SSOT). */
export async function setUserAccountEnabledByAdminAction(input: {
  userId: string;
  enabled: boolean;
}): Promise<SetUserAccountEnabledResult> {
  const caller = await assertAdminCaller();
  if (!caller.ok) return { ok: false, message: caller.message };

  const parsed = validateSetUserAccountEnabledInput(input, caller.callerId);
  if (!parsed.ok) return { ok: false, message: parsed.message };

  const admin = serviceAdmin(caller.url, caller.serviceKey);

  const { data: profile, error: profileErr } = await admin
    .from("profiles")
    .select("id, nome, role_key")
    .eq("id", parsed.userId)
    .maybeSingle();
  if (profileErr) return { ok: false, message: profileErr.message };
  if (!profile) return { ok: false, message: "Profilo non trovato." };

  const targetRole = resolveRole((profile as ProfileRow).role_key);
  if (!parsed.enabled) {
    const lastAdminErr = await validateLastAdminTarget(admin, parsed.userId, targetRole, "disable");
    if (lastAdminErr) return { ok: false, message: lastAdminErr };
  }

  const banDuration = parsed.enabled ? "none" : "876000h";
  const { error: banErr } = await admin.auth.admin.updateUserById(parsed.userId, {
    ban_duration: banDuration,
  });
  if (banErr) {
    await writeSecurityAuditLog(admin, {
      actorUserId: caller.callerId,
      targetUserId: parsed.userId,
      action: parsed.enabled ? "RIATTIVAZIONE UTENTE" : "DISATTIVAZIONE UTENTE",
      result: "failure",
    });
    return { ok: false, message: banErr.message || "Operazione non riuscita." };
  }

  if (!parsed.enabled) {
    await revokeUserSessionsAdmin({ admin, targetAccessJwt: null });
  }

  clearServerAuthSnapshotCacheForUser(parsed.userId);
  invalidateRbacTruthServer();

  await writeSecurityAuditLog(admin, {
    actorUserId: caller.callerId,
    targetUserId: parsed.userId,
    action: parsed.enabled ? "RIATTIVAZIONE UTENTE" : "DISATTIVAZIONE UTENTE",
    result: "success",
  });

  return { ok: true };
}

"use server";

import type { SupabaseClient } from "@supabase/supabase-js";
import { PROFILES_COLUMNS, USER_PERMISSIONS_COLUMNS } from "@/lib/db/table-select-columns";
import {
  CLIENT_LAVORAZIONI_SETTINGS_KEY,
  CLIENT_LAVORAZIONI_SETTINGS_MODULE,
  parseClientPortalAccess,
} from "@/lib/lavorazioni/client-portal-access";
import {
  normalizeClienteRef,
  roleHasClientPortalAccess,
  validateClienteAssociationForRole,
} from "@/src/lib/auth/cliente-portal-scope";
import { loadKnownClientiSetFromMezzi } from "@/src/lib/auth/load-known-clienti";
import { normalizeUsername } from "@/src/lib/auth/username";
import { hasPermission, resolveRole, ROLE_LABELS, type AppRole } from "@/lib/auth/rbac";
import { createSupabaseServerUserClient } from "@/src/lib/supabase/server-user-client";
import { createServiceAdminClient } from "@/lib/supabase/create-service-admin-client.server";
import { assertAdminCaller } from "@/lib/auth/assert-admin-caller.server";
import { listUsersByAdminAction } from "@/src/actions/admin-users";
import type { SecurityUserAdminRow } from "@/src/actions/admin-users.types";
import { isUserBanned } from "@/lib/auth/user-ban-state";
import { loadAllUserPermissionRows as loadRbacUserPermissionRows, listAllRoles, loadRolePermissionKeys } from "@/src/lib/rbac/load-rbac-data";
import {
  validateLastAdminTarget,
  validateSecurityUserBatchPatches,
} from "@/lib/validation/security-actions-validation";
import type { GestionalePermissionModule } from "@/src/lib/permissions/gestionale-modules";
import { onUserRoleChangedServer } from "@/src/lib/rbac/on-user-role-changed.server";
import { clearServerAuthSnapshotCacheForUser } from "@/src/lib/auth/server-session-cache";
import { hasModulePermissionOverrides } from "@/lib/security/user-module-permissions";
import type { ProfileRow, RoleRow, UserPermissionRow } from "@/src/types/supabase-tables";

export type SecurityUserModulePermissionEntry = {
  module: GestionalePermissionModule;
  canRead: boolean;
  canWrite: boolean;
};

export type SecurityUserPermissionRow = SecurityUserAdminRow & {
  clientLavorazioniAccess: boolean;
  /** Accesso garantito dal ruolo (toggle non modificabile). */
  clientLavorazioniAccessFromRole: boolean;
  hasModulePermissionOverrides: boolean;
};

export type SecurityUserBatchPatch = {
  userId: string;
  nome?: string;
  cognome?: string | null;
  username?: string;
  ruolo?: string;
  clienteRef?: string | null;
  modulePermissions?: SecurityUserModulePermissionEntry[] | null;
  clearModulePermissions?: boolean;
};

export type ListSecurityUsersPermissionsResult =
  | {
      ok: true;
      users: SecurityUserPermissionRow[];
      portalSettingsUpdatedAt: string | null;
      permissionRows: UserPermissionRow[];
      rolePermissionKeysByRole: Record<string, string[]>;
      assignableRoles: Pick<RoleRow, "key" | "name">[];
    }
  | { ok: false; message: string };

export type BatchUpdateSecurityUsersResult =
  | { ok: true; updatedCount: number; roleChangedUserIds: string[] }
  | { ok: false; message: string };

function roleGrantsClientPortal(rolePermissionKeys: string[]): boolean {
  return rolePermissionKeys.includes("can_access_client_area");
}

function toPermissionRow(
  user: SecurityUserAdminRow,
  permissionRows: UserPermissionRow[],
  rolePermissionKeys: string[],
): SecurityUserPermissionRow {
  const fromRole = roleGrantsClientPortal(rolePermissionKeys);
  return {
    ...user,
    clientLavorazioniAccessFromRole: fromRole,
    clientLavorazioniAccess: fromRole,
    hasModulePermissionOverrides: hasModulePermissionOverrides(rolePermissionKeys, user.id, permissionRows),
  };
}

async function deleteUserModulePermissions(admin: SupabaseClient, userId: string): Promise<void> {
  const { error } = await admin.from("user_permissions").delete().eq("user_id", userId);
  if (error) throw new Error(error.message);
}

async function applyUserModulePermissions(
  admin: SupabaseClient,
  userId: string,
  modulePermissions: SecurityUserModulePermissionEntry[] | null,
  userRole?: AppRole,
  rolePermissionKeys?: string[],
): Promise<boolean> {
  await deleteUserModulePermissions(admin, userId);
  if (!modulePermissions?.length) return true;

  if (userRole === "guest") {
    throw new Error(`Il ruolo ${ROLE_LABELS.guest} non ammette override permessi modulo.`);
  }

  const { data: perms, error: permErr } = await admin.from("permissions").select("id, key");
  if (permErr) throw new Error(permErr.message);
  const permByKey = new Map((perms ?? []).map((p) => [p.key as string, p.id as string]));

  const { computeModulePermissionDraft, planModulePermissionPersist } = await import(
    "@/lib/security/user-module-permissions"
  );
  const roleKeys = rolePermissionKeys ?? [];
  const draft = computeModulePermissionDraft(roleKeys, userId, []).map((row) => {
    const entry = modulePermissions.find((e) => e.module === row.module);
    if (!entry) return row;
    return {
      ...row,
      canRead: entry.canRead,
      canWrite: entry.canRead ? entry.canWrite : false,
      isCustomized: true,
      overrideRead:
        entry.canRead === row.roleCanRead
          ? ("inherit" as const)
          : entry.canRead
            ? ("allow" as const)
            : ("deny" as const),
      overrideWrite:
        entry.canWrite === row.roleCanWrite
          ? ("inherit" as const)
          : entry.canWrite
            ? ("allow" as const)
            : ("deny" as const),
    };
  });

  const plan = planModulePermissionPersist(roleKeys, draft);

  if (plan.deleteAll) return true;

  const rows = plan.overrides
    .map((o: { permissionKey: string; effect: "allow" | "deny" }) => {
      const permission_id = permByKey.get(o.permissionKey);
      if (!permission_id) return null;
      return { user_id: userId, permission_id, effect: o.effect };
    })
    .filter(
      (r): r is { user_id: string; permission_id: string; effect: "allow" | "deny" } => r != null,
    );

  if (!rows.length) return true;
  const { error } = await admin.from("user_permissions").upsert(rows, { onConflict: "user_id,permission_id" });
  if (error) throw new Error(error.message);
  return true;
}

export async function listSecurityUsersPermissionsAction(): Promise<ListSecurityUsersPermissionsResult> {
  const admin = await assertAdminCaller();
  if (!admin.ok) return { ok: false, message: admin.message };

  const usersRes = await listUsersByAdminAction();
  if (!usersRes.ok) return { ok: false, message: usersRes.message };

  const sb = await createSupabaseServerUserClient();
  const { data: row } = await sb
    .from("app_settings")
    .select("value, updated_at")
    .eq("module", CLIENT_LAVORAZIONI_SETTINGS_MODULE)
    .eq("key", CLIENT_LAVORAZIONI_SETTINGS_KEY)
    .maybeSingle();

  const { createClient } = await import("@supabase/supabase-js");
  const serviceAdmin = createClient(admin.url, admin.serviceKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });

  const userIds = usersRes.users.map((u) => u.id);
  let permissionRows: UserPermissionRow[] = [];
  try {
    permissionRows = await loadRbacUserPermissionRows(serviceAdmin, userIds);
  } catch (e) {
    return {
      ok: false,
      message: e instanceof Error ? e.message : "Errore caricamento permessi modulo.",
    };
  }

  const assignableRoles = (await listAllRoles(serviceAdmin))
    .filter((r) => r.is_active)
    .map((r) => ({ key: r.key, name: r.name }));

  const uniqueRoles = [
    ...new Set([...usersRes.users.map((u) => resolveRole(u.ruolo)), ...assignableRoles.map((r) => r.key)]),
  ];
  const roleKeysMap = new Map<string, string[]>();
  await Promise.all(
    uniqueRoles.map(async (rk) => {
      roleKeysMap.set(rk, await loadRolePermissionKeys(serviceAdmin, rk));
    }),
  );

  const users = usersRes.users.map((u) =>
    toPermissionRow(u, permissionRows, roleKeysMap.get(resolveRole(u.ruolo)) ?? []),
  );
  return {
    ok: true,
    users,
    portalSettingsUpdatedAt: row?.updated_at ?? null,
    permissionRows,
    rolePermissionKeysByRole: Object.fromEntries(roleKeysMap),
    assignableRoles,
  };
}

async function writeSecurityBatchLog(
  admin: SupabaseClient,
  input: {
    actorUserId: string;
    actorName: string;
    patches: SecurityUserBatchPatch[];
    profileById: Map<string, ProfileRow>;
  },
) {
  const { error } = await admin.from("log_modifiche").insert({
    entita: "security",
    entita_id: input.actorUserId,
    azione: "BATCH_UPDATE_USERS",
    autore_id: input.actorUserId,
    payload: {
      event: "AGGIORNAMENTO UTENTI E PERMESSI",
      actor: input.actorName,
      count: input.patches.length,
      userIds: input.patches.map((p) => p.userId),
      transitions: input.patches
        .filter((p) => p.ruolo != null)
        .map((p) => ({
          userId: p.userId,
          from: resolveRole(input.profileById.get(p.userId)?.role_key),
          to: p.ruolo,
        })),
      compact: `(AGGIORNAMENTO UTENTI, ${input.patches.length} modifiche, ${input.actorName})`,
    },
  });
  if (error) console.warn("[security] batch log:", error.message);
}

export async function batchUpdateSecurityUsersAction(
  patches: SecurityUserBatchPatch[],
): Promise<BatchUpdateSecurityUsersResult> {
  const validated = validateSecurityUserBatchPatches(patches);
  if (!validated.ok) return { ok: false, message: validated.message };
  if (!validated.patches.length) return { ok: true, updatedCount: 0, roleChangedUserIds: [] };

  const caller = await assertAdminCaller();
  if (!caller.ok) return { ok: false, message: caller.message };

  const admin = createServiceAdminClient(caller.url, caller.serviceKey);
  const sbUser = await createSupabaseServerUserClient();

  const normalized = validated.patches
    .map((p) => ({
      userId: p.userId,
      nome: p.nome,
      cognome: p.cognome,
      username: p.username,
      ruolo: p.ruolo != null ? resolveRole(p.ruolo) : undefined,
      clienteRef: p.clienteRef,
      modulePermissions: p.modulePermissions,
      clearModulePermissions: p.clearModulePermissions,
    }))
    .filter((p) => p.userId);

  if (!normalized.length) return { ok: true, updatedCount: 0, roleChangedUserIds: [] };

  let knownClienti: Set<string>;
  try {
    knownClienti = await loadKnownClientiSetFromMezzi(admin);
  } catch (e) {
    return {
      ok: false,
      message: e instanceof Error ? e.message : "Errore caricamento anagrafica clienti.",
    };
  }

  const patchUserIds = normalized.map((p) => p.userId);
  const { data: profilesBefore, error: profilesLoadErr } = await admin
    .from("profiles")
    .select(PROFILES_COLUMNS)
    .in("id", patchUserIds);
  if (profilesLoadErr) return { ok: false, message: profilesLoadErr.message };
  const profileById = new Map(((profilesBefore ?? []) as ProfileRow[]).map((p) => [p.id, p]));

  for (const patch of normalized) {
    const authLookup = await admin.auth.admin.getUserById(patch.userId);
    if (authLookup.error) {
      return { ok: false, message: authLookup.error.message };
    }
    if (isUserBanned(authLookup.data.user)) {
      return {
        ok: false,
        message: "Impossibile modificare un utente disattivato. Riattivalo prima di applicare altre modifiche.",
      };
    }
  }

  let updatedCount = 0;
  const roleChangedUserIds: string[] = [];

  for (const patch of normalized) {
    const profile = profileById.get(patch.userId);
    if (!profile) return { ok: false, message: `Profilo non trovato (${patch.userId}).` };

    if (patch.nome != null && patch.nome !== profile.nome?.trim()) {
      if (!patch.nome) return { ok: false, message: "Il nome non può essere vuoto." };
      const { error } = await admin.from("profiles").update({ nome: patch.nome }).eq("id", patch.userId);
      if (error) return { ok: false, message: error.message };
      await admin.auth.admin
        .updateUserById(patch.userId, {
          app_metadata: { cab_nome: patch.nome },
        })
        .catch(() => {});
      updatedCount += 1;
    }

    if (patch.cognome !== undefined) {
      const currentCognome =
        typeof profile.cognome === "string" && profile.cognome.trim() ? profile.cognome.trim() : null;
      const nextCognome = patch.cognome?.trim() || null;
      if (nextCognome !== currentCognome) {
        const { error } = await admin.from("profiles").update({ cognome: nextCognome }).eq("id", patch.userId);
        if (error) return { ok: false, message: error.message };
        await admin.auth.admin
          .updateUserById(patch.userId, {
            app_metadata: { cab_cognome: nextCognome },
          })
          .catch(() => {});
        updatedCount += 1;
      }
    }

    if (patch.username != null) {
      const currentUsername = normalizeUsername(profile.username ?? "");
      if (patch.username !== currentUsername) {
        const { data: available, error: rpcErr } = await sbUser.rpc("check_username_available", {
          p_username: patch.username,
          p_exclude_user_id: patch.userId,
        });
        if (rpcErr) return { ok: false, message: "Impossibile verificare il nome utente. Riprova." };
        if (available !== true) return { ok: false, message: "Username già utilizzato." };

        const { error } = await admin.from("profiles").update({ username: patch.username }).eq("id", patch.userId);
        if (error) {
          const msg =
            error.message.includes("unique") || error.message.includes("duplicate")
              ? "Username già utilizzato."
              : error.message;
          return { ok: false, message: msg };
        }
        await admin.auth.admin
          .updateUserById(patch.userId, {
            app_metadata: { cab_username: patch.username },
          })
          .catch(() => {});
        clearServerAuthSnapshotCacheForUser(patch.userId);
        updatedCount += 1;
      }
    }

    const effectiveRole = patch.ruolo != null ? patch.ruolo : resolveRole(profile.role_key);
    const effectiveClienteRef =
      patch.clienteRef !== undefined ? patch.clienteRef : normalizeClienteRef(profile.cliente_ref);
    const clienteRefErr = validateClienteAssociationForRole(effectiveRole, effectiveClienteRef, knownClienti);
    if (clienteRefErr) return { ok: false, message: clienteRefErr };

    if (patch.clienteRef !== undefined) {
      const currentRef = normalizeClienteRef(profile.cliente_ref);
      if (patch.clienteRef !== currentRef) {
        const { error } = await admin
          .from("profiles")
          .update({ cliente_ref: patch.clienteRef })
          .eq("id", patch.userId);
        if (error) return { ok: false, message: error.message };
        clearServerAuthSnapshotCacheForUser(patch.userId);
        updatedCount += 1;
      }
    }

    const roleChanged = patch.ruolo != null && resolveRole(profile.role_key) !== patch.ruolo;
    if (roleChanged) {
      const prevRole = resolveRole(profile.role_key);
      if (prevRole === "admin" && patch.ruolo !== "admin") {
        const lastAdminErr = await validateLastAdminTarget(admin, patch.userId, prevRole, "role_downgrade");
        if (lastAdminErr) return { ok: false, message: lastAdminErr };
      }
      const { error: roleErr } = await admin.rpc("security_set_user_role", {
        p_user_id: patch.userId,
        p_role_key: patch.ruolo,
      });
      if (roleErr) return { ok: false, message: roleErr.message };

      const authLookup = await admin.auth.admin.getUserById(patch.userId);
      if (authLookup.error) return { ok: false, message: authLookup.error.message };
      const { error: metaErr } = await admin.auth.admin.updateUserById(patch.userId, {
        app_metadata: { ...(authLookup.data.user?.app_metadata ?? {}), cab_ruolo: patch.ruolo },
      });
      if (metaErr) return { ok: false, message: metaErr.message };

      onUserRoleChangedServer(patch.userId);
      roleChangedUserIds.push(patch.userId);
      updatedCount += 1;
    }

    if (patch.modulePermissions !== undefined) {
      if (effectiveRole === "guest") {
        return {
          ok: false,
          message: `Il ruolo ${ROLE_LABELS.guest} non ammette override permessi modulo.`,
        };
      }
      try {
        if (await applyUserModulePermissions(admin, patch.userId, patch.modulePermissions, effectiveRole)) {
          updatedCount += 1;
        }
      } catch (e) {
        return { ok: false, message: e instanceof Error ? e.message : "Errore salvataggio permessi pagine." };
      }
    } else if (patch.clearModulePermissions === true) {
      try {
        if (await applyUserModulePermissions(admin, patch.userId, null, effectiveRole)) {
          updatedCount += 1;
        }
      } catch (e) {
        return { ok: false, message: e instanceof Error ? e.message : "Errore permessi modulo." };
      }
    }
  }

  await writeSecurityBatchLog(admin, {
    actorUserId: caller.callerId,
    actorName: caller.callerName,
    patches: normalized,
    profileById,
  });

  return { ok: true, updatedCount, roleChangedUserIds };
}

export type ClienteAssociationAuditIssue = {
  userId: string;
  nome: string;
  email: string;
  ruolo: AppRole;
  clienteRef: string | null;
  category:
    | "cliente_senza_associazione"
    | "associazione_invalida"
    | "ref_orfano_staff"
    | "allowlist_non_autorizzato";
  detail: string;
};

export type ClienteAssociationAuditResult = {
  ok: true;
  issues: ClienteAssociationAuditIssue[];
  allowlistCleaned: Array<{ userId: string; nome: string; ruolo: string }>;
  knownClientiCount: number;
  scannedAt: string;
};

export type ClienteAssociationAuditActionResult =
  | ClienteAssociationAuditResult
  | { ok: false; message: string };

async function cleanupClientPortalAllowlist(
  sbUser: SupabaseClient,
  users: SecurityUserAdminRow[],
  callerId: string,
): Promise<{ cleaned: Array<{ userId: string; nome: string; ruolo: string }>; issues: ClienteAssociationAuditIssue[] }> {
  const { data: settingsRow } = await sbUser
    .from("app_settings")
    .select("value, updated_at")
    .eq("module", CLIENT_LAVORAZIONI_SETTINGS_MODULE)
    .eq("key", CLIENT_LAVORAZIONI_SETTINGS_KEY)
    .maybeSingle();

  const settings = parseClientPortalAccess(settingsRow?.value);
  const usersById = new Map(users.map((u) => [u.id, u]));
  const issues: ClienteAssociationAuditIssue[] = [];
  const cleaned: Array<{ userId: string; nome: string; ruolo: string }> = [];
  const nextIds: string[] = [];

  for (const userId of settings.enabledUserIds) {
    const user = usersById.get(userId);
    if (!user) {
      issues.push({
        userId,
        nome: "—",
        email: "",
        ruolo: "guest",
        clienteRef: null,
        category: "allowlist_non_autorizzato",
        detail: "Utente in allowlist non trovato in elenco profili.",
      });
      continue;
    }
    if (!roleHasClientPortalAccess(user.ruolo)) {
      issues.push({
        userId: user.id,
        nome: user.nome,
        email: user.email,
        ruolo: user.ruolo,
        clienteRef: user.clienteRef,
        category: "allowlist_non_autorizzato",
        detail: "Rimosso dall'allowlist: ruolo senza accesso portale.",
      });
      cleaned.push({ userId: user.id, nome: user.nome, ruolo: user.ruolo });
      continue;
    }
    nextIds.push(userId);
  }

  if (nextIds.length !== settings.enabledUserIds.length) {
    const value = { enabledUserIds: nextIds };
    if (!settingsRow) {
      const { error } = await sbUser.from("app_settings").insert({
        module: CLIENT_LAVORAZIONI_SETTINGS_MODULE,
        key: CLIENT_LAVORAZIONI_SETTINGS_KEY,
        value,
        updated_by: callerId,
      });
      if (error) throw new Error(error.message);
    } else {
      const { error } = await sbUser
        .from("app_settings")
        .update({ value, updated_by: callerId })
        .eq("module", CLIENT_LAVORAZIONI_SETTINGS_MODULE)
        .eq("key", CLIENT_LAVORAZIONI_SETTINGS_KEY)
        .eq("updated_at", settingsRow.updated_at);
      if (error) throw new Error("Conflitto aggiornamento allowlist portale. Riprova.");
    }
  }

  return { cleaned, issues };
}

/** Report associazioni cliente + pulizia allowlist portale (no auto-fix su profili). */
export async function auditClienteAssociationsAction(): Promise<ClienteAssociationAuditActionResult> {
  const caller = await assertAdminCaller();
  if (!caller.ok) return { ok: false, message: caller.message };

  const usersRes = await listUsersByAdminAction();
  if (!usersRes.ok) return { ok: false, message: usersRes.message };

  const { createClient } = await import("@supabase/supabase-js");
  const admin = createClient(caller.url, caller.serviceKey, {
    auth: { autoRefreshToken: false, persistSession: false },
  });
  const sbUser = await createSupabaseServerUserClient();

  let knownClienti: Set<string>;
  try {
    knownClienti = await loadKnownClientiSetFromMezzi(admin);
  } catch (e) {
    return {
      ok: false,
      message: e instanceof Error ? e.message : "Errore caricamento anagrafica clienti.",
    };
  }

  const issues: ClienteAssociationAuditIssue[] = [];

  for (const user of usersRes.users) {
    const ref = normalizeClienteRef(user.clienteRef);
    if (user.ruolo === "cliente") {
      if (!ref) {
        issues.push({
          userId: user.id,
          nome: user.nome,
          email: user.email,
          ruolo: user.ruolo,
          clienteRef: null,
          category: "cliente_senza_associazione",
          detail: "Ruolo Cliente senza cliente associato.",
        });
      } else if (knownClienti.size > 0 && !knownClienti.has(ref)) {
        issues.push({
          userId: user.id,
          nome: user.nome,
          email: user.email,
          ruolo: user.ruolo,
          clienteRef: ref,
          category: "associazione_invalida",
          detail: "Cliente associato non presente in anagrafica mezzi.",
        });
      }
    } else if (ref) {
      issues.push({
        userId: user.id,
        nome: user.nome,
        email: user.email,
        ruolo: user.ruolo,
        clienteRef: ref,
        category: "ref_orfano_staff",
        detail: "Cliente associato valorizzato per utente non Cliente (informativo).",
      });
    }
  }

  try {
    const allowlist = await cleanupClientPortalAllowlist(sbUser, usersRes.users, caller.callerId);
    issues.push(...allowlist.issues);
    return {
      ok: true,
      issues,
      allowlistCleaned: allowlist.cleaned,
      knownClientiCount: knownClienti.size,
      scannedAt: new Date().toISOString(),
    };
  } catch (e) {
    return { ok: false, message: e instanceof Error ? e.message : "Errore pulizia allowlist." };
  }
}

