"use client";

import { useCallback, useEffect, useMemo, useState } from "react";
import { useAuth } from "@/context/auth-context";
import { isStaffInboxEligible } from "@/lib/notifications/staff-inbox-eligible";
import {
  clearMagazzinoNotifications,
  countReadAdminNotifications,
  emptyAdminNotificationStore,
  getUnreadCount,
  isNotificationUnread,
  listNotifications,
  loadAdminNotificationStore,
  markAllAdminNotificationsRead,
  markAdminNotificationRead,
  removeAdminNotification,
  removeReadAdminNotifications,
  subscribeAdminNotificationStore,
  type AdminNotificationStoreState,
} from "@/lib/lavorazioni/admin-notification-store";
import type { AdminDashboardNotification } from "@/lib/notifications/admin-dashboard-notifications";
import { useEffectivePermissions } from "@/src/lib/runtime/truth-layer/use-effective-permissions";
import { useNotificationsV2Mode } from "@/src/hooks/gestionale/use-notifications-v2-mode";

export function useAdminNotificationStore() {
  const { user } = useAuth();
  const { snapshot, isLoading: permsLoading } = useEffectivePermissions();
  const { readsDb, isLoading: flagLoading } = useNotificationsV2Mode();
  const userId = user?.id ?? "";
  const staffEligible =
    !permsLoading &&
    isStaffInboxEligible(snapshot ? { ruolo: snapshot.role } : user, snapshot?.rbacContext);
  const enabled = staffEligible && !flagLoading && !readsDb && userId.length > 0;

  // SSR/hydration: mai leggere localStorage nel render iniziale (vedi docs/bootstrap-hydration.md).
  const [state, setState] = useState<AdminNotificationStoreState>(emptyAdminNotificationStore);

  useEffect(() => {
    if (!enabled) {
      setState(emptyAdminNotificationStore());
      return;
    }
    setState(loadAdminNotificationStore(userId));
    return subscribeAdminNotificationStore((changedUserId) => {
      if (changedUserId === userId) {
        setState(loadAdminNotificationStore(userId));
      }
    });
  }, [enabled, userId]);

  const notifications = useMemo(() => (enabled ? listNotifications(state) : []), [enabled, state]);
  const unreadCount = useMemo(() => (enabled ? getUnreadCount(state) : 0), [enabled, state]);
  const readCount = useMemo(() => (enabled ? countReadAdminNotifications(state) : 0), [enabled, state]);

  const markAllRead = useCallback(() => {
    if (!enabled) return;
    setState(markAllAdminNotificationsRead(userId));
  }, [enabled, userId]);

  const markNotificationRead = useCallback(
    (notification: AdminDashboardNotification) => {
      if (!enabled) return;
      setState(markAdminNotificationRead(userId, notification));
    },
    [enabled, userId],
  );

  const dismissNotification = useCallback(
    (notification: AdminDashboardNotification) => {
      if (!enabled) return;
      setState(removeAdminNotification(userId, notification));
    },
    [enabled, userId],
  );

  const removeReadNotifications = useCallback(() => {
    if (!enabled) return;
    setState(removeReadAdminNotifications(userId));
  }, [enabled, userId]);

  const clearMagazzinoNotifs = useCallback(() => {
    if (!enabled) return;
    setState(clearMagazzinoNotifications(userId));
  }, [enabled, userId]);

  const isUnread = useCallback(
    (notification: AdminDashboardNotification) =>
      enabled ? isNotificationUnread(state, notification) : false,
    [enabled, state],
  );

  return {
    notifications,
    unreadCount,
    readCount,
    markAllRead,
    markNotificationRead,
    dismissNotification,
    removeReadNotifications,
    clearMagazzinoNotifications: clearMagazzinoNotifs,
    isUnread,
    canReadDashboard: enabled,
    permLoading: permsLoading || flagLoading,
    enabled,
  };
}

export type { AdminDashboardNotification };

"use client";

import { useQuery, type UseQueryResult } from "@tanstack/react-query";
import { useAuth } from "@/context/auth-context";
import { useRbac } from "@/src/hooks/use-rbac";
import { QK } from "@/src/lib/react-query/invalidate-related";
import {
  appSettingsAuditService,
  type AppSettingsAuditListParams,
} from "@/src/services/app-settings-audit.service";
import type { AppSettingsAuditRow } from "@/src/types/supabase-tables";

/**
 * Pronto per una futura pagina log admin: esegue fetch solo se `ruolo === 'admin'`.
 */
export function useAppSettingsAuditQuery(
  params: AppSettingsAuditListParams = {},
): UseQueryResult<AppSettingsAuditRow[], Error> {
  const { user } = useAuth();
  const rbac = useRbac();
  const limit = params.limit ?? 200;
  const module = params.module ?? "";
  const key = params.key ?? "";

  return useQuery({
    queryKey: [...QK.settingsAudit, module, key, limit] as const,
    queryFn: async () => {
      const r = await appSettingsAuditService.list({ ...params, limit });
      if (!r.success) throw new Error(r.error ?? "Errore lettura audit impostazioni");
      return r.data ?? [];
    },
    enabled: !!user?.id && rbac.hasPermission("manageSecurity"),
    staleTime: 60_000,
    gcTime: 300_000,
  });
}

"use client";

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import { useInfiniteQuery, useQuery, useQueryClient } from "@tanstack/react-query";
import { useAuth, isAuthSessionEstablished } from "@/context/auth-context";
import type { InboxCursor, InboxNotificationRow } from "@/lib/notifications/notification-types";
import { isStaffInboxEligible } from "@/lib/notifications/staff-inbox-eligible";
import { RealtimeInboxCoordinator } from "@/lib/notifications/realtime-inbox-coordinator";
import { notificationsV2ReadsDb } from "@/lib/notifications/notifications-v2-flag";
import { notificationsService } from "@/src/services/notifications.service";
import { QK } from "@/src/lib/react-query/invalidate-related";
import { useEffectivePermissions } from "@/src/lib/runtime/truth-layer/use-effective-permissions";
import { useNotificationsV2Mode } from "@/src/hooks/gestionale/use-notifications-v2-mode";

const PAGE_SIZE = 50;

function cursorFromRow(row: InboxNotificationRow): InboxCursor {
  return {
    priority_rank: row.priority_rank,
    created_at: row.created_at,
    id: row.id,
  };
}

export function useNotificationCenter(drawerOpen = false) {
  const { user, status } = useAuth();
  const userId = user?.id ?? "";
  const { snapshot, isLoading: permsLoading } = useEffectivePermissions();
  const { readsDb, mode } = useNotificationsV2Mode();
  const queryClient = useQueryClient();
  const coordinatorRef = useRef<RealtimeInboxCoordinator | null>(null);

  const rbacCtx = snapshot?.rbacContext;
  const enabled =
    isAuthSessionEstablished(status) &&
    userId.length > 0 &&
    !permsLoading &&
    readsDb &&
    isStaffInboxEligible(snapshot?.role ? { ruolo: snapshot.role } : user, rbacCtx);

  const inboxQuery = useInfiniteQuery({
    queryKey: [...QK.notificationsInbox, userId] as const,
    queryFn: async ({ pageParam }) => {
      const res = await notificationsService.listInbox({
        limit: PAGE_SIZE,
        cursor: pageParam ?? null,
      });
      if (!res.success) throw new Error(res.error ?? "Errore inbox");
      return res.data ?? [];
    },
    initialPageParam: null as InboxCursor | null,
    getNextPageParam: (lastPage) => {
      if (lastPage.length < PAGE_SIZE) return undefined;
      const last = lastPage[lastPage.length - 1];
      return last ? cursorFromRow(last) : undefined;
    },
    enabled,
    staleTime: 30_000,
  });

  const unreadQuery = useQuery({
    queryKey: [...QK.notificationsUnread, userId] as const,
    queryFn: async () => {
      const res = await notificationsService.countUnread();
      if (!res.success) throw new Error(res.error ?? "Errore conteggio");
      return res.data ?? 0;
    },
    enabled,
    staleTime: 15_000,
  });

  const notifications = useMemo(
    () => inboxQuery.data?.pages.flat() ?? [],
    [inboxQuery.data?.pages],
  );

  const unreadCount = unreadQuery.data ?? 0;

  const refresh = useCallback(async () => {
    await Promise.all([inboxQuery.refetch(), unreadQuery.refetch()]);
  }, [inboxQuery, unreadQuery]);

  const markAllRead = useCallback(async () => {
    if (!enabled) return;
    let total = 0;
    for (let i = 0; i < 10; i++) {
      const res = await notificationsService.markAllRead(200);
      if (!res.success) break;
      total += res.data ?? 0;
      if ((res.data ?? 0) === 0) break;
    }
    if (total > 0) await refresh();
  }, [enabled, refresh]);

  const markedAllOnOpenRef = useRef(false);

  useEffect(() => {
    if (!drawerOpen) {
      markedAllOnOpenRef.current = false;
      return;
    }
    if (!enabled || markedAllOnOpenRef.current) return;
    markedAllOnOpenRef.current = true;
    void markAllRead();
  }, [drawerOpen, enabled, markAllRead]);

  const dismissNotification = useCallback(
    async (row: InboxNotificationRow) => {
      if (!enabled) return;
      await notificationsService.dismiss(row.id);
      await refresh();
    },
    [enabled, refresh],
  );

  const [isDismissingAll, setIsDismissingAll] = useState(false);

  const dismissAllNotifications = useCallback(async () => {
    if (!enabled || isDismissingAll) return 0;
    setIsDismissingAll(true);
    try {
      let total = 0;
      for (let i = 0; i < 10; i++) {
        const res = await notificationsService.listInbox({ limit: 200, cursor: null });
        if (!res.success) break;
        const rows = res.data ?? [];
        if (rows.length === 0) break;
        const results = await Promise.all(rows.map((row) => notificationsService.dismiss(row.id)));
        total += results.filter((r) => r.success).length;
        if (rows.length < 200) break;
      }
      if (total > 0) await refresh();
      return total;
    } finally {
      setIsDismissingAll(false);
    }
  }, [enabled, isDismissingAll, refresh]);

  const loadMore = useCallback(() => {
    if (inboxQuery.hasNextPage && !inboxQuery.isFetchingNextPage) {
      void inboxQuery.fetchNextPage();
    }
  }, [inboxQuery]);

  useEffect(() => {
    if (!enabled) {
      coordinatorRef.current?.stop();
      coordinatorRef.current = null;
      return;
    }
    const coord = new RealtimeInboxCoordinator({ userId, queryClient, drawerOpen });
    coordinatorRef.current = coord;
    void coord.start();
    return () => {
      coord.stop();
      coordinatorRef.current = null;
    };
  }, [enabled, userId, queryClient]);

  useEffect(() => {
    coordinatorRef.current?.setDrawerOpen(drawerOpen);
  }, [drawerOpen]);

  return {
    notifications,
    unreadCount,
    enabled,
    mode,
    isLoading: inboxQuery.isLoading || unreadQuery.isLoading || permsLoading,
    dismissNotification,
    dismissAllNotifications,
    isDismissingAll,
    loadMore,
    hasMore: Boolean(inboxQuery.hasNextPage),
    isLoadingMore: inboxQuery.isFetchingNextPage,
    channelStatus: coordinatorRef.current?.channelStatus ?? "off",
  };
}

/** Hook legacy wrapper: delega a v2 quando readsDb. */
export function useNotificationCenterOrLegacyEnabled(): boolean {
  const { readsDb } = useNotificationsV2Mode();
  return readsDb;
}

"use client";

import { useEffect, useMemo, useState } from "react";
import { useAuth } from "@/context/auth-context";
import { latestUndoableConfigurazioneSave } from "@/lib/configurazione/configurazione-undo-storage";
import { useUndoSessionId } from "@/lib/gestionale-log/use-undo-session-id";
import { CAB_CONFIGURAZIONE_UNDO_REFRESH } from "@/lib/sistema/cab-events";

/** Ultimo salvataggio configurazione annullabile per utente/sessione correnti. */
export function useUndoableConfigurazioneSave(options?: { enabled?: boolean }) {
  const { user } = useAuth();
  const sessionId = useUndoSessionId();
  const enabled = options?.enabled !== false;
  const [revision, setRevision] = useState(0);

  useEffect(() => {
    if (!enabled) return;
    const onRefresh = () => setRevision((n) => n + 1);
    window.addEventListener(CAB_CONFIGURAZIONE_UNDO_REFRESH, onRefresh);
    return () => window.removeEventListener(CAB_CONFIGURAZIONE_UNDO_REFRESH, onRefresh);
  }, [enabled]);

  const undoable = useMemo(() => {
    if (!enabled) return null;
    return latestUndoableConfigurazioneSave(user?.id, sessionId);
  }, [enabled, user?.id, sessionId, revision]);

  return { undoable, sessionId, userId: user?.id ?? null };
}

