"use client";

import { useMemo } from "react";
import { useQuery, type UseQueryResult } from "@tanstack/react-query";
import { permissionsService } from "@/src/services/permissions.service";
import { useAuth, isAuthSessionEstablished } from "@/context/auth-context";
import { buildEffectivePermissionsByModule, type EffectiveModulePermission } from "@/src/lib/permissions/effective-permissions";
import {
  GESTIONALE_PERMISSION_MODULES,
  type GestionalePermissionModule,
} from "@/src/lib/permissions/gestionale-modules";
import { navHrefToSection, resolveRole, type RbacSection } from "@/lib/auth/rbac";
import { gestionaleNavHrefToModule } from "@/src/lib/permissions/gestionale-modules";
import { useRbac } from "@/src/hooks/use-rbac";
import { QK } from "@/src/lib/react-query/invalidate-related";
import type { UserPermissionRow } from "@/src/types/supabase-tables";

async function fetchMyPermissions(userId: string | undefined): Promise<UserPermissionRow[]> {
  const r = await permissionsService.listMyPermissions(userId);
  if (!r.success) throw new Error(r.error ?? "Errore permessi");
  return r.data ?? [];
}

/** Role permission keys from DB (SSOT). */
export function useRolePermissionKeysQuery(): UseQueryResult<string[], Error> {
  const { user, status } = useAuth();
  return useQuery({
    queryKey: [...QK.userPermissions, "role-keys", user?.id ?? "anon"] as const,
    queryFn: async () => {
      const r = await permissionsService.listMyRolePermissionKeys(user?.id);
      if (!r.success) throw new Error(r.error ?? "Errore permessi ruolo");
      return r.data ?? [];
    },
    enabled: isAuthSessionEstablished(status) && !!user?.id,
    staleTime: Number.POSITIVE_INFINITY,
    gcTime: 86_400_000,
    refetchOnMount: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    retry: 1,
  });
}

/** Una sola fetch per sessione (invalidare esplicitamente dopo cambio permessi admin). */
export function useUserPermissionsQuery(): UseQueryResult<UserPermissionRow[], Error> {
  const { user, status } = useAuth();
  return useQuery({
    queryKey: [...QK.userPermissions, user?.id ?? "anon"] as const,
    queryFn: () => fetchMyPermissions(user?.id),
    enabled: isAuthSessionEstablished(status) && !!user?.id,
    staleTime: Number.POSITIVE_INFINITY,
    gcTime: 86_400_000,
    refetchOnMount: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    retry: 1,
  });
}

export type GlobalPermissions = {
  role: ReturnType<typeof resolveRole>;
  isAdmin: boolean;
  isOperatore: boolean;
  isOspite: boolean;
  canEditInventory: boolean;
  canManageUsers: boolean;
  canManageSecurity: boolean;
  canManageSettings: boolean;
  canEditWorkOrders: boolean;
  canEditVehicles: boolean;
  canUploadDocuments: boolean;
  canDeleteRecords: boolean;
  canViewReports: boolean;
  canViewAuditLogs: boolean;
  isLoading: boolean;
};

export type ModulePermission = EffectiveModulePermission & { isLoading: boolean };

export type PermissionsSnapshot = {
  global: GlobalPermissions;
  modules: Record<GestionalePermissionModule, ModulePermission>;
};

function buildGlobalPermissions(
  user: ReturnType<typeof useAuth>["user"],
  rbac: ReturnType<typeof useRbac>,
  authLoading: boolean,
): GlobalPermissions {
  return {
    role: resolveRole(user),
    isAdmin: rbac.isAdmin,
    isOperatore: rbac.isOperatore,
    isOspite: rbac.isOspite,
    canEditInventory: rbac.hasPermission("editInventory"),
    canManageUsers: rbac.hasPermission("manageUsers"),
    canManageSecurity: rbac.hasPermission("manageSecurity"),
    canManageSettings: rbac.hasPermission("manageSettings"),
    canEditWorkOrders: rbac.hasPermission("editWorkOrders"),
    canEditVehicles: rbac.hasPermission("editVehicles"),
    canUploadDocuments: rbac.hasPermission("uploadDocuments"),
    canDeleteRecords: rbac.hasPermission("deleteRecords"),
    canViewReports: rbac.hasPermission("viewReports"),
    canViewAuditLogs: rbac.hasPermission("viewAuditLogs"),
    isLoading: authLoading,
  };
}

/** Snapshot unico — preferire nelle pagine che leggono global + modulo (evita doppia sottoscrizione). */
export function usePermissionsSnapshot(): PermissionsSnapshot {
  const rbac = useRbac();
  const { user, status } = useAuth();
  const permsQuery = useUserPermissionsQuery();
  const roleKeysQuery = useRolePermissionKeysQuery();
  const authLoading = status === "loading";
  const moduleLoading =
    authLoading || permsQuery.isLoading || roleKeysQuery.isLoading;

  const global = useMemo(
    () => buildGlobalPermissions(user, rbac, authLoading),
    [
      user,
      rbac.isAdmin,
      rbac.isOperatore,
      rbac.isOspite,
      rbac.hasPermission,
      authLoading,
    ],
  );

  const modules = useMemo(() => {
    const map = buildEffectivePermissionsByModule({
      userId: user?.id ?? "",
      roleKey: user?.roleKey ?? user?.ruolo,
      rolePermissionKeys: roleKeysQuery.data ?? [],
      permissionRows: permsQuery.data,
    });
    const out = {} as Record<GestionalePermissionModule, ModulePermission>;
    for (const mod of GESTIONALE_PERMISSION_MODULES) {
      out[mod] = { ...map[mod], isLoading: moduleLoading };
    }
    return out;
  }, [user?.id, user?.roleKey, user?.ruolo, roleKeysQuery.data, moduleLoading]);

  return useMemo(() => ({ global, modules }), [global, modules]);
}

export function usePermissions(): GlobalPermissions;
export function usePermissions(module: GestionalePermissionModule): ModulePermission;
export function usePermissions(
  module?: GestionalePermissionModule,
): GlobalPermissions | ModulePermission {
  const snapshot = usePermissionsSnapshot();
  if (!module) return snapshot.global;
  return snapshot.modules[module];
}

const SECTION_TO_MODULE: Partial<Record<RbacSection, GestionalePermissionModule>> = {
  magazzino: "magazzino",
  preventivi: "preventivi",
  lavorazioni: "lavorazioni",
  mezzi: "mezzi",
  report: "report",
  documenti: "documenti",
  dipendenti: "dipendenti",
  fatturazione: "fatturazione",
  ddt: "ddt",
};

/** Nav ERP: `user_permissions` per modulo operativo; capability RBAC per security/impostazioni. */
export function useNavHrefPermission(href: string): { canRead: boolean; canWrite: boolean; isLoading: boolean } {
  const rbac = useRbac();
  const { user, status } = useAuth();
  const permsQuery = useUserPermissionsQuery();
  const roleKeysQuery = useRolePermissionKeysQuery();
  const moduleFromHref = gestionaleNavHrefToModule(href);
  const section = navHrefToSection(href);

  return useMemo(() => {
    if (!section) {
      return { canRead: true, canWrite: rbac.hasCapability("can_write_operational"), isLoading: rbac.isLoading };
    }

    const mod = moduleFromHref ?? SECTION_TO_MODULE[section];
    if (mod) {
      const map = buildEffectivePermissionsByModule({
        userId: user?.id ?? "",
        roleKey: user?.roleKey ?? user?.ruolo,
        rolePermissionKeys: roleKeysQuery.data ?? [],
        permissionRows: permsQuery.data,
      });
      const row = map[mod];
      return {
        canRead: row.canRead,
        canWrite: row.canWrite,
        isLoading:
          rbac.isLoading ||
          status === "loading" ||
          permsQuery.isLoading ||
          roleKeysQuery.isLoading,
      };
    }

    return {
      canRead: rbac.canRead(section),
      canWrite: rbac.canWrite(section),
      isLoading: rbac.isLoading,
    };
  }, [
    section,
    moduleFromHref,
    rbac.user,
    rbac.isLoading,
    rbac.canRead,
    rbac.canWrite,
    user?.id,
    user?.roleKey,
    user?.ruolo,
    roleKeysQuery.data,
    roleKeysQuery.isLoading,
    permsQuery.data,
    permsQuery.isLoading,
    status,
  ]);
}

"use client";

import { useCallback, useMemo } from "react";
import { useAuth, isAuthSessionEstablished } from "@/context/auth-context";
import { useClientLavorazioniAccess } from "@/src/hooks/use-client-lavorazioni-access";
import { denyUnless, assertAllowed } from "@/lib/auth/guard-action";
import {
  canAccessPage,
  canDelete,
  canRead,
  canWrite,
  hasPermission as checkPermission,
  type CanAccessPageOptions,
  type PermissionKey,
  type RbacSection,
  type Capability,
} from "@/lib/auth/rbac";
import type { RequiredRbacContext } from "@/lib/rbac";
import { hasResolvedCapability } from "@/src/lib/rbac/resolve-user-permissions";
import { useEffectivePermissions } from "@/src/lib/runtime/truth-layer/use-effective-permissions";
import { isRbacSnapshotReady } from "@/src/lib/rbac/rbac-snapshot-access";
import { readStickyRbacSnapshot } from "@/src/lib/rbac/sticky-rbac-snapshot";

export function useRbac() {
  const { user, status } = useAuth();
  const clientLav = useClientLavorazioniAccess();
  const { snapshot, isLoading: permsLoading } = useEffectivePermissions();
  const sticky = readStickyRbacSnapshot();
  const effectiveSnap =
    snapshot && isRbacSnapshotReady(snapshot)
      ? snapshot
      : sticky && isRbacSnapshotReady(sticky)
        ? sticky
        : null;

  const isLoading = status === "loading" || (permsLoading && !effectiveSnap);
  const role = effectiveSnap?.role ?? user?.ruolo ?? "guest";
  const rbacCtx = effectiveSnap?.rbacContext as RequiredRbacContext | undefined;
  const rbacUser = effectiveSnap ? effectiveSnap.role : user;
  const operatorGlobalSettingsPilotActive = effectiveSnap?.pilot.effectiveEnabled ?? false;
  const clientLavorazioniAllowed = clientLav.allowed;

  const hasPermission = useCallback(
    (permission: PermissionKey) => {
      if (!rbacCtx || !rbacUser) return false;
      return checkPermission(rbacUser, permission, rbacCtx);
    },
    [rbacUser, rbacCtx],
  );
  const hasCapabilityFn = useCallback(
    (capability: Capability) =>
      effectiveSnap?.resolved ? hasResolvedCapability(effectiveSnap.resolved, capability) : false,
    [effectiveSnap?.resolved],
  );
  const canReadFn = useCallback(
    (section: RbacSection) => {
      if (!rbacCtx || !rbacUser) return false;
      return canRead(rbacUser, section, rbacCtx);
    },
    [rbacUser, rbacCtx],
  );
  const canWriteFn = useCallback(
    (section: RbacSection) => {
      if (!rbacCtx || !rbacUser) return false;
      return canWrite(rbacUser, section, rbacCtx);
    },
    [rbacUser, rbacCtx],
  );
  const canDeleteFn = useCallback(
    (section: RbacSection) => {
      if (!rbacCtx || !rbacUser) return false;
      return canDelete(rbacUser, section, rbacCtx);
    },
    [rbacUser, rbacCtx],
  );
  const canAccessPageFn = useCallback(
    (pathname: string, opts?: CanAccessPageOptions) => {
      if (!rbacCtx || !rbacUser) return false;
      return canAccessPage(rbacUser, pathname, { clientLavorazioniAllowed, ...opts }, rbacCtx);
    },
    [rbacUser, rbacCtx, clientLavorazioniAllowed],
  );
  const guardWrite = useCallback(
    (section: RbacSection, onDenied?: (msg: string) => void) => {
      if (!rbacCtx || !rbacUser) return denyUnless(false, onDenied);
      return denyUnless(canWrite(rbacUser, section, rbacCtx), onDenied);
    },
    [rbacUser, rbacCtx],
  );
  const guardRead = useCallback(
    (section: RbacSection, onDenied?: (msg: string) => void) => {
      if (!rbacCtx || !rbacUser) return denyUnless(false, onDenied);
      return denyUnless(canRead(rbacUser, section, rbacCtx), onDenied);
    },
    [rbacUser, rbacCtx],
  );
  const assertWrite = useCallback(
    (section: RbacSection) => {
      if (!rbacCtx || !rbacUser) assertAllowed(false);
      else assertAllowed(canWrite(rbacUser, section, rbacCtx));
    },
    [rbacUser, rbacCtx],
  );

  const isAdmin = role === "admin";
  const isManager = role === "manager";
  const isOperatore = role === "operatore" || role === "manager";
  const isGuest = role === "guest";
  const isCliente = role === "cliente";
  const isReadOnly = role === "guest" || role === "cliente";

  return useMemo(
    () => ({
      user,
      role,
      isLoading,
      operatorGlobalSettingsPilotActive,
      clientLavorazioniLoading: false,
      hasPermission,
      hasCapability: hasCapabilityFn,
      canRead: canReadFn,
      canWrite: canWriteFn,
      canDelete: canDeleteFn,
      canAccessPage: canAccessPageFn,
      guardWrite,
      guardRead,
      assertWrite,
      isAdmin,
      isManager,
      isOperatore,
      isGuest,
      isOspite: isGuest,
      isCliente,
      isReadOnly,
      effectivePermissions: effectiveSnap,
    }),
    [
      user,
      role,
      isLoading,
      operatorGlobalSettingsPilotActive,
      hasPermission,
      hasCapabilityFn,
      canReadFn,
      canWriteFn,
      canDeleteFn,
      canAccessPageFn,
      guardWrite,
      guardRead,
      assertWrite,
      isAdmin,
      isManager,
      isOperatore,
      isGuest,
      isCliente,
      isReadOnly,
      effectiveSnap,
    ],
  );
}

export type UseRbacReturn = ReturnType<typeof useRbac> & { role: ReturnType<typeof useRbac>["role"] };

/** Sessione pronta per valutazioni RBAC lato client. */
export function useRbacReady(): boolean {
  const { status, user } = useAuth();
  return isAuthSessionEstablished(status) && !!user?.id;
}

"use client";

import { useMemo } from "react";
import type { DateRange } from "@/lib/report/date-ranges";
import { filterEntriesForReportTimesheetKpi } from "@/lib/dipendenti/timesheet-report-kpi-filter";
import { resolveReportTimesheetRange } from "@/lib/dipendenti/timesheet-report-range";
import { shiftMonthKey } from "@/lib/dipendenti/timesheet-month";
import type { DipendenteTimesheetEmployeeRow, DipendenteTimesheetEntryRow } from "@/lib/dipendenti/types";
import { useGlobalOptions } from "@/src/hooks/use-global-options";
import { useServiceQuery } from "@/src/hooks/use-service-query";
import { QK } from "@/src/lib/react-query/query-keys";
import { dipendentiTimesheetService } from "@/src/services/dipendenti-timesheet.service";

function entriesQueryKey(from: string, to: string) {
  return [...QK.dipendentiTimesheetEntries, from, to] as const;
}

export function useReportTimesheetKpi(filterRange: DateRange) {
  const { dipendenti: dipendentiOpts } = useGlobalOptions({ debugTag: "useReportTimesheetKpi" });
  const tipiAssenza = dipendentiOpts.tipiAssenza;

  const timesheetRange = useMemo(() => resolveReportTimesheetRange(filterRange), [filterRange]);
  const { from, to, periodLabel, showMonthDelta, monthKey } = timesheetRange;
  const previousMonthKey = monthKey ? shiftMonthKey(monthKey, -1) : null;

  const employeesQuery = useServiceQuery(QK.dipendentiTimesheetEmployees, () =>
    dipendentiTimesheetService.listEmployees(),
  );

  const entriesQuery = useServiceQuery(entriesQueryKey(from, to), () =>
    dipendentiTimesheetService.listEntriesForRange(from, to),
  );

  const previousMonthQuery = useServiceQuery(
    [...QK.dipendentiTimesheetEntries, "prev", previousMonthKey ?? ""] as const,
    () => dipendentiTimesheetService.listEntriesForMonth(previousMonthKey!),
    { enabled: showMonthDelta && previousMonthKey != null },
  );

  const isLoading =
    employeesQuery.isPending ||
    entriesQuery.isPending ||
    (showMonthDelta && previousMonthQuery.isPending);
  const isError = employeesQuery.isError || entriesQuery.isError;

  const rawEntries = (entriesQuery.data ?? []) as DipendenteTimesheetEntryRow[];
  const rawPreviousEntries = showMonthDelta
    ? ((previousMonthQuery.data ?? []) as DipendenteTimesheetEntryRow[])
    : [];

  const entries = useMemo(
    () => filterEntriesForReportTimesheetKpi(rawEntries, tipiAssenza),
    [rawEntries, tipiAssenza],
  );
  const previousMonthEntries = useMemo(
    () => filterEntriesForReportTimesheetKpi(rawPreviousEntries, tipiAssenza),
    [rawPreviousEntries, tipiAssenza],
  );

  return {
    periodLabel,
    singleMonth: showMonthDelta,
    isLoading,
    isError,
    employees: (employeesQuery.data ?? []) as DipendenteTimesheetEmployeeRow[],
    entries,
    previousMonthEntries,
    refetch: () => {
      void employeesQuery.refetch();
      void entriesQuery.refetch();
      if (showMonthDelta) void previousMonthQuery.refetch();
    },
  };
}

"use client";

import { useCallback, useMemo } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import {
  ensureSchedeBundlesInCache,
  schedeEnsureQueryKey,
} from "@/lib/schede/schede-sync-adapter";
import { useViewQueryOpts } from "@/lib/view/view-query-opts";
import { useRealtimeStatus } from "@/src/context/realtime-status-context";
import { QK, SCHEde_BUNDLES_QUERY_KEY } from "@/src/lib/react-query/query-keys";
import type { LavorazioneSchedeStore } from "@/types/schede";

export { SCHEde_BUNDLES_QUERY_KEY, SCHEDE_STORE_QUERY_KEY } from "@/src/lib/react-query/query-keys";

const BUNDLE_OPTS = {
  refetchOnWindowFocus: false,
  refetchOnReconnect: true,
} as const;

export type SchedeBundlesQueryOptions = {
  /** VIEW layer (portale clienti): refetch stale al mount. Default CORE gestionale. */
  viewLayer?: boolean;
  /** Lazy load: fetch solo bundle per questi id (no monolith getAll). */
  lavorazioneIds?: readonly string[];
};

/** Bundle schede per lavorazione — React Query unica source UI (DB lazy per id). */
export function useSchedeBundlesQuery(enabled = true, options?: SchedeBundlesQueryOptions) {
  const qc = useQueryClient();
  const { gestionale } = useRealtimeStatus();
  const viewOpts = useViewQueryOpts();
  const realtimeConnected = gestionale === "connected";
  const viewLayer = options?.viewLayer === true;
  const lavorazioneIds = options?.lavorazioneIds ?? [];
  const ensureKey = useMemo(() => schedeEnsureQueryKey(lavorazioneIds), [lavorazioneIds]);
  const hasIds = lavorazioneIds.length > 0;

  const ensureQ = useQuery({
    queryKey: ensureKey,
    queryFn: () => ensureSchedeBundlesInCache(qc, lavorazioneIds),
    enabled: enabled && hasIds,
    staleTime: viewLayer ? viewOpts.staleTime : realtimeConnected ? 30_000 : 5_000,
    refetchInterval: false,
    refetchOnMount: viewLayer ? viewOpts.refetchOnMount : realtimeConnected ? false : undefined,
    ...BUNDLE_OPTS,
  });

  const storeQ = useQuery({
    queryKey: SCHEde_BUNDLES_QUERY_KEY,
    queryFn: () => qc.getQueryData<LavorazioneSchedeStore>(SCHEde_BUNDLES_QUERY_KEY) ?? {},
    staleTime: Infinity,
    refetchOnMount: false,
    refetchOnWindowFocus: false,
    refetchOnReconnect: false,
    initialData: () => qc.getQueryData<LavorazioneSchedeStore>(SCHEde_BUNDLES_QUERY_KEY) ?? {},
  });

  const store: LavorazioneSchedeStore = storeQ.data ?? {};

  const invalidate = useCallback(() => {
    void qc.invalidateQueries({ queryKey: QK.schede, refetchType: "active" });
  }, [qc]);

  return {
    store,
    isLoading: enabled && hasIds ? ensureQ.isLoading : false,
    isFetching: ensureQ.isFetching,
    invalidate,
    refetch: ensureQ.refetch,
  };
}

/** @deprecated Usare `useSchedeBundlesQuery`. */
export function useSchedeStoreQuery(enabled = true) {
  return useSchedeBundlesQuery(enabled);
}

/** Slice bundle per singola riga — evita di passare l'intero `store` ai componenti memo. */
export function useSchedeBundleForRow(lavorazioneId: string | undefined) {
  const { bundle } = useSchedeBundle(lavorazioneId);
  return bundle;
}

/** Bundle schede per singola lavorazione — lazy fetch on demand. */
export function useSchedeBundle(lavorazioneId: string | undefined) {
  const ids = useMemo(() => (lavorazioneId ? [lavorazioneId] : []), [lavorazioneId]);
  const { store, isLoading, invalidate, refetch } = useSchedeBundlesQuery(Boolean(lavorazioneId), {
    lavorazioneIds: ids,
  });
  const bundle = useMemo(
    () => (lavorazioneId ? store[lavorazioneId] : undefined),
    [store, lavorazioneId],
  );
  return { bundle, store, isLoading, invalidate, refetch };
}

