export const DEFAULT_PRIORITA_LAVORAZIONI_DB: PrioritaLavorazione[] = ["bassa", "media", "alta", "urgente"];

export type CabAppSettingsResolved = {
  lavorazioni: {
    stati: StatoLavorazioneConfig[];
    addettiRecords: AddettoRecord[];
    addetti: string[];
    addettoColors: Record<string, string>;
    prioritaColors: Partial<Record<PrioritaLav, string>>;
    prioritaDb: PrioritaLavorazione[];
  };
  mezziListe: MezziListePrefs;
  magazzinoMaster: MagazzinoMasterPrefs;
  preventiviDefaults: SistemaPreventiviDefaults;
  dipendenti: {
    tipiAssenza: TipoAssenzaConfig[];
  };
  branding: CabBrandingSettings;
};

const FALLBACK_PREVENTIVI: SistemaPreventiviDefaults = { costoOrarioDefault: 48 };

function defaultLavorazioni(): CabAppSettingsResolved["lavorazioni"] {
  const { addettiRecords, addetti } = syncLavorazioniAddettiFromRecords(defaultAddettiRecords());
  return {
    stati: [...DEFAULT_STATI_LAVORAZIONI_WORKFLOW],
    addettiRecords,
    addetti,
    addettoColors: syncAddettoColorMap(addetti, undefined),
    prioritaColors: {},
    prioritaDb: [...DEFAULT_PRIORITA_LAVORAZIONI_DB],
  };
}

function resolveAddettiFromPayload(o: Record<string, unknown>): {
  addettiRecords: AddettoRecord[];
  addetti: string[];
} {
  const fromRecords = parseAddettiRecordsFromPayload(o.addettiRecords);
  if (fromRecords) {
    return syncLavorazioniAddettiFromRecords(fromRecords);
  }
  if (Array.isArray(o.addetti)) {
    const legacy = (o.addetti as unknown[])
      .filter((x): x is string => typeof x === "string" && x.trim().length > 0)
      .map((x) => x.trim());
    if (legacy.length) {
      return syncLavorazioniAddettiFromRecords(migrateLegacyAddettiStrings(legacy));
    }
  }
  const fallback = syncLavorazioniAddettiFromRecords(defaultAddettiRecords());
  return fallback;
}

function parsePrioritaDb(_raw: unknown): PrioritaLavorazione[] {
  return [...DEFAULT_PRIORITA_LAVORAZIONI_DB];
}

function parseLavorazioniPayload(raw: unknown): CabAppSettingsResolved["lavorazioni"] {
  const base = defaultLavorazioni();
  if (!raw || typeof raw !== "object") return base;
  const o = raw as Record<string, unknown>;
  if (Array.isArray(o.stati)) {
    const stati = normalizeStatiList(o.stati as StatoLavorazioneConfig[]);
    if (stati.length) base.stati = stati;
  }
  const addettiResolved = resolveAddettiFromPayload(o);
  base.addettiRecords = addettiResolved.addettiRecords;
  base.addetti = addettiResolved.addetti;
  base.addettoColors = syncAddettoColorMap(
    base.addetti,
    o.addettoColors && typeof o.addettoColors === "object" && !Array.isArray(o.addettoColors)
      ? (o.addettoColors as Record<string, string>)
      : undefined,
  );
  if (o.addettoColors && typeof o.addettoColors === "object" && !Array.isArray(o.addettoColors)) {
    base.addettoColors = { ...base.addettoColors, ...(o.addettoColors as Record<string, string>) };
  }
  if (o.prioritaColors && typeof o.prioritaColors === "object" && !Array.isArray(o.prioritaColors)) {
    base.prioritaColors = { ...base.prioritaColors, ...(o.prioritaColors as Partial<Record<PrioritaLav, string>>) };
  }
  base.prioritaDb = parsePrioritaDb(o.prioritaDb);
  return base;
}

function parseMezziListePayload(raw: unknown): MezziListePrefs {
  const d = createMezziListePrefsDefault();
  if (!raw || typeof raw !== "object") return d;
  const o = raw as Record<string, unknown>;
  const out: MezziListePrefs = {
    clienti: Array.isArray(o.clienti) ? o.clienti.filter((x): x is string => typeof x === "string") : d.clienti,
    utilizzatori: Array.isArray(o.utilizzatori)
      ? o.utilizzatori.filter((x): x is string => typeof x === "string")
      : d.utilizzatori,
    cantieri: Array.isArray(o.cantieri) ? o.cantieri.filter((x): x is string => typeof x === "string") : d.cantieri,
    marche: Array.isArray(o.marche) ? o.marche.filter((x): x is string => typeof x === "string") : d.marche,
    modelli: Array.isArray(o.modelli) ? o.modelli.filter((x): x is string => typeof x === "string") : d.modelli,
    tipiAttrezzatura: Array.isArray(o.tipiAttrezzatura)
      ? o.tipiAttrezzatura.filter((x): x is string => typeof x === "string")
      : d.tipiAttrezzatura,
    stati: Array.isArray(o.stati) ? o.stati.filter((x): x is string => typeof x === "string") : d.stati,
    attrezzature: Array.isArray(o.attrezzature) ? (o.attrezzature as MezziListePrefs["attrezzature"]) : d.attrezzature,
    telai: Array.isArray(o.telai) ? (o.telai as MezziListePrefs["telai"]) : d.telai,
    tipiTelaio: Array.isArray(o.tipiTelaio) ? o.tipiTelaio.filter((x): x is string => typeof x === "string") : d.tipiTelaio,
    scontoRicambiByCliente: parseScontoRicambiByCliente(o.scontoRicambiByCliente),
  };
  return migrateMezziListePrefs(out);
}

function parseMagazzinoMasterPayload(raw: unknown): MagazzinoMasterPrefs {
  const empty: MagazzinoMasterPrefs = {
    marche: [],
    categorie: [],
    mezziCompatibili: [],
    fornitori: [],
    produttori: [],
  };
  if (!raw || typeof raw !== "object") return empty;
  const o = raw as Record<string, unknown>;
  const partial: MagazzinoMasterPrefs = {
    marche: Array.isArray(o.marche) ? o.marche.filter((x): x is string => typeof x === "string") : [],
    scontoFornitoreByMarca: parseScontoFornitoreByMarca(o.scontoFornitoreByMarca),
    categorie: Array.isArray(o.categorie) ? o.categorie.filter((x): x is string => typeof x === "string") : [],
    mezziCompatibili: Array.isArray(o.mezziCompatibili)
      ? o.mezziCompatibili.filter((x): x is string => typeof x === "string")
      : [],
    fornitori: Array.isArray(o.fornitori) ? o.fornitori.filter((x): x is string => typeof x === "string") : [],
    scontoFornitoreByFornitore: parseScontoFornitoreByFornitore(o.scontoFornitoreByFornitore),
    produttori: Array.isArray(o.produttori) ? o.produttori.filter((x): x is string => typeof x === "string") : [],
    produttoriByFornitore: parseProduttoriByFornitore(o.produttoriByFornitore),
  };
  return { ...partial, produttori: mergeProduttoriFromMagazzinoMaster(partial) };
}

function parsePreventiviDefaultsPayload(raw: unknown): SistemaPreventiviDefaults {
  if (!raw || typeof raw !== "object") return { ...FALLBACK_PREVENTIVI };
  const c = Number((raw as { costoOrarioDefault?: unknown }).costoOrarioDefault);
  return {
    costoOrarioDefault: Number.isFinite(c) && c > 0 ? Math.round(c * 100) / 100 : FALLBACK_PREVENTIVI.costoOrarioDefault,
  };
}

export function resolveCabAppSettingsFromRows(
  rows: AppSettingRow[],
  legacy?: Partial<CabAppSettingsResolved> | null,
): CabAppSettingsResolved {
  const pick = (m: string, k: string): AppSettingRow | undefined =>
    rows.find((r) => r.module === m && r.key === k);

  const lavRow = pick(CAB_SETTINGS_MODULE.lavorazioni, CAB_SETTINGS_KEY.prefs);
  const lavorazioni =
    lavRow != null
      ? parseLavorazioniPayload(lavRow.value)
      : legacy?.lavorazioni != null
        ? parseLavorazioniPayload(legacy.lavorazioni as unknown)
        : defaultLavorazioni();

  const mezziRow = pick(CAB_SETTINGS_MODULE.mezzi, CAB_SETTINGS_KEY.liste);
  const mezziListe =
    mezziRow != null
      ? parseMezziListePayload(mezziRow.value)
      : legacy?.mezziListe != null
        ? migrateMezziListePrefs(legacy.mezziListe)
        : createMezziListePrefsDefault();

  const magRow = pick(CAB_SETTINGS_MODULE.magazzino, CAB_SETTINGS_KEY.master);
  const magazzinoMaster =
    magRow != null
      ? parseMagazzinoMasterPayload(magRow.value)
      : legacy?.magazzinoMaster != null
        ? parseMagazzinoMasterPayload(legacy.magazzinoMaster as unknown)
        : { marche: [], categorie: [], mezziCompatibili: [], fornitori: [], produttori: [] };

  const prevRow = pick(CAB_SETTINGS_MODULE.preventivi, CAB_SETTINGS_KEY.defaults);
  const preventiviDefaults =
    prevRow != null
      ? parsePreventiviDefaultsPayload(prevRow.value)
      : legacy?.preventiviDefaults != null
        ? legacy.preventiviDefaults
        : { ...FALLBACK_PREVENTIVI };

  const dipRow = pick(CAB_SETTINGS_MODULE.dipendenti, CAB_SETTINGS_KEY.prefs);
  const dipendenti = {
    tipiAssenza:
      dipRow != null
        ? parseTipiAssenzaFromPayload((dipRow.value as Record<string, unknown>).tipiAssenza)
        : defaultTipiAssenza(),
  };

  const brandRow = pick(CAB_SETTINGS_MODULE.system, CAB_SETTINGS_KEY.branding);
  const branding =
    brandRow != null
      ? parseBrandingSettingsPayload(brandRow.value)
      : legacy?.branding != null
        ? parseBrandingSettingsPayload(legacy.branding)
        : { ...DEFAULT_CAB_BRANDING_SETTINGS };

  return { lavorazioni, mezziListe, magazzinoMaster, preventiviDefaults, dipendenti, branding };
}

export function buildBulkRowsFromResolved(r: CabAppSettingsResolved): { module: string; key: string; value: Record<string, unknown> }[] {
  return [
    {
      module: CAB_SETTINGS_MODULE.lavorazioni,
      key: CAB_SETTINGS_KEY.prefs,
      value: {
        stati: r.lavorazioni.stati,
        addettiRecords: r.lavorazioni.addettiRecords,
        addetti: r.lavorazioni.addetti,
        addettoColors: r.lavorazioni.addettoColors,
        prioritaColors: r.lavorazioni.prioritaColors,
        prioritaDb: r.lavorazioni.prioritaDb,
      },
    },
    {
      module: CAB_SETTINGS_MODULE.mezzi,
      key: CAB_SETTINGS_KEY.liste,
      value: { ...(r.mezziListe as unknown as Record<string, unknown>) },
    },
    {
      module: CAB_SETTINGS_MODULE.magazzino,
      key: CAB_SETTINGS_KEY.master,
      value: { ...(r.magazzinoMaster as unknown as Record<string, unknown>) },
    },
    {
      module: CAB_SETTINGS_MODULE.preventivi,
      key: CAB_SETTINGS_KEY.defaults,
      value: { ...(r.preventiviDefaults as unknown as Record<string, unknown>) },
    },
    {
      module: CAB_SETTINGS_MODULE.dipendenti,
      key: CAB_SETTINGS_KEY.prefs,
      value: { tipiAssenza: r.dipendenti.tipiAssenza },
    },
    {
      module: CAB_SETTINGS_MODULE.system,
      key: CAB_SETTINGS_KEY.branding,
      value: {
        primaryColor: r.branding.primaryColor,
        logoStoragePath: r.branding.logoStoragePath,
        updatedAt: r.branding.updatedAt ?? new Date().toISOString(),
      },
    },
  ];
}

import {
  canAccessPage,
  pathnameToSection,
  type CanAccessPageOptions,
  type RbacSection,
  type RbacUser,
} from "@/lib/auth/rbac";
import type { RequiredRbacContext } from "@/lib/rbac";
import { hasResolvedCapability } from "@/src/lib/rbac/resolve-user-permissions";
import { moduleAllows } from "@/src/lib/auth/effective-module-access";
import type { GestionalePermissionModule } from "@/src/lib/permissions/gestionale-modules";
import type { EffectivePermissionsSnapshot } from "@/src/lib/runtime/truth-layer/types";

const SECTION_TO_MODULE: Partial<Record<RbacSection, GestionalePermissionModule>> = {
  magazzino: "magazzino",
  preventivi: "preventivi",
  lavorazioni: "lavorazioni",
  mezzi: "mezzi",
  report: "report",
  documenti: "documenti",
  dipendenti: "dipendenti",
  fatturazione: "fatturazione",
  ddt: "ddt",
};

/** Hard gate / derived — non passano da user_permissions (RBAC_PRECEDENCE step 1). */
const NON_MODULE_SECTIONS = new Set<RbacSection>([
  "dashboard",
  "security",
  "impostazioni",
  "lavorazioni_clienti",
]);

export type CanAccessRouteInput = {
  user: RbacUser;
  pathname: string;
  opts?: CanAccessPageOptions;
  ctx?: RequiredRbacContext;
  /** Se presente, applica user_permissions + role_permissions via snapshot DB. */
  snapshot?: EffectivePermissionsSnapshot | null;
};

/** Accesso route: hard gate + moduli ERP via snapshot (precedence allineata). */
export function canAccessRoute(input: CanAccessRouteInput): boolean {
  const { user, pathname, opts, ctx, snapshot } = input;
  const effectiveCtx = ctx ?? snapshot?.rbacContext;
  const section = pathnameToSection(pathname);

  if (!section || NON_MODULE_SECTIONS.has(section)) {
    if (!effectiveCtx?.resolved) return false;
    return canAccessPage(user, pathname, opts, effectiveCtx as RequiredRbacContext);
  }

  const module = SECTION_TO_MODULE[section];
  if (!module) {
    if (!effectiveCtx?.resolved) return false;
    return canAccessPage(user, pathname, opts, effectiveCtx as RequiredRbacContext);
  }

  const resolved = snapshot?.resolved ?? effectiveCtx?.resolved;
  if (!resolved || !hasResolvedCapability(resolved, "can_read_operational")) {
    return false;
  }

  if (snapshot) {
    return moduleAllows(snapshot.modules, module, "read");
  }

  if (!effectiveCtx?.resolved) return false;
  return canAccessPage(user, pathname, opts, effectiveCtx as RequiredRbacContext);
}

import type { GestionalePermissionModule } from "@/src/lib/permissions/gestionale-modules";
import { GESTIONALE_PERMISSION_MODULES } from "@/src/lib/permissions/gestionale-modules";
import type { UserPermissionRow } from "@/src/types/supabase-tables";
import { buildEffectivePermissionsByModule } from "@/src/lib/permissions/effective-permissions";
import { resolveRole } from "@/lib/auth/rbac";

export type ModulePermissionOp = "read" | "write";

export function moduleAllows(
  map: Record<GestionalePermissionModule, import("@/src/lib/permissions/effective-permissions").EffectiveModulePermission>,
  module: GestionalePermissionModule,
  op: ModulePermissionOp,
): boolean {
  const row = map[module];
  return op === "read" ? row.canRead : row.canWrite;
}

export function buildModuleAccessMap(input: {
  userId: string;
  roleKey: string | null | undefined;
  rolePermissionKeys: string[];
  rows: UserPermissionRow[] | null | undefined;
}): Record<GestionalePermissionModule, import("@/src/lib/permissions/effective-permissions").EffectiveModulePermission> {
  const overrides = (input.rows ?? [])
    .map((row) => {
      const key = row.permissions?.key;
      if (!key || (row.effect !== "allow" && row.effect !== "deny")) return null;
      return { permissionKey: key, effect: row.effect };
    })
    .filter((x): x is { permissionKey: string; effect: "allow" | "deny" } => x != null);

  return buildEffectivePermissionsByModule({
    userId: input.userId,
    roleKey: resolveRole(input.roleKey),
    rolePermissionKeys: input.rolePermissionKeys,
    userOverrides: overrides,
  });
}

