"use client";

import {
  DDT_DOCUMENTS_COLUMNS,
  DDT_DOCUMENTS_INDEX_COLUMNS,
  DDT_LINKS_COLUMNS,
  DDT_ROWS_COLUMNS,
} from "@/lib/db/table-select-columns";
import { fetchDdtListPayload } from "@/lib/ddt/ddt-fetch";
import type { DdtCreateInput, DdtDetail } from "@/lib/ddt/types";
